function ChatSettingsPanel({ conv, myId, meAvatar, meName, isPinned, isLocked, wallpaper, nameBar, chatLockAvailable, onClose, onTogglePin, onToggleArchive, onSetWallpaper, onSetNameBar, onEnableLock, onDisableLock, onDeleteChat, onReportUser, onNicknameSaved, onNeedChatLockSetup, onOpenProfile, isMuted, onSetMute, onCall, disappearSecs, onSetDisappear, tools }) {
  const [showDisappear, setShowDisappear] = useState(false);
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const [showMuteOptions, setShowMuteOptions] = useState(false);
  useBackClose(showMuteOptions, () => setShowMuteOptions(false));
  const { theme } = useTheme();
  const [nickname, setNickname] = useState('');
  const [myAlias, setMyAlias] = useState('');
  const [showWallpaper, setShowWallpaper] = useState(false);
  const [showNameBar, setShowNameBar] = useState(false);
  const [showNicknames, setShowNicknames] = useState(false);
  const [showReportUser, setShowReportUser] = useState(false);
  const [followerCount, setFollowerCount] = useState(0);
  const [followingCount, setFollowingCount] = useState(0);
  const [listModal, setListModal] = useState(null);
  const [note, setNote] = useState(() => contactNoteFor(conv.otherProfile.id));
  const [noteOpen, setNoteOpen] = useState(false);

  useEffect(() => {
    (async () => {
      const { data } = await supabase.from('contact_nicknames').select('nickname').eq('owner_id', myId).eq('contact_id', conv.otherProfile.id).maybeSingle();
      setNickname(data ? data.nickname : '');
      const { data: aliasRow } = await supabase.from('self_aliases').select('alias').eq('user_id', myId).eq('viewer_id', conv.otherProfile.id).maybeSingle();
      setMyAlias(aliasRow ? aliasRow.alias : '');
      const { count: followers } = await supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', conv.otherProfile.id).eq('status', 'accepted');
      setFollowerCount(followers || 0);
      const { count: following } = await supabase.from('follows').select('*', { count: 'exact', head: true }).eq('follower_id', conv.otherProfile.id).eq('status', 'accepted');
      setFollowingCount(following || 0);
    })();
  }, [conv.otherProfile.id]);

  const saveMyAlias = async (val) => {
    if (val.trim()) {
      await supabase.from('self_aliases').upsert({ user_id: myId, viewer_id: conv.otherProfile.id, alias: val.trim() }, { onConflict: 'user_id,viewer_id' });
    } else {
      await supabase.from('self_aliases').delete().eq('user_id', myId).eq('viewer_id', conv.otherProfile.id);
    }
    await sendMessage(myId, conv.otherProfile.id, 'system', val.trim() ? `Now appears as "${val.trim()}" to you` : 'Reverted to their real name', null);
    setMyAlias(val.trim());
  };
  const saveNickname = async (val) => {
    if (val.trim()) {
      await supabase.from('contact_nicknames').upsert({ owner_id: myId, contact_id: conv.otherProfile.id, nickname: val.trim() }, { onConflict: 'owner_id,contact_id' });
      await sendMessage(myId, conv.otherProfile.id, 'system', `Nickname updated to "${val.trim()}"`, null);
    } else {
      await supabase.from('contact_nicknames').delete().eq('owner_id', myId).eq('contact_id', conv.otherProfile.id);
      await sendMessage(myId, conv.otherProfile.id, 'system', 'Nickname removed', null);
    }
    setNickname(val.trim());
    onNicknameSaved(val.trim() || null, conv.otherProfile.id);
  };

  const otherName = conv.realName || conv.otherProfile.name;
  const p = conv.otherProfile;
  const infoBits = [
    p.pronouns ? p.pronouns : null,
    p.age != null && !p.hide_age ? `${p.age} yrs` : null,
    p.country && !p.hide_country ? countryFlag(p.country) : null,
  ].filter(Boolean);
  const showBio = p.bio && !p.hide_bio;
  const sectionLabel = { fontSize: 11, fontWeight: 900, color: theme.muted, letterSpacing: '0.1em', margin: '16px 4px 6px' };
  const card = { borderRadius: 18, background: theme.rowBg, border: `1px solid ${theme.border}`, overflow: 'hidden' };
  const quickAction = (icon, label, onClick) => (
    <div role="button" onClick={onClick} style={{ flex: 1, borderRadius: 14, background: theme.dark ? 'rgba(255,255,255,0.06)' : theme.rowBg, border: `1px solid ${theme.border}`, padding: '9px 4px', textAlign: 'center', fontSize: 11, fontWeight: 800, color: theme.ink, cursor: 'pointer' }}>
      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 4, color: theme.coralDeep }}>{icon}</div>{label}
    </div>
  );
  const c = igPalette(theme);
  const muteLabel = isMuted === true ? 'Muted' : isMuted ? `Muted until ${new Date(isMuted).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}` : 'Off';

  return (
    <>
    <WideDim onClose={onClose} z={33} />
    <div {...edgeBack} style={{
      position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 33, fontFamily: FONT,
      display: 'flex', flexDirection: 'column', overflow: 'hidden',
    }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Chat settings" onBack={onClose} />
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(28px + env(safe-area-inset-bottom))' }}>
        <div style={{ textAlign: 'center', padding: '8px 20px 4px' }}>
          <div role="button" onClick={() => onOpenProfile(p)} style={{ display: 'flex', justifyContent: 'center', cursor: 'pointer' }}>
            <Avatar emoji={conv.otherProfile.avatar} name={otherName} frame={conv.otherProfile.avatar_frame} size={92} frameFit />
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 12, padding: '0 6px' }}>
            <NameBadge name={otherName} verified={p.verified} custom={p.custom_badge} size={15} lines={2} style={{ justifyContent: 'center', textAlign: 'center', fontWeight: 700, fontSize: otherName.length > 30 ? 16 : 18 }} />
          </div>
          <div style={{ fontSize: 13, color: c.dim, marginTop: 3, padding: '0 16px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>@{conv.otherProfile.username}</div>
          {infoBits.length > 0 && <div style={{ fontSize: 13, color: c.dim, marginTop: 6 }}>{infoBits.join(' \u00b7 ')}</div>}
          {showBio && <div style={{ fontSize: 13.5, marginTop: 8, lineHeight: 1.45, padding: '0 8px' }}><RichText text={p.bio} onMention={onOpenProfile} /></div>}
          <div style={{ display: 'flex', justifyContent: 'center', gap: 26, marginTop: 14 }}>
            <div role="button" onClick={conv.otherProfile.is_bot ? undefined : () => setListModal('followers')} style={{ cursor: conv.otherProfile.is_bot ? 'default' : 'pointer' }}>
              <span style={{ fontWeight: 700, fontSize: 15 }}>{conv.otherProfile.is_bot ? (BOT_FOLLOWER_BASE + (followerCount || 0)).toLocaleString('en-US') : followerCount}</span> <span style={{ fontSize: 13, color: c.dim }}>followers</span>
            </div>
            {!conv.otherProfile.is_bot && (
              <div role="button" onClick={() => setListModal('following')} style={{ cursor: 'pointer' }}>
                <span style={{ fontWeight: 700, fontSize: 15 }}>{followingCount}</span> <span style={{ fontSize: 13, color: c.dim }}>following</span>
              </div>
            )}
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginTop: 18, flexWrap: 'wrap' }}>
            {[
              [<User size={21} strokeWidth={1.6} />, 'Profile', () => onOpenProfile(p)],
              ...(onCall ? [[<Phone size={21} strokeWidth={1.6} />, 'Call', () => onCall('voice')], [<VideoIcon size={21} strokeWidth={1.6} />, 'Video', () => onCall('video')]] : []),
              ...(tools && tools.onSearch ? [[<Search size={21} strokeWidth={1.6} />, 'Search', tools.onSearch]] : []),
              ...(onSetMute ? [[isMuted ? <BellOff size={21} strokeWidth={1.6} /> : <Bell size={21} strokeWidth={1.6} />, isMuted ? 'Muted' : 'Mute', () => setShowMuteOptions(true)]] : []),
            ].map(([icon, label, fn]) => (
              <div key={label} role="button" aria-label={label} onClick={fn} style={{ textAlign: 'center', cursor: 'pointer', width: 56 }}>
                <div style={{ width: 52, height: 52, borderRadius: '50%', border: `1px solid ${c.line}`, background: c.field, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 6px' }}>{icon}</div>
                <div style={{ fontSize: 12, color: c.dim }}>{label}</div>
              </div>
            ))}
          </div>
        </div>

        <IgHeading>Private note</IgHeading>
        {note ? (
          <div role="button" aria-label="Edit private note" onClick={() => setNoteOpen(true)} className="zchat-row-press" style={{ margin: '2px 16px 6px', padding: '12px 14px', borderRadius: 14, background: c.field, border: `1px solid ${c.line}`, cursor: 'pointer' }}>
            <div style={{ fontSize: 14, lineHeight: 1.45, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>{note}</div>
            <div style={{ fontSize: 11.5, color: c.dim, marginTop: 6 }}>Only you can see this. Tap to edit.</div>
          </div>
        ) : (
          <IgRow icon={<Pencil />} label="Add a private note" sub="Only you can see it" onClick={() => setNoteOpen(true)} />
        )}
        {tools && (
          <>
            <IgHeading>In this chat</IgHeading>
            <IgRow icon={<ImageIcon />} label="Media, links and voice" onClick={tools.onMedia} />
            {tools.onJumpDate && <IgRow icon={<CalendarIcon />} label="Jump to a date" onClick={tools.onJumpDate} />}
            {tools.onPinned && <IgRow icon={<Pin_ color="currentColor" />} label="Pinned messages" value={String(tools.pinnedCount)} onClick={tools.onPinned} />}
            {tools.onScheduled && <IgRow icon={<Clock />} label="Scheduled messages" value={String(tools.scheduledCount)} onClick={tools.onScheduled} />}
            {tools.onGame && <IgRow icon={<GamepadIcon />} label="Play a game" onClick={tools.onGame} />}
            <IgRow icon={<Activity />} label="Chat insights" onClick={tools.onInsights} />
            <IgRow icon={<Download />} label="Export chat" onClick={tools.onExport} />
          </>
        )}

        <IgHeading>Look</IgHeading>
        <IgRow icon={<ImageIcon />} label="Chat wallpaper" onClick={() => setShowWallpaper(true)} />
        <IgRow icon={<Palette />} label="Header style" onClick={() => setShowNameBar(true)} />
        {tools && <IgRow icon={<BubblesIcon />} label="Chat bubbles" value={tools.bubbleLabel || ''} onClick={tools.onBubbles} />}
        <IgRow icon={<AtSign />} label="Nicknames" onClick={() => setShowNicknames(true)} />

        {onSetMute && (
          <>
            <IgHeading>Notifications</IgHeading>
            <IgRow icon={isMuted ? <BellOff /> : <Bell />} label="Mute notifications" value={muteLabel} onClick={() => setShowMuteOptions(true)} />
          </>
        )}

        <IgHeading>Privacy and manage</IgHeading>
        <IgRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />
        {showDisappear && <DisappearSheet value={disappearSecs} subject="this chat" onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}
        <IgRow icon={<Pin_ color="currentColor" />} label="Pin chat" onClick={onTogglePin} right={<IgToggle on={!!isPinned} />} />
        <IgRow icon={<Archive />} label="Archive chat" onClick={onToggleArchive} />
        <IgRow icon={<Lock />} label="Lock this chat" onClick={() => { if (isLocked) onDisableLock(); else if (chatLockAvailable) onEnableLock(); else onNeedChatLockSetup(); }} right={<IgToggle on={!!isLocked} />} />

        <IgHeading>More</IgHeading>
        {tools && tools.onClear && <IgRow icon={<Trash2 />} label="Clear chat" bold onClick={tools.onClear} />}
        {tools && tools.onToggleBlock && <IgRow icon={<Ban />} label={tools.blocked ? `Unblock ${otherName}` : `Block ${otherName}`} bold onClick={tools.onToggleBlock} />}
        {!(tools && tools.isBot) && <IgRow icon={<Flag />} label={`Report ${otherName}`} bold onClick={() => setShowReportUser(true)} />}
        {!(tools && tools.isBot) && <IgRow icon={<Trash2 />} label={`Delete chat with ${otherName}`} bold onClick={onDeleteChat} />}
      </div>
      {showMuteOptions && onSetMute && (
        <div onClick={() => setShowMuteOptions(false)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ fontWeight: 900, fontSize: 16, color: theme.ink, marginBottom: 12 }}>Mute notifications</div>
            {[['Off', null], ['8 hours', 8 * 3600000], ['1 week', 7 * 86400000], ['Always', 'forever']].map(([label, ms]) => (
              <div key={label} role="button" onClick={() => { onSetMute(ms === 'forever' ? new Date('2999-01-01').toISOString() : ms ? new Date(Date.now() + ms).toISOString() : null); setShowMuteOptions(false); }}
                style={{ padding: '13px 6px', fontSize: 15, fontWeight: 700, color: theme.ink, cursor: 'pointer', borderBottom: `1px solid ${theme.border}` }}>{label}</div>
            ))}
          </div>
        </div>
      )}
      {showWallpaper && (
        <WallpaperPicker value={wallpaper} onSelect={onSetWallpaper} onClose={() => setShowWallpaper(false)} title={conv.otherProfile.name} avatar={conv.otherProfile.avatar} />
      )}
      {showNameBar && (
        <NameBarPicker value={nameBar} onSelect={onSetNameBar} onClose={() => setShowNameBar(false)} title={conv.otherProfile.name} avatar={conv.otherProfile.avatar} />
      )}
      {showNicknames && (
        <NicknamesModal 
          conv={conv} myAvatar={meAvatar} myName={meName}
          currentNickname={nickname} currentAlias={myAlias}
          onSaveNickname={saveNickname} onSaveAlias={saveMyAlias}
          onClose={() => setShowNicknames(false)}
        />
      )}
      {showReportUser && (
        <ReportReasonPicker
          onCancel={() => setShowReportUser(false)}
          onSubmit={(reason) => { onReportUser(reason); setShowReportUser(false); }}
        />
      )}
      {noteOpen && (
        <ContactNoteSheet name={otherName} value={note} onClose={() => setNoteOpen(false)} onSave={(t) => { saveContactNote(conv.otherProfile.id, t); setNote(contactNoteFor(conv.otherProfile.id)); }} />
      )}
      {listModal && (
        <FollowListModal userId={conv.otherProfile.id} viewerId={myId} mode={listModal} onClose={() => setListModal(null)}
          onOpenProfile={(pf) => { setListModal(null); onOpenProfile(pf); }} />
      )}
    </div>
    </>
  );
}

function Pin_({ size = 16, color = ACCENT.coral }) {
  return <Pin size={size} color={color} strokeWidth={2} fill={color} fillOpacity={0.18} />;
}


function GroupAvatar({ avatar, name, size = 44 }) {
  const { theme } = useTheme();
  if (avatar) {
    return <img src={avatar} alt="" onContextMenu={(e) => e.preventDefault()} draggable={false} style={{ width: size, height: size, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} />;
  }
  return (
    <div style={{
      width: size, height: size, borderRadius: '50%', background: theme.coral, flexShrink: 0,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      <Users size={Math.round(size * 0.5)} color="white" />
    </div>
  );
}

function CreateGroupPanel({ myId, onClose, onCreated }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [step, setStep] = useState('members');
  useBackClose(step === 'details', () => setStep('members'));
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const [name, setName] = useState('');
  const [bio, setBio] = useState('');
  const [accent, setAccent] = useState(() => GROUP_ACCENTS[Math.floor(Math.random() * GROUP_ACCENTS.length)]);
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreview, setAvatarPreview] = useState(null);
  const [cropFile, setCropFile] = useState(null);
  const [creating, setCreating] = useState(false);
  const [showColour, setShowColour] = useState(false);
  useBackClose(showColour, () => setShowColour(false));
  const [err, setErr] = useState('');
  const timer = useRef(null);

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      setResults(sanitizeAvatarList(data, myId).filter((u) => u.id !== myId));
    }, 300);
  };

  const toggleSelect = (p) => {
    setSelected((prev) => (prev.find((s) => s.id === p.id) ? prev.filter((s) => s.id !== p.id) : [...prev, p]));
  };

  const create = async () => {
    if (!name.trim() || creating) return;
    setCreating(true);
    setErr('');
    let avatarUrl = null;
    if (avatarFile) {
      const { url } = await uploadMedia(avatarFile, myId);
      avatarUrl = url || null;
    }
    const { data: group, error } = await supabase.from('groups').insert({ name: name.trim().slice(0, 50), bio: bio.trim() || null, avatar: avatarUrl, created_by: myId }).select().single();
    if (error || !group) { setCreating(false); setErr(friendlyError(error, "Couldn't create the group. Try again.")); return; }
    const { error: memberErr } = await supabase.from('group_members').insert({ group_id: group.id, user_id: myId, role: 'admin', added_by: myId });
    if (memberErr) { setCreating(false); setErr(friendlyError(memberErr, "Couldn't create the group. Try again.")); return; }
    if (selected.length) {
      const { error: inviteErr } = await supabase.from('group_members').insert(selected.slice(0, 49).map((p) => ({ group_id: group.id, user_id: p.id, role: 'member', added_by: myId })));
      if (inviteErr) { setCreating(false); setErr(friendlyError(inviteErr, "Couldn't add those people. Try again.")); return; }
      const { data: creator } = await getProfile(myId);
      selected.slice(0, 49).forEach((p) => sendPushNotification(p.id, 'ZChat', `${creator?.name || 'Someone'} added you to ${group.name}`, `/?group=${group.id}`, creator?.avatar));
    }
    await supabase.from('messages').insert({
      sender_id: myId, group_id: group.id, type: 'system',
      content: selected.length ? `Group created and ${selected.map((p) => p.name).join(', ')} added` : 'Group created',
    });
    let savedAccent = null;
    try {
      const { error: accentErr } = await supabase.from('groups').update({ accent }).eq('id', group.id);
      if (!accentErr) savedAccent = accent;
    } catch {}
    setCreating(false);
    onCreated(savedAccent ? { ...group, accent: savedAccent } : group);
  };

  const isPicked = (id) => !!selected.find((s) => s.id === id);
  const heading = step === 'members' ? 'Choose members' : 'Make it yours';
  const canNext = selected.length > 0;

  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 40, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title={heading} subtitle={step === 'members' ? 'Step 1 of 2' : 'Step 2 of 2'} onBack={() => (step === 'details' ? setStep('members') : onClose())} />

      {step === 'members' ? (
        <>
          {selected.length > 0 && (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, padding: '4px 18px 10px', maxHeight: 112, overflowY: 'auto' }}>
              {selected.map((p) => (
                <div key={p.id} role="button" onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 10px 4px 4px', borderRadius: 18, background: `${accent}26`, border: `1px solid ${accent}66`, cursor: 'pointer' }}>
                  <Avatar emoji={p.avatar} name={p.name} size={24} />
                  <span style={{ fontSize: 12.5, fontWeight: 800, color: theme.ink, maxWidth: 110, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.name}</span>
                  <X size={13} color={theme.muted} />
                </div>
              ))}
            </div>
          )}
          <div style={{ padding: '0 18px 10px' }}>
            <div style={{ position: 'relative' }}>
              <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
              <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search username" autoCapitalize="none" style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
            </div>
          </div>
          <div style={{ overflowY: 'auto', flex: 1, padding: '0 18px' }}>
            {!q.trim() && suggested.length > 0 && <div style={{ fontSize: 11.5, fontWeight: 800, color: theme.muted, margin: '4px 2px' }}>People you follow</div>}
            {results.map((p) => (
              <div key={p.id} onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 4px', cursor: 'pointer' }}>
                <Avatar emoji={p.avatar} name={p.name} frame={p.avatar_frame} size={42} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 800, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
                  <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
                </div>
                <div style={{ width: 22, height: 22, borderRadius: '50%', border: `2px solid ${isPicked(p.id) ? accent : theme.border}`, background: isPicked(p.id) ? accent : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {isPicked(p.id) && <Check size={13} color="white" />}
                </div>
              </div>
            ))}
          </div>
          <div style={{ padding: 18, paddingBottom: 'calc(18px + env(safe-area-inset-bottom))' }}>
            <button onClick={() => setStep('details')} disabled={!canNext} style={{ ...primaryBtn(theme, !canNext), background: canNext ? accent : undefined }}>
              {canNext ? `Next with ${selected.length} ${selected.length === 1 ? 'person' : 'people'}` : 'Pick at least one person'}
            </button>
          </div>
        </>
      ) : (
        <div style={{ padding: '4px 18px 20px', paddingBottom: 'calc(20px + env(safe-area-inset-bottom))', flex: 1, overflowY: 'auto' }}>
          <div style={{ textAlign: 'center', padding: '6px 0 20px' }}>
            <div onClick={() => document.getElementById('group-avatar-input').click()} style={{ display: 'inline-block', cursor: 'pointer', position: 'relative', padding: 3, borderRadius: 36, border: `2px solid ${accent}` }}>
              {avatarPreview ? (
                <img src={avatarPreview} alt="" onContextMenu={(e) => e.preventDefault()} draggable={false} style={{ width: 96, height: 96, borderRadius: 30, objectFit: 'cover', display: 'block' }} />
              ) : (
                <GroupAvatar avatar={null} name={name || 'New group'} size={96} />
              )}
              <div style={{ position: 'absolute', bottom: -4, right: -4, width: 28, height: 28, borderRadius: '50%', background: theme.ink, color: theme.panelBg, border: `2px solid ${theme.panelBg}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Camera size={13} /></div>
            </div>
            <input id="group-avatar-input" type="file" accept="image/*" style={{ display: 'none' }}
              onChange={(e) => { const f = e.target.files?.[0]; if (f) setCropFile(f); e.target.value = ''; }} />
            <div style={{ fontWeight: 800, fontSize: (name || '').length > 26 ? 19 : 23, color: theme.ink, marginTop: 14, wordBreak: 'break-word', padding: '0 8px' }}>{name.trim() || 'Name your group'}</div>
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: 10 }}>
              {selected.slice(0, 5).map((p, i) => (
                <span key={p.id} style={{ marginLeft: i ? -8 : 0, display: 'inline-flex', borderRadius: '50%', boxShadow: `0 0 0 2px ${theme.panelBg}` }}><Avatar emoji={p.avatar} name={p.name} size={26} /></span>
              ))}
              <span style={{ marginLeft: 8, fontSize: 12, fontWeight: 700, color: theme.muted }}>You and {selected.length} {selected.length === 1 ? 'other' : 'others'}</span>
            </div>
          </div>
          <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6, fontWeight: 800 }}>Group name</div>
          <input value={name} onChange={(e) => setName(e.target.value.slice(0, 50))} placeholder="e.g. Weekend Trip" style={{ ...inputStyle(theme), marginBottom: 16 }} />
          <div style={{ fontSize: 12, color: theme.muted, marginBottom: 6, fontWeight: 800 }}>What is it about? (optional)</div>
          <input value={bio} onChange={(e) => setBio(e.target.value.slice(0, 120))} placeholder="A line about this group" style={{ ...inputStyle(theme), marginBottom: 16 }} />
          <div role="button" onClick={() => setShowColour(true)} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 4px', marginBottom: 14, cursor: 'pointer', borderTop: `1px solid ${theme.border}`, borderBottom: `1px solid ${theme.border}` }}>
            <span style={{ fontSize: 15, fontWeight: 600, color: theme.ink }}>Group colour</span>
            <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ width: 22, height: 22, borderRadius: '50%', background: accent, border: `2px solid ${theme.border}` }} />
              <ChevronRight size={18} color={theme.muted} />
            </span>
          </div>
          <button onClick={create} disabled={!name.trim() || creating} style={{ ...primaryBtn(theme, !name.trim() || creating), background: name.trim() ? accent : undefined }}>
            {creating ? <Spinner size={14} /> : 'Create group'}
          </button>
          {err && <div style={{ color: theme.danger, fontSize: 12.5, marginTop: 10, textAlign: 'center' }}>{err}</div>}
        </div>
      )}
      {showColour && <GroupColourSheet value={accent} onPick={setAccent} onClose={() => setShowColour(false)} />}
      {cropFile && (
        <PhotoCropEditor file={cropFile} isAvatar onCancel={() => setCropFile(null)} onConfirm={(blob) => {
          const file = new File([blob], 'group.jpg', { type: 'image/jpeg' });
          setAvatarFile(file);
          setAvatarPreview(URL.createObjectURL(blob));
          setCropFile(null);
        }} />
      )}
    </div>
    </>
  );
}

function GroupColourSheet({ value, onPick, onClose }) {
  const { theme } = useTheme();
  return ReactDOM.createPortal(
    <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 720, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end', fontFamily: FONT }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '20px 18px calc(22px + env(safe-area-inset-bottom))' }}>
        <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink }}>Group colour</div>
        <div style={{ fontSize: 12.5, color: theme.muted, margin: '4px 0 16px' }}>Used for the group photo ring and the tabs.</div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 14, justifyItems: 'center' }}>
          {GROUP_ACCENTS.map((col) => (
            <div key={col} role="button" aria-label={`Use colour ${col}`} onClick={() => { onPick(col); onClose(); }} style={{
              width: 52, height: 52, borderRadius: '50%', background: col, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
              border: value === col ? `3px solid ${theme.ink}` : `1px solid ${theme.border}`,
            }}>{value === col && <Check size={20} color="white" />}</div>
          ))}
        </div>
      </div>
    </div>,
    document.body
  );
}

function GroupInfoPanel({ group, members, myId, iFollowIds, privacyAllowed, myRole, isOwner, onClose, onPromote, onDemote, onMute, onUnmute, onKick, onLeave, onOpenProfile, onSaveBio, onSaveName, onSaveAvatar, onAddMembers, onTransferOwnership, onSetWallpaper, onSetHeaderStyle, onOpenSettings, messages = [], onSetAccent, disappearSecs, onSetDisappear, onOpenMedia, onJumpToMessage, tools }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const c = igPalette(theme);
  const isAdmin = myRole === 'admin';
  const accent = groupAccent(group);
  const [tab, setTab] = useState('members');
  const [q, setQ] = useState('');
  const [menuFor, setMenuFor] = useState(null);
  const [menuAnchor, setMenuAnchor] = useState(null);
  const [editingBio, setEditingBio] = useState(false);
  const [bio, setBio] = useState(group.bio || '');
  const [editingName, setEditingName] = useState(false);
  const [name, setName] = useState(group.name);
  const [cropFile, setCropFile] = useState(null);
  const [showAddMembers, setShowAddMembers] = useState(false);
  const [showWallpaper, setShowWallpaper] = useState(false);
  const [showHeaderStyle, setShowHeaderStyle] = useState(false);
  const [showDisappear, setShowDisappear] = useState(false);
  const [showColour, setShowColour] = useState(false);
  useBackClose(showColour, () => setShowColour(false));
  const soleAdmin = isAdmin && members.filter((m) => m.role === 'admin').length === 1 && members.length > 1;
  const online = members.filter(isMemberOnline);
  const dayAgo = Date.now() - 86400000;
  const todayCount = messages.filter((m) => m.type !== 'system' && !m.deleted && new Date(m.created_at).getTime() > dayAgo).length;
  const nameOf = (id) => { const f = members.find((x) => x.user_id === id); return f && f.profile ? f.profile.name : 'Someone'; };
  const term = q.trim().toLowerCase();
  const rank = (m) => (m.user_id === group.created_by ? 0 : m.role === 'admin' ? 1 : 2);
  const shown = members
    .filter((m) => m.profile && (!term || (m.profile.name || '').toLowerCase().includes(term) || (m.profile.username || '').toLowerCase().includes(term)))
    .sort((a, b) => rank(a) - rank(b) || (a.profile.name || '').localeCompare(b.profile.name || ''));
  const media = messages.filter((m) => !m.deleted && (m.type === 'image' || m.type === 'video') && m.media_url).slice().reverse().slice(0, 90);
  const links = [];
  const seenLinks = new Set();
  for (let i = messages.length - 1; i >= 0 && links.length < 40; i--) {
    const m = messages[i];
    if (m.deleted || m.type !== 'text') continue;
    for (const url of extractLinks(m.content)) {
      if (seenLinks.has(url)) continue;
      seenLinks.add(url);
      links.push({ url, from: nameOf(m.sender_id), at: m.created_at });
    }
  }
  const pinned = messages.filter((m) => !m.deleted && m.type !== 'system' && isActiveUntil(m.pinned_until)).slice().reverse();
  const domainOf = (u) => { try { return new URL(/^https?:/i.test(u) ? u : `https://${u}`).hostname.replace(/^www\./, ''); } catch { return u; } };
  const hrefOf = (u) => (u.includes('@') && !/^https?:|^www\./i.test(u) ? `mailto:${u}` : (/^https?:/i.test(u) ? u : `https://${u}`));
  const chip = (label) => (
    <span style={{ flex: 'none', fontSize: 10.5, fontWeight: 800, padding: '1px 7px', borderRadius: 8, border: `1px solid ${c.line}`, color: c.dim }}>{label}</span>
  );

  const memberRow = (m) => {
    const on = isMemberOnline(m);
    const isOwnerRow = m.user_id === group.created_by;
    return (
      <div key={m.user_id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px 16px' }}>
        <div onClick={() => onOpenProfile(m.profile)} style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, minWidth: 0, cursor: 'pointer' }}>
          <Avatar emoji={m.profile.avatar} name={m.profile.name} frame={m.profile.avatar_frame} online={on ? true : null} size={48} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: 'flex', alignItems: 'center', minWidth: 0, fontWeight: 700, fontSize: 14.5 }}>
              <NameBadge name={`${m.profile.name}${m.user_id === myId ? ' (you)' : ''}`} verified={m.profile.verified} custom={m.profile.custom_badge} size={13} />
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 3, fontSize: 12, color: c.dim, minWidth: 0 }}>
              {isOwnerRow ? chip('Owner') : m.role === 'admin' ? chip('Admin') : null}
              {m.muted && chip('Muted')}
              <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: on ? '#34d399' : c.dim, fontWeight: on ? 700 : 400 }}>{on ? 'Online now' : `@${m.profile.username}`}</span>
            </div>
          </div>
        </div>
        {isAdmin && m.user_id !== myId && !isOwnerRow && (
          <MoreVertical size={18} color={c.dim} style={{ cursor: 'pointer', flexShrink: 0 }}
            onClick={(e) => { e.stopPropagation(); setMenuAnchor(e.currentTarget); setMenuFor(menuFor === m.user_id ? null : m.user_id); }} />
        )}
      </div>
    );
  };

  const sectionTitle = (label, n) => (
    <div style={{ fontSize: 12, fontWeight: 700, color: c.dim, margin: '12px 16px 2px' }}>{label} {n}</div>
  );
  const tabs = [['members', 'Members', members.length], ['media', 'Media', media.length], ['links', 'Links', links.length], ['pinned', 'Pinned', pinned.length]];
  const empty = (text) => <div style={{ textAlign: 'center', padding: '28px 16px', fontSize: 13, color: c.dim }}>{text}</div>;
  const nameLen = (group.name || '').length;

  return (
    <>
    <WideDim onClose={onClose} z={40} />
    <div {...edgeBack} style={{ position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 40, display: 'flex', flexDirection: 'column', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <div style={{ paddingTop: 'env(safe-area-inset-top)', flexShrink: 0 }}>
        <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: 52, padding: '0 8px' }}>
          <div role="button" aria-label="Back" onClick={onClose} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><ArrowLeft size={24} strokeWidth={2} /></div>
          <div style={{ position: 'absolute', left: 0, right: 0, textAlign: 'center', fontSize: 16, fontWeight: 700, pointerEvents: 'none' }}>Group info</div>
          {onOpenSettings ? <div role="button" aria-label="Group settings" onClick={onOpenSettings} style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><SettingsIcon size={21} strokeWidth={1.8} /></div> : <span style={{ width: 44 }} />}
        </div>
      </div>
      <div style={{ overflowY: 'auto', flex: 1, minHeight: 0, WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(24px + env(safe-area-inset-bottom))' }}>
        <div style={{ textAlign: 'center', padding: '10px 16px 4px' }}>
          <div onClick={() => isAdmin && document.getElementById('group-info-avatar-input').click()} style={{ display: 'inline-block', position: 'relative', cursor: isAdmin ? 'pointer' : 'default', padding: 3, borderRadius: 36, border: `2px solid ${accent}` }}>
            <GroupAvatar avatar={group.avatar} name={group.name} size={100} />
            {isAdmin && (
              <div style={{ position: 'absolute', bottom: -4, right: -4, width: 28, height: 28, borderRadius: '50%', background: c.fg, color: c.bg, border: `2px solid ${c.bg}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Camera size={13} />
              </div>
            )}
          </div>
          {isAdmin && (
            <input id="group-info-avatar-input" type="file" accept="image/*" style={{ display: 'none' }}
              onChange={(e) => { const f = e.target.files?.[0]; if (f) setCropFile(f); e.target.value = ''; }} />
          )}
          {editingName ? (
            <div style={{ display: 'flex', gap: 6, marginTop: 14, justifyContent: 'center' }}>
              <input value={name} onChange={(e) => setName(e.target.value.slice(0, 50))} style={{ ...inputStyle(theme), fontSize: 14, width: 210 }} />
              <button onClick={() => { onSaveName(name); setEditingName(false); }} style={{ padding: '0 16px', borderRadius: 12, border: 'none', background: c.fg, color: c.bg, fontWeight: 800, fontSize: 12.5, cursor: 'pointer', fontFamily: FONT }}>Save</button>
            </div>
          ) : (
            <div onClick={() => isAdmin && setEditingName(true)} style={{
              marginTop: 14, padding: '0 6px', fontWeight: 800, fontSize: nameLen > 34 ? 18 : nameLen > 20 ? 21 : 25, lineHeight: 1.15, cursor: isAdmin ? 'pointer' : 'default',
              wordBreak: 'break-word', overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical',
            }}>{group.name}</div>
          )}
          <div style={{ fontSize: 13, color: c.dim, marginTop: 6 }}>
            {members.length} {members.length === 1 ? 'member' : 'members'}{group.created_at ? ` \u00b7 Created ${new Date(group.created_at).toLocaleDateString(undefined, { month: 'short', year: 'numeric' })}` : ''}
          </div>
          <div style={{ fontSize: 13, color: c.dim, marginTop: 3 }}>
            <span style={{ color: online.length ? '#34d399' : c.dim, fontWeight: 700 }}>{online.length} online now</span>
            {` \u00b7 ${todayCount} ${todayCount === 1 ? 'message' : 'messages'} today`}
          </div>
        </div>

        {tools && (
          <div style={{ display: 'flex', justifyContent: 'center', gap: 12, margin: '16px 0 4px', flexWrap: 'wrap' }}>
            {[
              [<Search size={21} strokeWidth={1.6} />, 'Search', tools.onSearch],
              tools.onMute ? [tools.muted ? <BellOff size={21} strokeWidth={1.6} /> : <Bell size={21} strokeWidth={1.6} />, tools.muted ? 'Muted' : 'Mute', tools.onMute] : null,
              tools.onCall ? [<Phone size={21} strokeWidth={1.6} />, tools.inCall ? 'Join' : 'Call', () => tools.onCall('voice')] : null,
              tools.onCall ? [<VideoIcon size={21} strokeWidth={1.6} />, 'Video', () => tools.onCall('video')] : null,
            ].filter(Boolean).map(([icon, label, fn]) => (
              <div key={label} role="button" aria-label={label} onClick={fn} style={{ textAlign: 'center', cursor: 'pointer', width: 58 }}>
                <div style={{ width: 52, height: 52, borderRadius: '50%', border: `1px solid ${c.line}`, background: c.field, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 6px' }}>{icon}</div>
                <div style={{ fontSize: 12, color: c.dim }}>{label}</div>
              </div>
            ))}
          </div>
        )}

        <IgHeading>About</IgHeading>
        <div style={{ padding: '0 16px 6px' }}>
          {editingBio ? (
            <div style={{ display: 'flex', gap: 6 }}>
              <input value={bio} onChange={(e) => setBio(e.target.value.slice(0, 120))} placeholder="What's this group about?" style={{ ...inputStyle(theme), fontSize: 13 }} />
              <button onClick={() => { onSaveBio(bio); setEditingBio(false); }} style={{ padding: '0 16px', borderRadius: 13, border: 'none', background: c.fg, color: c.bg, fontWeight: 800, fontSize: 12.5, cursor: 'pointer', fontFamily: FONT }}>Save</button>
            </div>
          ) : (
            <div onClick={() => isAdmin && setEditingBio(true)} style={{ fontSize: 14, lineHeight: 1.5, color: group.bio ? c.fg : c.dim, cursor: isAdmin ? 'pointer' : 'default', wordBreak: 'break-word' }}>
              {group.bio ? <RichText text={group.bio} onMention={onOpenProfile} /> : (isAdmin ? 'Add a group bio' : 'No bio yet')}
            </div>
          )}
        </div>
        <div style={{ height: 8 }} />
        {isAdmin && <IgRow icon={<UserPlus />} label="Add people" onClick={() => setShowAddMembers(true)} />}
        <IgRow icon={<ImageIcon />} label="Wallpaper" onClick={() => setShowWallpaper(true)} />
        {isAdmin && <IgRow icon={<Palette />} label="Header style" onClick={() => setShowHeaderStyle(true)} />}
        <IgRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />
        {isAdmin && <IgRow icon={<Palette />} label="Group colour" onClick={() => setShowColour(true)} right={<span style={{ width: 22, height: 22, borderRadius: '50%', background: accent, border: `2px solid ${c.line}`, flex: 'none' }} />} />}
        {onOpenSettings && <IgRow icon={<SettingsIcon />} label="Group settings" onClick={onOpenSettings} />}
        {tools && (
          <>
            <IgHeading>In this chat</IgHeading>
            <IgRow icon={<ImageIcon />} label="Media, links and voice" onClick={tools.onMedia} />
            {tools.onJumpDate && <IgRow icon={<CalendarIcon />} label="Jump to a date" onClick={tools.onJumpDate} />}
            {tools.onPinned && <IgRow icon={<Pin_ color="currentColor" />} label="Pinned messages" value={String(tools.pinnedCount)} onClick={tools.onPinned} />}
            {tools.onScheduled && <IgRow icon={<Clock />} label="Scheduled messages" value={String(tools.scheduledCount)} onClick={tools.onScheduled} />}
            <IgRow icon={<BubblesIcon />} label="Chat bubbles" value={tools.bubbleLabel || ''} onClick={tools.onBubbles} />
            <IgRow icon={<Activity />} label="Chat insights" onClick={tools.onInsights} />
            <IgRow icon={<Download />} label="Export chat" onClick={tools.onExport} />
            {tools.onClear && <IgRow icon={<Trash2 />} label="Clear chat" bold onClick={tools.onClear} />}
          </>
        )}

        <div style={{ display: 'flex', borderBottom: `1px solid ${c.line}`, marginTop: 14 }}>
          {tabs.map(([k, label, n]) => (
            <div key={k} role="button" aria-label={`Tab ${label}`} onClick={() => setTab(k)} style={{
              flex: 1, textAlign: 'center', padding: '12px 2px', fontSize: 13.5, fontWeight: 700, cursor: 'pointer',
              color: tab === k ? c.fg : c.dim, borderBottom: tab === k ? `2px solid ${accent}` : '2px solid transparent', marginBottom: -1,
            }}>{label}{n ? ` ${n}` : ''}</div>
          ))}
        </div>

        {tab === 'members' && (
          <>
            {members.length > 6 && (
              <div style={{ position: 'relative', margin: '10px 16px 4px' }}>
                <Search size={15} color={c.dim} style={{ position: 'absolute', left: 12, top: 12 }} />
                <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search members" autoCapitalize="none" style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
              </div>
            )}
            {term ? (shown.length ? shown.map(memberRow) : empty('No member matches that.')) : (
              [[0, 'Owner'], [1, 'Admins'], [2, 'Members']].map(([r, label]) => {
                const list = shown.filter((m) => rank(m) === r);
                if (!list.length) return null;
                return <div key={r}>{sectionTitle(label, list.length)}{list.map(memberRow)}</div>;
              })
            )}
          </>
        )}

        {tab === 'media' && (media.length ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 2, marginTop: 2 }}>
            {media.map((m) => (
              <div key={m.id} role="button" onClick={() => onOpenMedia && onOpenMedia(m)} style={{ position: 'relative', aspectRatio: '1 / 1', background: c.field, overflow: 'hidden', cursor: 'pointer' }}>
                {m.type === 'video'
                  ? <VideoThumb src={m.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} />
                  : <img src={m.media_url} alt="" loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
                {m.type === 'video' && <Play size={15} color="white" style={{ position: 'absolute', top: 6, right: 6, filter: 'drop-shadow(0 1px 3px rgba(0,0,0,0.6))' }} />}
              </div>
            ))}
          </div>
        ) : empty('Photos and videos shared in this group show up here.'))}

        {tab === 'links' && (links.length ? links.map((l) => (
          <a key={l.url} href={hrefOf(l.url)} target="_blank" rel="noopener noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '11px 16px', textDecoration: 'none', color: 'inherit' }}>
            <LinkIcon size={22} strokeWidth={1.6} style={{ flex: 'none' }} />
            <div style={{ minWidth: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 14, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{domainOf(l.url)}</div>
              <div style={{ fontSize: 12, color: c.dim, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>Shared by {l.from} {timeAgoLong(l.at)}</div>
            </div>
          </a>
        )) : empty('Links shared in this group show up here.'))}

        {tab === 'pinned' && (pinned.length ? pinned.map((m) => (
          <div key={m.id} role="button" onClick={() => onJumpToMessage && onJumpToMessage(m.id)} style={{ padding: '11px 16px', cursor: 'pointer', borderBottom: `1px solid ${c.line}` }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: c.dim, marginBottom: 3 }}>{nameOf(m.sender_id)}</div>
            <div style={{ fontSize: 14, lineHeight: 1.4, wordBreak: 'break-word' }}>{String(describeMessage(m).text || '').slice(0, 200)}</div>
          </div>
        )) : empty('Pinned messages show up here.'))}

        <div style={{ marginTop: 18, opacity: (soleAdmin || isOwner) ? 0.55 : 1 }}>
          <IgRow icon={<LogOut />} bold onClick={() => { if (!soleAdmin && !isOwner) onLeave(); }}
            label={isOwner ? 'Transfer ownership before leaving' : soleAdmin ? 'Leave group (assign a new admin first)' : 'Leave group'} />
        </div>
      </div>

      <SmartMenu anchorEl={menuAnchor} open={!!menuFor} onClose={() => setMenuFor(null)} width={200}>
        {(() => {
          const mm = members.find((x) => x.user_id === menuFor);
          if (!mm || mm.user_id === group.created_by) return null;
          const item = (label, onClick, color, last) => (
            <div onClick={() => { onClick(); setMenuFor(null); }} style={{ padding: '11px 14px', fontSize: 13, fontWeight: 600, color: color || theme.ink, cursor: 'pointer', borderBottom: last ? 'none' : `1px solid ${theme.border}` }}>{label}</div>
          );
          return (
            <div style={{ background: theme.panelBg, borderRadius: 14, boxShadow: '0 8px 24px rgba(0,0,0,0.2)', border: `1px solid ${theme.border}`, overflow: 'hidden' }}>
              {isOwner && (mm.role === 'admin' ? item('Remove as admin', () => onDemote(mm.user_id)) : item('Make admin', () => onPromote(mm.user_id)))}
              {isOwner && item('Transfer ownership', () => onTransferOwnership(mm.user_id), accent)}
              {mm.muted ? item('Unmute member', () => onUnmute(mm.user_id)) : item('Mute member', () => onMute(mm.user_id))}
              {item('Remove from group', () => onKick(mm.user_id), theme.danger, true)}
            </div>
          );
        })()}
      </SmartMenu>
      {cropFile && (
        <PhotoCropEditor file={cropFile} isAvatar onCancel={() => setCropFile(null)} onConfirm={(blob) => { onSaveAvatar(blob); setCropFile(null); }} />
      )}
      {showWallpaper && <WallpaperPicker value={group.wallpaper} onSelect={onSetWallpaper} onClose={() => setShowWallpaper(false)} title={group.name} avatar={group.avatar} />}
      {showHeaderStyle && <NameBarPicker value={group.name_bar} onSelect={onSetHeaderStyle} onClose={() => setShowHeaderStyle(false)} title={group.name} avatar={group.avatar} />}
      {showDisappear && <DisappearSheet value={disappearSecs} subject="this group" canEdit={isAdmin} onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}
      {showColour && <GroupColourSheet value={accent} onPick={(col) => { if (onSetAccent) onSetAccent(col); }} onClose={() => setShowColour(false)} />}
      {showAddMembers && (
        <AddMembersPanel myId={myId} iFollowIds={iFollowIds} privacyAllowed={privacyAllowed} existingIds={members.map((m) => m.user_id)}
          onClose={() => setShowAddMembers(false)}
          onAdd={(people) => { onAddMembers(people); setShowAddMembers(false); }} />
      )}
    </div>
    </>
  );
}

function GroupSettingsPanel({ group, myId, isAdmin, isOwner, isMuted, onSetMute, isPinned, onTogglePin, onClose, onLeave, onDeleteGroup, onOpenAdmins, onOpenEdit, disappearSecs, onSetDisappear }) {
  useBackClose(true, onClose);
  const [showDisappear, setShowDisappear] = useState(false);
  const { theme } = useTheme();
  const [showMuteOptions, setShowMuteOptions] = useState(false);
  useBackClose(showMuteOptions, () => setShowMuteOptions(false));
  const [addPolicy, setAddPolicy] = useState(group.add_members_policy || 'everyone');
  const [sendPolicy, setSendPolicy] = useState(group.send_policy || 'everyone');
  const [inviteCode, setInviteCode] = useState(group.invite_code || '');
  const [inviteEnabled, setInviteEnabled] = useState(group.invite_enabled !== false);
  const [copied, setCopied] = useState(false);
  const [activity, setActivity] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    (async () => {
      const since = new Date(Date.now() - 7 * 86400000).toISOString();
      const { data } = await supabase.from('messages').select('sender_id, created_at').eq('group_id', group.id).gte('created_at', since).order('created_at', { ascending: false }).limit(500);
      if (!alive) return;
      const rows = data || [];
      const counts = {};
      rows.forEach((r) => { if (r.sender_id) counts[r.sender_id] = (counts[r.sender_id] || 0) + 1; });
      const topId = Object.keys(counts).sort((a, b) => counts[b] - counts[a])[0] || null;
      let topProfile = null;
      if (topId) {
        const { data: prof } = await supabase.from('profiles').select('id, name, username').eq('id', topId).maybeSingle();
        topProfile = prof;
      }
      setActivity({
        weekCount: rows.length,
        top: topProfile ? { name: topProfile.name || topProfile.username, count: counts[topId] } : null,
        lastActivity: rows[0] ? rows[0].created_at : null,
      });
    })();
    return () => { alive = false; };
  }, [group.id]);

  const savePolicy = async (field, value, setter) => {
    setter(value);
    const { error } = await supabase.from('groups').update({ [field]: value }).eq('id', group.id);
    if (error) alert(friendlyError(error, "Couldn't save that. Try again."));
  };
  const resetInvite = async () => {
    const fresh = Math.random().toString(36).slice(2, 10);
    setInviteCode(fresh);
    await supabase.from('groups').update({ invite_code: fresh }).eq('id', group.id);
  };
  const toggleInvite = async () => {
    const next = !inviteEnabled;
    setInviteEnabled(next);
    await supabase.from('groups').update({ invite_enabled: next }).eq('id', group.id);
  };
  const copyInvite = async () => {
    const link = `${siteOrigin()}/?join=${inviteCode}`;
    try { if (navigator.share) await navigator.share({ title: `Join ${group.name} on ZChat`, text: `Join the group ${group.name} on ZChat`, url: link }); else { await navigator.clipboard.writeText(link); setCopied(true); setTimeout(() => setCopied(false), 1800); } } catch {}
  };
  const doDelete = async () => {
    if (busy) return;
    setBusy(true);
    await onDeleteGroup();
  };

  const sectionLabel = { fontSize: 11, fontWeight: 900, color: theme.muted, letterSpacing: '0.1em', margin: '16px 4px 6px' };
  const card = { borderRadius: 18, background: theme.rowBg, border: `1px solid ${theme.border}`, overflow: 'hidden' };
  const muteLabel = isMuted === true ? 'Muted' : isMuted ? `Muted until ${new Date(isMuted).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}` : 'Off';

  const c = igPalette(theme);
  const segRow = (label, value, onPick) => (
    <div style={{ padding: '8px 16px 12px' }}>
      <div style={{ fontSize: 15, fontWeight: 500, marginBottom: 8 }}>{label}</div>
      <div style={{ display: 'flex', gap: 8 }}>
        {[['everyone', 'Everyone'], ['admins', 'Admins only']].map(([val, lab]) => (
          <div key={val} role="button" aria-label={`${label} ${lab}`} onClick={() => onPick(val)} style={{
            flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: 'pointer',
            background: value === val ? c.fg : c.field, color: value === val ? c.bg : c.fg,
          }}>{lab}</div>
        ))}
      </div>
    </div>
  );
  return (
    <>
    <WideDim onClose={onClose} z={34} />
    <div style={{ position: 'fixed', inset: 0, background: c.bg, color: c.fg, zIndex: 34, display: 'flex', flexDirection: 'column', overflow: 'hidden', fontFamily: FONT }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Group settings" onBack={onClose} />
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(28px + env(safe-area-inset-bottom))' }}>
        <IgHeading>Your settings</IgHeading>
        <IgRow icon={isMuted ? <BellOff /> : <Bell />} label="Mute notifications" value={muteLabel} onClick={() => setShowMuteOptions(true)} />
        <IgRow icon={<Pin_ color="currentColor" />} label="Pin group" onClick={onTogglePin} right={<IgToggle on={!!isPinned} />} />
        <IgRow icon={<Timer />} label="Disappearing messages" value={disappearLabel(disappearSecs)} onClick={() => setShowDisappear(true)} />
        {showDisappear && <DisappearSheet value={disappearSecs} subject="this group" canEdit={isAdmin} onPick={onSetDisappear} onClose={() => setShowDisappear(false)} />}

        {isAdmin && (
          <>
            <IgHeading>Admin controls</IgHeading>
            <IgRow icon={<Pencil />} label="Edit name, photo and description" onClick={onOpenEdit} />
            <IgRow icon={<ShieldCheck />} label="Manage members and admins" onClick={onOpenAdmins} />
            {segRow('Who can add members', addPolicy, (val) => savePolicy('add_members_policy', val, setAddPolicy))}
            {segRow('Who can send messages', sendPolicy, (val) => savePolicy('send_policy', val, setSendPolicy))}
            <IgRow icon={<LinkIcon />} label="Invite link" onClick={toggleInvite} right={<IgToggle on={inviteEnabled} />} />
            {inviteEnabled && (
              <div style={{ padding: '0 16px 12px 56px' }}>
                <div style={{ fontSize: 12.5, color: c.dim, marginBottom: 8, wordBreak: 'break-all' }}>{siteOrigin()}/?join={inviteCode}</div>
                <div style={{ display: 'flex', gap: 8 }}>
                  <div role="button" aria-label="Share invite link" onClick={copyInvite} style={{ flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: 'pointer', background: c.fg, color: c.bg }}>{copied ? 'Copied' : 'Share link'}</div>
                  <div role="button" aria-label="Reset invite link" onClick={resetInvite} style={{ flex: 1, textAlign: 'center', padding: '9px 6px', borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: 'pointer', background: c.field, color: c.fg }}>Reset link</div>
                </div>
              </div>
            )}
          </>
        )}

        <IgHeading>Activity</IgHeading>
        {activity === null ? (
          <div style={{ padding: 20, textAlign: 'center' }}><Spinner size={18} color={c.dim} /></div>
        ) : (
          <>
            {activity.top && <IgRow icon={<Users />} label="Most active this week" sub={`${activity.top.name} \u00b7 ${activity.top.count} messages`} />}
            <IgRow icon={<Clock />} label="Last activity" sub={activity.lastActivity ? timeAgoLong(activity.lastActivity) : 'No messages this week'} />
          </>
        )}

        <IgHeading>More</IgHeading>
        <IgRow icon={<LogOut />} label="Leave group" bold onClick={onLeave} />
        {isOwner && <IgRow icon={<Trash2 />} label="Delete group" bold onClick={() => setConfirmDelete(true)} />}
      </div>

      {showMuteOptions && (
        <div onClick={() => setShowMuteOptions(false)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ fontWeight: 900, fontSize: 16, color: theme.ink, marginBottom: 12 }}>Mute notifications</div>
            {[['Off', null], ['8 hours', 8 * 3600000], ['1 week', 7 * 86400000], ['Always', 'forever']].map(([label, ms]) => (
              <div key={label} role="button" onClick={() => { onSetMute(ms === 'forever' ? new Date('2999-01-01').toISOString() : ms ? new Date(Date.now() + ms).toISOString() : null); setShowMuteOptions(false); }}
                style={{ padding: '13px 6px', fontSize: 15, fontWeight: 700, color: theme.ink, cursor: 'pointer', borderBottom: `1px solid ${theme.border}` }}>{label}</div>
            ))}
          </div>
        </div>
      )}

      {confirmDelete && (
        <ConfirmDialog
          title={`Delete ${group.name}?`}
          body="This removes the group and its messages for everyone. This can't be undone."
          confirmLabel="Delete group"
          danger
          onCancel={() => setConfirmDelete(false)}
          onConfirm={doDelete}
        />
      )}
    </div>
    </>
  );
}

function GroupMembersPanel({ group, members, myId, isAdmin, isOwner, onClose, onOpenProfile, onAddMembers, onPromote, onDemote, onKick, onMute, onUnmute, onTransferOwnership }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [tab, setTab] = useState('all');
  const [sheetFor, setSheetFor] = useState(null);
  useBackClose(!!sheetFor, () => setSheetFor(null));

  const isOnline = (m) => m.profile && !m.profile.hide_activity && m.profile.last_seen && Date.now() - new Date(m.profile.last_seen).getTime() < 3 * 60 * 1000;
  const onlineCount = members.filter(isOnline).length;
  const adminCount = members.filter((m) => m.role === 'admin' || m.user_id === group.created_by).length;

  const filtered = members
    .filter((m) => (tab === 'online' ? isOnline(m) : tab === 'admins' ? (m.role === 'admin' || m.user_id === group.created_by) : true))
    .filter((m) => !q.trim() || (m.profile.name || '').toLowerCase().includes(q.trim().toLowerCase()) || (m.profile.username || '').toLowerCase().includes(q.trim().toLowerCase()))
    .sort((a, b) => {
      const rank = (m) => (m.user_id === group.created_by ? 0 : m.role === 'admin' ? 1 : 2);
      return rank(a) - rank(b) || (a.profile.name || '').localeCompare(b.profile.name || '');
    });

  const sheetMember = sheetFor ? members.find((m) => m.user_id === sheetFor) : null;

  return (
    <>
    <WideDim onClose={onClose} z={35} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 35, display: 'flex', flexDirection: 'column', overflow: 'hidden' }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Members" onBack={onClose} right={isAdmin ? <div role="button" aria-label="Add members" onClick={onAddMembers} style={{ fontSize: 14, fontWeight: 800, color: theme.coral, cursor: 'pointer', padding: '0 10px', height: 44, display: 'flex', alignItems: 'center' }}>Add</div> : null} />
      <div style={{ padding: '12px 18px 0', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, height: 40, borderRadius: 13, background: theme.rowBg, border: `1px solid ${theme.border}`, padding: '0 12px' }}>
          <Search size={15} color={theme.muted} />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search members" style={{ flex: 1, border: 'none', outline: 'none', background: 'transparent', color: theme.ink, fontSize: 14, fontFamily: FONT }} />
        </div>
        <div style={{ display: 'flex', gap: 6, marginTop: 10, overflowX: 'auto', scrollbarWidth: 'none' }}>
          {[['all', `All ${members.length}`], ['online', `Online ${onlineCount}`], ['admins', `Admins ${adminCount}`]].map(([k, label]) => {
            const on = tab === k;
            return (
              <div key={k} role="button" onClick={() => setTab(k)} style={{ flexShrink: 0, padding: '8px 14px', borderRadius: 12, fontSize: 12.5, fontWeight: 800, cursor: 'pointer', background: on ? theme.coral : theme.rowBg, color: on ? 'white' : theme.ink, border: `1px solid ${on ? theme.coral : theme.border}` }}>{label}</div>
            );
          })}
        </div>
      </div>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', padding: '10px 18px', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 30, color: theme.muted, fontSize: 13.5 }}>No members match.</div>
        ) : filtered.map((m) => (
          <div key={m.user_id} role="button" onClick={() => (isAdmin && m.user_id !== myId && m.user_id !== group.created_by ? setSheetFor(m.user_id) : onOpenProfile(m.profile))}
            style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 4px', cursor: 'pointer' }}>
            <Avatar emoji={m.profile.avatar} name={m.profile.name} frame={m.profile.avatar_frame} size={42} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, display: 'flex', alignItems: 'center', gap: 6 }}>
                <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{m.profile.name}</span><VerifiedBadge tier={m.profile.verified} custom={m.profile.custom_badge} size={12} />
              </div>
              <div style={{ fontSize: 11.5, color: theme.muted, display: 'flex', gap: 6, alignItems: 'center' }}>
                {isOnline(m) ? <span style={{ color: '#22c55e', fontWeight: 700 }}>Online</span> : (m.profile.last_seen ? timeAgoLong(m.profile.last_seen) : '')}
              </div>
            </div>
            {m.user_id === group.created_by ? (
              <span style={{ fontSize: 9.5, fontWeight: 900, padding: '2px 7px', borderRadius: 8, background: 'rgba(251,191,36,0.15)', color: '#fbbf24' }}>Owner</span>
            ) : m.role === 'admin' && <span style={{ fontSize: 9.5, fontWeight: 900, padding: '2px 7px', borderRadius: 8, background: 'rgba(96,165,250,0.15)', color: '#60a5fa' }}>Admin</span>}
          </div>
        ))}
      </div>

      {sheetMember && (
        <div onClick={() => setSheetFor(null)} style={{ position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: theme.panelBg, borderRadius: '22px 22px 0 0', padding: '18px 18px calc(18px + env(safe-area-inset-bottom))' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}>
              <Avatar emoji={sheetMember.profile.avatar} name={sheetMember.profile.name} frame={sheetMember.profile.avatar_frame} size={42} />
              <div>
                <div style={{ fontWeight: 900, fontSize: 15, color: theme.ink }}>{sheetMember.profile.name}</div>
                <div style={{ fontSize: 12, color: theme.muted }}>@{sheetMember.profile.username}</div>
              </div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              <div role="button" onClick={() => { setSheetFor(null); onOpenProfile(sheetMember.profile); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>View profile</div>
              {isOwner && (sheetMember.role === 'admin' ? (
                <div role="button" onClick={() => { onDemote(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Remove admin</div>
              ) : (
                <div role="button" onClick={() => { onPromote(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Make admin</div>
              ))}
              {sheetMember.muted ? (
                <div role="button" onClick={() => { onUnmute(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Unmute in group</div>
              ) : (
                <div role="button" onClick={() => { onMute(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: theme.rowBg, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.ink, cursor: 'pointer' }}>Mute in group</div>
              )}
              <div role="button" onClick={() => { onKick(sheetMember.user_id); setSheetFor(null); }} style={{ padding: '12px 8px', borderRadius: 13, background: `${theme.danger}1A`, textAlign: 'center', fontSize: 13, fontWeight: 700, color: theme.danger, cursor: 'pointer' }}>Remove</div>
            </div>
          </div>
        </div>
      )}
    </div>
    </>
  );
}
function AddMembersPanel({ myId, existingIds, onClose, onAdd, iFollowIds, privacyAllowed }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const timer = useRef(null);

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId)
        .filter((u) => !existingIds.includes(u.id))
        .filter((u) => privacyAllows(u, 'privacy_groups', myId, iFollowIds, privacyAllowed))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      setResults(sanitizeAvatarList(data, myId).filter((u) => u.id !== myId && !existingIds.includes(u.id) && !selected.find((s) => s.id === u.id)));
    }, 300);
  };

  const toggleSelect = (p) => {
    setSelected((prev) => (prev.find((s) => s.id === p.id) ? prev.filter((s) => s.id !== p.id) : [...prev, p]));
  };

  return (
    <>
    <WideDim onClose={onClose} z={45} />
    <div style={{ position: 'fixed', inset: 0, background: theme.bgGradient, zIndex: 45, display: 'flex', flexDirection: 'column' }} className="zchat-panel-open zchat-wide-page">
      <IgTopBar title="Add members" subtitle={selected.length ? `${selected.length} selected` : undefined} onBack={onClose} />
      <div style={{ padding: '14px 18px 8px' }}>
        <div style={{ position: 'relative' }}>
          <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
          <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search username" autoCapitalize="none"
            style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
        </div>
      </div>
      <div style={{ overflowY: 'auto', flex: 1, padding: '0 18px' }}>
        {results.map((p) => (
          <div key={p.id} onClick={() => toggleSelect(p)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '9px 4px', cursor: 'pointer' }}>
            <Avatar emoji={p.avatar} name={p.name} frame={p.avatar_frame} size={40} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
              <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
            </div>
            <div style={{
              width: 20, height: 20, borderRadius: '50%', border: `2px solid ${selected.find((s) => s.id === p.id) ? theme.coral : theme.border}`,
              background: selected.find((s) => s.id === p.id) ? theme.coral : 'transparent',
            }} />
          </div>
        ))}
      </div>
      <div style={{ padding: 18, paddingBottom: 'calc(18px + env(safe-area-inset-bottom))' }}>
        <button onClick={() => onAdd(selected)} disabled={selected.length === 0} style={primaryBtn(theme, selected.length === 0)}>
          Add {selected.length || ''}
        </button>
      </div>
    </div>
    </>
  );
}


function PrivacyField({ label, hidden, onToggle, last }) {
  const { theme } = useTheme();
  return (
    <div role="button" aria-label={label} onClick={onToggle} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 2px', borderBottom: last ? 'none' : `1px solid ${theme.border}`, cursor: 'pointer' }}>
      <span style={{ fontSize: 15, fontWeight: 600, color: theme.ink }}>{label}</span>
      <ToggleSwitch on={!hidden} onClick={(e) => { e.stopPropagation(); onToggle(); }} />
    </div>
  );
}

function AccountPrivacyPanel({ profile, onClose, onSaved }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [isPrivate, setIsPrivate] = useState(profile.is_private || false);
  const [hidePhoto, setHidePhoto] = useState(profile.hide_photo || false);
  const [hideBio, setHideBio] = useState(profile.hide_bio || false);
  const [hideGender, setHideGender] = useState(profile.hide_gender || false);
  const [hideAge, setHideAge] = useState(profile.hide_age || false);
  const [hideCountry, setHideCountry] = useState(profile.hide_country || false);
  const [saving, setSaving] = useState(false);

  const save = async () => {
    setSaving(true);
    const { data } = await updateProfile(profile.id, {
      is_private: isPrivate, hide_photo: hidePhoto, hide_bio: hideBio,
      hide_gender: hideGender, hide_age: hideAge, hide_country: hideCountry,
    });
    setSaving(false);
    if (data) { onSaved(data); onClose(); }
  };

  const dirty = isPrivate !== !!profile.is_private || hidePhoto !== !!profile.hide_photo || hideBio !== !!profile.hide_bio || hideGender !== !!profile.hide_gender || hideAge !== !!profile.hide_age || hideCountry !== !!profile.hide_country;
  return (
    <FullPage title="Privacy" onBack={onClose} zIndex={60}
      footer={<button onClick={save} disabled={saving || !dirty} className="zchat-press" style={{ ...primaryBtn(theme, saving || !dirty) }}>{saving ? <Spinner /> : 'Save changes'}</button>}>
      <div style={{ marginTop: 6 }}>
        <div role="button" aria-label="Private account" onClick={() => setIsPrivate((s) => !s)} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, padding: '13px 2px', cursor: 'pointer' }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 15, fontWeight: 700, color: theme.ink }}>Private account</div>
            <div style={{ fontSize: 12.5, color: theme.muted, marginTop: 2, lineHeight: 1.4 }}>New followers need your approval before they see your posts</div>
          </div>
          <ToggleSwitch on={isPrivate} onClick={(e) => { e.stopPropagation(); setIsPrivate((s) => !s); }} />
        </div>
      </div>
      <div style={{ padding: '22px 2px 4px', fontSize: 13, fontWeight: 600, color: theme.muted }}>Visible to others</div>
      <div>
        <PrivacyField label="Profile photo" hidden={hidePhoto} onToggle={() => setHidePhoto((s) => !s)} />
        <PrivacyField label="Bio" hidden={hideBio} onToggle={() => setHideBio((s) => !s)} />
        <PrivacyField label="Age" hidden={hideAge} onToggle={() => setHideAge((s) => !s)} />
        <PrivacyField label="Country" hidden={hideCountry} onToggle={() => setHideCountry((s) => !s)} last />
      </div>
      <div style={{ padding: '14px 2px 0', fontSize: 12.5, color: theme.muted, lineHeight: 1.6 }}>Switch something off and it disappears from your profile for everyone except you.</div>
    </FullPage>
  );
}

const PROFILE_LINK_REGEX = /^https?:\/\/[^\s/]+\/\?profile=([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;

const CHAT_HISTORY_LIMIT = 800;
const CHAT_MEDIA_LIMIT = 3000;
const PUBLIC_SITE_URL = 'https://getzchat.com';
function siteOrigin() {
  if (typeof window === 'undefined') return PUBLIC_SITE_URL;
  const host = window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1' || host.endsWith('.local')) return window.location.origin;
  return PUBLIC_SITE_URL;
}

function profileShareLink(profileId) {
  const origin = siteOrigin();
  return `${origin}/?profile=${profileId}`;
}

function parseProfileLink(text) {
  if (!text) return null;
  const match = String(text).trim().match(PROFILE_LINK_REGEX);
  return match ? match[1] : null;
}

async function copyTextToClipboard(text) {
  try {
    if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); return true; }
  } catch {}
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

const sharedProfileCache = new Map();

function ProfileLinkCard({ profileId, onOpen }) {
  const { theme } = useTheme();
  const [p, setP] = useState(() => sharedProfileCache.get(profileId));

  useEffect(() => {
    if (sharedProfileCache.has(profileId)) { setP(sharedProfileCache.get(profileId)); return undefined; }
    let cancelled = false;
    getProfile(profileId)
      .then(({ data }) => {
        const value = data && !data.is_deleted ? data : null;
        sharedProfileCache.set(profileId, value);
        if (!cancelled) setP(value);
      })
      .catch(() => { if (!cancelled) setP(null); });
    return () => { cancelled = true; };
  }, [profileId]);

  if (p === undefined) {
    return (
      <div style={{ width: 210, height: 176, borderRadius: 16, background: theme.rowBg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Spinner size={16} color={theme.muted} />
      </div>
    );
  }
  if (p === null) {
    return (
      <div style={{ width: 210, borderRadius: 16, background: theme.rowBg, padding: '18px 14px', textAlign: 'center', fontSize: 12.5, color: theme.muted }}>
        This profile is not available
      </div>
    );
  }
  const photo = p.hide_photo ? '' : p.avatar;
  const hasPhoto = typeof photo === 'string' && photo.startsWith('http');
  return (
    <div style={{ width: 210, borderRadius: 16, overflow: 'hidden', background: theme.rowBg }}>
      <div style={{ height: 110, position: 'relative', background: hasPhoto ? '#000' : colorForName(p.name) }}>
        {hasPhoto ? (
          <img src={photo} alt="" draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        ) : (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 44, fontWeight: 800, color: 'rgba(255,255,255,0.92)' }}>
            {(p.name || '?').trim().charAt(0).toUpperCase()}
          </div>
        )}
        <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '18px 10px 6px', background: 'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.7) 100%)', color: 'white' }}>
          <div style={{ fontSize: 14, fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
          <div style={{ fontSize: 11, opacity: 0.85, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
        </div>
      </div>
      <div onPointerDown={(e) => e.stopPropagation()} onClick={(e) => { e.stopPropagation(); if (onOpen) onOpen(p); }} style={{
        margin: 8, padding: '8px 0', borderRadius: 12, background: theme.coral, color: 'white', textAlign: 'center',
        fontSize: 12.5, fontWeight: 700, cursor: 'pointer',
      }}>View profile</div>
    </div>
  );
}

function ShareProfileSheet({ profile, myId, conversations, groups, onSend, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const link = profileShareLink(profile.id);
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=10&data=${encodeURIComponent(link)}`;
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [selected, setSelected] = useState([]);
  const [note, setNote] = useState('');
  const [sending, setSending] = useState(false);
  const [toast, setToast] = useState('');
  const timer = useRef(null);
  const toastTimer = useRef(null);

  const flash = (msg) => {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(''), 1800);
  };

  const userItem = (p) => ({ key: 'u-' + p.id, kind: 'user', id: p.id, name: p.name, avatar: p.avatar, sub: '@' + p.username });
  const groupItem = (g) => ({ key: 'g-' + g.id, kind: 'group', id: g.id, name: g.name, avatar: g.avatar, sub: 'Group' });

  const baseItems = [
    ...(conversations || []).filter((c) => !c.otherProfile.is_deleted).map((c) => userItem(c.otherProfile)),
    ...(groups || []).map(groupItem),
  ];

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      const people = sanitizeAvatarList(data, myId).filter((u) => u.id !== myId && !u.is_deleted).map(userItem);
      const term = val.trim().toLowerCase();
      const groupMatches = (groups || []).filter((g) => (g.name || '').toLowerCase().includes(term)).map(groupItem);
      setResults([...groupMatches, ...people]);
    }, 300);
  };

  const list = q.trim().length >= 2 ? results : baseItems;
  const isSelected = (item) => selected.some((s) => s.key === item.key);
  const toggle = (item) => setSelected((prev) => (prev.some((s) => s.key === item.key) ? prev.filter((s) => s.key !== item.key) : [...prev, item]));

  const doCopy = async () => {
    const ok = await copyTextToClipboard(link);
    flash(ok ? 'Link copied' : "Couldn't copy the link");
  };

  const doNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title: `${profile.name} on ZChat`, text: `Check out ${profile.name} (@${profile.username}) on ZChat`, url: link });
      } catch {}
      return;
    }
    doCopy();
  };

  const send = async () => {
    if (!selected.length || sending) return;
    setSending(true);
    await onSend(selected, note.trim(), link);
    setSending(false);
    flash(selected.length === 1 ? `Sent to ${selected[0].name}` : `Sent to ${selected.length} chats`);
    setSelected([]);
    setNote('');
  };

  const actionBtn = (icon, label, onClick) => (
    <div onClick={onClick} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, cursor: 'pointer', flex: 1 }}>
      <div style={{ width: 52, height: 52, borderRadius: '50%', background: theme.rowBg, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink }}>{icon}</div>
      <span style={{ fontSize: 11.5, color: theme.muted, fontWeight: 600 }}>{label}</span>
    </div>
  );

  return (
    <div onClick={onClose} style={{
      position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.55)', zIndex: 60,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} className="zchat-fade">
      <div onClick={(e) => e.stopPropagation()} style={{
        background: theme.panelBg, borderRadius: '26px 26px 0 0', width: '100%', maxWidth: 480, maxHeight: '90vh',
        overflowY: 'auto', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', position: 'relative',
      }}>
        <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 4px' }}>
          <div style={{ width: 40, height: 4, borderRadius: 2, background: theme.border }} />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '4px 18px 12px' }}>
          <div style={{ fontWeight: 800, fontSize: 17, color: theme.ink }}>Share profile</div>
          <X size={20} style={{ cursor: 'pointer', color: theme.muted }} onClick={onClose} />
        </div>

        <div style={{ margin: '0 18px', borderRadius: 24, background: theme.coral, padding: '20px 18px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <div style={{ background: 'white', borderRadius: 18, padding: 10 }}>
            <img src={qrUrl} alt="" width={170} height={170} draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ display: 'block', width: 170, height: 170 }} />
          </div>
          <div style={{ color: 'white', fontWeight: 800, fontSize: 18, marginTop: 12 }}>@{profile.username}</div>
          <div style={{ color: 'rgba(255,255,255,0.85)', fontSize: 12.5, marginTop: 2 }}>{profile.name} on ZChat</div>
        </div>

        <div style={{ display: 'flex', padding: '16px 18px 6px' }}>
          {actionBtn(<Copy size={20} />, 'Copy link', doCopy)}
          {actionBtn(<Share2 size={20} />, 'Share to', doNativeShare)}
          {actionBtn(<Download size={20} />, 'Save QR', () => silentDownload(qrUrl, `zchat-${profile.username}-qr.png`))}
        </div>

        <div style={{ padding: '12px 18px 4px', fontSize: 13, fontWeight: 800, color: theme.ink }}>Send in ZChat</div>
        <div style={{ padding: '4px 18px 8px' }}>
          <div style={{ position: 'relative' }}>
            <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 12 }} />
            <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search people or groups" autoCapitalize="none"
              style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 13.5 }} />
          </div>
        </div>
        <div style={{ padding: '0 12px', paddingBottom: selected.length ? 8 : 'calc(18px + env(safe-area-inset-bottom))' }}>
          {list.length === 0 && (
            <div style={{ textAlign: 'center', padding: 18, fontSize: 13, color: theme.muted }}>
              {q.trim().length >= 2 ? 'No one found' : 'Your chats will show here'}
            </div>
          )}
          {list.map((item) => (
            <div key={item.key} onClick={() => toggle(item)} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px 6px', cursor: 'pointer', borderRadius: 12 }}>
              {item.kind === 'group' ? <GroupAvatar avatar={item.avatar} name={item.name} size={42} /> : <Avatar emoji={item.avatar} name={item.name} frame={item.avatar_frame} size={42} />}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 14, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.name}</div>
                <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.sub}</div>
              </div>
              <div style={{
                width: 22, height: 22, borderRadius: '50%', flexShrink: 0,
                border: `2px solid ${isSelected(item) ? theme.coral : theme.border}`, background: isSelected(item) ? theme.coral : 'transparent',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>{isSelected(item) && <Check size={13} color="white" />}</div>
            </div>
          ))}
        </div>

        {selected.length > 0 && (
          <div style={{
            position: 'sticky', bottom: 0, background: theme.panelBg, borderTop: `1px solid ${theme.border}`,
            padding: '10px 18px', paddingBottom: 'calc(10px + env(safe-area-inset-bottom))', display: 'flex', gap: 8, alignItems: 'center',
          }}>
            <input value={note} onChange={(e) => setNote(e.target.value.slice(0, 500))} placeholder="Write a message"
              style={{ ...inputStyle(theme), padding: '10px 14px', fontSize: 14, borderRadius: 22 }} />
            <button onClick={send} disabled={sending} style={{
              padding: '10px 18px', borderRadius: 22, border: 'none', background: theme.coral, color: 'white',
              fontWeight: 700, fontSize: 13.5, cursor: sending ? 'default' : 'pointer', fontFamily: FONT, flexShrink: 0,
            }}>{sending ? <Spinner size={13} /> : (selected.length > 1 ? `Send (${selected.length})` : 'Send')}</button>
          </div>
        )}

        {toast && (
          <div style={{
            position: 'sticky', bottom: selected.length ? 70 : 16, margin: '0 auto', width: 'fit-content',
            background: theme.ink, color: theme.panelBg, fontSize: 12.5, fontWeight: 700, padding: '8px 14px', borderRadius: 20,
          }} className="zchat-fade">{toast}</div>
        )}
      </div>
    </div>
  );
}

function PosterIconButton({ onClick, children, label }) {
  return (
    <div role="button" aria-label={label} onClick={onClick} style={{
      width: 38, height: 38, borderRadius: '50%', background: 'rgba(0,0,0,0.38)',
      backdropFilter: 'blur(8px)', WebkitBackdropFilter: 'blur(8px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'white', flexShrink: 0,
    }}>{children}</div>
  );
}

function ProfilePanel({ profile, isSelf, userId, isOnline, onClose, onReport, onSaved, onOpenSettings, onOpenProfile, onMessage, isBlocked, onBlock, onUnblock, shareConversations, shareGroups, onShareToChats, canCall, onCall, onOpenHighlight, meProfile, onOpenCollection, isZAdmin, iFollowIds, privacyAllowed, initialEdit = false, initialShare = false }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const [reportOpen, setReportOpen] = useState(false);
  const [reportSent, setReportSent] = useState(false);
  const [editing, setEditing] = useState(false);
  const [bio, setBio] = useState(profile.bio || '');
  const [age, setAge] = useState(profile.age != null ? String(profile.age) : '');
  const [country, setCountry] = useState(profile.country || '');
  const [showCountryPicker, setShowCountryPicker] = useState(false);
  const [avatar, setAvatar] = useState(profile.avatar || '');
  const [avatarUploading, setAvatarUploading] = useState(false);
  const [cropFile, setCropFile] = useState(null);
  const [saving, setSaving] = useState(false);
  const [showEmail, setShowEmail] = useState(false);
  const cachedStats = profileStatsCache.get(profile.id) || {};
  const [followState, setFollowState] = useState(cachedStats.followState || 'none');
  const [theyFollowMe, setTheyFollowMe] = useState(!!cachedStats.theyFollowMe);
  const [followerCount, setFollowerCount] = useState(cachedStats.followers ?? null);
  const [followingCount, setFollowingCount] = useState(cachedStats.following ?? null);
  const [mutualCount, setMutualCount] = useState(cachedStats.mutual ?? null);
  const [postCount, setPostCount] = useState(cachedStats.posts ?? null);
  const [ownedRewards, setOwnedRewards] = useState([]);
  const [profileTab, setProfileTab] = useState('posts');
  const [tryOnFrame, setTryOnFrame] = useState(null);
  useEffect(() => {
    let alive = true;
    let retryTimer = null;
    const load = (attempt) => {
      supabase.from('user_rewards').select('kind, reward_key, expires_at').eq('user_id', profile.id).then(({ data, error }) => {
        if (!alive) return;
        if (error) {
          if ((attempt || 0) < 4) { clearTimeout(retryTimer); retryTimer = setTimeout(() => load((attempt || 0) + 1), Math.min(1200 * ((attempt || 0) + 1), 6000)); }
          return;
        }
        setOwnedRewards(data || []);
      });
    };
    load(0);
    return () => { alive = false; clearTimeout(retryTimer); };
  }, [profile.id]);
  const profileFrameUrl = useFrameUrl(profile.avatar_frame);
  useEffect(() => {
    let cancelled = false;
    supabase.from('posts').select('*', { count: 'exact', head: true }).eq('user_id', profile.id).then(({ count, error }) => {
      if (cancelled) return;
      const value = error ? 0 : (count || 0);
      setPostCount(value);
      saveProfileStats(profile.id, { posts: value });
    });
    return () => { cancelled = true; };
  }, [profile.id]);
  const [followBusy, setFollowBusy] = useState(false);
  const [username, setUsername] = useState(profile.username || '');
  const [displayName, setDisplayName] = useState(profile.name || '');
  const [socialLinks, setSocialLinks] = useState(() => readSocialLinks(profile.social_links).map((l) => ({ url: l.url, title: l.title })));
  const [pronouns, setPronouns] = useState(profile.pronouns || '');
  const [whatsapp, setWhatsapp] = useState(profile.whatsapp || '');
  const [usernameErr, setUsernameErr] = useState('');
  const [listModal, setListModal] = useState(null);
  const [showPrivacySettings, setShowPrivacySettings] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [showMore, setShowMore] = useState(false);
  const [banAsk, setBanAsk] = useState(false);
  const [banReason, setBanReason] = useState('');
  const [banBusy, setBanBusy] = useState(false);
  const [banDone, setBanDone] = useState(null);
  useBackClose(editing, () => cancelEditing());
  useBackClose(showMore, () => setShowMore(false));
  useBackClose(banAsk, () => setBanAsk(false));
  const bioRef = useRef(null);
  const [bioMention, setBioMention] = useState(null);

  const pickBioMention = (picked) => {
    if (!bioMention) return;
    const { value, caret } = applyMention(bio, bioMention, picked.username, BIO_MAX);
    setBio(value);
    setBioMention(null);
    requestAnimationFrame(() => {
      const el = bioRef.current;
      if (!el) return;
      el.focus();
      el.setSelectionRange(caret, caret);
    });
  };

  const cooldownDaysLeft = (() => {
    if (!profile.username_changed_at) return 0;
    const days = 7 - (Date.now() - new Date(profile.username_changed_at).getTime()) / 86400000;
    return days > 0 ? Math.ceil(days) : 0;
  })();

  useEffect(() => {
    let cancelled = false;
    const loadCounts = async () => {
      const { count: followers } = await supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', profile.id).eq('status', 'accepted');
      if (!cancelled && followers != null) { setFollowerCount((prev) => (prev === followers ? prev : followers)); saveProfileStats(profile.id, { followers }); }
      const { count: following } = await supabase.from('follows').select('*', { count: 'exact', head: true }).eq('follower_id', profile.id).eq('status', 'accepted');
      if (!cancelled && following != null) { setFollowingCount((prev) => (prev === following ? prev : following)); saveProfileStats(profile.id, { following }); }
      if (isSelf) return;
      const { data } = await supabase.from('follows').select('status').eq('follower_id', userId).eq('following_id', profile.id).maybeSingle();
      const nextState = data ? data.status : 'none';
      if (!cancelled) { setFollowState((prev) => (prev === nextState ? prev : nextState)); saveProfileStats(profile.id, { followState: nextState }); }
      const { data: back } = await supabase.from('follows').select('status').eq('follower_id', profile.id).eq('following_id', userId).eq('status', 'accepted').maybeSingle();
      if (!cancelled) { setTheyFollowMe(!!back); saveProfileStats(profile.id, { theyFollowMe: !!back }); }
      const { data: myFollowing } = await supabase.from('follows').select('following_id').eq('follower_id', userId).eq('status', 'accepted');
      const ids = (myFollowing || []).map((r) => r.following_id).filter((id) => id !== profile.id).slice(0, 300);
      if (!ids.length) { if (!cancelled) { setMutualCount(0); saveProfileStats(profile.id, { mutual: 0 }); } return; }
      const { count: mutual } = await supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', profile.id).eq('status', 'accepted').in('follower_id', ids);
      if (!cancelled) { setMutualCount(mutual || 0); saveProfileStats(profile.id, { mutual: mutual || 0 }); }
    };
    loadCounts();
    const channel = supabase.channel('profile-follows-' + profile.id)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'follows' }, (payload) => {
        const row = payload.new || payload.old;
        if (row.following_id === profile.id || row.follower_id === profile.id) loadCounts();
      })
      .subscribe();
    return () => { cancelled = true; supabase.removeChannel(channel); };
  }, [profile.id, isSelf]);

  const toggleFollow = async () => {
    if (followBusy) return;
    setFollowBusy(true);
    if (followState === 'accepted' || followState === 'pending') {
      await supabase.from('follows').delete().eq('follower_id', userId).eq('following_id', profile.id);
      if (followState === 'accepted') setFollowerCount((c) => Math.max(0, (c || 0) - 1));
      setFollowState('none');
    } else {
      const status = profile.is_private ? 'pending' : 'accepted';
      await supabase.from('follows').insert({ follower_id: userId, following_id: profile.id, status });
      if (status === 'accepted') setFollowerCount((c) => (c || 0) + 1);
      setFollowState(status);
      const viewerProfile = (await getProfile(userId)).data;
      sendPushNotification(profile.id, 'ZChat', status === 'pending' ? `${viewerProfile?.name || 'Someone'} requested to follow you` : `${viewerProfile?.name || 'Someone'} started following you`, status === 'pending' ? '/?requests=1' : `/?profile=${userId}`, viewerProfile?.avatar);
    }
    setFollowBusy(false);
  };

  const startEditing = () => {
    setBio(profile.bio || '');
    setAge(profile.age != null ? String(profile.age) : '');
    setCountry(profile.country || '');
    setAvatar(profile.avatar || '');
    setUsername(profile.username || '');
    setDisplayName(profile.name || '');
    setSocialLinks(readSocialLinks(profile.social_links).map((l) => ({ url: l.url, title: l.title })));
    setPronouns(profile.pronouns || '');
    setWhatsapp(profile.whatsapp || '');
    setUsernameErr('');
    setBioMention(null);
    setEditing(true);
  };
  useEffect(() => {
    if (initialEdit && isSelf) startEditing();
    else if (initialShare) setShowShare(true);
  }, []);

  const cancelEditing = () => {
    setEditing(false);
    setUsername(profile.username || '');
    setUsernameErr('');
    setBioMention(null);
  };

  const handleAvatarChange = (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (file) setCropFile(file);
  };

  const uploadCropped = async (blob) => {
    setCropFile(null);
    setAvatarUploading(true);
    const namedFile = new File([blob], 'avatar.jpg', { type: 'image/jpeg' });
    const { url, error } = await uploadMedia(namedFile, userId);
    if (!error && url) setAvatar(url);
    setAvatarUploading(false);
  };

  const save = async () => {
    const cleanUsername = username.toLowerCase().replace(/[^a-z0-9._]/g, '');
    let parsedAge = age.trim() === '' ? null : parseInt(age, 10);
    if (parsedAge != null && Number.isFinite(parsedAge)) {
      if (parsedAge < 12) { setUsernameErr('Age must be at least 12.'); return; }
      if (parsedAge > 99) { setUsernameErr('Age must be 99 or under.'); return; }
    }
    const cleanName = displayName.replace(/\s+/g, ' ').trim().slice(0, NAME_MAX);
    if (cleanName.length < 1) { setUsernameErr('Add your name.'); return; }
    const fields = { name: cleanName, bio: bio.slice(0, BIO_MAX), avatar, age: Number.isFinite(parsedAge) ? parsedAge : null, country: country.trim() || null };
    if (cleanUsername !== profile.username) {
      if (cooldownDaysLeft > 0) { setUsernameErr(`You can change your username again in ${cooldownDaysLeft} day${cooldownDaysLeft === 1 ? '' : 's'}.`); return; }
      const problem = usernameProblem(cleanUsername);
      if (problem) { setUsernameErr(`${problem}.`); return; }
      fields.username = cleanUsername;
      fields.username_changed_at = new Date().toISOString();
    }
    setUsernameErr('');
    setSaving(true);
    const cleanLinks = readSocialLinks(socialLinks).map((l) => ({ url: l.url, title: l.title || null }));
    const phone = cleanWhatsappNumber(whatsapp);
    let { data, error } = await updateProfile(profile.id, { ...fields, social_links: cleanLinks, whatsapp: phone || null, pronouns: pronouns.trim().slice(0, 40) || null });
    if (error && /pronouns/i.test(error.message || '')) {
      alert('Pronouns could not be saved yet. Ask the ZChat team to run the pronouns update.');
      ({ data, error } = await updateProfile(profile.id, { ...fields, social_links: cleanLinks, whatsapp: phone || null }));
    }
    if (error && /social_links|whatsapp|column/i.test(error.message || '')) {
      ({ data, error } = await updateProfile(profile.id, fields));
    }
    setSaving(false);
    if (error) {
      const msg = (error.message || '').toLowerCase();
      setUsernameErr(msg.includes('duplicate') || msg.includes('unique') ? 'That username is already taken.' : friendlyError(error, "Couldn't save your profile. Try again."));
      return;
    }
    if (data) { notifyBioMentions(data, profile.bio, data.bio); onSaved(data); setEditing(false); }
  };

  if (profile.is_deleted && !isSelf) {
    return (
      <div style={{
        position: 'absolute', inset: 0, background: 'rgba(20,16,14,0.5)',
        display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50, padding: 18,
      }} className="zchat-fade">
        <div style={{
          background: theme.panelBg, borderRadius: 28, padding: 30, textAlign: 'center', position: 'relative',
          width: '100%', maxWidth: 320, boxShadow: '0 30px 80px rgba(0,0,0,0.3)',
        }}>
          <div onClick={onClose} style={{
            position: 'absolute', top: 16, right: 16, width: 30, height: 30, borderRadius: '50%',
            background: theme.rowBg, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
          }}><X size={16} color={theme.ink} /></div>
          <div style={{
            width: 64, height: 64, borderRadius: '50%', margin: '10px auto 14px', background: theme.rowBg,
            display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.muted,
          }}><User size={28} /></div>
          <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, marginBottom: 6 }}>User not found</div>
          <div style={{ fontSize: 12.5, color: theme.muted }}>This account no longer exists.</div>
        </div>
      </div>
    );
  }

  const allowsProfile = privacyAllows(profile, 'privacy_profile', userId, iFollowIds, privacyAllowed);
  const allowsBio = privacyAllows(profile, 'privacy_bio', userId, iFollowIds, privacyAllowed);
  const allowsLastSeen = privacyAllows(profile, 'privacy_lastseen', userId, iFollowIds, privacyAllowed);
  const canSeeDetails = isSelf || ((!profile.is_private || followState === 'accepted') && allowsProfile);
  const shownPhoto = editing ? avatar : ((isSelf || !profile.hide_photo) ? profile.avatar : '');
  const hasPhoto = typeof shownPhoto === 'string' && shownPhoto.startsWith('http');
  const initial = (profile.name || '?').trim().charAt(0).toUpperCase() || '?';
  const lastSeenText = !isSelf && !isOnline && !profile.hide_activity && allowsLastSeen ? formatLastSeen(profile.last_seen) : null;
  const statusText = isOnline ? 'Online now' : lastSeenText;
  const countryName = profile.country ? (COUNTRIES.find(([c]) => c === profile.country)?.[1] || profile.country) : null;
  const infoBits = canSeeDetails ? [
    countryName && (isSelf || !profile.hide_country) ? `${countryFlag(profile.country)} ${countryName}` : null,
    profile.age != null && (isSelf || !profile.hide_age) ? `${profile.age}` : null,
  ].filter(Boolean) : [];
  const showBio = canSeeDetails && allowsBio && profile.bio && (isSelf || !profile.hide_bio);
  const labelStyle = { fontSize: 13, color: theme.muted, marginBottom: 6, fontWeight: 700 };
  const pillBtn = (primary) => ({
    flex: 1, height: 46, padding: '0 10px', borderRadius: 16, cursor: 'pointer', fontFamily: FONT, fontSize: 13.5, fontWeight: 700, boxSizing: 'border-box', whiteSpace: 'nowrap', minWidth: 0,
    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7,
    border: primary ? 'none' : `1px solid ${theme.dark ? 'rgba(255,255,255,0.09)' : 'rgba(0,0,0,0.06)'}`,
    background: primary ? `linear-gradient(135deg, ${theme.coral}, #8b5cf6)` : (theme.dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)'),
    color: primary ? 'white' : theme.ink,
    boxShadow: primary ? `0 6px 16px ${theme.coral}40` : 'none',
  });

  const stat = (value, label, onClick) => (
    <div onClick={onClick} style={{ flex: 1, textAlign: 'center', cursor: onClick ? 'pointer' : 'default', padding: '4px 2px' }}>
      <div style={{ fontSize: 19, fontWeight: 800, color: theme.ink, letterSpacing: '-0.02em', minHeight: 24 }}>{value == null ? '' : formatCount(value)}</div>
      <div style={{ fontSize: 13, color: theme.muted, fontWeight: 500, marginTop: 1 }}>{label}</div>
    </div>
  );
  const statDivider = <div style={{ width: 1, height: 16, background: theme.border, alignSelf: 'center' }} />;
  const pageBg = theme.bgGradient;
  const glassFill = theme.dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)';
  const glassCircle = { width: 38, height: 38, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: theme.ink, background: theme.dark ? 'rgba(0,0,0,0.35)' : 'rgba(255,255,255,0.65)', border: `1px solid ${theme.dark ? 'rgba(255,255,255,0.12)' : 'rgba(0,0,0,0.06)'}`, backdropFilter: 'blur(12px)', WebkitBackdropFilter: 'blur(12px)' };
  const statTile = (value, label, onClick) => (
    <div role={onClick ? 'button' : undefined} onClick={onClick} style={{ padding: '11px 4px', borderRadius: 18, textAlign: 'center', cursor: onClick ? 'pointer' : 'default', background: glassFill, border: `1px solid ${theme.dark ? 'rgba(255,255,255,0.09)' : 'rgba(0,0,0,0.06)'}` }}>
      <div style={{ fontSize: 19, fontWeight: 800, color: theme.ink, letterSpacing: '-0.02em', minHeight: 23 }}>{value == null ? '' : formatCount(value)}</div>
      <div style={{ fontSize: 11.5, color: theme.muted, fontWeight: 600, marginTop: 1 }}>{label}</div>
    </div>
  );

  const sheetRow = (icon, label, onClick, danger) => (
    <div onClick={onClick} style={{
      display: 'flex', alignItems: 'center', gap: 12, padding: '14px 10px', cursor: 'pointer',
      fontSize: 14.5, fontWeight: 600, color: danger ? theme.danger : theme.ink,
    }}>{icon}{label}</div>
  );

  return (
    <div {...edgeBack} onClick={(e) => { if (e.target === e.currentTarget && !editing) onClose(); }} style={{ position: 'fixed', inset: 0, zIndex: 50, background: 'rgba(5,8,16,0.6)', display: 'flex', justifyContent: 'center' }} className="zchat-panel-open">
    <div style={{ width: '100%', maxWidth: 560, height: '100%', background: theme.dark ? '#000' : '#fff', display: 'flex', flexDirection: 'column', position: 'relative', overflow: 'hidden' }}>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', overflowX: 'hidden', WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain', touchAction: 'pan-y' }}>
        {editing ? (
        <div style={{ position: 'relative', height: 'min(42vh, 320px)', minHeight: 240, background: hasPhoto ? '#000' : colorForName(profile.name), overflow: 'hidden' }}>
          {hasPhoto ? (
            <img src={shownPhoto} alt="" draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
          ) : (
            <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', paddingBottom: 80, fontSize: 130, fontWeight: 800, color: 'rgba(255,255,255,0.9)', fontFamily: FONT }}>{initial}</div>
          )}
          <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', background: 'linear-gradient(180deg, rgba(0,0,0,0.38) 0%, rgba(0,0,0,0) 20%, rgba(0,0,0,0) 48%, rgba(0,0,0,0.82) 100%)' }} />

          <div style={{ position: 'absolute', top: 'calc(12px + env(safe-area-inset-top))', left: 14, right: 14, display: 'flex', justifyContent: 'space-between', zIndex: 2 }}>
            <PosterIconButton label="Close" onClick={editing ? cancelEditing : onClose}><ArrowLeft size={19} /></PosterIconButton>
            {!editing && (
              <div style={{ display: 'flex', gap: 8 }}>
                <PosterIconButton label="Share profile" onClick={() => setShowShare(true)}><Share2 size={17} /></PosterIconButton>
                {isSelf ? (
                  <PosterIconButton label="Settings" onClick={onOpenSettings}><SettingsIcon size={17} /></PosterIconButton>
                ) : (
                  <PosterIconButton label="More" onClick={() => setShowMore(true)}><MoreVertical size={18} /></PosterIconButton>
                )}
              </div>
            )}
          </div>

          <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '0 20px 18px', color: 'white', zIndex: 1 }}>
            {editing ? (
              <label style={{
                display: 'inline-flex', alignItems: 'center', gap: 8, padding: '10px 16px', borderRadius: 24, cursor: 'pointer',
                background: 'rgba(0,0,0,0.45)', backdropFilter: 'blur(8px)', WebkitBackdropFilter: 'blur(8px)', fontSize: 13.5, fontWeight: 700,
              }}>
                {avatarUploading ? <Spinner size={14} /> : <Camera size={16} />}
                Change photo
                <input type="file" accept="image/*" style={{ display: 'none' }} onChange={handleAvatarChange} />
              </label>
            ) : (
              <>
                {statusText && (
                  <div style={{
                    display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: 11.5, fontWeight: 700, marginBottom: 8,
                    background: 'rgba(0,0,0,0.35)', padding: '4px 10px', borderRadius: 20,
                  }}>
                    <span style={{ width: 7, height: 7, borderRadius: '50%', background: isOnline ? '#31D158' : '#B9BCC3' }} />
                    {statusText}
                  </div>
                )}
                <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.08, letterSpacing: '-0.02em', textShadow: '0 2px 12px rgba(0,0,0,0.45)', wordBreak: 'break-word' }}>{profile.name}<VerifiedBadge tier={profile.verified} custom={profile.custom_badge} size={24} /></div>
                <div style={{ fontSize: 13.5, marginTop: 4, color: 'rgba(255,255,255,0.88)', textShadow: '0 1px 6px rgba(0,0,0,0.5)' }}>
                  @{profile.username}{profile.pronouns ? ` · ${profile.pronouns}` : ''}{infoBits.map((b) => ` · ${b}`).join('')}
                </div>
              </>
            )}
          </div>
        </div>
        ) : (
          <div style={{ position: 'relative', paddingBottom: 4 }}>
            <div style={{ position: 'absolute', left: -60, right: -60, top: -60, height: 540, overflow: 'hidden', pointerEvents: 'none' }}>
              {hasPhoto
                ? <img src={shownPhoto} alt="" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', filter: 'blur(18px) saturate(1.25)', opacity: theme.dark ? 0.95 : 0.8, transform: 'scale(1.08)' }} />
                : <div style={{ position: 'absolute', inset: 0, background: colorForName(profile.name), filter: 'blur(50px)', opacity: theme.dark ? 0.75 : 0.5 }} />}
            </div>
            <div style={{ position: 'absolute', left: 0, right: 0, top: 0, height: 480, pointerEvents: 'none', background: `linear-gradient(180deg, ${theme.dark ? 'rgba(0,0,0,0.18)' : 'rgba(255,255,255,0.08)'} 0%, rgba(0,0,0,0) 45%, ${pageBg} 100%)` }} />

            <div style={{ position: 'relative', zIndex: 2, display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 14px', paddingTop: 'calc(12px + env(safe-area-inset-top))' }}>
              <div role="button" aria-label="Close" onClick={onClose} style={glassCircle}><ArrowLeft size={19} /></div>
              <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, display: 'flex', alignItems: 'center', minWidth: 0, maxWidth: '55%' }}>
                <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{profile.username}</span>
              </div>
              <div style={{ display: 'flex', gap: 8 }}>
                {isSelf && <div role="button" aria-label="Share profile" onClick={() => setShowShare(true)} style={glassCircle}><Share2 size={17} /></div>}
                {isSelf
                  ? <div role="button" aria-label="Settings" onClick={onOpenSettings} style={glassCircle}><SettingsIcon size={17} /></div>
                  : <div role="button" aria-label="More" onClick={() => setShowMore(true)} style={glassCircle}><MoreVertical size={18} /></div>}
              </div>
            </div>

            <div style={{ position: 'relative', zIndex: 3, display: 'flex', justifyContent: 'center', marginTop: 4 }}>
              <div style={{ position: 'relative', width: 210, height: 210 }}>
                {(() => {
                  const fspec = AVATAR_FRAMES[profile.avatar_frame];
                  const box = 210;
                  const photo = fspec ? Math.round(Math.min(176, Math.max(110, box / fspec.scale))) : 168;
                  const off = (box - photo) / 2;
                  const fw = photo * (fspec ? fspec.scale : 1);
                  return (
                    <>
                      <div style={{ position: 'absolute', left: off, top: off, width: photo, height: photo, borderRadius: '50%', overflow: 'hidden', background: hasPhoto ? '#000' : colorForName(profile.name), boxShadow: '0 6px 18px rgba(0,0,0,0.22)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        {hasPhoto
                          ? <img src={shownPhoto} alt="" draggable={false} onContextMenu={(e) => e.preventDefault()} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
                          : <span style={{ fontSize: photo * 0.46, fontWeight: 800, color: 'rgba(255,255,255,0.92)', fontFamily: FONT }}>{initial}</span>}
                      </div>
                      {fspec && profileFrameUrl && (
                        <img src={profileFrameUrl} alt="" draggable={false} aria-hidden="true" style={{ ...frameMaskStyle(fspec), position: 'absolute', width: fw, height: fw, left: box / 2 - fw * (fspec.centerX ?? 0.5), top: box / 2 - fw * fspec.centerY, pointerEvents: 'none', zIndex: 2, maxWidth: 'none', animation: (theme.dark ? fspec.animation : (fspec.animationLight || fspec.animation)) || 'none' }} />
                      )}
                      {isOnline && (
                        <div style={{ position: 'absolute', right: fspec ? 10 : off + photo * 0.06, bottom: fspec ? 10 : off + photo * 0.06, width: 22, height: 22, borderRadius: '50%', background: '#22c55e', border: `4px solid ${pageBg}`, zIndex: 3, boxShadow: '0 2px 8px rgba(0,0,0,0.35)' }} />
                      )}
                    </>
                  );
                })()}
              </div>
            </div>

            {NAMEPLATES[profile.nameplate] && (() => {
              const plateW = Math.min(360, (typeof window !== 'undefined' ? window.innerWidth : 390) - 32);
              const pullPx = Math.round(nameplatePull(profile.nameplate) * plateW / 100) + 8;
              return (
                <div style={{ position: 'relative', zIndex: 2, width: plateW, margin: `-${pullPx}px auto 0` }}>
                  <NameplateBanner plate={profile.nameplate} name={profile.name} username={profile.username} verified={profile.verified} custom={profile.custom_badge} />
                </div>
              );
            })()}
            <div style={{ position: 'relative', zIndex: 2, textAlign: 'center', marginTop: NAMEPLATES[profile.nameplate] ? 2 : 14, padding: '0 20px' }}>
              {(!NAMEPLATES[profile.nameplate] || (profile.name || '').length > 14) && (
                <div style={{ marginTop: NAMEPLATES[profile.nameplate] ? 2 : 0, fontSize: NAMEPLATES[profile.nameplate] ? 17 : ((profile.name || '').length > 26 ? 21 : 27), fontWeight: 900, color: theme.ink, letterSpacing: '-0.02em', lineHeight: 1.15, wordBreak: 'break-word' }}>{profile.name}<VerifiedBadge tier={profile.verified} custom={profile.custom_badge} size={22} /></div>
              )}
              <div style={{ fontSize: 13, color: theme.muted, marginTop: 3 }}>
                {NAMEPLATES[profile.nameplate] ? [profile.pronouns, ...infoBits].filter(Boolean).join(' · ') : `@${profile.username}${profile.pronouns ? ` · ${profile.pronouns}` : ''}${infoBits.map((b) => ` · ${b}`).join('')}`}
                {statusText ? <span style={{ color: isOnline ? '#22c55e' : theme.muted, fontWeight: isOnline ? 700 : 600 }}>{[profile.pronouns, ...infoBits].filter(Boolean).length || !NAMEPLATES[profile.nameplate] ? ' · ' : ''}{statusText}</span> : null}
              </div>
            </div>
          </div>
        )}

        <div style={{ paddingTop: editing ? 16 : 14, paddingLeft: editing ? 18 : 14, paddingRight: editing ? 18 : 14, paddingBottom: 'calc(28px + env(safe-area-inset-bottom))', maxWidth: 520, margin: '0 auto', position: 'relative', zIndex: 2 }}>
          {editing ? (
            <div>
              <div style={{ ...labelStyle, display: 'flex', justifyContent: 'space-between' }}><span>Name</span><span style={{ fontWeight: 600 }}>{displayName.length}/{NAME_MAX}</span></div>
              <input value={displayName} maxLength={NAME_MAX} onChange={(e) => setDisplayName(e.target.value.slice(0, NAME_MAX))}
                style={{ ...inputStyle(theme), marginBottom: 12 }} placeholder="Name" />
              <div style={{ ...labelStyle, display: 'flex', justifyContent: 'space-between' }}><span>Username</span><span style={{ fontWeight: 600 }}>{username.length}/{USERNAME_MAX}</span></div>
              <div style={{ position: 'relative', marginBottom: 4 }}>
                <span style={{ position: 'absolute', left: 14, top: 13, color: theme.muted, fontSize: 16 }}>@</span>
                <input value={username} maxLength={USERNAME_MAX} onChange={(e) => { setUsername(e.target.value.toLowerCase().replace(/[^a-z0-9._]/g, '').slice(0, USERNAME_MAX)); setUsernameErr(''); }}
                  style={{ ...inputStyle(theme), paddingLeft: 26 }} autoCapitalize="none" />
              </div>
              {username !== profile.username && usernameProblem(username) && <div style={{ fontSize: 11.5, color: theme.danger, marginBottom: 8 }}>{usernameProblem(username)}</div>}
              {cooldownDaysLeft > 0 && (
                <div style={{ fontSize: 11, color: theme.muted, marginBottom: 10 }}>You can change your username again in {cooldownDaysLeft} day{cooldownDaysLeft === 1 ? '' : 's'}.</div>
              )}
              {usernameErr && <div style={{ fontSize: 11.5, color: theme.danger, marginBottom: 10 }}>{usernameErr}</div>}
              <SocialLinksEditor links={socialLinks} onChange={setSocialLinks} whatsapp={whatsapp} onWhatsappChange={setWhatsapp} labelStyle={labelStyle} />
              <div style={{ ...labelStyle, marginTop: 10, display: 'flex', justifyContent: 'space-between' }}><span>Bio</span><span style={{ fontWeight: 600, color: bio.length >= BIO_MAX ? theme.danger : theme.muted }}>{bio.length}/{BIO_MAX}</span></div>
              <textarea ref={bioRef} value={bio}
                onChange={(e) => { const v = e.target.value.slice(0, BIO_MAX); setBio(v); setBioMention(getActiveMention(v, e.target.selectionStart)); }}
                onClick={(e) => setBioMention(getActiveMention(e.target.value, e.target.selectionStart))}
                placeholder="Tell people about yourself, type @ to mention someone"
                style={{ ...inputStyle(theme), height: 76, resize: 'none', fontFamily: FONT, marginBottom: bioMention ? 0 : 14 }} />
              {bioMention && (
                <div style={{ margin: '6px 0 14px' }}>
                  <MentionSuggestions query={bioMention.query} excludeIds={[profile.id]} myId={userId} onPick={pickBioMention} />
                </div>
              )}
              <div style={{ display: 'flex', gap: 10, marginBottom: 14 }}>
                <div style={{ flex: 1 }}>
                  <div style={labelStyle}>Age</div>
                  <input value={age} onChange={(e) => setAge(e.target.value.replace(/[^0-9]/g, '').slice(0, 2))}
                    onBlur={() => { if (age && parseInt(age, 10) < 12) setAge('12'); }}
                    inputMode="numeric" placeholder="Age" style={inputStyle(theme)} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={labelStyle}>Country</div>
                  <div onClick={() => setShowCountryPicker(true)} style={{ ...inputStyle(theme), cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8 }}>
                    {country ? <span style={{ fontSize: 18 }}>{countryFlag(country)}</span> : <span style={{ color: theme.muted }}>Choose</span>}
                  </div>
                </div>
              </div>
              <PronounsPicker value={pronouns} onChange={setPronouns} labelStyle={labelStyle} />
              <div style={{ height: 18 }} />
              <div style={{ display: 'flex', gap: 8 }}>
                <button onClick={cancelEditing} style={pillBtn(false)}>Cancel</button>
                <button onClick={save} disabled={saving || avatarUploading} style={pillBtn(true)}>
                  {(saving || avatarUploading) ? <Spinner size={14} /> : 'Save'}
                </button>
              </div>
            </div>
          ) : (
            <>
              {canSeeDetails && (
                <div style={{ display: 'flex', alignItems: 'center', height: 62, borderRadius: 18, marginBottom: 10, background: glassFill, border: `1px solid ${theme.dark ? 'rgba(255,255,255,0.09)' : 'rgba(0,0,0,0.06)'}` }}>
                  {[
                    !profile.is_bot && { v: postCount, l: 'Posts', on: null },
                    { v: profile.is_bot ? BOT_FOLLOWER_BASE + (followerCount || 0) : followerCount, l: 'Followers', on: profile.is_bot ? null : () => setListModal('followers') },
                    !profile.is_bot && { v: followingCount, l: 'Following', on: () => setListModal('following') },
                  ].filter(Boolean).map((c, i) => (
                    <React.Fragment key={c.l}>
                      {i > 0 && <div style={{ width: 1, height: 28, background: theme.border }} />}
                      <div role={c.on ? 'button' : undefined} onClick={c.on || undefined} style={{ flex: 1, textAlign: 'center', cursor: c.on ? 'pointer' : 'default' }}>
                        <div style={{ fontSize: 20, fontWeight: 900, color: theme.ink, letterSpacing: '-0.02em', minHeight: 24 }}>{c.v == null ? '' : formatCount(c.v)}</div>
                        <div style={{ fontSize: 11.5, color: theme.muted, fontWeight: 600 }}>{c.l}</div>
                      </div>
                    </React.Fragment>
                  ))}
                </div>
              )}
              {isSelf ? (
                <>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button onClick={startEditing} style={pillBtn(true)}><Edit3 size={15} /> Edit profile</button>
                  <button onClick={() => setShowShare(true)} style={pillBtn(false)}><Share2 size={15} /> Share</button>
                  <button onClick={() => setShowPrivacySettings(true)} aria-label="Privacy" style={{ ...pillBtn(false), flex: '0 0 46px', padding: 0 }}><Lock size={16} /></button>
                </div>
                </>
              ) : (
                <div style={{ display: 'flex', gap: 8 }}>
                  {!profile.is_bot && (
                    <div style={{ flex: 1, display: 'flex' }}>
                      <FollowActionButton state={followState} theyFollowMe={theyFollowMe} busy={followBusy} onClick={toggleFollow} />
                    </div>
                  )}
                  {(followState === 'accepted' || profile.is_bot) ? (
                    <button onClick={() => onMessage(profile)} style={pillBtn(false)}><ChatBubbleIcon size={17} /> Message</button>
                  ) : (
                    <button onClick={() => setShowShare(true)} style={pillBtn(false)}><Share2 size={15} /> Share</button>
                  )}
                  {canCall && followState === 'accepted' && (
                    <>
                      <button onClick={() => onCall('voice')} aria-label="Voice call" style={{ ...pillBtn(false), flex: '0 0 44px', padding: 0 }}><Phone size={17} /></button>
                      <button onClick={() => onCall('video')} aria-label="Video call" style={{ ...pillBtn(false), flex: '0 0 44px', padding: 0 }}><VideoIcon size={18} /></button>
                    </>
                  )}
                </div>
              )}

              {reportSent && (
                <div style={{ marginTop: 12, fontSize: 12.5, color: theme.teal, fontWeight: 700, textAlign: 'center' }} className="zchat-fade">
                  Report sent. Thanks for flagging this.
                </div>
              )}

              {canSeeDetails ? (
                <>
                  {showBio && (
                    <div style={{ fontSize: 14.5, color: theme.ink, lineHeight: 1.55, marginTop: 16, wordBreak: 'break-word', textAlign: 'center', padding: '0 10px' }}>
                      <RichText text={profile.bio} onMention={(p) => onOpenProfile(sanitizeAvatar(p, userId))} />
                    </div>
                  )}
                  {profile.is_bot && (
                    <div style={{ marginTop: 16, padding: '14px 14px 12px', borderRadius: 20, background: theme.rowBg, border: `1px solid ${theme.border}` }}>
                      <div style={{ fontSize: 13, fontWeight: 900, color: theme.ink, marginBottom: 10, display: 'flex', alignItems: 'center', gap: 7 }}><Sparkles size={15} color={theme.coral} /> What I can do</div>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7 }}>
                        {['Answer anything', 'Write and fix code', 'Translate', 'Look at photos and videos', 'Understand voice messages', 'Remember our chat', 'Help in groups with @zchatbot'].map((t) => (
                          <span key={t} style={{ fontSize: 12.5, fontWeight: 700, color: theme.ink, padding: '6px 11px', borderRadius: 14, background: `${theme.coral}1A`, border: `1px solid ${theme.coral}33` }}>{t}</span>
                        ))}
                      </div>
                    </div>
                  )}
                  {!isSelf && !profile.is_bot && mutualCount > 0 && (
                    <div role="button" onClick={() => setListModal('mutual')} style={{ textAlign: 'center', fontSize: 12.5, color: theme.muted, marginTop: 12, cursor: 'pointer' }}>
                      Followed by <b style={{ color: theme.ink }}>{formatCount(mutualCount)}</b> {mutualCount === 1 ? 'person' : 'people'} you follow
                    </div>
                  )}
                  {!editing && !profile.is_bot && (
                    <>
                      <div style={{ display: 'flex', gap: 6, marginTop: 14, padding: 4, borderRadius: 16, background: glassFill }}>
                        {[['posts', 'Posts'], ['highlights', 'Highlights'], ['collection', 'Collection'], ['links', 'Links']].map(([k, label]) => (
                          <div key={k} role="button" onClick={() => setProfileTab(k)} style={{ flex: 1, textAlign: 'center', padding: '9px 0', borderRadius: 12, fontSize: 13, fontWeight: 800, cursor: 'pointer', color: profileTab === k ? '#fff' : theme.muted, background: profileTab === k ? theme.coral : 'transparent', transition: 'background 0.18s ease, color 0.18s ease' }}>{label}</div>
                        ))}
                      </div>
                      {profileTab === 'posts' && <ProfilePosts profile={profile} isSelf={isSelf} userId={userId} meProfile={meProfile} />}
                      {profileTab === 'highlights' && <ProfileHighlights profile={profile} isSelf={isSelf} userId={userId} onOpenHighlight={(h) => onOpenHighlight && onOpenHighlight(h, profile)} />}
                      {profileTab === 'collection' && <ProfileCollectionShowcase profile={profile} rewards={ownedRewards} isSelf={isSelf} onPreview={(k) => setTryOnFrame(k)} onOpenCollection={onOpenCollection} />}
                      {profileTab === 'links' && <ProfileSocialRow links={profile.social_links} whatsapp={profile.whatsapp} />}
                    </>
                  )}
                </>
              ) : (
                <div style={{ marginTop: 20, padding: '22px 16px', textAlign: 'center', borderRadius: 20, background: theme.rowBg }}>
                  <div style={{
                    width: 46, height: 46, borderRadius: '50%', margin: '0 auto 10px', border: `1.5px solid ${theme.border}`,
                    display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.muted,
                  }}><Lock size={20} /></div>
                  <div style={{ fontWeight: 800, fontSize: 14.5, color: theme.ink, marginBottom: 4 }}>This account is private</div>
                  <div style={{ fontSize: 12.5, color: theme.muted, lineHeight: 1.5 }}>
                    Follow {profile.name} to see their bio, followers, and more.
                  </div>
                </div>
              )}

              {isSelf && (
                <div style={{ marginTop: 18, textAlign: 'center' }}>
                  {!showEmail ? (
                    <span onClick={() => setShowEmail(true)} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, color: theme.coralDeep, fontSize: 12.5, fontWeight: 700, cursor: 'pointer' }}>
                      <Mail size={13} /> Show your email
                    </span>
                  ) : (
                    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', justifyContent: 'center' }}>
                      <span style={{ fontSize: 12.5, fontWeight: 700, color: theme.ink }}>{profile.email}</span>
                      <span onClick={() => setShowEmail(false)} style={{ color: theme.coralDeep, fontWeight: 800, fontSize: 11, cursor: 'pointer' }}>Hide</span>
                    </span>
                  )}
                </div>
              )}
            </>
          )}
        </div>
      </div>

      {showMore && (
        <div onClick={() => setShowMore(false)} style={{
          position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.5)', zIndex: 58,
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
        }} className="zchat-fade">
          <div onClick={(e) => e.stopPropagation()} style={{
            background: theme.panelBg, borderRadius: '24px 24px 0 0', width: '100%', maxWidth: 480, padding: '10px 10px',
            paddingBottom: 'calc(10px + env(safe-area-inset-bottom))',
          }}>
            {sheetRow(<Share2 size={18} />, 'Share profile', () => { setShowMore(false); setShowShare(true); })}
            {sheetRow(<Copy size={18} />, 'Copy profile link', async () => { await copyTextToClipboard(profileShareLink(profile.id)); setShowMore(false); })}
            {!reportSent && !profile.is_bot && sheetRow(<Flag size={18} color={theme.danger} />, 'Report account', () => { setShowMore(false); setReportOpen(true); }, true)}
            {!profile.is_bot && sheetRow(<Ban size={18} color={theme.danger} />, isBlocked ? 'Unblock account' : 'Block account', () => { setShowMore(false); if (isBlocked) onUnblock(profile.id); else onBlock(profile.id); }, true)}
            {isZAdmin && !isSelf && (profile.banned
              ? sheetRow(<ShieldCheck size={18} color={theme.teal} />, 'Remove from ZChat ban list', async () => {
                  setShowMore(false);
                  await supabase.rpc('admin_unban', { p_user_id: profile.id });
                  onSaved({ ...profile, banned: false });
                }, false)
              : sheetRow(<ShieldOff size={18} color={theme.danger} />, 'Ban from ZChat', () => { setShowMore(false); setBanAsk(true); }, true))}
            <div onClick={() => setShowMore(false)} style={{ textAlign: 'center', padding: '12px 0 4px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
          </div>
        </div>
      )}
      {banAsk && (
        <div onClick={() => !banBusy && setBanAsk(false)} style={{ position: 'absolute', inset: 0, background: 'rgba(10,8,6,0.62)', zIndex: 60, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 22 }} className="zchat-fade">
          <div onClick={(e) => e.stopPropagation()} style={{ background: theme.panelBg, borderRadius: 22, width: '100%', maxWidth: 380, padding: 22 }}>
            {banDone ? (
              <>
                <div style={{ fontWeight: 900, fontSize: 17, color: theme.ink, marginBottom: 10 }}>Banned</div>
                <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.7, marginBottom: 18 }}>
                  @{profile.username} can no longer sign in. Their email and their phone are on the block list, so a new account from that phone will be refused.
                  {banDone.messages_removed ? ` ${banDone.messages_removed} of their messages were removed from every chat.` : ''}
                </div>
                <button style={primaryBtn(theme)} onClick={() => { setBanAsk(false); setBanDone(null); onClose(); }}>Done</button>
              </>
            ) : (
              <>
                <div style={{ fontWeight: 900, fontSize: 17, color: theme.ink, marginBottom: 8 }}>Ban @{profile.username} from ZChat?</div>
                <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.7, marginBottom: 14 }}>
                  This blocks their login, their email and the phone they signed up on, and removes every message they sent. Keep a screenshot first if you may need it later.
                </div>
                <input style={inputStyle(theme)} placeholder="Reason, for your records" value={banReason}
                  onChange={(e) => setBanReason(e.target.value)} />
                <button style={{ ...primaryBtn(theme, banBusy), background: theme.danger, marginTop: 14 }} disabled={banBusy}
                  onClick={async () => {
                    setBanBusy(true);
                    const { data, error } = await supabase.rpc('admin_ban', { p_user_id: profile.id, p_reason: banReason });
                    setBanBusy(false);
                    if (error) { setBanReason(''); alert(error.message || 'Could not ban this account.'); return; }
                    setBanDone(data || {});
                  }}>{banBusy ? <Spinner /> : 'Ban this account'}</button>
                <div onClick={() => !banBusy && setBanAsk(false)} style={{ textAlign: 'center', padding: '14px 0 2px', fontWeight: 700, color: theme.muted, cursor: 'pointer' }}>Cancel</div>
              </>
            )}
          </div>
        </div>
      )}
      {tryOnFrame && (
        <FrameTryOnPage me={profile} frameKey={tryOnFrame} onClose={() => setTryOnFrame(null)} action={null} />
      )}
      {showShare && (
        <ShareProfileSheet profile={profile} myId={userId} conversations={shareConversations} groups={shareGroups}
          onSend={onShareToChats} onClose={() => setShowShare(false)} />
      )}
      {cropFile && <PhotoCropEditor file={cropFile} isAvatar onCancel={() => setCropFile(null)} onConfirm={uploadCropped} />}
      {listModal && (
        <FollowListModal userId={profile.id} viewerId={userId} mode={listModal} onClose={() => setListModal(null)}
          onOpenProfile={(p) => { setListModal(null); onOpenProfile(p); }} />
      )}
      {showPrivacySettings && (
        <AccountPrivacyPanel profile={profile} onClose={() => setShowPrivacySettings(false)}
          onSaved={(updated) => { onSaved(updated); setShowPrivacySettings(false); }} />
      )}
      {showCountryPicker && (
        <CountryPicker value={country} onSelect={setCountry} onClose={() => setShowCountryPicker(false)} />
      )}
      {reportOpen && !reportSent && (
        <ReportReasonPicker onCancel={() => setReportOpen(false)} onSubmit={async (reason) => { await onReport(profile, reason); setReportSent(true); setReportOpen(false); }} />
      )}
    </div>
    </div>
  );
}

function StatusTicks({ status }) {
  const { theme } = useTheme();
  if (status === 'queued') return <Clock size={13} color={theme.muted} />;
  if (status === 'sent') return <Check size={14} color={theme.muted} />;
  if (status === 'read') return <CheckCheck size={14} color={theme.coral} />;
  return <CheckCheck size={14} color={theme.muted} />;
}

const REACTION_EMOJIS = ['\u{2764}\u{FE0F}', '\u{1F602}', '\u{1F62E}', '\u{1F622}', '\u{1F44D}', '\u{1F525}'];

const LINK_REGEX = /((?:https?:\/\/|www\.)[^\s<]+[^\s<.,:;!?'")\]]|[\w.+-]+@[\w-]+\.[\w.-]+)/gi;
function linkifyText(text) {
  if (!text) return text;
  const parts = [];
  let lastIndex = 0;
  let match;
  let key = 0;
  LINK_REGEX.lastIndex = 0;
  while ((match = LINK_REGEX.exec(text)) !== null) {
    if (match.index > lastIndex) parts.push(text.slice(lastIndex, match.index));
    const token = match[0];
    const isEmail = token.includes('@') && !token.toLowerCase().startsWith('http') && !token.toLowerCase().startsWith('www.');
    const href = isEmail ? `mailto:${token}` : (token.toLowerCase().startsWith('http') ? token : `https://${token}`);
    parts.push(
      <a key={key++} href={href} target={isEmail ? undefined : '_blank'} rel="noopener noreferrer"
        onClick={(e) => e.stopPropagation()}
        style={{ color: 'inherit', textDecoration: 'underline', wordBreak: 'break-all' }}>
        {token}
      </a>
    );
    lastIndex = match.index + token.length;
  }
  if (lastIndex < text.length) parts.push(text.slice(lastIndex));
  return parts;
}

const MENTION_REGEX = /(^|[^a-zA-Z0-9._@])@([a-zA-Z0-9._]{3,30})/g;
function splitMentions(text) {
  const out = [];
  let last = 0;
  let match;
  MENTION_REGEX.lastIndex = 0;
  while ((match = MENTION_REGEX.exec(text)) !== null) {
    const handle = match[2].replace(/\.+$/, '');
    if (handle.length < 3 || handle.length > USERNAME_MAX) continue;
    const at = match.index + match[1].length;
    if (at > last) out.push(text.slice(last, at));
    out.push({ mention: handle.toLowerCase(), raw: '@' + handle });
    last = at + 1 + handle.length;
  }
  if (last < text.length) out.push(text.slice(last));
  return out;
}

function extractMentions(text) {
  const found = new Set();
  if (!text) return found;
  splitMentions(text).forEach((seg) => { if (seg && seg.mention) found.add(seg.mention); });
  return found;
}

const mentionCache = new Map();
const mentionPending = new Set();
const mentionListeners = new Set();
let mentionTimer = null;
function requestMentionProfiles(names) {
  names.forEach((n) => { if (n && !mentionCache.has(n)) mentionPending.add(n); });
  if (!mentionPending.size || mentionTimer) return;
  mentionTimer = setTimeout(async () => {
    const batch = [...mentionPending];
    mentionPending.clear();
    mentionTimer = null;
    const { data, error } = await supabase.from('profiles').select('*').in('username', batch);
    if (error) return;
    batch.forEach((n) => mentionCache.set(n, null));
    (data || []).forEach((p) => { if (!p.is_deleted && p.username) mentionCache.set(p.username.toLowerCase(), p); });
    mentionListeners.forEach((fn) => fn());
  }, 50);
}

function useMentionProfiles(names) {
  const [, setTick] = useState(0);
  const key = names.slice().sort().join(',');
  useEffect(() => {
    if (!key) return undefined;
    const listener = () => setTick((t) => t + 1);
    mentionListeners.add(listener);
    requestMentionProfiles(key.split(','));
    return () => { mentionListeners.delete(listener); };
  }, [key]);
}

const INLINE_FORMAT_RE = /(^|[\s(])([*_~`])(\S(?:[^\n]*?\S)?)\2(?=[\s).,!?:;]|$)/;
function formatInline(text, keyBase) {
  if (text && text.indexOf('||') >= 0 && prefOn('zchat-format') && /\|\|[^|\n]+?\|\|/.test(text)) {
    const parts = text.split(/\|\|([^|\n]+?)\|\|/);
    return parts.map((p, i) => (i % 2
      ? <Spoiler key={`${keyBase}-sp${i}`}>{formatInlineBase(p, `${keyBase}-sp${i}`)}</Spoiler>
      : <React.Fragment key={`${keyBase}-tx${i}`}>{formatInlineBase(p, `${keyBase}-tx${i}`)}</React.Fragment>));
  }
  return formatInlineBase(text, keyBase);
}
function formatInlineBase(text, keyBase) {
  if (!text || !prefOn('zchat-format') || !/[*_~`]/.test(text)) return text;
  const out = [];
  let rest = text;
  let k = 0;
  let guard = 0;
  while (rest && guard < 60) {
    guard += 1;
    const m = rest.match(INLINE_FORMAT_RE);
    if (!m) break;
    const at = m.index + m[1].length;
    if (at > 0) out.push(rest.slice(0, at));
    const mark = m[2];
    const inner = m[3];
    const key = `${keyBase}-${k++}`;
    if (mark === '*') out.push(<strong key={key} style={{ fontWeight: 800 }}>{formatInline(inner, key)}</strong>);
    else if (mark === '_') out.push(<em key={key}>{formatInline(inner, key)}</em>);
    else if (mark === '~') out.push(<span key={key} style={{ textDecoration: 'line-through' }}>{formatInline(inner, key)}</span>);
    else out.push(<code key={key} style={{ fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace', fontSize: '0.92em', padding: '0 4px', borderRadius: 5, background: 'rgba(127,127,127,0.18)' }}>{inner}</code>);
    rest = rest.slice(at + m[0].length - m[1].length);
  }
  if (rest) out.push(rest);
  return out.length === 1 && typeof out[0] === 'string' ? out[0] : out;
}
function RichText({ text, onMention }) {
  const { theme } = useTheme();
  const linked = linkifyText(text);
  const pieces = [];
  (Array.isArray(linked) ? linked : [linked]).forEach((part) => {
    if (typeof part === 'string') splitMentions(part).forEach((seg) => pieces.push(seg));
    else pieces.push(part);
  });
  const names = [...new Set(pieces.filter((seg) => seg && seg.mention).map((seg) => seg.mention))];
  useMentionProfiles(names);
  return (
    <>
      {pieces.map((seg, i) => {
        if (!seg || !seg.mention) return <React.Fragment key={i}>{typeof seg === 'string' ? formatInline(seg, i) : seg}</React.Fragment>;
        const found = mentionCache.get(seg.mention);
        if (!found) return <React.Fragment key={i}>{seg.raw}</React.Fragment>;
        return (
          <span key={i}
            onPointerDown={(e) => e.stopPropagation()}
            onClick={(e) => { e.stopPropagation(); if (onMention) onMention(found); }}
            style={{ color: theme.dark ? theme.gold : theme.coralDeep, fontWeight: 700, cursor: onMention ? 'pointer' : 'default' }}>
            {seg.raw}
          </span>
        );
      })}
    </>
  );
}

function getActiveMention(text, caret) {
  if (caret == null) return null;
  const before = text.slice(0, caret);
  const match = before.match(/(^|[^a-zA-Z0-9._@])@([a-zA-Z0-9._]{0,30})$/);
  if (!match) return null;
  return { query: match[2].toLowerCase(), start: caret - match[2].length - 1, end: caret };
}

function applyMention(text, mention, username, maxLen) {
  const before = text.slice(0, mention.start);
  const after = text.slice(mention.end).replace(/^[a-zA-Z0-9._]*/, '').replace(/^\s/, '');
  const insert = `@${username} `;
  const value = (before + insert + after).slice(0, maxLen);
  return { value, caret: Math.min(before.length + insert.length, value.length) };
}

function MentionSuggestions({ query, priority, excludeIds, myId, onPick }) {
  const { theme } = useTheme();
  const [remote, setRemote] = useState([]);
  useEffect(() => {
    let cancelled = false;
    if (!query) { setRemote([]); return undefined; }
    const timer = setTimeout(async () => {
      const pattern = query.replace(/[\\%_]/g, (c) => `\\${c}`) + '%';
      const { data } = await supabase.from('profiles').select('id, name, username, avatar, hide_photo, is_deleted')
        .ilike('username', pattern).not('is_deleted', 'is', true).limit(8);
      if (!cancelled) setRemote(data || []);
    }, 180);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [query]);

  const excluded = new Set(excludeIds || []);
  const seen = new Set();
  const list = [];
  const consider = (p) => {
    if (!p || !p.username || p.is_deleted || excluded.has(p.id) || seen.has(p.id)) return;
    const uname = p.username.toLowerCase();
    if (query && !uname.startsWith(query) && !(p.name || '').toLowerCase().startsWith(query)) return;
    seen.add(p.id);
    list.push(sanitizeAvatar(p, myId));
  };
  (priority || []).forEach(consider);
  remote.forEach(consider);
  if (!list.length) return null;

  return (
    <div className="zchat-fade" style={{
      background: theme.panelBg, border: `1px solid ${theme.border}`, borderRadius: 16,
      boxShadow: '0 8px 24px rgba(0,0,0,0.18)', maxHeight: 208, overflowY: 'auto', WebkitOverflowScrolling: 'touch',
    }}>
      {list.slice(0, 8).map((p, i) => (
        <div key={p.id}
          onPointerDown={(e) => e.preventDefault()}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => onPick(p)}
          style={{
            display: 'flex', alignItems: 'center', gap: 10, padding: '8px 12px', cursor: 'pointer',
            borderTop: i ? `1px solid ${theme.border}` : 'none',
          }}>
          <Avatar emoji={p.avatar} name={p.name} frame={p.avatar_frame} size={30} />
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={p.name} verified={p.verified} custom={p.custom_badge} size={12} /></div>
            <div style={{ fontSize: 11.5, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>@{p.username}</div>
          </div>
        </div>
      ))}
    </div>
  );
}


function mergeDuelState(st, merge) {
  if (!st || !merge) return st;
  if (DUEL_KINDS[st.g]) {
    const next = { ...st, rx: st.rx != null ? st.rx : (merge.rx != null ? merge.rx : null), ro: st.ro != null ? st.ro : (merge.ro != null ? merge.ro : null) };
    if (!next.w) next.w = duelWinner(next);
    return next;
  }
  if (st.g === 'dice') {
    const next = { ...st, dx: st.dx || merge.dx || null, do: st.do || merge.do || null };
    if (!next.w && next.dx && next.do) { const a = diceRank(next.dx).score; const b = diceRank(next.do).score; next.w = a === b ? 'd' : a > b ? 'x' : 'o'; }
    return next;
  }
  return st;
}
function bubblePropsEqual(a, b) {
  if (b.holder) b.holder.current = b;
  for (const k in b) {
    if (k === 'holder') continue;
    const x = a[k];
    const y = b[k];
    if (x === y) continue;
    if (typeof x === 'function' && typeof y === 'function') continue;
    if (x && y && typeof x === 'object' && typeof y === 'object' && !Array.isArray(x) && !Array.isArray(y)) {
      const kx = Object.keys(x);
      if (kx.length !== Object.keys(y).length) return false;
      for (let i = 0; i < kx.length; i++) if (x[kx[i]] !== y[kx[i]]) return false;
      continue;
    }
    return false;
  }
  for (const k in a) if (!(k in b)) return false;
  return true;
}

const MessageBubbleMemo = React.memo(function MessageBubbleMemo(props) {
  const { holder } = props;
  holder.current = props;
  const fns = useRef({});
  const out = {};
  for (const k in props) {
    if (k === 'holder') continue;
    const v = props[k];
    if (typeof v === 'function') {
      if (!fns.current[k]) fns.current[k] = (...args) => { const f = holder.current && holder.current[k]; return typeof f === 'function' ? f(...args) : undefined; };
      out[k] = fns.current[k];
    } else out[k] = v;
  }
  return <MessageBubble {...out} />;
}, bubblePropsEqual);

function MessageBubble({ onOpenOnce, onVote, onShowVotes, gameMerge, gameLive, onGameMove, onGameRematch, onOpenGame, onPlayDuel, peerName, myId, isBot, m, isMe, onDelete, selectionMode, selected, onToggleSelect, onLongPress, onOpenImage, onOpenVideo, reactions, onReact, onOpenWhoReacted, replyPreview, onSwipeReply, onJumpToMessage, highlighted, senderLabel, senderAvatar, hideReadStatus, onOpenSenderProfile, canModerate, onOpenMention, mentionsMe, onOpenStoryRef, onCallBack, onOpenSticker, tightBelow, senderVerified, onOpenPost, tightAbove, senderFrame, senderCustomBadge }) {
  const mediaOnly = !m.deleted && (m.type === 'image' || m.type === 'video')
    && !replyPreview && !senderLabel && !m.forwarded
    && !(m.content && !String(m.content).startsWith('/'));
  const { theme, fontScale, bubbleColor } = useTheme();
  const cachedVideoSrc = useCachedMedia(m.type === 'video' ? m.media_url : null);
  const [hover, setHover] = useState(false);
  const [burstHeart, setBurstHeart] = useState(false);
  const lastTapRef = useRef(0);
  const pressTimerRef = useRef(null);
  const longPressFiredRef = useRef(false);
  const startPosRef = useRef({ x: 0, y: 0 });
  const activePointerRef = useRef(null);
  const [mouseOver, setMouseOver] = useState(false);
  const dragXRef = useRef(0);
  const bubbleWrapRef = useRef(null);
  const replyArrowRef = useRef(null);
  const draggingRef = useRef(false);
  const swipedPastThresholdRef = useRef(false);
  const time = m.created_at ? new Date(m.created_at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) : '';
  const bubbleColorSpec = BUBBLE_COLORS[bubbleColor] || BUBBLE_COLORS.default;
  const sharedProfileId = m.type === 'text' && !m.deleted ? parseProfileLink(m.content) : null;
  const sharedPostId = m.type === 'text' && !m.deleted ? parsePostLink(m.content) : null;
  const pollData = m.type === 'text' && !m.deleted ? parsePoll(m.content) : null;
  const onceInfo = !m.deleted ? parseOnce(m) : null;
  const eventData = m.type === 'text' && !m.deleted && !pollData ? parseEventMsg(m.content) : null;
  const diceData = m.type === 'text' && !m.deleted && !pollData && !eventData ? parseDice(m.content) : null;
  const extraCard = m.type === 'text' && !m.deleted && !pollData && !eventData && !diceData ? parseExtraCard(m.content) : null;
  const blurInfo = !m.deleted && !onceInfo ? parseBlur(m) : null;
  const mediaCaption = blurInfo ? blurInfo.c : m.content;
  const gameState = mergeDuelState(m.type === 'text' && !m.deleted ? parseGameMessage(m.content) : null, gameMerge);
  const gameFresh = !!gameState && !!m.created_at && (Date.now() - new Date(m.created_at).getTime()) < 20000;
  const moveKey = gameState ? `${gameState.id}:${gameState.n}` : null;
  const [sendingMove, setSendingMove] = useState(false);
  useEffect(() => { setSendingMove(false); }, [moveKey]);
  const guardedGameMove = (next) => {
    if (!moveKey || sendingMove || sentGameMoveKeys.has(moveKey)) return;
    sentGameMoveKeys.add(moveKey);
    setSendingMove(true);
    Promise.resolve(onGameMove ? onGameMove(next) : false).then((ok) => {
      if (ok === false) { sentGameMoveKeys.delete(moveKey); setSendingMove(false); }
    }).catch(() => { sentGameMoveKeys.delete(moveKey); setSendingMove(false); });
  };
  const moveSent = !!moveKey && (sendingMove || sentGameMoveKeys.has(moveKey));
  const bareCard = !m.deleted && m.type === 'text' && (!!gameState || !!pollData || !!eventData || !!diceData || !!extraCard);
  const locationShare = m.type === 'text' && !m.deleted && !gameState && !pollData && !eventData && !diceData && !extraCard ? parseLocationMessage(m.content) : null;
  const linkPreviewUrl = m.type === 'text' && !m.deleted && !sharedPostId && !sharedProfileId && !gameState && !locationShare && !pollData && !eventData && !diceData && !extraCard ? firstPreviewableUrl(m.content) : null;
  const inlineTime = m.type === 'text' && !m.deleted && !!m.content && !sharedProfileId && !sharedPostId && !gameState && !locationShare && !pollData && !eventData && !diceData && !extraCard && !(m.story_id && (m.content === STORY_MENTION_TEXT || m.content === STORY_GROUP_MENTION_TEXT || m.content === STORY_SHARE_TEXT));

  if (m.type === 'system' && parseCallLog(m.content)) {
    return <CallLogBubble m={m} isMe={isMe} onCallBack={onCallBack} />;
  }
  if (m.type === 'system') {
    const note = systemNoteFor(m, myId);
    return (
      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 10 }}>
        <div style={{ background: theme.rowBg, color: note ? theme.ink : theme.muted, fontSize: 12, fontWeight: 600, padding: '6px 14px', borderRadius: 14, textAlign: 'center', maxWidth: '80%', display: 'flex', alignItems: 'center', gap: 6 }}>
          {note && note.kind === 'shot' && <Camera size={13} />}
          {note && note.kind === 'buzz' && <BuzzIcon size={14} />}
          {note ? note.text : m.content}
        </div>
      </div>
    );
  }

  const grouped = {};
  (reactions || []).forEach((r) => { if (isHiddenReaction(r.emoji)) return; grouped[r.emoji] = (grouped[r.emoji] || 0) + 1; });
  const groupedEntries = Object.entries(grouped);

  const handleRowTap = (e) => {
    if (longPressFiredRef.current) { longPressFiredRef.current = false; return; }
    if (selectionMode) { onToggleSelect(m.id); return; }
    const now = Date.now();
    if (onceInfo) {
      if (onOpenOnce && !isMe) onOpenOnce(m);
    } else if (now - lastTapRef.current < 350 && prefOn('zchat-doubletap') && !pollData && !eventData && !diceData && !extraCard) {
      onReact(m.id, '\u2764\u{FE0F}');
      setBurstHeart(true);
      setTimeout(() => setBurstHeart(false), 650);
    } else if (m.type === 'image') {
      onOpenImage(m.media_url);
    } else if (m.type === 'video') {
      onOpenVideo({ url: m.media_url, trimStart: m.trim_start, trimEnd: m.trim_end, overlayUrl: m.overlay_url });
    }
    lastTapRef.current = now;
  };

  const clearPressTimer = () => { clearTimeout(pressTimerRef.current); pressTimerRef.current = null; setHover(false); };

  const handlePointerDown = (e) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    if (e.pointerType === 'touch' && e.clientX <= EDGE_BACK_PX && window.innerWidth < 900) return;
    activePointerRef.current = e.pointerId;
    setHover(true);
    startPosRef.current = { x: e.clientX, y: e.clientY };
    swipedPastThresholdRef.current = false;
    if (bubbleWrapRef.current) bubbleWrapRef.current.style.transition = 'none';
    clearTimeout(pressTimerRef.current);
    pressTimerRef.current = setTimeout(() => {
      longPressFiredRef.current = true;
      onLongPress(m.id);
    }, 420);
  };
  const handlePointerMove = (e) => {
    if (activePointerRef.current !== e.pointerId) return;
    if (e.pointerType === 'mouse' && (e.buttons & 1) !== 1) { finalizeDrag(); return; }
    const dx = e.clientX - startPosRef.current.x;
    const dy = e.clientY - startPosRef.current.y;
    if (Math.abs(dx) > 5 || Math.abs(dy) > 5) clearPressTimer();
    if (!m.deleted && !selectionMode && prefOn('zchat-swipe-reply') && Math.abs(dx) > Math.abs(dy) && dx > 0) {
      draggingRef.current = true;
      const clamped = Math.min(dx, 60);
      dragXRef.current = clamped;
      if (bubbleWrapRef.current) bubbleWrapRef.current.style.transform = `translateX(${clamped}px)`;
      if (replyArrowRef.current) replyArrowRef.current.style.opacity = Math.min(1, clamped / 24);
      swipedPastThresholdRef.current = clamped >= 26;
    }
  };
  const finalizeDrag = () => {
    activePointerRef.current = null;
    clearPressTimer();
    if (draggingRef.current) {
      const shouldFire = swipedPastThresholdRef.current;
      draggingRef.current = false;
      dragXRef.current = 0;
      if (bubbleWrapRef.current) {
        bubbleWrapRef.current.style.transition = 'transform 0.2s ease';
        bubbleWrapRef.current.style.transform = 'translateX(0px)';
      }
      if (replyArrowRef.current) replyArrowRef.current.style.opacity = 0;
      if (shouldFire) onSwipeReply(m);
    }
  };

  const bubbleKey = !m.deleted && m.type !== 'system' ? bubbleKeyOf(m.bubble_style) : null;
  const bubbleSpec = bubbleKey ? resolveBubbleSpec(BUBBLE_STYLES[bubbleKey], theme) : null;
  const bubbleBg = m.deleted ? theme.rowBg : (isMe ? (bubbleColorSpec.me || theme.bubbleMe) : (bubbleColorSpec.them || theme.bubbleThem));

  return (
    <div
      id={`msg-${m.id}`}
      style={{
        display: 'flex', justifyContent: isMe ? 'flex-end' : 'flex-start', alignItems: 'flex-start', gap: 8, marginBottom: groupedEntries.length > 0 && !m.deleted ? 14 : tightBelow ? 1 : 6,
        touchAction: 'pan-y', WebkitTapHighlightColor: 'transparent', overscrollBehaviorX: 'none', cursor: 'pointer',
        background: selected ? `${theme.coral}14` : highlighted ? `${theme.coral}22` : 'transparent',
        transition: 'background 0.3s ease',
        marginLeft: -18, marginRight: -18, paddingLeft: 18, paddingRight: 18, paddingTop: 2, paddingBottom: 2,
      }}
      onClick={handleRowTap}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={finalizeDrag}
      onPointerCancel={finalizeDrag}
      onPointerLeave={(e) => { if (e.pointerType === 'mouse') setMouseOver(false); finalizeDrag(); }}
      onPointerEnter={(e) => { if (e.pointerType === 'mouse') setMouseOver(true); }}
      onContextMenu={(e) => { if (isTouchDevice()) return; e.preventDefault(); if (!selectionMode) onLongPress(m.id); }}
    >
      {selectionMode && (
        <div style={{
          width: 20, height: 20, borderRadius: '50%', border: `2px solid ${selected ? theme.coral : theme.border}`,
          background: selected ? theme.coral : 'transparent', flexShrink: 0, cursor: 'pointer',
          display: 'flex', alignItems: 'center', justifyContent: 'center', marginTop: 2,
        }}>
          {selected && <Check size={12} color="white" />}
        </div>
      )}
      {isMe && !m.deleted && !selectionMode && canHoverPointer() && (
        <Trash2 size={14} color={theme.muted} style={{ cursor: 'pointer', flexShrink: 0, visibility: mouseOver ? 'visible' : 'hidden', marginTop: 4 }}
          onClick={(e) => { e.stopPropagation(); onDelete(m.id); }} />
      )}
      {senderLabel && !m.deleted && (
        tightBelow
          ? <div style={{ width: 24, flexShrink: 0 }} />
          : (
            <div onClick={(e) => { e.stopPropagation(); onOpenSenderProfile && onOpenSenderProfile(); }} style={{ cursor: onOpenSenderProfile ? 'pointer' : 'default', flexShrink: 0, alignSelf: 'flex-end' }}>
              <Avatar emoji={senderAvatar} name={senderLabel} frame={senderFrame} size={24} />
            </div>
          )
      )}
      {/* media with no caption, no reply and no sender label fills the bubble */}
      <div style={{ position: 'relative', maxWidth: senderLabel ? `calc(${isBot ? 92 : 80}% - 30px)` : `${isBot ? 92 : 80}%`, marginTop: bubbleSpec ? (bubbleSpec.top || 0) : 0 }}>
        {!selectionMode && !m.deleted && (
          <div ref={replyArrowRef} style={{
            position: 'absolute', top: 10, left: -30, transform: 'translateY(-50%)',
            opacity: 0, pointerEvents: 'none',
          }}>
            <Reply size={16} color={theme.coral} />
          </div>
        )}
        <div ref={bubbleWrapRef} style={{ transform: 'translateX(0px)' }}>
        <div style={{ position: 'relative' }}>
        <div style={{
          background: bubbleBg,
          borderRadius: 19,
          borderBottomRightRadius: isMe && !m.deleted ? 5 : 19,
          borderBottomLeftRadius: !isMe && !m.deleted ? 5 : 19,
          padding: m.type === 'text' || m.deleted ? '6px 11px' : (mediaOnly && !bubbleSpec ? 0 : 4),
          border: m.deleted ? `1px dashed ${theme.border}` : mentionsMe ? `1.5px solid ${theme.coral}` : (mediaOnly ? 'none' : `1px solid ${theme.dark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.04)'}`),
          boxShadow: m.deleted || mediaOnly ? 'none' : '0 1px 2px rgba(0,0,0,0.06)',
          ...(mediaOnly ? { background: 'transparent', overflow: 'hidden' } : {}),
          ...(m.deleted ? {} : { borderRadius: 16 }),
          ...(bubbleSpec && m.type !== 'sticker' ? bubbleStyleCss(bubbleSpec, isMe) : {}),
          ...(bubbleSpec && mediaOnly ? { overflow: 'visible' } : {}),
          ...(m.type === 'sticker' && !m.deleted ? { background: 'transparent', border: 'none', boxShadow: 'none', padding: 0, overflow: 'visible' } : {}),
          ...(bareCard ? { background: 'transparent', border: 'none', boxShadow: 'none', padding: 0, overflow: 'visible' } : {}),
        }}>
          {bubbleSpec && bubbleSpec.deco && BUBBLE_DECO[bubbleKey] && m.type !== 'sticker' && !bareCard && <div aria-hidden="true" style={{ position: 'absolute', pointerEvents: 'none', zIndex: 1, ...bubbleSpec.deco }}>{BUBBLE_DECO[bubbleKey]()}</div>}
          {senderLabel && !m.deleted && !tightAbove && (
            <div style={{ fontSize: 11.5, fontWeight: 700, color: theme.coralDeep, marginBottom: 3, padding: m.type !== 'text' ? '0 4px' : 0 }}>
              <NameBadge name={senderLabel} verified={senderVerified} custom={senderCustomBadge} size={11} />
            </div>
          )}
          {m.forwarded && !m.deleted && (
            <div style={{
              display: 'flex', alignItems: 'center', gap: 4, fontSize: 10.5, color: theme.muted, fontStyle: 'italic',
              marginBottom: 3, padding: m.type !== 'text' ? '0 4px' : 0,
            }}>
              <Forward size={10} color={theme.muted} /> {m.forwarded_from_name ? `Forwarded from ${m.forwarded_from_name}` : 'Forwarded'}
            </div>
          )}
          {replyPreview && !m.deleted && (
            <div style={{ marginBottom: 6, minWidth: 150 }}>
              <ReplyQuote m={replyPreview} label={replyPreview.senderLabel} bar={bubbleSpec ? bubbleSpec.line : undefined} dim={bubbleSpec ? bubbleSpec.ink : undefined}
                onClick={(e) => { e.stopPropagation(); onJumpToMessage && onJumpToMessage(replyPreview.id); }} />
            </div>
          )}
          {m.deleted ? (
            <div style={{ fontSize: 13, color: theme.muted, fontStyle: 'italic' }}>This message was deleted</div>
          ) : (
            <>
              {onceInfo && <OnceChip m={m} isMe={isMe} reactions={reactions} myId={myId} onOpen={onOpenOnce} ink={bubbleSpec ? bubbleSpec.ink : undefined} isGroup={!!senderLabel || !!hideReadStatus} />}
              {m.type === 'image' && !onceInfo && <BlurGate on={!!blurInfo} id={m.id}><ChatImage src={m.media_url} caption={mediaCaption} /></BlurGate>}
              {m.type === 'video' && !onceInfo && (<BlurGate on={!!blurInfo} id={m.id}>
                <div onClick={(e) => { e.stopPropagation(); onOpenVideo({ url: m.media_url, trimStart: m.trim_start, trimEnd: m.trim_end, overlayUrl: m.overlay_url }); }} style={{ position: 'relative', width: 240, maxWidth: '100%', height: 240, borderRadius: 14, overflow: 'hidden', marginBottom: m.content ? 4 : 2, background: '#000', cursor: 'pointer' }}>
                  <VideoThumb src={USE_VIDEO_THUMBS ? m.media_url : (cachedVideoSrc || m.media_url)} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', pointerEvents: 'none' }} />
                  {m.overlay_url && <img src={m.overlay_url} alt="" draggable={false} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} />}
                  <div style={{
                    position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none',
                    background: 'rgba(0,0,0,0.18)',
                  }}>
                    <div style={{ width: 44, height: 44, borderRadius: '50%', background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <Play size={20} color="white" style={{ marginLeft: 2 }} />
                    </div>
                  </div>
                  <div onClick={(e) => { e.stopPropagation(); silentDownload(m.media_url, 'zchat-video.mp4'); }} style={{
                    position: 'absolute', top: 6, right: 6, width: 26, height: 26, borderRadius: '50%',
                    background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                  }}><Download size={13} color="white" /></div>
                </div>
              </BlurGate>)}
              {(m.type === 'image' || m.type === 'video') && !onceInfo && mediaCaption && !String(mediaCaption).startsWith('/') && (
                <div style={{ fontSize: 15 * fontScale, color: bubbleSpec ? bubbleSpec.ink : theme.ink, wordBreak: 'break-word', whiteSpace: 'pre-wrap', lineHeight: 1.32, padding: '2px 2px 16px', maxWidth: 250 }}>
                  <RichText text={mediaCaption} onMention={onOpenMention} />
                </div>
              )}
              {m.type === 'audio' && <div style={{ paddingBottom: 14 }}><AudioBubble url={m.media_url} isMe={isMe} ink={bubbleSpec ? bubbleSpec.ink : undefined} line={bubbleSpec ? bubbleSpec.line : undefined} /></div>}
              {m.type === 'sticker' && (
                m.content && /^https?:/i.test(m.content) ? (
                  <img src={m.content} alt="Sticker" draggable={false} onClick={(e) => { if (selectionMode || !onOpenSticker) return; e.stopPropagation(); onOpenSticker(m); }} className="zchat-wave-pop" style={{ display: 'block', width: 120, height: 120, objectFit: 'contain', marginBottom: 18, cursor: 'pointer' }} />
                ) : m.content && m.content.startsWith('/') ? (
                  <div onClick={(e) => { if (selectionMode || !onOpenSticker) return; e.stopPropagation(); onOpenSticker(m); }} style={{ cursor: 'pointer' }}>
                    <LoopingSticker src={m.content} size={96} className="zchat-wave-pop" style={{ display: 'block', marginBottom: 18 }} />
                  </div>
                ) : (
                  <div className="zchat-wave-pop" style={{ fontSize: 64, lineHeight: 1, padding: '4px 10px' }}>{m.content}</div>
                )
              )}
              {m.story_id && <StoryRefCard m={m} isMe={isMe} onOpen={onOpenStoryRef} />}
              {sharedPostId && (
                <div style={{ paddingTop: 2, paddingBottom: 16 }}>
                  <PostLinkCard postId={sharedPostId} onOpen={onOpenPost} />
                </div>
              )}
              {sharedProfileId && (
                <div style={{ paddingTop: 2, paddingBottom: 16 }}>
                  <ProfileLinkCard profileId={sharedProfileId} onOpen={onOpenMention} />
                </div>
              )}
              {gameState && (
                <div style={{ paddingTop: 2, paddingBottom: 18, position: 'relative' }}>
                  {moveSent && gameLive && (
                    <div onClick={(e) => e.stopPropagation()} style={{ position: 'absolute', inset: '2px 0 18px', zIndex: 3, borderRadius: 22, background: 'rgba(8,5,20,0.28)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <span style={{ padding: '7px 14px', borderRadius: 999, background: 'rgba(15,10,30,0.82)', color: 'white', fontSize: 12.5, fontWeight: 800, display: 'inline-flex', alignItems: 'center', gap: 8, boxShadow: '0 6px 18px rgba(0,0,0,0.35)' }}>
                        <Spinner size={13} color="white" />Sending
                      </span>
                    </div>
                  )}
                  {gameState.g === 'ttt' && (
                    <TicTacToeCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onMove={guardedGameMove} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {gameState.g === 'c4' && (
                    <ConnectFourCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onMove={guardedGameMove} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {gameState.g === 'rps' && (
                    <RpsCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onMove={guardedGameMove} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {gameState.g === 'score' && (
                    <ScoreCard state={gameState} isMe={isMe} senderName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined} onPlay={() => onOpenGame && onOpenGame(gameState.k)} />
                  )}
                  {gameState.g === 'dots' && (
                    <DotsCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onMove={guardedGameMove} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {gameState.g === 'hang' && (
                    <HangCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onMove={guardedGameMove} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {DUEL_KINDS[gameState.g] && (
                    <DuelCard state={gameState} myId={myId} live={!!gameLive} fresh={gameFresh} peerName={peerName} ink={bubbleSpec ? bubbleSpec.ink : undefined}
                      onPlay={() => onPlayDuel && onPlayDuel(gameState)} onRematch={onGameRematch ? () => onGameRematch(gameState) : null} />
                  )}
                  {BOARD_CARDS[gameState.g] && React.createElement(BOARD_CARDS[gameState.g], { state: gameState, myId, live: !!gameLive, fresh: gameFresh, peerName, onMove: guardedGameMove, onRematch: onGameRematch ? () => onGameRematch(gameState) : null })}
                </div>
              )}
              {pollData && (
                <div style={{ paddingTop: 2, paddingBottom: 18 }}>
                  <PollCard poll={pollData} votes={reactions} myId={myId} onVote={onVote ? (i) => onVote(m, i) : null} onShowVotes={onShowVotes ? () => onShowVotes(m) : null} />
                </div>
              )}
              {diceData && (
                <div style={{ paddingTop: 2, paddingBottom: 18 }}>
                  {(() => {
                    const fr = (() => { if (diceRolledOnce.has(m.id)) return false; diceRolledOnce.add(m.id); return !!m.created_at && Date.now() - new Date(m.created_at).getTime() < 9000; })();
                    return diceData.k === 'pick'
                      ? <PickCard d={diceData} ink={bubbleSpec ? bubbleSpec.ink : undefined} fresh={fr} />
                      : <RollCard d={diceData} ink={bubbleSpec ? bubbleSpec.ink : undefined} fresh={fr} />;
                  })()}
                </div>
              )}
              {eventData && (
                <div style={{ paddingTop: 2, paddingBottom: 18 }}>
                  <EventCard ev={eventData} votes={reactions} myId={myId} onVote={onVote ? (i) => onVote(m, i) : null} onShowVotes={onShowVotes ? () => onShowVotes(m) : null} />
                </div>
              )}
              {extraCard && (
                <div style={{ paddingTop: 2, paddingBottom: 18 }}>
                  {extraCard.k === 'list' && <ChecklistCard list={extraCard.d} votes={reactions} onToggle={onVote ? (i) => onVote(m, i) : null} />}
                  {extraCard.k === 'bill' && <BillCard bill={extraCard.d} votes={reactions} myId={myId} senderId={m.sender_id} onToggle={onVote ? () => onVote(m, 0) : null} onShowVotes={onShowVotes ? () => onShowVotes(m) : null} />}
                  {extraCard.k === 'count' && <CountdownCard cd={extraCard.d} />}
                </div>
              )}
              {locationShare && (
                <div style={{ paddingTop: 2, paddingBottom: 16 }}>
                  <LocationCard loc={locationShare} isMe={isMe} ink={bubbleSpec ? bubbleSpec.ink : undefined} />
                </div>
              )}
              {m.type === 'text' && m.content && !sharedProfileId && !sharedPostId && !gameState && !locationShare && !pollData && !eventData && !diceData && !extraCard && !(m.story_id && (m.content === STORY_MENTION_TEXT || m.content === STORY_GROUP_MENTION_TEXT || m.content === STORY_SHARE_TEXT)) && (
                <div style={{
                  fontSize: (m.text_size ? textSizePx(m.text_size) : 15) * fontScale,
                  fontWeight: m.text_size === 'l' || m.text_size === 'xl' ? 800 : 400,
                  ...fontStyleCss(m.text_font),
                  color: m.text_color || (bubbleSpec ? bubbleSpec.ink : theme.ink),
                  wordBreak: 'break-word', whiteSpace: 'pre-wrap',
                  lineHeight: m.text_size === 'xl' ? 1.12 : m.text_size === 'l' ? 1.2 : 1.32,
                  display: 'flow-root',
                }}>
                  {isBot ? <BotRichText text={m.content} onMention={onOpenMention} /> : <RichText text={m.content} onMention={onOpenMention} />}
                  {linkPreviewUrl && <LinkPreviewCard url={linkPreviewUrl} />}
                  <span data-msg-time="true" style={{ float: 'right', display: 'inline-flex', alignItems: 'center', gap: 3, marginLeft: 10, marginTop: 7, marginBottom: -3, height: 14, lineHeight: 1, position: 'relative', top: 1, userSelect: 'none' }}>
                    {m.edited && <span style={{ fontSize: 8, color: theme.muted, fontStyle: 'italic' }}>edited</span>}
                    <span style={{ fontSize: 10.5, color: bubbleSpec ? bubbleSpec.ink : theme.muted, opacity: bubbleSpec ? 0.7 : 1 }}>{time}</span>
                    {isMe && <StatusTicks status={m.queued ? 'queued' : (!hideReadStatus && m.read) ? 'read' : m.delivered ? 'delivered' : 'sent'} />}
                  </span>
                </div>
              )}
            </>
          )}
          {!m.deleted && !inlineTime && (
            <div style={{
              position: 'absolute', bottom: bareCard ? 0 : 4, right: bareCard ? 12 : 8, display: 'flex', alignItems: 'center', gap: 3,
              background: m.type === 'text' ? 'none' : 'rgba(0,0,0,0.4)', borderRadius: 8,
              padding: m.type === 'text' ? 0 : '1px 5px',
            }}>
              {m.edited && <span style={{ fontSize: 8, color: m.type === 'text' ? theme.muted : 'rgba(255,255,255,0.85)', fontStyle: 'italic' }}>edited</span>}
              <span style={{ fontSize: 10.5, color: m.type === 'text' ? theme.muted : 'rgba(255,255,255,0.85)' }}>{time}</span>
              {isMe && <StatusTicks status={m.queued ? 'queued' : (!hideReadStatus && m.read) ? 'read' : m.delivered ? 'delivered' : 'sent'} />}
            </div>
          )}
        </div>
        {groupedEntries.length > 0 && !m.deleted && (
          <div onClick={(e) => { e.stopPropagation(); onOpenWhoReacted(m.id); }} style={{
            position: 'absolute', bottom: -10, [isMe ? 'left' : 'right']: 6, cursor: 'pointer',
            background: theme.panelBg, borderRadius: 10, padding: '1px 6px', fontSize: 10.5,
            display: 'flex', alignItems: 'center', gap: 3, boxShadow: '0 1px 4px rgba(0,0,0,0.15)', zIndex: 1,
          }}>
            {groupedEntries.map(([emoji, count]) => <span key={emoji}>{emoji}{count > 1 ? count : ''}</span>)}
          </div>
        )}
        {burstHeart && (
          <div style={{
            position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 44, pointerEvents: 'none', animation: 'zchat-heart-burst 0.6s ease',
          }}>{'\u2764\u{FE0F}'}</div>
        )}
        </div>
        </div>
      </div>
    </div>
  );
}
function playPing() {
  if (quietNow()) return;
  playUiSound('receive');
}
function playReactionPing() {
  if (quietNow()) return;
  try { if (localStorage.getItem('zchat-reaction-sound') === 'off') return; } catch {}
  playUiSound('like');
}

function pairKey(a, b) { return a < b ? [a, b] : [b, a]; }


function ImageViewer({ url, onClose, onForward, onReport, once, caption, onEdit }) {
  useBackClose(true, onClose);
  const [ui, setUi] = useState(true);
  const [menuOpen, setMenuOpen] = useState(false);
  const rootRef = useRef(null);
  const imgRef = useRef(null);
  const bgRef = useRef(null);
  const g = useRef({ s: 1, x: 0, y: 0, dy: 0, pts: new Map(), mode: null, start: null, pinch: null, lastTap: 0, tapTimer: null, moved: false, samples: [], closing: false });
  const paint = (anim) => {
    const st = g.current;
    const el = imgRef.current;
    if (el) {
      el.style.transition = anim ? 'transform 0.26s cubic-bezier(0.2, 0.8, 0.2, 1)' : 'none';
      el.style.transform = `translate3d(${st.x}px, ${st.y + st.dy}px, 0) scale(${st.s})`;
    }
    const bg = bgRef.current;
    if (bg) {
      bg.style.transition = anim ? 'opacity 0.26s ease' : 'none';
      bg.style.opacity = String(1 - Math.min(0.85, Math.abs(st.dy) / 420));
    }
  };
  const bounds = () => {
    const el = imgRef.current;
    const st = g.current;
    if (!el) return { mx: 0, my: 0 };
    const w = el.offsetWidth * st.s;
    const h = el.offsetHeight * st.s;
    return { mx: Math.max(0, (w - window.innerWidth) / 2), my: Math.max(0, (h - window.innerHeight) / 2) };
  };
  const clampPan = () => {
    const st = g.current;
    const b = bounds();
    st.x = Math.max(-b.mx, Math.min(b.mx, st.x));
    st.y = Math.max(-b.my, Math.min(b.my, st.y));
  };
  const zoomAt = (cx, cy, target) => {
    const st = g.current;
    const el = imgRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const ccx = r.left + r.width / 2 - st.x;
    const ccy = r.top + r.height / 2 - st.y;
    const qx = (cx - ccx - st.x) / st.s;
    const qy = (cy - ccy - st.y) / st.s;
    st.s = target;
    st.x = cx - ccx - target * qx;
    st.y = cy - ccy - target * qy;
    if (target <= 1.001) { st.s = 1; st.x = 0; st.y = 0; }
    clampPan();
    paint(true);
  };
  const closeBySwipe = (dir) => {
    const st = g.current;
    st.closing = true;
    st.dy = dir * window.innerHeight;
    paint(true);
    if (rootRef.current) rootRef.current.setAttribute('data-ghost-skip', '1');
    setTimeout(onClose, 200);
  };
  const onDown = (e) => {
    const st = g.current;
    if (st.closing) return;
    if (e.target && e.target.closest && e.target.closest('[data-viewer-ui]')) return;
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch {}
    st.pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
    st.moved = false;
    if (st.pts.size === 1) {
      st.mode = null;
      st.start = { x: e.clientX, y: e.clientY, sx: st.x, sy: st.y, t: Date.now() };
      st.samples = [[e.clientY, Date.now()]];
    } else if (st.pts.size === 2) {
      const [a, b] = [...st.pts.values()];
      const el = imgRef.current;
      const r = el ? el.getBoundingClientRect() : { left: 0, top: 0, width: 0, height: 0 };
      st.mode = 'pinch';
      st.dy = 0;
      st.pinch = { d0: Math.hypot(a.x - b.x, a.y - b.y) || 1, s0: st.s, mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2, x0: st.x, y0: st.y, cx: r.left + r.width / 2 - st.x, cy: r.top + r.height / 2 - st.y };
      clearTimeout(st.tapTimer);
    }
  };
  const onMove = (e) => {
    const st = g.current;
    if (!st.pts.has(e.pointerId) || st.closing) return;
    st.pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (st.mode === 'pinch' && st.pts.size >= 2) {
      const [a, b] = [...st.pts.values()];
      const p = st.pinch;
      const d = Math.hypot(a.x - b.x, a.y - b.y) || 1;
      const s = Math.max(0.8, Math.min(5, p.s0 * (d / p.d0)));
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2;
      const qx = (p.mx - p.cx - p.x0) / p.s0;
      const qy = (p.my - p.cy - p.y0) / p.s0;
      st.s = s;
      st.x = mx - p.cx - s * qx;
      st.y = my - p.cy - s * qy;
      st.moved = true;
      paint(false);
      return;
    }
    if (st.pts.size !== 1 || !st.start) return;
    const dx = e.clientX - st.start.x;
    const dy = e.clientY - st.start.y;
    if (!st.moved && Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
    st.moved = true;
    if (st.s > 1.02) {
      st.mode = 'pan';
      st.x = st.start.sx + dx;
      st.y = st.start.sy + dy;
      paint(false);
      return;
    }
    if (!st.mode) st.mode = Math.abs(dy) > Math.abs(dx) ? 'dismiss' : 'none';
    if (st.mode === 'dismiss') {
      st.dy = dy;
      st.samples.push([e.clientY, Date.now()]);
      if (st.samples.length > 5) st.samples.shift();
      paint(false);
    }
  };
  const onUp = (e) => {
    const st = g.current;
    if (!st.pts.has(e.pointerId)) return;
    st.pts.delete(e.pointerId);
    if (st.closing) return;
    if (st.mode === 'pinch') {
      if (st.pts.size === 1) {
        const [p] = [...st.pts.values()];
        st.mode = 'pan';
        st.start = { x: p.x, y: p.y, sx: st.x, sy: st.y, t: Date.now() };
        return;
      }
      if (st.s < 1) { st.s = 1; st.x = 0; st.y = 0; }
      clampPan();
      paint(true);
      st.mode = null;
      return;
    }
    if (st.pts.size > 0) return;
    if (st.mode === 'dismiss') {
      const a = st.samples[0];
      const b = st.samples[st.samples.length - 1];
      const v = a && b && b[1] > a[1] ? (b[0] - a[0]) / (b[1] - a[1]) : 0;
      if (Math.abs(st.dy) > 120 || Math.abs(v) > 0.7) { closeBySwipe(st.dy >= 0 ? 1 : -1); return; }
      st.dy = 0;
      paint(true);
      st.mode = null;
      return;
    }
    if (st.mode === 'pan') { clampPan(); paint(true); st.mode = null; return; }
    if (!st.moved) {
      const now = Date.now();
      if (now - st.lastTap < 280) {
        clearTimeout(st.tapTimer);
        st.lastTap = 0;
        zoomAt(e.clientX, e.clientY, st.s > 1.05 ? 1 : 2.6);
        return;
      }
      st.lastTap = now;
      clearTimeout(st.tapTimer);
      st.tapTimer = setTimeout(() => { setMenuOpen(false); setUi((v) => !v); }, 270);
    }
    st.mode = null;
  };
  const onWheel = (e) => {
    const st = g.current;
    const next = Math.max(1, Math.min(5, st.s * (e.deltaY < 0 ? 1.15 : 0.87)));
    zoomAt(e.clientX, e.clientY, next);
  };
  useEffect(() => () => clearTimeout(g.current.tapTimer), []);
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return undefined;
    const h = (e) => { if (e.ctrlKey || e.metaKey) e.preventDefault(); };
    el.addEventListener('wheel', h, { passive: false });
    return () => el.removeEventListener('wheel', h);
  }, []);
  const item = (label, onClick, danger) => (
    <div role="button" onClick={(e) => { e.stopPropagation(); setMenuOpen(false); onClick(); }} style={{ padding: '13px 16px', fontSize: 15, fontWeight: 600, color: danger ? '#FF6B6B' : 'white', cursor: 'pointer', borderTop: '1px solid rgba(255,255,255,0.08)' }}>{label}</div>
  );
  const chrome = { transition: 'opacity 0.2s ease, visibility 0.2s', opacity: ui ? 1 : 0, visibility: ui ? 'visible' : 'hidden' };
  const art = !once && !!onEdit && isPaintUrl(url);
  return (
    <div ref={rootRef} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 200, overflow: 'hidden' }}>
      <div ref={bgRef} style={{ position: 'absolute', inset: 0, background: '#000' }} />
      <div onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onWheel={onWheel} data-no-swipe="true"
        style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', touchAction: 'none' }}>
        <img ref={imgRef} src={url} alt="" onContextMenu={(e) => e.preventDefault()} draggable={false}
          style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain', userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none', transformOrigin: '50% 50%', willChange: 'transform', pointerEvents: 'none' }} />
      </div>
      <div data-viewer-ui="true" style={chrome}>
        <ViewerTopBar onClose={onClose} title={once ? 'View once' : ''} right={once ? null : (
          <div style={{ position: 'relative', pointerEvents: 'auto' }}>
            <ViewerButton label="More" onClick={() => setMenuOpen((v) => !v)}><MoreVertical size={22} /></ViewerButton>
            {menuOpen && (
              <div onClick={(e) => e.stopPropagation()} style={{ position: 'absolute', top: 54, right: 0, background: '#1C1C1F', borderRadius: 14, overflow: 'hidden', width: 200, boxShadow: '0 12px 32px rgba(0,0,0,0.5)', fontFamily: FONT }}>
                <div style={{ marginTop: -1 }}>
                  {onEdit && item(art ? 'Edit this art' : 'Draw on it', () => onEdit(url))}
                  {item('Save to phone', () => silentDownload(url, 'zchat-photo.jpg'))}
                  {onForward && item('Forward', onForward)}
                  {onReport && item('Report', onReport, true)}
                </div>
              </div>
            )}
          </div>
        )} />
        {(caption || art) && (
          <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '34px 18px calc(20px + env(safe-area-inset-bottom))', background: caption ? 'linear-gradient(180deg, transparent, rgba(0,0,0,0.75))' : 'none', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 14, fontFamily: FONT, pointerEvents: 'none' }}>
            {art && (
              <button type="button" onClick={(e) => { e.stopPropagation(); onEdit(url); }}
                style={{ pointerEvents: 'auto', height: 46, padding: '0 22px', borderRadius: 23, border: '1.5px solid rgba(255,255,255,0.32)', background: 'rgba(24,24,27,0.84)', color: 'white', fontWeight: 800, fontSize: 15, fontFamily: FONT, display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', boxShadow: '0 4px 14px rgba(0,0,0,0.5)' }}>
                <PaintToolIcon k="brush" size={19} />Edit this art
              </button>
            )}
            {caption && <div style={{ width: '100%', color: 'white', fontSize: 15, lineHeight: 1.4, textAlign: 'center', wordBreak: 'break-word' }}>{caption}</div>}
          </div>
        )}
      </div>
    </div>
  );
}

function MessageActionBar({ count, canEditActions, onCancel, onForward, onDeleteForMe, onDeleteForEveryone, onReport }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const btn = { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, cursor: 'pointer', color: theme.ink, fontSize: 10, fontWeight: 600, flexShrink: 0, minWidth: 52 };
  return (
    <div style={{ background: theme.rowBg }} className="zchat-fade">
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 16px 6px' }}>
        <X size={18} style={{ cursor: 'pointer', color: theme.ink, flexShrink: 0 }} onClick={onCancel} />
        <span style={{ fontWeight: 800, fontSize: 14, color: theme.ink }}>{count} selected</span>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 14, padding: '2px 16px 10px' }}>
        <div style={btn} onClick={onForward}><Forward size={16} /><span>Forward</span></div>
        {canEditActions.canReport && <div style={btn} onClick={onReport}><Flag size={16} color={theme.danger} /><span style={{ color: theme.danger }}>Report</span></div>}
        <div style={btn} onClick={onDeleteForMe}><Trash2 size={16} /><span style={{ whiteSpace: 'nowrap' }}>Delete me</span></div>
        {canEditActions.allMine && <div style={btn} onClick={onDeleteForEveryone}><Trash2 size={16} color={theme.danger} /><span style={{ color: theme.danger, whiteSpace: 'nowrap' }}>Delete all</span></div>}
      </div>
    </div>
  );
}

function ForwardPicker({ conversations, groups = [], onCancel, onPick, myId }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const timer = useRef(null);

  const [suggested, setSuggested] = useState([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      const { data: f } = await supabase.from('follows').select('following_id').eq('follower_id', myId).eq('status', 'accepted').limit(200);
      const ids = (f || []).map((x) => x.following_id);
      if (!ids.length) return;
      const { data: profs } = await supabase.from('profiles').select('*').in('id', ids).eq('is_deleted', false);
      if (!alive) return;
      const list = sanitizeAvatarList(profs, myId).sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      setSuggested(list);
      setResults(list);
    })();
    return () => { alive = false; };
  }, [myId]);
  const doSearch = (val) => {
    setQ(val);
    clearTimeout(timer.current);
    if (val.trim().length < 2) { setResults(suggested); return; }
    setSearching(true);
    timer.current = setTimeout(async () => {
      const { data } = await searchAccounts(val.trim());
      setResults(sanitizeAvatarList(data, myId).filter((u) => u.id !== myId));
      setSearching(false);
    }, 300);
  };

  const list = q.trim().length >= 2 ? results : conversations.map((c) => c.otherProfile);

  const searchingMode = q.trim().length >= 2;
  return (
    <FullPage title="Forward to" subtitle="Pick a person" onBack={onCancel} zIndex={90}>
      <label style={{ display: 'flex', alignItems: 'center', gap: 8, height: 40, padding: '0 12px', borderRadius: 12, background: theme.rowBg, color: theme.muted, margin: '8px 0 6px' }}>
        <Search size={17} />
        <input value={q} onChange={(e) => doSearch(e.target.value)} placeholder="Search by username" aria-label="Search people to forward to" autoCapitalize="none"
          style={{ flex: 1, minWidth: 0, border: 0, outline: 0, background: 'transparent', color: theme.ink, fontFamily: FONT, fontSize: 15 }} />
        {searching ? <Spinner size={14} color={theme.muted} /> : q ? <X size={16} style={{ cursor: 'pointer' }} onClick={() => doSearch('')} /> : null}
      </label>
      {!searchingMode && list.length > 0 && <div style={{ padding: '14px 2px 4px', fontSize: 13, fontWeight: 600, color: theme.muted }}>Recent chats</div>}
      {list.length === 0 && (searchingMode || !groups.length) && (
        <EmptyState art={searchingMode ? 'nothing' : 'nochats'} title={searchingMode ? 'No one found' : 'No chats yet'} text={searchingMode ? 'Check the spelling of the username.' : 'Search for someone by username to forward this to them.'} />
      )}
      {list.map((p) => (
        <UserListRow key={p.id} profile={p} onClick={() => onPick(p)} rightContent={<ChevronRight size={18} color={theme.muted} />} />
      ))}
      {!searchingMode && groups.length > 0 && <div style={{ padding: '14px 2px 4px', fontSize: 13, fontWeight: 600, color: theme.muted }}>Groups</div>}
      {!searchingMode && groups.map((g) => (
        <div key={g.id} role="button" aria-label={`Forward to ${g.name}`} onClick={() => onPick({ __group: g })} style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '9px 0', minHeight: 66, cursor: 'pointer' }}>
          <GroupAvatar avatar={g.avatar} name={g.name} size={48} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 15, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{g.name}</div>
            <div style={{ fontSize: 13, color: theme.muted, marginTop: 1 }}>Group</div>
          </div>
          <ChevronRight size={18} color={theme.muted} />
        </div>
      ))}
    </FullPage>
  );
}


