function SmartMenu({ anchorEl, open, onClose, children, width = 170 }) {
  useBackClose(!!open, onClose);
  const [pos, setPos] = useState(null);
  const boxRef = useRef(null);
  useLayoutEffect(() => {
    if (!open || !anchorEl) { setPos(null); return undefined; }
    const compute = () => {
      const r = anchorEl.getBoundingClientRect();
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const maxH = Math.max(120, vh - 16);
      const h = Math.min(boxRef.current ? boxRef.current.scrollHeight : 170, maxH);
      let top = r.bottom + 6;
      if (top + h > vh - 8) top = r.top - h - 6 >= 8 ? r.top - h - 6 : Math.max(8, vh - 8 - h);
      let left = r.right - width;
      if (left < 8) left = 8;
      if (left + width > vw - 8) left = Math.max(8, vw - width - 8);
      setPos({ top, left, maxH });
    };
    const onScroll = (e) => { if (boxRef.current && e.target && e.target.nodeType === 1 && boxRef.current.contains(e.target)) return; onClose(); };
    compute();
    window.addEventListener('resize', compute);
    window.addEventListener('scroll', onScroll, true);
    return () => { window.removeEventListener('resize', compute); window.removeEventListener('scroll', onScroll, true); };
  }, [open, anchorEl, onClose]);

  if (!open || !anchorEl) return null;
  return ReactDOM.createPortal(
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, zIndex: 998 }} />
      <div ref={boxRef} style={{ position: 'fixed', top: pos ? pos.top : 0, left: pos ? pos.left : 0, width, zIndex: 999, maxHeight: pos ? pos.maxH : undefined, overflowY: 'auto', overscrollBehavior: 'contain', visibility: pos ? 'visible' : 'hidden', borderRadius: 14 }} onClick={(e) => e.stopPropagation()} className="zchat-fade">
        {children}
      </div>
    </>,
    document.body
  );
}

function friendlyError(error, fallback = 'Something went wrong. Try again.') {
  const msg = String((error && error.message) || error || '').toLowerCase();
  if (!msg) return fallback;
  if (msg.includes('failed to fetch') || msg.includes('network') || msg.includes('load failed')) return "You're offline. Check your connection and try again.";
  if (msg.includes('rate limit') || msg.includes('too many')) return 'Too many tries. Wait a minute and try again.';
  if (msg.includes('already registered') || msg.includes('already been registered') || msg.includes('user already exists')) return 'That email already has an account. Sign in instead.';
  if (msg.includes('duplicate') || msg.includes('unique')) return 'That name is already taken. Try another one.';
  if (msg.includes('invalid login') || msg.includes('invalid credentials')) return 'Incorrect email or password.';
  if (msg.includes('same password') || msg.includes('different from the old')) return 'Choose a password you have not used before.';
  if (msg.includes('password') && (msg.includes('characters') || msg.includes('short') || msg.includes('weak'))) return 'Use a stronger password with at least 6 characters.';
  if (msg.includes('expired') || msg.includes('otp') || msg.includes('token')) return 'That code expired. Ask for a new one.';
  if (msg.includes('email') && msg.includes('invalid')) return 'Enter a valid email address.';
  if (msg.includes('too large') || msg.includes('exceeded the maximum')) return 'That file is too big.';
  if (msg.includes('permission') || msg.includes('policy') || msg.includes('not allowed') || msg.includes('jwt') || msg.includes('unauthorized')) return "You don't have permission to do that.";
  return fallback;
}

function formatListTime(value) {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const now = new Date();
  if (d.toDateString() === now.toDateString()) return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  if (d.toDateString() === yesterday.toDateString()) return 'Yesterday';
  if (now.getTime() - d.getTime() < 6 * 86400000) return d.toLocaleDateString([], { weekday: 'short' });
  return d.toLocaleDateString([], d.getFullYear() === now.getFullYear() ? { day: 'numeric', month: 'short' } : { day: 'numeric', month: 'short', year: 'numeric' });
}

function ReplyQuote({ m, label, onClick, bar, dim, compact }) {
  const { theme } = useTheme();
  const gs = m && m.type === 'text' ? parseGameMessage(m.content) : null;
  const loc = m && m.type === 'text' && !gs ? parseLocationMessage(m.content) : null;
  const isStickerImg = m && m.type === 'sticker' && m.content && (m.content.startsWith('/') || /^https?:/i.test(m.content));
  const muted = dim || theme.muted;
  let icon = null;
  let text = quoteTextFor(m);
  if (gs) icon = gs.g === 'score' ? <TrophyIcon size={13} color="#F59E0B" /> : <GamepadIcon size={13} color={theme.coral} />;
  else if (loc) icon = <Compass size={13} color={theme.coral} />;
  else if (m && m.type === 'text' && parsePoll(m.content)) icon = <PollIcon size={13} color={theme.coral} />;
  else if (m && m.type === 'text' && parseEventMsg(m.content)) icon = <CalendarIcon size={13} color={theme.coral} />;
  else if (m && m.type === 'audio') icon = <Mic size={13} color={theme.coral} />;
  else if (m && m.type === 'image') icon = <Camera size={13} color={theme.coral} />;
  else if (m && m.type === 'video') icon = <VideoIcon size={13} color={theme.coral} />;
  const thumb = m && (m.type === 'image' || m.type === 'video') && m.media_url && !parseOnce(m) ? (
    <div style={{ width: compact ? 34 : 40, height: compact ? 34 : 40, borderRadius: 8, overflow: 'hidden', flexShrink: 0, background: 'rgba(0,0,0,0.25)', position: 'relative' }}>
      {m.type === 'image'
        ? <img src={m.media_url} alt="" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        : <VideoThumb src={m.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />}
      {m.type === 'video' && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Play size={14} color="white" fill="white" /></div>}
    </div>
  ) : isStickerImg ? (
    <img src={m.content} alt="" draggable={false} style={{ width: compact ? 30 : 36, height: compact ? 30 : 36, objectFit: 'contain', flexShrink: 0 }} />
  ) : null;
  const textStyle = m && m.type === 'text' && !gs && !loc && !isSpecialContent(m.content) ? { ...fontStyleCss(m.text_font), ...(m.text_color ? { color: m.text_color } : {}) } : {};
  return (
    <div onClick={onClick} style={{ display: 'flex', alignItems: 'stretch', gap: 8, borderRadius: 10, overflow: 'hidden', background: 'rgba(0,0,0,0.06)', cursor: onClick ? 'pointer' : 'default', minWidth: 0 }}>
      <div style={{ width: 3, flexShrink: 0, background: bar || theme.coral }} />
      <div style={{ flex: 1, minWidth: 0, padding: compact ? '4px 0' : '5px 0', display: 'flex', alignItems: 'center', gap: 8 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          {label && <div style={{ fontWeight: 700, color: bar || theme.coralDeep, fontSize: 10.5, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>}
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11.5, color: muted, lineHeight: 1.35, minWidth: 0 }}>
            {icon && <span style={{ display: 'flex', flexShrink: 0 }}>{icon}</span>}
            <span style={{ ...textStyle, overflow: 'hidden', textOverflow: 'ellipsis', display: '-webkit-box', WebkitLineClamp: compact ? 1 : 2, WebkitBoxOrient: 'vertical', wordBreak: 'break-word' }}>{text}</span>
          </div>
        </div>
        {thumb && <div style={{ paddingRight: 6, display: 'flex' }}>{thumb}</div>}
      </div>
    </div>
  );
}
const SPECIAL_PREFIXES = ['zpoll:', 'zevent:', 'zdice:', 'zlist:', 'zbill:', 'zcount:'];
function isSpecialContent(content) {
  return typeof content === 'string' && SPECIAL_PREFIXES.some((p) => content.indexOf(p) === 0);
}
function quoteTextFor(m) {
  if (!m) return '';
  if (m.type === 'text') {
    const gs = parseGameMessage(m.content);
    if (gs) return gs.g === 'score' ? `High score in ${gameTitle(gs)}` : gameTitle(gs);
    const qp = parsePoll(m.content);
    if (qp) return `Poll: ${qp.q}`;
    const qe = parseEventMsg(m.content);
    if (qe) return `Event: ${qe.t}`;
    const qd = parseDice(m.content);
    if (qd) return diceSummary(qd);
    const qx = extraCardSummary(m.content);
    if (qx) return qx;
    if (parseLocationMessage(m.content)) return 'Location';
    if (parseProfileLink(m.content)) return 'Profile';
    if (parsePostLink(m.content)) return 'Post';
    return m.content || '';
  }
  if (parseOnce(m)) return m.type === 'video' ? 'View once video' : 'View once photo';
  if (parseBlur(m)) return m.type === 'video' ? 'Hidden video' : 'Hidden photo';
  if (m.type === 'image') return 'Photo';
  if (m.type === 'audio' || m.type === 'voice') return 'Voice message';
  if (m.type === 'sticker') return 'Sticker';
  if (m.type === 'system') return 'Message';
  return 'Video';
}
function plainPreviewText(text) {
  return String(text || '')
    .replace(/\|\|[^|\n]+?\|\|/g, '\u2022\u2022\u2022\u2022')
    .replace(/```[a-zA-Z0-9]*\n?([\s\S]*?)```/g, '$1')
    .replace(/`([^`]*)`/g, '$1')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/(^|\s)[*_]([^*_]+)[*_](?=\s|$)/g, '$1$2')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*[-*]\s+/gm, '')
    .replace(/\s*\n+\s*/g, ' ')
    .trim();
}
function describeMessage(m) {
  if (!m) return { kind: 'none', text: '' };
  if (m.deleted) return { kind: 'deleted', text: 'This message was deleted' };
  if (m.story_id) {
    if (m.content === STORY_MENTION_TEXT || m.content === STORY_GROUP_MENTION_TEXT || m.content === STORY_SHARE_TEXT) return { kind: 'story', text: m.content };
    return { kind: 'story', text: `Story reply: ${m.content || ''}` };
  }
  switch (m.type) {
    case 'image': return parseBlur(m) ? { kind: 'hidden', text: 'Hidden photo' } : { kind: 'image', text: parseOnce(m) ? 'View once photo' : (m.content || 'Photo') };
    case 'video': return parseBlur(m) ? { kind: 'hidden', text: 'Hidden video' } : { kind: 'video', text: parseOnce(m) ? 'View once video' : (m.content || 'Video') };
    case 'audio': return { kind: 'audio', text: 'Voice message' };
    case 'sticker': return { kind: 'sticker', text: 'Sticker' };
    case 'system': {
      const log = parseCallLog(m.content);
      if (log) {
        const Kind = log.k === 'video' ? 'Video' : 'Voice';
        const text = log.s === 'group' ? `${Kind} group call` : (log.s === 'missed' || log.s === 'declined') ? `Missed ${Kind.toLowerCase()} call` : `${Kind} call \u00b7 ${formatCallDuration((log.d || 0) * 1000)}`;
        return { kind: log.s === 'missed' || log.s === 'declined' ? 'callmissed' : 'call', text };
      }
      const note = systemNoteFor(m, null);
      return { kind: 'system', text: note ? note.text : (m.content || '') };
    }
    default: {
      const gs = parseGameMessage(m.content);
      if (gs) return { kind: 'game', text: gs.g === 'score' ? `High score in ${gameTitle(gs)}` : gameTitle(gs) };
      const dp = parsePoll(m.content);
      if (dp) return { kind: 'poll', text: `Poll: ${dp.q}` };
      const de = parseEventMsg(m.content);
      if (de) return { kind: 'event', text: `Event: ${de.t}` };
      const ddc = parseDice(m.content);
      if (ddc) return { kind: 'text', text: diceSummary(ddc) };
      const dxc = parseExtraCard(m.content);
      if (dxc) return { kind: dxc.k, text: extraCardSummary(m.content) };
      if (parseLocationMessage(m.content)) return { kind: 'location', text: 'Location' };
      if (parseProfileLink(m.content)) return { kind: 'contact', text: 'Shared a profile' };
      return { kind: 'text', text: parsePostLink(m.content) ? 'Shared a post' : plainPreviewText(m.content || '') };
    }
  }
}

const PREVIEW_ICONS = { image: Camera, video: VideoIcon, audio: Mic, sticker: Smile, deleted: Ban, story: StatusIcon, call: Phone, callmissed: PhoneMissedIcon, game: GamepadIcon, location: Compass, poll: PollIcon, event: CalendarIcon, list: ChecklistIcon, bill: BillIcon, count: CountdownIcon, contact: ContactCardIcon, hidden: HiddenPhotoIcon };
function PhoneMissedIcon({ size = 14, style }) { return <Phone size={size} color="#FF3B30" style={style} />; }

function PreviewLine({ preview, prefix, color, weight = 400, size = 12 }) {
  const Icon = preview ? PREVIEW_ICONS[preview.kind] : null;
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 4, minWidth: 0, fontSize: size, color, fontWeight: weight, fontStyle: preview && preview.kind === 'deleted' ? 'italic' : 'normal' }}>
      {prefix ? <span style={{ flexShrink: 0 }}>{prefix}</span> : null}
      {Icon ? <Icon size={size + 1} style={{ flexShrink: 0 }} /> : null}
      <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', minWidth: 0 }}>{preview ? preview.text : ''}</span>
    </span>
  );
}

function activityLabel(kind) {
  const labels = {
    typing: 'typing',
    sticker: 'choosing a sticker',
    photo: 'selecting a photo',
    video: 'selecting a video',
    voice: 'recording a voice message',
  };
  return `${labels[kind] || 'typing'}\u2026`;
}

function InAppMessageToast({ toast, top, onOpen, onDismiss }) {
  const { theme } = useTheme();
  const startRef = useRef(null);
  const suppressRef = useRef(false);
  const holdRef = useRef(false);
  const [dragY, setDragY] = useState(0);

  useEffect(() => {
    setDragY(0);
    let left = 6000;
    const t = setInterval(() => {
      if (!holdRef.current) left -= 250;
      if (left <= 0) { clearInterval(t); onDismiss(); }
    }, 250);
    return () => clearInterval(t);
  }, [toast.key]);

  return (
    <div key={toast.key} className="zchat-toast-in"
      onPointerDown={(e) => { e.stopPropagation(); holdRef.current = true; startRef.current = { y: e.clientY, moved: false }; }}
      onPointerMove={(e) => {
        const s = startRef.current;
        if (!s) return;
        const dy = e.clientY - s.y;
        if (Math.abs(dy) > 12) s.moved = true;
        if (s.moved) setDragY(Math.min(0, dy));
      }}
      onPointerUp={(e) => {
        e.stopPropagation();
        holdRef.current = false;
        const s = startRef.current;
        startRef.current = null;
        if (s && s.moved) {
          suppressRef.current = true;
          setTimeout(() => { suppressRef.current = false; }, 80);
          if (dragY < -28) onDismiss(); else setDragY(0);
        }
      }}
      onPointerCancel={() => { holdRef.current = false; startRef.current = null; setDragY(0); }}
      onClick={(e) => { e.stopPropagation(); e.preventDefault(); if (suppressRef.current) return; onOpen(); }}
      style={{
        position: 'fixed', top, left: 10, right: 10, zIndex: 300, maxWidth: 420, margin: '0 auto',
        display: 'flex', alignItems: 'center', gap: 11, padding: '11px 14px 11px 11px', borderRadius: 20,
        background: theme.dark ? '#1A1C24' : '#FFFFFF',
        border: `1px solid ${theme.border}`, borderLeft: toast.accent === 'missed' ? '4px solid #FF3B30' : `1px solid ${theme.border}`, boxShadow: '0 12px 32px rgba(0,0,0,0.3)',
        transform: `translateY(${dragY}px)`, transition: startRef.current ? 'none' : 'transform 0.2s ease',
        cursor: 'pointer', touchAction: 'pan-x', userSelect: 'none', WebkitTapHighlightColor: 'transparent',
      }}>
      <div style={{ position: 'relative', flexShrink: 0, pointerEvents: 'none' }}>
        {toast.kind === 'notice' ? (
          toast.icon ? <MailBadgeIcon type={toast.icon === 'warning' ? 'report_warning' : toast.icon === 'mention' ? 'mention' : toast.icon === 'update' ? 'update' : toast.icon === 'badge' ? 'badge' : 'mail'} badgeTier={toast.badgeTier} size={42} />
            : toast.isGroupIcon ? <GroupAvatar avatar={toast.groupAvatar} name={toast.title} size={42} /> : <Avatar emoji={toast.avatar} name={toast.avatarName} frame={toast.frame} size={42} />
        ) : toast.kind === 'group'
          ? <GroupAvatar avatar={toast.groupAvatar} name={toast.title} size={42} />
          : <Avatar emoji={toast.avatar} name={toast.avatarName} frame={toast.frame} size={42} />}
        {toast.kind === 'group' && (
          <div style={{ position: 'absolute', right: -4, bottom: -4, borderRadius: '50%', border: `2px solid ${theme.panelBg}` }}>
            <Avatar emoji={toast.avatar} name={toast.avatarName} frame={toast.frame} size={20} />
          </div>
        )}
      </div>
      <div style={{ flex: 1, minWidth: 0, pointerEvents: 'none' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
          <span style={{ fontSize: 13.5, fontWeight: 800, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}><NameBadge name={toast.title} verified={toast.verified} custom={toast.customBadge} size={12} /></span>
          <span style={{ fontSize: 10.5, color: theme.muted, flexShrink: 0 }}>now</span>
        </div>
        {toast.kind !== 'notice' && prefOn('zchat-hide-previews')
          ? <PreviewLine preview={{ kind: 'text', text: 'New message' }} color={theme.muted} size={12.5} />
          : <PreviewLine preview={toast.preview} prefix={toast.prefix} color={theme.muted} size={12.5} />}
      </div>
    </div>
  );
}

function ChatRowSheet({ title, subtitle, avatar, actions, onClose, zIndex = 94, portal = false, peek = null }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const drag = useSheetDrag(onClose);
  const body = (
    <div onClick={onClose} className="zchat-fade" style={{
      position: 'fixed', inset: 0, zIndex, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT,
      background: 'rgba(0,0,0,0.45)',
    }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ transform: drag.sheetStyle.transform, transition: drag.sheetStyle.transition,
        width: '100%', maxWidth: 460, maxHeight: 'min(86vh, calc(100% - 24px))', display: 'flex', flexDirection: 'column', background: theme.panelBg, borderRadius: '24px 24px 0 0', overflow: 'hidden',
        paddingBottom: 'calc(8px + env(safe-area-inset-bottom))', boxShadow: '0 -10px 40px rgba(0,0,0,0.25)',
      }}>
        <div {...drag.sheetProps} style={{ touchAction: 'none', flexShrink: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '10px 0 2px' }}>
            <div style={{ width: 38, height: 4, borderRadius: 2, background: theme.border }} />
          </div>
          {(title || avatar) && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 18px 12px', borderBottom: `1px solid ${theme.border}` }}>
              {avatar}
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 800, fontSize: 15, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</div>
                {subtitle && <div style={{ fontSize: 12, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{subtitle}</div>}
              </div>
            </div>
          )}
        </div>
        <div data-sheet-scroll="true" style={{ overflowY: 'auto', minHeight: 0, WebkitOverflowScrolling: 'touch', touchAction: 'pan-y', paddingTop: peek ? 0 : 4 }}>
          {peek}
          {actions.filter(Boolean).map((a) => (
            <div key={a.label} role="button" aria-label={a.label} onClick={() => { onClose(); a.onClick(); }} className="zchat-row-press" style={{
              display: 'flex', alignItems: 'center', gap: 14, padding: a.hint ? '9px 20px' : '14px 20px', cursor: 'pointer', boxSizing: 'border-box', minHeight: 52,
              fontSize: 15, fontWeight: 600, color: a.danger ? theme.danger : theme.ink,
            }}>
              <span style={{ display: 'flex', width: 24, justifyContent: 'center', color: a.danger ? theme.danger : theme.muted, flexShrink: 0 }}>{a.icon}</span>
              <span style={{ flex: 1, minWidth: 0 }}>
                {a.label}
                {a.hint && <span style={{ display: 'block', fontSize: 12, color: theme.muted, fontWeight: 500, marginTop: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{a.hint}</span>}
              </span>
              {a.right}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
  return portal ? <Portal>{body}</Portal> : body;
}

function ConfirmSheet({ title, text, confirmLabel = 'Confirm', danger = true, onConfirm, onCancel, busy = false, zIndex = 95 }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  return (
    <div onClick={() => !busy && onCancel()} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT, background: 'rgba(0,0,0,0.45)' }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxWidth: 460, background: theme.panelBg, borderRadius: '24px 24px 0 0', padding: '18px 16px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))', boxShadow: '0 -10px 40px rgba(0,0,0,0.25)' }}>
        <div style={{ textAlign: 'center', padding: '4px 10px 14px' }}>
          <div style={{ fontSize: 17, fontWeight: 800, color: theme.ink }}>{title}</div>
          {text && <div style={{ fontSize: 13.5, color: theme.muted, lineHeight: 1.55, marginTop: 6 }}>{text}</div>}
        </div>
        <button onClick={() => !busy && onConfirm()} disabled={busy} className="zchat-press" style={{ width: '100%', height: 50, borderRadius: 16, border: 'none', background: danger ? theme.danger : theme.coral, color: 'white', fontWeight: 800, fontSize: 15.5, fontFamily: FONT, cursor: 'pointer', opacity: busy ? 0.6 : 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{busy ? <Spinner size={16} /> : confirmLabel}</button>
        <button onClick={() => !busy && onCancel()} className="zchat-press" style={{ width: '100%', height: 50, borderRadius: 16, border: 'none', background: theme.rowBg, color: theme.ink, fontWeight: 700, fontSize: 15.5, fontFamily: FONT, cursor: 'pointer', marginTop: 8 }}>Cancel</button>
      </div>
    </div>
  );
}

function MessageContextMenu({ onReadAloud, onRemind, message, isMine, canEditText, canModerate, anchorRect, bubble, isPinned, onPin, onUnpin, onClose, onReact, onReply, onCopy, onEdit, onForward, onReport, onDeleteForMe, onDeleteForEveryone, onSelectMultiple, onSave, onToggleSave, isSaved, onInfo, onEditArt, onShareImage }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [showFullEmoji, setShowFullEmoji] = useState(false);
  const [favKeys, setFavKeys] = useState(() => getFavoriteStickerKeys());
  const [measured, setMeasured] = useState({ menu: 0, bubble: 0 });
  const [more, setMore] = useState(false);
  const menuRef = useRef(null);
  const bubbleRef = useRef(null);
  const openedAtRef = useRef(Date.now());
  const guard = (fn) => (...args) => { if (Date.now() - openedAtRef.current < 450) return; if (fn) fn(...args); };
  const stickerMatch = message.type === 'sticker' ? STICKERS.find((s) => s.file === message.content) : null;

  useEffect(() => {
    setMeasured({ menu: menuRef.current ? menuRef.current.scrollHeight : 0, bubble: bubbleRef.current ? bubbleRef.current.offsetHeight : 0 });
  }, []);
  useLayoutEffect(() => {
    if (!more || !menuRef.current) return;
    const h = menuRef.current.scrollHeight;
    setMeasured((m) => (m.menu === h ? m : { ...m, menu: h }));
  }, [more]);

  const vh = window.visualViewport ? window.visualViewport.height : window.innerHeight;
  const vw = window.innerWidth;
  const rect = anchorRect || { top: vh * 0.3, left: Math.max(0, (vw - Math.min(vw, 560)) / 2), width: Math.min(vw, 560), height: 60 };
  const maxBubble = Math.round(vh * 0.38);
  const barH = 50;
  const gap = 10;
  const minTop = 52 + barH + gap;
  const room = vh - 14 - minTop;
  const menuNat = measured.menu || 300;
  const bubbleNat = Math.min(measured.bubble || rect.height, maxBubble);
  const bubbleH = Math.max(Math.min(bubbleNat, 96), Math.min(bubbleNat, room - menuNat - gap));
  const menuMax = Math.max(160, room - bubbleH - gap);
  const menuH = Math.min(menuNat, menuMax);
  const maxTop = vh - 14 - menuH - gap - bubbleH;
  const top = Math.max(minTop, Math.min(rect.top, Math.max(minTop, maxTop)));
  const special = message.type === 'text' && !!(parseGameMessage(message.content) || isSpecialContent(message.content));
  const onceMsg = !!parseOnce(message);
  const sideStyle = isMine
    ? { right: Math.max(10, vw - (rect.left + rect.width) + 14) }
    : { left: Math.max(10, rect.left + 14) };
  const ready = measured.menu > 0;

  const row = (icon, label, onClick, danger, key, fresh) => (
    <div key={key || label} role="button" aria-label={label} onClick={guard(onClick)} className={fresh ? 'zchat-row-press zchat-tab-in' : 'zchat-row-press'} style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, padding: '12px 16px', cursor: 'pointer',
      fontSize: 14.5, fontWeight: 600, color: danger ? theme.danger : theme.ink, borderTop: `1px solid ${theme.border}`,
    }}>
      <span>{label}</span>
      <span style={{ display: 'flex' }}>{icon}</span>
    </div>
  );
  const nd = !message.deleted;
  const plainText = message.type === 'text' && !special;
  const paintImg = message.type === 'image' && !!onEditArt && !onceMsg && isPaintUrl(message.media_url);
  const allRows = [
    nd && { k: 'reply', main: true, icon: <Reply size={18} />, label: 'Reply', on: onReply },
    nd && plainText && { k: 'copy', main: true, icon: <Copy size={18} />, label: 'Copy', on: onCopy },
    nd && !onceMsg && (message.type === 'image' || message.type === 'video') && { k: 'save', main: true, icon: <Download size={18} />, label: 'Save', on: onSave },
    nd && canEditText && !special && { k: 'edit', main: true, icon: <Edit3 size={18} />, label: 'Edit', on: onEdit },
    nd && !onceMsg && message.type === 'image' && onEditArt && { k: 'art', main: paintImg, icon: <PaintToolIcon k="brush" size={18} />, label: paintImg ? 'Edit this art' : 'Draw on it', on: onEditArt },
    nd && !onceMsg && !(message.type === 'text' && parseGameMessage(message.content)) && { k: 'fwd', main: true, icon: <Forward size={18} />, label: 'Forward', on: onForward },
    nd && stickerMatch && { k: 'fav', main: true, icon: <Star_ size={18} color="#FFB800" filled={favKeys.has(stickerMatch.key)} />, label: favKeys.has(stickerMatch.key) ? 'Remove from favorites' : 'Add to favorites', on: () => { setFavKeys(new Set(toggleFavoriteSticker(stickerMatch.key))); onClose(); } },
    isMine && nd && { k: 'unsend', main: true, icon: <Trash2 size={18} />, label: 'Unsend', on: onDeleteForEveryone, danger: true },
    nd && plainText && onReadAloud && { k: 'read', icon: <Volume2 size={18} />, label: 'Read aloud', on: onReadAloud },
    nd && plainText && onShareImage && { k: 'img', icon: <ImageIcon size={18} />, label: 'Share as image', on: onShareImage },
    nd && !onceMsg && message.type !== 'system' && onToggleSave && { k: 'saved', icon: <Bookmark size={18} fill={isSaved ? 'currentColor' : 'none'} />, label: isSaved ? 'Remove from Saved' : 'Add to Saved', on: onToggleSave },
    nd && message.type !== 'system' && onPin && { k: 'pin', icon: <Pin_ size={18} color={theme.ink} />, label: isPinned ? 'Unpin' : 'Pin', on: isPinned ? onUnpin : onPin },
    nd && message.type !== 'system' && onRemind && { k: 'remind', icon: <Clock size={18} />, label: 'Remind me', on: onRemind },
    { k: 'select', icon: <CheckCheck size={18} />, label: 'Select', on: onSelectMultiple },
    onInfo && message.type !== 'system' && { k: 'info', icon: <HelpCircle size={18} />, label: 'Info', on: onInfo },
    !isMine && nd && { k: 'report', icon: <Flag size={18} />, label: 'Report', on: onReport, danger: true },
    { k: 'delme', icon: <Trash2 size={18} />, label: 'Delete for me', on: onDeleteForMe, danger: true },
    !isMine && canModerate && nd && { k: 'delall', icon: <Trash2 size={18} />, label: 'Delete for everyone', on: onDeleteForEveryone, danger: true },
  ].filter(Boolean);
  const mainRows = allRows.filter((r) => r.main);
  const extraRows = allRows.filter((r) => !r.main);
  const collapse = extraRows.length > 1 && mainRows.length > 0;
  const shownRows = !collapse || more ? [...mainRows, ...extraRows] : mainRows;
  const moveT = 'top 0.24s cubic-bezier(0.2, 0.8, 0.2, 1)';

  return (
    <div onClick={guard(onClose)} onContextMenu={(e) => e.preventDefault()} style={{ position: 'fixed', inset: 0, zIndex: 95 }}>
      <div className="zchat-fade" style={{
        position: 'absolute', inset: 0,
        background: theme.dark ? 'rgba(0,0,0,0.6)' : 'rgba(18,18,26,0.38)',
      }} />
      {!message.deleted && !onceMsg && !(message.type === 'text' && isSpecialContent(message.content)) && (
        <div onClick={(e) => e.stopPropagation()} className={ready ? 'zchat-pop' : ''} style={{
          position: 'absolute', top: top - barH - gap, ...sideStyle, height: barH, boxSizing: 'border-box', transition: ready ? moveT : 'none',
          display: 'flex', alignItems: 'center', gap: 6, padding: '0 10px', borderRadius: 26,
          background: theme.panelBg, boxShadow: '0 8px 28px rgba(0,0,0,0.28)', opacity: ready ? 1 : 0,
        }}>
          {getQuickReactions().map((e) => (
            <div key={e} onClick={guard(() => onReact(e))} style={{ fontSize: 25, cursor: 'pointer', padding: '0 2px', lineHeight: 1 }}>{e}</div>
          ))}
          <div onClick={() => setShowFullEmoji(true)} style={{
            width: 30, height: 30, borderRadius: '50%', background: theme.rowBg, display: 'flex',
            alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0, color: theme.muted, fontSize: 18, fontWeight: 800,
          }}>+</div>
        </div>
      )}
      <div ref={bubbleRef} data-zclone="1" style={{
        position: 'absolute', top, left: rect.left, width: rect.width, paddingLeft: 18, paddingRight: 18, boxSizing: 'border-box',
        maxHeight: measured.bubble ? bubbleH : maxBubble, overflow: 'hidden', pointerEvents: 'none', opacity: ready ? 1 : 0,
        WebkitMaskImage: measured.bubble && bubbleNat > bubbleH ? 'linear-gradient(180deg, #000 78%, transparent)' : 'none', maskImage: measured.bubble && bubbleNat > bubbleH ? 'linear-gradient(180deg, #000 78%, transparent)' : 'none',
        transform: ready ? 'scale(1)' : 'scale(0.97)', transition: `transform 0.18s ease, opacity 0.12s ease${ready ? `, ${moveT}` : ''}`,
      }}>{bubble}</div>
      <div ref={menuRef} onClick={(e) => e.stopPropagation()} className={ready ? 'zchat-pop' : ''} style={{
        position: 'absolute', top: top + bubbleH + gap, ...sideStyle, width: 236, borderRadius: 16, overflowX: 'hidden', overflowY: ready && menuNat > menuMax ? 'auto' : 'hidden', transition: ready ? moveT : 'none',
        maxHeight: ready ? menuMax : undefined, WebkitOverflowScrolling: 'touch', overscrollBehavior: 'contain',
        background: theme.panelBg, boxShadow: '0 10px 32px rgba(0,0,0,0.3)', opacity: ready ? 1 : 0,
      }}>
        <div style={{ marginTop: -1 }}>
          {shownRows.map((r) => row(r.icon, r.label, r.on, r.danger, r.k, more && !r.main))}
          {collapse && !more && (
            <div key="more" role="button" aria-label="More actions" onClick={guard(() => { hapticTap(); setMore(true); })} className="zchat-row-press" style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, padding: '12px 16px', cursor: 'pointer',
              fontSize: 14.5, fontWeight: 600, color: theme.ink, borderTop: `1px solid ${theme.border}`,
            }}>
              <span>More</span>
              <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" style={{ display: 'block' }}><circle cx="5" cy="12" r="1.9" fill="currentColor" /><circle cx="12" cy="12" r="1.9" fill="currentColor" /><circle cx="19" cy="12" r="1.9" fill="currentColor" /></svg>
            </div>
          )}
        </div>
      </div>
      {showFullEmoji && (
        <FullEmojiPicker onClose={() => setShowFullEmoji(false)} onPick={(e) => { onReact(e); setShowFullEmoji(false); }} />
      )}
    </div>
  );
}

function loadImageElement(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = url;
  });
}

function PhotoCropEditor({ file, onCancel, onConfirm }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [url, setUrl] = useState(null);
  const [natural, setNatural] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [saving, setSaving] = useState(false);
  const pointersRef = useRef(new Map());
  const pinchRef = useRef(null);
  const imgRef = useRef(null);
  const size = Math.max(220, Math.min((typeof window !== 'undefined' ? window.innerWidth : 360) - 48, 340));

  useEffect(() => {
    const u = URL.createObjectURL(file);
    setUrl(u);
    loadImageElement(u).then((img) => { imgRef.current = img; setNatural({ w: img.naturalWidth, h: img.naturalHeight }); }).catch(() => onCancel());
    return () => URL.revokeObjectURL(u);
  }, [file]);

  const base = natural ? Math.max(size / natural.w, size / natural.h) : 1;
  const dispW = natural ? natural.w * base * zoom : size;
  const dispH = natural ? natural.h * base * zoom : size;
  const clampOffset = (o, z) => {
    if (!natural) return o;
    const w = natural.w * base * z;
    const h = natural.h * base * z;
    const mx = Math.max(0, (w - size) / 2);
    const my = Math.max(0, (h - size) / 2);
    return { x: Math.max(-mx, Math.min(mx, o.x)), y: Math.max(-my, Math.min(my, o.y)) };
  };
  const setZoomSafe = (z) => {
    const nz = Math.max(1, Math.min(5, z));
    setZoom(nz);
    setOffset((o) => clampOffset(o, nz));
  };

  const onDown = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointersRef.current.size === 2) {
      const [a, b] = [...pointersRef.current.values()];
      pinchRef.current = { dist: Math.hypot(a.x - b.x, a.y - b.y), zoom };
    }
  };
  const onMove = (e) => {
    const prev = pointersRef.current.get(e.pointerId);
    if (!prev) return;
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pointersRef.current.size >= 2 && pinchRef.current) {
      const [a, b] = [...pointersRef.current.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      setZoomSafe(pinchRef.current.zoom * (dist / Math.max(1, pinchRef.current.dist)));
      return;
    }
    const dx = e.clientX - prev.x;
    const dy = e.clientY - prev.y;
    setOffset((o) => clampOffset({ x: o.x + dx, y: o.y + dy }, zoom));
  };
  const onUp = (e) => {
    pointersRef.current.delete(e.pointerId);
    if (pointersRef.current.size < 2) pinchRef.current = null;
  };

  const confirm = () => {
    if (!natural || !imgRef.current || saving) return;
    setSaving(true);
    const scale = base * zoom;
    const sw = size / scale;
    const sx = (dispW / 2 - size / 2 - offset.x) / scale;
    const sy = (dispH / 2 - size / 2 - offset.y) / scale;
    const out = 640;
    const canvas = document.createElement('canvas');
    canvas.width = out;
    canvas.height = out;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(imgRef.current, sx, sy, sw, sw, 0, 0, out, out);
    canvas.toBlob((blob) => { setSaving(false); if (blob) onConfirm(blob); }, 'image/jpeg', 0.92);
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, background: '#000', zIndex: 150, display: 'flex', flexDirection: 'column',
      paddingTop: 'env(safe-area-inset-top)', paddingBottom: 'env(safe-area-inset-bottom)', color: 'white',
    }} className="zchat-fade">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px' }}>
        <span onClick={onCancel} style={{ fontSize: 15, fontWeight: 600, cursor: 'pointer', padding: 6 }}>Cancel</span>
        <span style={{ fontSize: 15, fontWeight: 800 }}>Move and scale</span>
        <span onClick={confirm} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: 6, color: theme.gold }}>{saving ? <Spinner size={15} /> : 'Done'}</span>
      </div>
      <div style={{ flex: 1, minHeight: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden', position: 'relative' }}
        onWheel={(e) => setZoomSafe(zoom * (1 - e.deltaY * 0.0015))}>
        <div
          onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
          style={{ position: 'relative', width: size, height: size, touchAction: 'none', cursor: 'grab' }}>
          {url && natural ? (
            <img src={url} alt="" draggable={false} style={{
              position: 'absolute', left: 0, top: 0, width: dispW, height: dispH, maxWidth: 'none', userSelect: 'none', pointerEvents: 'none',
              transform: `translate(${size / 2 - dispW / 2 + offset.x}px, ${size / 2 - dispH / 2 + offset.y}px)`,
            }} />
          ) : (
            <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Spinner size={24} /></div>
          )}
          <div style={{ position: 'absolute', inset: 0, borderRadius: '50%', boxShadow: '0 0 0 2000px rgba(0,0,0,0.6)', border: '2px solid rgba(255,255,255,0.85)', pointerEvents: 'none' }} />
        </div>
      </div>
      <div style={{ padding: '14px 28px 22px', display: 'flex', alignItems: 'center', gap: 14 }}>
        <ImageIcon size={14} color="rgba(255,255,255,0.7)" />
        <input type="range" min="1" max="5" step="0.01" value={zoom} onChange={(e) => setZoomSafe(parseFloat(e.target.value))} style={{ flex: 1, accentColor: theme.coral }} />
        <ImageIcon size={20} color="rgba(255,255,255,0.9)" />
      </div>
    </div>
  );
}

const EDITOR_COLORS = ['#FFFFFF', '#111111', '#FF3B30', '#FF9500', '#FFCC00', '#34C759', '#2E7CF6', '#AF52DE', '#FF2D92'];
const BRUSH_SIZES = [4, 8, 14];

function strokeToPath(points, W, H) {
  if (!points || !points.length) return '';
  const d = points.map((p, i) => `${i ? 'L' : 'M'}${(p[0] * W).toFixed(1)} ${(p[1] * H).toFixed(1)}`).join(' ');
  return points.length === 1 ? `${d} l0.1 0` : d;
}

function paintEdits(ctx, item, W, H, offsetX, offsetY, scale, stickerImages = {}) {
  (item.stickers || []).forEach((st) => {
    const img = stickerImages[st.id];
    if (!img || !img.naturalWidth) return;
    const w = st.size * W * scale;
    const h = w * (img.naturalHeight / img.naturalWidth);
    ctx.drawImage(img, st.x * W * scale - offsetX - w / 2, st.y * H * scale - offsetY - h / 2, w, h);
  });
  item.strokes.forEach((s) => {
    if (!s.points.length) return;
    ctx.save();
    ctx.strokeStyle = s.color;
    ctx.lineWidth = s.size * W * scale;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    s.points.forEach((p, i) => {
      const x = p[0] * W * scale - offsetX;
      const y = p[1] * H * scale - offsetY;
      if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y);
    });
    if (s.points.length === 1) ctx.lineTo(s.points[0][0] * W * scale - offsetX + 0.1, s.points[0][1] * H * scale - offsetY);
    ctx.stroke();
    ctx.restore();
  });
  item.texts.forEach((t) => {
    const fontSize = t.size * W * scale;
    const lines = t.text.split('\n');
    const lineHeight = fontSize * 1.18;
    const cx = t.x * W * scale - offsetX;
    const cy = t.y * H * scale - offsetY;
    ctx.save();
    ctx.font = `800 ${fontSize}px Manrope, -apple-system, BlinkMacSystemFont, system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = t.color;
    ctx.shadowColor = 'rgba(0,0,0,0.45)';
    ctx.shadowBlur = fontSize * 0.25;
    ctx.shadowOffsetY = fontSize * 0.04;
    lines.forEach((line, i) => ctx.fillText(line, cx, cy + (i - (lines.length - 1) / 2) * lineHeight));
    ctx.restore();
  });
}

async function loadStickerImages(item) {
  const out = {};
  for (const st of item.stickers || []) {
    try { out[st.id] = await loadImageElement(st.src); } catch {}
  }
  return out;
}

async function prepareImageFile(file, url) {
  if (/gif/i.test(file.type)) return file;
  if (file.size < 1.8 * 1024 * 1024 && /jpe?g|png|webp/i.test(file.type)) return file;
  try {
    const img = await loadImageElement(url);
    const scale = Math.min(1, 2560 / Math.max(img.naturalWidth, img.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.naturalWidth * scale);
    canvas.height = Math.round(img.naturalHeight * scale);
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.88));
    return blob ? new File([blob], 'photo.jpg', { type: 'image/jpeg' }) : file;
  } catch {
    return file;
  }
}

async function exportEditedImage(item) {
  const hasEdits = item.crop || item.texts.length || item.strokes.length || (item.stickers || []).length || (item.filter && item.filter !== 'none');
  if (!hasEdits) return prepareImageFile(item.file, item.url);
  try { if (document.fonts && document.fonts.load) await document.fonts.load('800 40px Manrope'); } catch {}
  const img = await loadImageElement(item.url);
  const W = img.naturalWidth;
  const H = img.naturalHeight;
  const c = item.crop || { x: 0, y: 0, w: 1, h: 1 };
  const rw = c.w * W;
  const rh = c.h * H;
  const scale = Math.min(1, 2560 / Math.max(rw, rh));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(rw * scale));
  canvas.height = Math.max(1, Math.round(rh * scale));
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, c.x * W, c.y * H, rw, rh, 0, 0, canvas.width, canvas.height);
  if (item.filter && item.filter !== 'none') applyPhotoFilter(ctx, canvas.width, canvas.height, item.filter);
  paintEdits(ctx, item, W, H, c.x * W * scale, c.y * H * scale, scale, await loadStickerImages(item));
  const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.9));
  return blob ? new File([blob], 'photo.jpg', { type: 'image/jpeg' }) : item.file;
}

async function exportVideoOverlay(item) {
  if (!item.texts.length && !item.strokes.length && !(item.stickers || []).length) return null;
  if (!item.width || !item.height) return null;
  try { if (document.fonts && document.fonts.load) await document.fonts.load('800 40px Manrope'); } catch {}
  const scale = Math.min(1, 1280 / Math.max(item.width, item.height));
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(item.width * scale);
  canvas.height = Math.round(item.height * scale);
  paintEdits(canvas.getContext('2d'), item, item.width, item.height, 0, 0, scale, await loadStickerImages(item));
  const blob = await new Promise((res) => canvas.toBlob(res, 'image/png'));
  return blob ? new File([blob], 'overlay.png', { type: 'image/png' }) : null;
}

function MediaComposer({ files, recipientName, onCancel, onSend, onActivity, mode: composerMode = 'chat', mentionGroups = [], myId, privacyCtx, onceDefault, hiddenDefault }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [items, setItems] = useState(() => files.map((f, i) => ({
    id: `${Date.now()}-${i}`, kind: (f.type || '').startsWith('video') ? 'video' : 'image', file: f, url: URL.createObjectURL(f),
    width: 0, height: 0, duration: 0, crop: null, texts: [], strokes: [], stickers: [], trimStart: 0, trimEnd: null, filter: 'none',
  })));
  const [index, setIndex] = useState(0);
  const [mode, setMode] = useState('view');
  const [caption, setCaption] = useState('');
  const [once, setOnce] = useState(!!onceDefault);
  const [hideIt, setHideIt] = useState(!!hiddenDefault && !onceDefault);
  const [sending, setSending] = useState(false);
  const [stage, setStage] = useState({ w: 0, h: 0 });
  const [draftCrop, setDraftCrop] = useState(null);
  const [cropAspect, setCropAspect] = useState(null);
  const [brushColor, setBrushColor] = useState('#FF3B30');
  const [brushSize, setBrushSize] = useState(BRUSH_SIZES[1]);
  const [textDraft, setTextDraft] = useState(null);
  const [playing, setPlaying] = useState(false);
  const [mentions, setMentions] = useState([]);
  const [showMentionPicker, setShowMentionPicker] = useState(false);
  const [showStickerPicker, setShowStickerPicker] = useState(false);
  const [selectedSticker, setSelectedSticker] = useState(null);
  const isStory = composerMode === 'story';
  const isPost = composerMode === 'post';
  const stageRef = useRef(null);
  const innerRef = useRef(null);
  const videoRef = useRef(null);
  const livePathRef = useRef(null);
  const drawRef = useRef(null);
  const dragRef = useRef(null);
  const frameRef = useRef({ frameW: 1, frameH: 1, innerW: 1, innerH: 1 });
  const trimBarRef = useRef(null);
  const sentRef = useRef(false);
  useBackClose(mode !== 'view', () => setMode('view'));
  useBackClose(!!textDraft, () => saveText());
  useBackClose(showStickerPicker, () => setShowStickerPicker(false));

  const cur = items[Math.min(index, items.length - 1)];

  useEffect(() => {
    const el = stageRef.current;
    if (!el) return undefined;
    const measure = () => setStage({ w: el.clientWidth, h: el.clientHeight });
    measure();
    let ro = null;
    if (typeof ResizeObserver !== 'undefined') { ro = new ResizeObserver(measure); ro.observe(el); }
    window.addEventListener('resize', measure);
    return () => { if (ro) ro.disconnect(); window.removeEventListener('resize', measure); };
  }, []);

  useEffect(() => {
    items.forEach((it) => {
      if (it.width) return;
      if (it.kind === 'image') {
        loadImageElement(it.url).then((img) => updateItem(it.id, { width: img.naturalWidth, height: img.naturalHeight })).catch(() => updateItem(it.id, { width: 1000, height: 1000 }));
      } else {
        const v = document.createElement('video');
        v.preload = 'metadata';
        v.muted = true;
        v.playsInline = true;
        v.onloadedmetadata = () => updateItem(it.id, { width: v.videoWidth || 720, height: v.videoHeight || 1280, duration: Number.isFinite(v.duration) ? v.duration : 0 });
        v.onerror = () => updateItem(it.id, { width: 720, height: 1280 });
        v.src = it.url;
      }
    });
  }, [items.length]);

  useEffect(() => {
    if (!onActivity || !cur) return undefined;
    onActivity(cur.kind === 'video' ? 'video' : 'photo');
    const t = setInterval(() => onActivity(cur.kind === 'video' ? 'video' : 'photo'), 2000);
    return () => clearInterval(t);
  }, [cur && cur.kind]);

  useEffect(() => () => {
    if (!sentRef.current) items.forEach((it) => URL.revokeObjectURL(it.url));
  }, []);

  useEffect(() => { setMode('view'); setPlaying(false); }, [index]);

  function updateItem(id, patch) {
    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, ...(typeof patch === 'function' ? patch(it) : patch) } : it)));
  }

  if (!cur) return null;

  const W = cur.width || 1;
  const H = cur.height || 1;
  const region = mode === 'crop' || !cur.crop ? { x: 0, y: 0, w: 1, h: 1 } : cur.crop;
  const pad = mode === 'crop' ? 26 : 0;
  const availW = Math.max(60, stage.w - pad * 2);
  const availH = Math.max(60, stage.h - pad * 2);
  const scale = Math.min(availW / (region.w * W), availH / (region.h * H));
  const frameW = region.w * W * scale;
  const frameH = region.h * H * scale;
  const innerW = W * scale;
  const innerH = H * scale;
  frameRef.current = { frameW, frameH, innerW, innerH };

  const removeItem = (id) => {
    const it = items.find((x) => x.id === id);
    if (it) URL.revokeObjectURL(it.url);
    const next = items.filter((x) => x.id !== id);
    if (!next.length) { onCancel(); return; }
    setItems(next);
    setIndex((i) => Math.min(i, next.length - 1));
  };

  const startCrop = () => {
    setDraftCrop(cur.crop || { x: 0, y: 0, w: 1, h: 1 });
    setCropAspect(null);
    setMode('crop');
  };

  const applyAspect = (ratio) => {
    setCropAspect(ratio);
    if (!ratio) return;
    setDraftCrop(() => {
      let w = 1;
      let h = (w * W) / (H * ratio);
      if (h > 1) { h = 1; w = (h * H * ratio) / W; }
      return { x: (1 - w) / 2, y: (1 - h) / 2, w, h };
    });
  };

  const cropDown = (e, handle) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = { type: 'crop', handle, sx: e.clientX, sy: e.clientY, orig: { ...draftCrop } };
  };
  const cropMove = (e) => {
    const d = dragRef.current;
    if (!d || d.type !== 'crop') return;
    const { frameW: fw, frameH: fh } = frameRef.current;
    const dx = (e.clientX - d.sx) / fw;
    const dy = (e.clientY - d.sy) / fh;
    const o = d.orig;
    const min = 0.1;
    const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
    if (d.handle === 'move') {
      setDraftCrop({ ...o, x: clamp(o.x + dx, 0, 1 - o.w), y: clamp(o.y + dy, 0, 1 - o.h) });
      return;
    }
    const right = o.x + o.w;
    const bottom = o.y + o.h;
    let x = o.x;
    let y = o.y;
    let w = o.w;
    let h = o.h;
    if (d.handle.includes('w')) { x = clamp(o.x + dx, 0, right - min); w = right - x; }
    if (d.handle.includes('e')) { w = clamp(o.w + dx, min, 1 - o.x); }
    if (d.handle.includes('n')) { y = clamp(o.y + dy, 0, bottom - min); h = bottom - y; }
    if (d.handle.includes('s')) { h = clamp(o.h + dy, min, 1 - o.y); }
    if (cropAspect) {
      h = (w * W) / (H * cropAspect);
      const maxH = d.handle.includes('n') ? bottom : 1 - o.y;
      if (h > maxH) { h = maxH; w = (h * H * cropAspect) / W; }
      if (d.handle.includes('w')) x = right - w;
      if (d.handle.includes('n')) y = bottom - h;
    }
    setDraftCrop({ x, y, w, h });
  };
  const dragEnd = () => { dragRef.current = null; };

  const finishCrop = () => {
    const c = draftCrop;
    const full = !c || (c.x < 0.002 && c.y < 0.002 && c.w > 0.996 && c.h > 0.996);
    updateItem(cur.id, { crop: full ? null : c });
    setMode('view');
  };

  const pointOnInner = (e) => {
    const rect = innerRef.current.getBoundingClientRect();
    return [Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width)), Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height))];
  };
  const drawDown = (e) => {
    if (mode !== 'draw' || !innerRef.current) return;
    e.currentTarget.setPointerCapture?.(e.pointerId);
    drawRef.current = { points: [pointOnInner(e)], size: brushSize / frameRef.current.innerW, color: brushColor };
    if (livePathRef.current) livePathRef.current.setAttribute('d', strokeToPath(drawRef.current.points, W, H));
  };
  const drawMove = (e) => {
    if (!drawRef.current) return;
    drawRef.current.points.push(pointOnInner(e));
    if (livePathRef.current) livePathRef.current.setAttribute('d', strokeToPath(drawRef.current.points, W, H));
  };
  const drawUp = () => {
    const s = drawRef.current;
    drawRef.current = null;
    if (livePathRef.current) livePathRef.current.setAttribute('d', '');
    if (s && s.points.length) updateItem(cur.id, (it) => ({ strokes: [...it.strokes, s] }));
  };

  const textDown = (e, t) => {
    if (mode === 'draw' || mode === 'crop') return;
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = { type: 'text', id: t.id, sx: e.clientX, sy: e.clientY, ox: t.x, oy: t.y, moved: false };
  };
  const textMove = (e) => {
    const d = dragRef.current;
    if (!d || d.type !== 'text') return;
    const dx = e.clientX - d.sx;
    const dy = e.clientY - d.sy;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) d.moved = true;
    if (!d.moved) return;
    const { innerW: iw, innerH: ih } = frameRef.current;
    updateItem(cur.id, (it) => ({ texts: it.texts.map((x) => (x.id === d.id ? { ...x, x: Math.max(0, Math.min(1, d.ox + dx / iw)), y: Math.max(0, Math.min(1, d.oy + dy / ih)) } : x)) }));
  };
  const textUp = (e, t) => {
    const d = dragRef.current;
    dragRef.current = null;
    if (d && d.type === 'text' && !d.moved) setTextDraft({ id: t.id, text: t.text, color: t.color, size: t.size });
  };

  const saveText = () => {
    const td = textDraft;
    setTextDraft(null);
    if (!td) return;
    const value = td.text.replace(/\s+$/, '');
    if (!value.trim()) {
      if (td.id) updateItem(cur.id, (it) => ({ texts: it.texts.filter((x) => x.id !== td.id) }));
      return;
    }
    if (td.id) {
      updateItem(cur.id, (it) => ({ texts: it.texts.map((x) => (x.id === td.id ? { ...x, text: value, color: td.color, size: td.size } : x)) }));
    } else {
      const r = cur.crop || { x: 0, y: 0, w: 1, h: 1 };
      updateItem(cur.id, (it) => ({ texts: [...it.texts, { id: `t${Date.now()}`, text: value, color: td.color, size: td.size, x: r.x + r.w / 2, y: r.y + r.h * 0.42 }] }));
    }
  };

  const togglePlay = () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) { v.play().catch(() => {}); } else { v.pause(); }
  };

  const onVideoTime = (e) => {
    const v = e.currentTarget;
    const end = cur.trimEnd != null ? cur.trimEnd : v.duration;
    if (end && v.currentTime >= end) { v.currentTime = cur.trimStart || 0; if (mode !== 'trim') v.play().catch(() => {}); }
    if (cur.trimStart && v.currentTime < cur.trimStart - 0.2) v.currentTime = cur.trimStart;
  };

  const trimDown = (e, which) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = { type: 'trim', which };
  };
  const trimMove = (e) => {
    const d = dragRef.current;
    if (!d || d.type !== 'trim' || !trimBarRef.current || !cur.duration) return;
    const rect = trimBarRef.current.getBoundingClientRect();
    const t = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width)) * cur.duration;
    const end = cur.trimEnd != null ? cur.trimEnd : cur.duration;
    if (d.which === 'start') {
      const v = Math.min(t, end - 1);
      updateItem(cur.id, { trimStart: Math.max(0, v) });
      if (videoRef.current) videoRef.current.currentTime = Math.max(0, v);
    } else {
      const v = Math.max(t, (cur.trimStart || 0) + 1);
      updateItem(cur.id, { trimEnd: Math.min(cur.duration, v) });
      if (videoRef.current) videoRef.current.currentTime = Math.min(cur.duration, v);
    }
  };

  const send = async () => {
    if (sending) return;
    setSending(true);
    try {
      const outputs = [];
      for (const it of items) {
        if (it.kind === 'image') {
          const file = await exportEditedImage(it);
          outputs.push({ kind: 'image', file, url: it.url });
        } else {
          const overlayFile = await exportVideoOverlay(it);
          const trimmed = it.duration && ((it.trimStart || 0) > 0.05 || (it.trimEnd != null && it.trimEnd < it.duration - 0.05));
          outputs.push({ kind: 'video', file: it.file, url: it.url, overlayFile, trimStart: trimmed ? (it.trimStart || 0) : null, trimEnd: trimmed ? (it.trimEnd != null ? it.trimEnd : it.duration) : null });
        }
      }
      sentRef.current = true;
      onSend(outputs, caption.trim(), mentions, { once: !isPost && !isStory && once, blur: !isPost && !isStory && !once && hideIt });
    } catch {
      setSending(false);
    }
  };

  const fmt = (s) => `${Math.floor((s || 0) / 60)}:${Math.floor((s || 0) % 60).toString().padStart(2, '0')}`;
  const toolBtn = (icon, label, onClick, active) => (
    <div role="button" aria-label={label} onClick={onClick} style={{
      width: 40, height: 40, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
      background: active ? 'white' : 'rgba(0,0,0,0.45)', color: active ? '#000' : 'white', flexShrink: 0,
    }}>{icon}</div>
  );
  const colorRow = (value, onPick) => (
    <div style={{ display: 'flex', gap: 10, justifyContent: 'center', flexWrap: 'wrap' }}>
      {EDITOR_COLORS.map((c) => (
        <div key={c} onClick={() => onPick(c)} style={{
          width: 26, height: 26, borderRadius: '50%', background: c, cursor: 'pointer', boxSizing: 'border-box',
          border: value === c ? '3px solid white' : '2px solid rgba(255,255,255,0.35)', transform: value === c ? 'scale(1.15)' : 'none',
        }} />
      ))}
    </div>
  );

  return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 120, background: '#000', color: 'white', display: 'flex', flexDirection: 'column', paddingTop: 'env(safe-area-inset-top)' }} className="zchat-fade">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '10px 12px', flexShrink: 0, minHeight: 60, boxSizing: 'border-box' }}>
        {mode === 'view' && (
          <>
            {toolBtn(<X size={20} />, 'Close', onCancel)}
            <div style={{ display: 'flex', gap: 8 }}>
              {cur.kind === 'image' && toolBtn(<FilterIcon size={18} />, 'Filters', () => setMode('filter'), cur.filter && cur.filter !== 'none')}
              {cur.kind === 'image' && toolBtn(<Crop size={18} />, 'Crop', startCrop)}
              {cur.kind === 'video' && cur.duration > 1 && toolBtn(<Scissors size={18} />, 'Trim', () => { setMode('trim'); if (videoRef.current) videoRef.current.pause(); })}
              {toolBtn(<Smile size={18} />, 'Stickers', () => { setShowStickerPicker(true); if (videoRef.current) videoRef.current.pause(); })}
              {toolBtn(<Type size={18} />, 'Add text', () => setTextDraft({ id: null, text: '', color: '#FFFFFF', size: 0.07 }))}
              {toolBtn(<Pencil size={18} />, 'Draw', () => { setMode('draw'); if (videoRef.current) videoRef.current.pause(); })}
              {isStory && toolBtn(<AtSign size={18} />, 'Mention', () => setShowMentionPicker(true))}
            </div>
          </>
        )}
        {mode === 'draw' && (
          <>
            {toolBtn(<Undo2 size={18} />, 'Undo', () => updateItem(cur.id, (it) => ({ strokes: it.strokes.slice(0, -1) })))}
            <span style={{ fontSize: 15, fontWeight: 800 }}>Draw</span>
            <span onClick={() => setMode('view')} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: '8px 10px' }}>Done</span>
          </>
        )}
        {mode === 'crop' && (
          <>
            <span onClick={() => setMode('view')} style={{ fontSize: 15, fontWeight: 600, cursor: 'pointer', padding: '8px 10px' }}>Cancel</span>
            <span onClick={() => { setDraftCrop({ x: 0, y: 0, w: 1, h: 1 }); setCropAspect(null); }} style={{ fontSize: 14, fontWeight: 600, cursor: 'pointer', padding: '8px 10px', color: 'rgba(255,255,255,0.75)' }}>Reset</span>
            <span onClick={finishCrop} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: '8px 10px', color: theme.gold }}>Done</span>
          </>
        )}
        {mode === 'trim' && (
          <>
            <span style={{ width: 60 }} />
            <span style={{ fontSize: 15, fontWeight: 800 }}>Trim video</span>
            <span onClick={() => setMode('view')} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: '8px 10px', color: theme.gold }}>Done</span>
          </>
        )}
      </div>

      <div ref={stageRef} onClick={() => { if (mode === 'view' && cur.kind === 'video') togglePlay(); }}
        style={{ flex: 1, minHeight: 0, position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden', touchAction: 'none' }}>
        {cur.width && stage.w ? (
          <div style={{ position: 'relative', width: frameW, height: frameH, overflow: mode === 'crop' ? 'visible' : 'hidden', flexShrink: 0 }}>
            <div ref={innerRef}
              onPointerDown={drawDown} onPointerMove={drawMove} onPointerUp={drawUp} onPointerCancel={drawUp}
              style={{ position: 'absolute', left: -region.x * innerW, top: -region.y * innerH, width: innerW, height: innerH, touchAction: 'none', cursor: mode === 'draw' ? 'crosshair' : 'default' }}>
              {cur.kind === 'image' ? (
                <img src={cur.url} alt="" draggable={false} style={{ width: '100%', height: '100%', display: 'block', userSelect: 'none', pointerEvents: 'none', filter: photoFilterCss(cur.filter) }} />
              ) : (
                <video ref={videoRef} src={cur.url} playsInline preload="auto"
                  onPlay={() => setPlaying(true)} onPause={() => setPlaying(false)} onTimeUpdate={onVideoTime}
                  onLoadedMetadata={(e) => { if (cur.trimStart) e.currentTarget.currentTime = cur.trimStart; }}
                  style={{ width: '100%', height: '100%', display: 'block', objectFit: 'fill', pointerEvents: 'none' }} />
              )}
              <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none', overflow: 'visible' }}>
                {cur.strokes.map((s, i) => (
                  <path key={i} d={strokeToPath(s.points, W, H)} stroke={s.color} strokeWidth={s.size * W} fill="none" strokeLinecap="round" strokeLinejoin="round" />
                ))}
                <path ref={livePathRef} stroke={brushColor} strokeWidth={(brushSize / Math.max(1, innerW)) * W} fill="none" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              {(cur.stickers || []).map((st) => (
                <img key={st.id} src={st.src} alt="" draggable={false}
                  onPointerDown={(e) => {
                    if (mode !== 'view') return;
                    e.stopPropagation();
                    e.currentTarget.setPointerCapture?.(e.pointerId);
                    dragRef.current = { type: 'sticker', id: st.id, sx: e.clientX, sy: e.clientY, ox: st.x, oy: st.y, moved: false };
                  }}
                  onPointerMove={(e) => {
                    const d = dragRef.current;
                    if (!d || d.type !== 'sticker' || d.id !== st.id) return;
                    const dx = e.clientX - d.sx;
                    const dy = e.clientY - d.sy;
                    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) d.moved = true;
                    if (!d.moved) return;
                    const { innerW: iw, innerH: ih } = frameRef.current;
                    updateItem(cur.id, (it) => ({ stickers: it.stickers.map((x) => (x.id === st.id ? { ...x, x: Math.max(0, Math.min(1, d.ox + dx / iw)), y: Math.max(0, Math.min(1, d.oy + dy / ih)) } : x)) }));
                  }}
                  onPointerUp={() => { const d = dragRef.current; dragRef.current = null; if (d && d.type === 'sticker' && !d.moved) setSelectedSticker(st.id === selectedSticker ? null : st.id); }}
                  onClick={(e) => e.stopPropagation()}
                  style={{ position: 'absolute', left: `${st.x * 100}%`, top: `${st.y * 100}%`, width: st.size * innerW, transform: 'translate(-50%, -50%)', touchAction: 'none', cursor: 'grab', pointerEvents: mode === 'view' ? 'auto' : 'none', outline: selectedSticker === st.id ? '2px dashed rgba(255,255,255,0.85)' : 'none', outlineOffset: 4, borderRadius: 8, userSelect: 'none' }} />
              ))}
              {cur.texts.map((t) => (
                <div key={t.id}
                  onPointerDown={(e) => textDown(e, t)} onPointerMove={textMove} onPointerUp={(e) => textUp(e, t)} onPointerCancel={() => { dragRef.current = null; }}
                  onClick={(e) => e.stopPropagation()}
                  style={{
                    position: 'absolute', left: `${t.x * 100}%`, top: `${t.y * 100}%`, transform: 'translate(-50%, -50%)',
                    color: t.color, fontSize: t.size * innerW, fontWeight: 800, lineHeight: 1.18, whiteSpace: 'pre', textAlign: 'center',
                    textShadow: '0 1px 8px rgba(0,0,0,0.45)', pointerEvents: mode === 'draw' || mode === 'crop' ? 'none' : 'auto',
                    touchAction: 'none', cursor: 'grab', userSelect: 'none', fontFamily: FONT,
                  }}>{t.text}</div>
              ))}
            </div>
            {cur.kind === 'video' && mode === 'view' && !playing && (
              <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
                <div style={{ width: 64, height: 64, borderRadius: '50%', background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <Play size={28} color="white" style={{ marginLeft: 3 }} />
                </div>
              </div>
            )}
            {mode === 'crop' && draftCrop && (
              <div onPointerDown={(e) => cropDown(e, 'move')} onPointerMove={cropMove} onPointerUp={dragEnd} onPointerCancel={dragEnd}
                style={{
                  position: 'absolute', left: draftCrop.x * frameW, top: draftCrop.y * frameH, width: draftCrop.w * frameW, height: draftCrop.h * frameH,
                  boxShadow: '0 0 0 4000px rgba(0,0,0,0.6)', outline: '1px solid rgba(255,255,255,0.9)', touchAction: 'none', cursor: 'move',
                }}>
                {[1, 2].map((n) => (
                  <React.Fragment key={n}>
                    <div style={{ position: 'absolute', left: `${(n * 100) / 3}%`, top: 0, bottom: 0, width: 1, background: 'rgba(255,255,255,0.35)', pointerEvents: 'none' }} />
                    <div style={{ position: 'absolute', top: `${(n * 100) / 3}%`, left: 0, right: 0, height: 1, background: 'rgba(255,255,255,0.35)', pointerEvents: 'none' }} />
                  </React.Fragment>
                ))}
                {['nw', 'ne', 'sw', 'se'].map((hnd) => (
                  <div key={hnd} onPointerDown={(e) => cropDown(e, hnd)} onPointerMove={cropMove} onPointerUp={dragEnd} onPointerCancel={dragEnd}
                    style={{ position: 'absolute', width: 48, height: 48, [hnd[0] === 'n' ? 'top' : 'bottom']: -24, [hnd[1] === 'w' ? 'left' : 'right']: -24, touchAction: 'none', cursor: hnd === 'nw' || hnd === 'se' ? 'nwse-resize' : 'nesw-resize' }}>
                    <div style={{
                      position: 'absolute', width: 22, height: 22, [hnd[0] === 'n' ? 'top' : 'bottom']: 21, [hnd[1] === 'w' ? 'left' : 'right']: 21,
                      [hnd[0] === 'n' ? 'borderTop' : 'borderBottom']: '4px solid white', [hnd[1] === 'w' ? 'borderLeft' : 'borderRight']: '4px solid white',
                    }} />
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          <Spinner size={26} />
        )}
      </div>

      {mode === 'crop' && (
        <div style={{ display: 'flex', gap: 8, justifyContent: 'center', padding: '14px 12px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))', flexShrink: 0 }}>
          {[{ l: 'Free', v: null }, { l: 'Square', v: 1 }, { l: '4:5', v: 0.8 }, { l: '16:9', v: 16 / 9 }].map((opt) => (
            <div key={opt.l} onClick={() => applyAspect(opt.v)} style={{
              padding: '8px 14px', borderRadius: 18, fontSize: 13, fontWeight: 700, cursor: 'pointer',
              background: cropAspect === opt.v ? 'white' : 'rgba(255,255,255,0.14)', color: cropAspect === opt.v ? '#000' : 'white',
            }}>{opt.l}</div>
          ))}
        </div>
      )}

      {mode === 'draw' && (
        <div style={{ padding: '12px 14px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))', display: 'flex', flexDirection: 'column', gap: 12, flexShrink: 0 }}>
          {colorRow(brushColor, setBrushColor)}
          <div style={{ display: 'flex', justifyContent: 'center', gap: 16, alignItems: 'center' }}>
            {BRUSH_SIZES.map((s) => (
              <div key={s} onClick={() => setBrushSize(s)} style={{ width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', borderRadius: '50%', background: brushSize === s ? 'rgba(255,255,255,0.18)' : 'transparent' }}>
                <div style={{ width: s + 4, height: s + 4, borderRadius: '50%', background: brushColor }} />
              </div>
            ))}
          </div>
        </div>
      )}

      {mode === 'filter' && (
        <div style={{ padding: '10px 0', paddingBottom: 'calc(12px + env(safe-area-inset-bottom))', flexShrink: 0 }}>
          <FilterStrip value={cur.filter} thumb={cur.url} onPick={(k) => updateItem(cur.id, { filter: k })} />
          <div style={{ display: 'flex', justifyContent: 'center', paddingTop: 12 }}>
            <div role="button" aria-label="Done" onClick={() => setMode('view')} style={{ padding: '10px 30px', borderRadius: 20, background: 'white', color: '#000', fontWeight: 800, fontSize: 14.5, cursor: 'pointer' }}>Done</div>
          </div>
        </div>
      )}

      {mode === 'trim' && (
        <div style={{ padding: '14px 22px', paddingBottom: 'calc(16px + env(safe-area-inset-bottom))', flexShrink: 0 }}>
          <div ref={trimBarRef} style={{ position: 'relative', height: 44, touchAction: 'none' }}>
            <div style={{ position: 'absolute', top: 16, left: 0, right: 0, height: 12, borderRadius: 6, background: 'rgba(255,255,255,0.2)' }} />
            <div style={{
              position: 'absolute', top: 16, height: 12, borderRadius: 6, background: theme.coral,
              left: `${((cur.trimStart || 0) / (cur.duration || 1)) * 100}%`,
              width: `${(((cur.trimEnd != null ? cur.trimEnd : cur.duration) - (cur.trimStart || 0)) / (cur.duration || 1)) * 100}%`,
            }} />
            {['start', 'end'].map((which) => {
              const value = which === 'start' ? (cur.trimStart || 0) : (cur.trimEnd != null ? cur.trimEnd : cur.duration);
              return (
                <div key={which} onPointerDown={(e) => trimDown(e, which)} onPointerMove={trimMove} onPointerUp={dragEnd} onPointerCancel={dragEnd}
                  style={{ position: 'absolute', top: 0, width: 44, height: 44, marginLeft: -22, left: `${(value / (cur.duration || 1)) * 100}%`, display: 'flex', alignItems: 'center', justifyContent: 'center', touchAction: 'none', cursor: 'ew-resize' }}>
                  <div style={{ width: 22, height: 22, borderRadius: '50%', background: 'white', border: `3px solid ${theme.coral}` }} />
                </div>
              );
            })}
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: 'rgba(255,255,255,0.75)', marginTop: 4 }}>
            <span>{fmt(cur.trimStart)}</span>
            <span>{fmt((cur.trimEnd != null ? cur.trimEnd : cur.duration) - (cur.trimStart || 0))} selected</span>
            <span>{fmt(cur.trimEnd != null ? cur.trimEnd : cur.duration)}</span>
          </div>
        </div>
      )}

      {mode === 'view' && (
        <div style={{ flexShrink: 0, paddingBottom: 'calc(10px + env(safe-area-inset-bottom))' }}>
          {items.length > 1 && (
            <div style={{ display: 'flex', gap: 8, padding: '10px 12px 4px', overflowX: 'auto' }}>
              {items.map((it, i) => (
                <div key={it.id} onClick={() => setIndex(i)} style={{
                  position: 'relative', width: 52, height: 52, borderRadius: 10, overflow: 'hidden', flexShrink: 0, cursor: 'pointer',
                  border: i === index ? '2px solid white' : '2px solid transparent', boxSizing: 'border-box',
                }}>
                  {it.kind === 'image'
                    ? <img src={it.url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
                    : <VideoThumb src={it.url} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />}
                  {i === index && (
                    <div onClick={(e) => { e.stopPropagation(); removeItem(it.id); }} style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <Trash2 size={16} color="white" />
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
          {isStory && mentions.length > 0 && (
            <div style={{ display: 'flex', gap: 6, padding: '8px 12px 0', overflowX: 'auto' }}>
              {mentions.map((mn) => (
                <div key={`${mn.kind}-${mn.id}`} onClick={() => setMentions((prev) => prev.filter((x) => !(x.id === mn.id && x.kind === mn.kind)))} style={{ display: 'flex', alignItems: 'center', gap: 4, padding: '5px 10px', borderRadius: 14, background: 'rgba(255,255,255,0.16)', fontSize: 12.5, fontWeight: 700, whiteSpace: 'nowrap', cursor: 'pointer' }}>
                  {mn.kind === 'group' ? <Users size={12} /> : <AtSign size={12} />}{mn.label}<X size={12} />
                </div>
              ))}
            </div>
          )}
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px 0' }}>
            {!isPost && !isStory && (
              <div role="button" aria-label={once ? 'View once on' : 'View once off'} onClick={() => { hapticTap(); playUiSound('toggle'); setOnce((v) => { if (!v) setHideIt(false); return !v; }); }} style={{ width: 46, height: 46, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0, background: once ? 'white' : 'rgba(255,255,255,0.14)' }}>
                <OnceIcon size={24} color={once ? '#000' : 'white'} used={once} />
              </div>
            )}
            {!isPost && !isStory && (
              <div role="button" aria-label={hideIt ? 'Hidden photo on' : 'Hidden photo off'} onClick={() => { hapticTap(); playUiSound('toggle'); setHideIt((v) => { if (!v) setOnce(false); return !v; }); }} style={{ width: 46, height: 46, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0, background: hideIt ? 'white' : 'rgba(255,255,255,0.14)' }}>
                <HiddenPhotoIcon size={22} color={hideIt ? '#000' : 'white'} />
              </div>
            )}
            <input value={caption} onChange={(e) => setCaption(e.target.value.slice(0, MAX_CHARS))} placeholder={isPost ? 'Write a caption' : 'Add a caption'}
              onKeyDown={(e) => { if (e.key === 'Enter' && !isTouchDevice()) { e.preventDefault(); send(); } }}
              style={{ flex: 1, minWidth: 0, padding: '12px 16px', borderRadius: 24, border: 'none', outline: 'none', background: 'rgba(255,255,255,0.14)', color: 'white', fontFamily: FONT, fontSize: 15 }} />
            {isPost ? (
              <div onPointerDown={(e) => e.preventDefault()} onClick={send} role="button" aria-label="Share post" style={{
                height: 48, padding: '0 18px', borderRadius: 24, background: theme.coral, color: 'white', display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', flexShrink: 0, fontWeight: 800, fontSize: 14,
              }}>{sending ? <Spinner size={16} /> : <><ImageIcon size={17} color="white" /> Share post</>}</div>
            ) : isStory ? (
              <div onPointerDown={(e) => e.preventDefault()} onClick={send} role="button" aria-label="Share to your story" style={{
                height: 48, padding: '0 16px', borderRadius: 24, background: 'white', color: '#000', display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer', flexShrink: 0, fontWeight: 800, fontSize: 14,
              }}>{sending ? <Spinner size={16} color="#000" /> : <><StatusIcon size={17} color="#000" /> Your story</>}</div>
            ) : (
              <div onPointerDown={(e) => e.preventDefault()} onClick={send} role="button" aria-label="Send" style={{
                width: 48, height: 48, borderRadius: '50%', background: theme.coral, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0,
              }}>{sending ? <Spinner size={18} /> : <Send size={20} color="white" style={{ marginLeft: -2 }} />}</div>
            )}
          </div>
          {isPost
            ? <div style={{ fontSize: 11.5, color: 'rgba(255,255,255,0.6)', padding: '6px 18px 0' }}>Shows on your profile and in Moments</div>
            : isStory
            ? <div style={{ fontSize: 11.5, color: 'rgba(255,255,255,0.6)', padding: '6px 18px 0' }}>Shared with your followers for 24 hours</div>
            : recipientName && <div style={{ fontSize: 11.5, color: once || hideIt ? 'white' : 'rgba(255,255,255,0.6)', fontWeight: once || hideIt ? 700 : 400, padding: '6px 18px 0' }}>To {recipientName}{once ? ', opens once' : hideIt ? ', hidden until they tap' : ''}</div>}
        </div>
      )}

      {selectedSticker && mode === 'view' && (cur.stickers || []).some((x) => x.id === selectedSticker) && (
        <div className="zchat-pop" style={{ position: 'absolute', left: '50%', top: 'calc(70px + env(safe-area-inset-top))', transform: 'translateX(-50%)', zIndex: 6, display: 'flex', gap: 8, padding: 6, borderRadius: 22, background: 'rgba(0,0,0,0.65)' }}>
          {[{ l: 'Smaller', f: 0.8 }, { l: 'Bigger', f: 1.25 }].map((b) => (
            <div key={b.l} onClick={() => updateItem(cur.id, (it) => ({ stickers: it.stickers.map((x) => (x.id === selectedSticker ? { ...x, size: Math.max(0.08, Math.min(0.9, x.size * b.f)) } : x)) }))} style={{ padding: '8px 14px', borderRadius: 16, background: 'rgba(255,255,255,0.14)', fontSize: 13, fontWeight: 700, cursor: 'pointer' }}>{b.l}</div>
          ))}
          <div onClick={() => { updateItem(cur.id, (it) => ({ stickers: it.stickers.filter((x) => x.id !== selectedSticker) })); setSelectedSticker(null); }} style={{ padding: '8px 14px', borderRadius: 16, background: '#FF3B30', fontSize: 13, fontWeight: 700, cursor: 'pointer' }}>Remove</div>
        </div>
      )}
      {showStickerPicker && (
        <div onClick={() => setShowStickerPicker(false)} style={{ position: 'absolute', inset: 0, zIndex: 8, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end' }}>
          <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', height: '60%', background: '#11151F', borderRadius: '22px 22px 0 0', display: 'flex', flexDirection: 'column', paddingBottom: 'env(safe-area-inset-bottom)' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 18px' }}>
              <span style={{ fontWeight: 800, fontSize: 15 }}>Stickers</span>
              <X size={20} style={{ cursor: 'pointer' }} onClick={() => setShowStickerPicker(false)} />
            </div>
            <div style={{ flex: 1, overflowY: 'auto', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: 8, padding: '0 12px 14px' }}>
              {orderStickersForPick().map((stk) => (
                <div key={stk.key} onClick={() => {
                  setShowStickerPicker(false);
                  const r = cur.crop || { x: 0, y: 0, w: 1, h: 1 };
                  const id = `s${Date.now()}`;
                  updateItem(cur.id, (it) => ({ stickers: [...(it.stickers || []), { id, src: stk.file, x: r.x + r.w / 2, y: r.y + r.h / 2, size: 0.32 }] }));
                  setSelectedSticker(id);
                }} style={{ aspectRatio: '1 / 1', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', borderRadius: 14, background: 'rgba(255,255,255,0.05)' }}>
                  <img src={stk.file} alt="" loading="lazy" draggable={false} style={{ width: '82%', height: '82%', objectFit: 'contain' }} />
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
      {showMentionPicker && (
        <StoryMentionPicker myId={myId} groups={mentionGroups} privacyCtx={privacyCtx} onClose={() => setShowMentionPicker(false)}
          onPick={(mn) => {
            setShowMentionPicker(false);
            setMentions((prev) => (prev.some((x) => x.id === mn.id && x.kind === mn.kind) ? prev : [...prev, mn]));
            const r = cur.crop || { x: 0, y: 0, w: 1, h: 1 };
            updateItem(cur.id, (it) => ({ texts: [...it.texts, { id: `m${Date.now()}`, text: `@${mn.label}`, color: '#FFFFFF', size: 0.06, x: r.x + r.w / 2, y: r.y + r.h * (0.62 + Math.min(0.24, it.texts.length * 0.08)) }] }));
          }} />
      )}
      {textDraft && (
        <div onClick={saveText} style={{ position: 'absolute', inset: 0, zIndex: 5, background: 'rgba(0,0,0,0.6)', display: 'flex', flexDirection: 'column', paddingTop: 'env(safe-area-inset-top)' }}>
          <div onClick={(e) => e.stopPropagation()} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 14px' }}>
            {textDraft.id
              ? <span onClick={() => { const id = textDraft.id; setTextDraft(null); updateItem(cur.id, (it) => ({ texts: it.texts.filter((x) => x.id !== id) })); }} style={{ fontSize: 15, fontWeight: 700, color: '#FF6B6B', cursor: 'pointer', padding: 8 }}>Delete</span>
              : <span style={{ width: 50 }} />}
            <input type="range" min="0.035" max="0.16" step="0.005" value={textDraft.size} onChange={(e) => setTextDraft((d) => ({ ...d, size: parseFloat(e.target.value) }))} style={{ width: 130, accentColor: 'white' }} />
            <span onClick={saveText} style={{ fontSize: 15, fontWeight: 800, cursor: 'pointer', padding: 8 }}>Done</span>
          </div>
          <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
            <textarea autoFocus value={textDraft.text} onClick={(e) => e.stopPropagation()} onChange={(e) => setTextDraft((d) => ({ ...d, text: e.target.value.slice(0, 200) }))}
              placeholder="Type something" rows={3}
              style={{
                width: '100%', background: 'transparent', border: 'none', outline: 'none', resize: 'none', textAlign: 'center',
                color: textDraft.color, fontFamily: FONT, fontWeight: 800, fontSize: Math.max(22, Math.min(46, textDraft.size * 380)), lineHeight: 1.18,
                textShadow: '0 1px 8px rgba(0,0,0,0.45)',
              }} />
          </div>
          <div onClick={(e) => e.stopPropagation()} style={{ padding: '10px 14px', paddingBottom: 'calc(16px + env(safe-area-inset-bottom))' }}>
            {colorRow(textDraft.color, (c) => setTextDraft((d) => ({ ...d, color: c })))}
          </div>
        </div>
      )}
    </div>
  );
}

function VideoViewer({ url, trimStart, trimEnd, overlayUrl, onClose, onForward, once }) {
  const [pip, setPip] = useState(false);
  useBackClose(!pip, onClose);
  const seekedRef = useRef(false);
  const [ratio, setRatio] = useState(null);
  const [ui, setUi] = useState(true);
  const hideRef = useRef(null);
  const playingRef = useRef(false);
  const videoRef = useRef(null);
  const pipRef = useRef(false);
  const canPip = typeof document !== 'undefined' && !once && (!!document.pictureInPictureEnabled || (typeof HTMLVideoElement !== 'undefined' && 'webkitSetPresentationMode' in HTMLVideoElement.prototype));
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return undefined;
    const enter = () => { pipRef.current = true; setPip(true); };
    const leave = () => { if (pipRef.current) { pipRef.current = false; setPip(false); onClose(); } };
    const wk = () => { if (v.webkitPresentationMode === 'picture-in-picture') enter(); else leave(); };
    v.addEventListener('enterpictureinpicture', enter);
    v.addEventListener('leavepictureinpicture', leave);
    v.addEventListener('webkitpresentationmodechanged', wk);
    return () => {
      v.removeEventListener('enterpictureinpicture', enter);
      v.removeEventListener('leavepictureinpicture', leave);
      v.removeEventListener('webkitpresentationmodechanged', wk);
      try { if (document.pictureInPictureElement === v) document.exitPictureInPicture().catch(() => {}); } catch {}
    };
  }, []);
  const startPip = async () => {
    const v = videoRef.current;
    if (!v) return;
    try {
      if (v.paused) await v.play().catch(() => {});
      if (document.pictureInPictureEnabled && v.requestPictureInPicture) await v.requestPictureInPicture();
      else if (v.webkitSetPresentationMode) v.webkitSetPresentationMode('picture-in-picture');
    } catch {}
  };
  const wake = () => {
    setUi(true);
    clearTimeout(hideRef.current);
    if (playingRef.current) hideRef.current = setTimeout(() => setUi(false), 2600);
  };
  useEffect(() => () => clearTimeout(hideRef.current), []);
  const onLoadedMetadata = (e) => {
    const v = e.currentTarget;
    if (v.videoWidth && v.videoHeight) setRatio(v.videoWidth / v.videoHeight);
    if (trimStart && !seekedRef.current) { v.currentTime = trimStart; seekedRef.current = true; }
  };
  const onTimeUpdate = (e) => {
    if (trimEnd && e.currentTarget.currentTime >= trimEnd) {
      e.currentTarget.pause();
      e.currentTarget.currentTime = trimStart || 0;
    }
  };
  const boxStyle = ratio
    ? { position: 'relative', width: `min(100vw, calc(var(--zfull, 100vh) * ${ratio}))`, aspectRatio: String(ratio), maxHeight: 'var(--zfull, 100vh)' }
    : { position: 'relative', maxWidth: '100%', maxHeight: '100%' };
  return (
    <div onPointerDown={wake} style={{ position: 'fixed', inset: 0, background: '#000', zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 0, visibility: pip ? 'hidden' : 'visible', pointerEvents: pip ? 'none' : 'auto' }} className="zchat-fade">
      <div style={{ transition: 'opacity 0.2s ease, visibility 0.2s', opacity: ui && !pip ? 1 : 0, visibility: ui && !pip ? 'visible' : 'hidden' }}>
        <ViewerTopBar onClose={onClose} title={once ? 'View once' : ''} right={once ? null : (
          <>
            {canPip && <ViewerButton label="Picture in picture" onClick={startPip}><PipIcon size={21} /></ViewerButton>}
            <ViewerButton label="Save video" onClick={() => silentDownload(url, 'zchat-video.mp4')}><Download size={21} /></ViewerButton>
            {onForward && <ViewerButton label="Forward" onClick={onForward}><Forward size={21} /></ViewerButton>}
          </>
        )} />
      </div>
      <div style={boxStyle} data-no-swipe="true">
        <video ref={videoRef} src={url} controls autoPlay playsInline onPlay={() => { playingRef.current = true; wake(); }} onPause={() => { playingRef.current = false; clearTimeout(hideRef.current); setUi(true); }} onEnded={() => { playingRef.current = false; setUi(true); }} controlsList={once ? 'nodownload noplaybackrate' : undefined} disablePictureInPicture={!!once} onContextMenu={(e) => e.preventDefault()} onLoadedMetadata={onLoadedMetadata} onTimeUpdate={onTimeUpdate}
          style={ratio ? { width: '100%', height: '100%', display: 'block', objectFit: 'contain' } : { maxWidth: '100vw', maxHeight: 'var(--zfull, 100vh)', display: 'block' }} />
        {overlayUrl && ratio && (
          <img src={overlayUrl} alt="" draggable={false} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none', objectFit: 'contain' }} />
        )}
      </div>
    </div>
  );
}

async function silentDownload(url, filename) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error('download');
    const blob = await res.blob();
    const file = new File([blob], filename, { type: blob.type || 'application/octet-stream' });
    if (isAppleMobile() && navigator.canShare && navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file] });
        return true;
      } catch (err) {
        if (err && err.name === 'AbortError') return false;
      }
    }
    const blobUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(blobUrl), 4000);
    return true;
  } catch {
    return false;
  }
}

function isActiveUntil(value) {
  return !!value && new Date(value).getTime() > Date.now();
}

function muteLabel(value) {
  if (!isActiveUntil(value)) return '';
  const until = new Date(value);
  if (until.getFullYear() >= 2090) return 'Muted';
  return `Muted until ${until.toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}`;
}

function LoopingSticker({ src, size = 128, style, className, alt = 'sticker' }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || !('IntersectionObserver' in window)) return undefined;
    const restart = () => { const url = el.getAttribute('data-src'); if (url) { el.src = ''; el.src = url; } };
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) restart(); });
    }, { threshold: 0.15 });
    io.observe(el);
    const onShow = () => { if (document.visibilityState === 'visible') restart(); };
    document.addEventListener('visibilitychange', onShow);
    return () => { io.disconnect(); document.removeEventListener('visibilitychange', onShow); };
  }, [src]);
  return (
    <img ref={ref} src={src} data-src={src} alt={alt} className={className} draggable={false}
      onContextMenu={(e) => e.preventDefault()} decoding="async"
      style={{ width: size, height: size, objectFit: 'contain', ...style }} />
  );
}

function ConfirmDialog({ title, body, confirmLabel = 'Delete', onCancel, onConfirm, danger = true, layer = 400 }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [busy, setBusy] = useState(false);
  return (
    <div onClick={onCancel} className="zchat-fade" style={{
      position: 'fixed', inset: 0, zIndex: layer, background: 'rgba(5,8,16,0.55)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24,
    }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-pop" style={{ background: theme.panelBg, borderRadius: 22, padding: '22px 20px 18px', width: '100%', maxWidth: 300, textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.35)' }}>
        <div style={{ fontWeight: 800, fontSize: 16, color: theme.ink, marginBottom: 6 }}>{title}</div>
        {body && <div style={{ fontSize: 13, color: theme.muted, lineHeight: 1.5, marginBottom: 18 }}>{body}</div>}
        <div style={{ display: 'flex', gap: 8 }}>
          <button onClick={onCancel} style={{ flex: 1, padding: 11, borderRadius: 13, border: `1.5px solid ${theme.border}`, background: 'transparent', color: theme.ink, fontWeight: 700, fontSize: 13.5, cursor: 'pointer', fontFamily: FONT }}>Cancel</button>
          <button disabled={busy} onClick={async () => { setBusy(true); await onConfirm(); setBusy(false); }} style={{ flex: 1, padding: 11, borderRadius: 13, border: 'none', background: danger ? theme.danger : theme.coral, color: 'white', fontWeight: 700, fontSize: 13.5, cursor: 'pointer', fontFamily: FONT }}>
            {busy ? <Spinner size={13} /> : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

function ChatSearchBar({ query, onChange, count, position, onPrev, onNext, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', borderBottom: `1px solid ${theme.border}`, background: theme.panelBg, flexShrink: 0 }} className="zchat-fade">
      <div style={{ position: 'relative', flex: 1 }}>
        <Search size={15} color={theme.muted} style={{ position: 'absolute', left: 12, top: 11 }} />
        <input autoFocus value={query} onChange={(e) => onChange(e.target.value)} placeholder="Search in this chat"
          onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); if (e.shiftKey) onNext(); else onPrev(); } if (e.key === 'Escape') onClose(); }}
          style={{ ...inputStyle(theme), padding: '9px 12px 9px 34px', fontSize: 14, borderRadius: 20 }} />
      </div>
      <span style={{ fontSize: 12, color: theme.muted, minWidth: 44, textAlign: 'center', fontWeight: 600 }}>
        {query.trim() ? (count ? `${position} of ${count}` : 'No results') : ''}
      </span>
      <div role="button" aria-label="Older result" onClick={onPrev} style={{ width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: count ? 'pointer' : 'default', color: count ? theme.ink : theme.muted, background: theme.rowBg }}>
        <ChevronRight size={17} style={{ transform: 'rotate(-90deg)' }} />
      </div>
      <div role="button" aria-label="Newer result" onClick={onNext} style={{ width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: count ? 'pointer' : 'default', color: count ? theme.ink : theme.muted, background: theme.rowBg }}>
        <ChevronRight size={17} style={{ transform: 'rotate(90deg)' }} />
      </div>
      <X size={19} color={theme.muted} style={{ cursor: 'pointer', flexShrink: 0 }} onClick={onClose} />
    </div>
  );
}

function PinnedMessagesBar({ pins, index, labelFor, onOpen }) {
  const { theme } = useTheme();
  if (!pins.length) return null;
  const current = pins[Math.min(index, pins.length - 1)];
  const preview = describeMessage(current);
  return (
    <div onClick={onOpen} style={{
      display: 'flex', alignItems: 'center', gap: 10, padding: '8px 14px', cursor: 'pointer', flexShrink: 0,
      background: theme.panelBg, borderBottom: `1px solid ${theme.border}`,
    }} className="zchat-fade">
      {pins.length > 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2, alignSelf: 'stretch', justifyContent: 'center' }}>
          {pins.map((p, i) => (
            <div key={p.id} style={{ width: 3, flex: 1, maxHeight: 12, borderRadius: 2, background: i === index ? theme.coral : theme.border }} />
          ))}
        </div>
      )}
      <Pin_ size={16} color={theme.coral} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 11.5, fontWeight: 800, color: theme.coral }}>
          {pins.length > 1 ? `Pinned message ${index + 1} of ${pins.length}` : 'Pinned message'}
        </div>
        <PreviewLine preview={preview} prefix={`${labelFor(current.sender_id)}: `} color={theme.ink} size={12.5} />
      </div>
      {(current.type === 'image') && current.media_url && (
        <img src={current.media_url} alt="" style={{ width: 34, height: 34, borderRadius: 8, objectFit: 'cover', flexShrink: 0 }} />
      )}
    </div>
  );
}

function extractLinks(text) {
  if (!text) return [];
  const found = [];
  LINK_REGEX.lastIndex = 0;
  let match;
  while ((match = LINK_REGEX.exec(text)) !== null) found.push(match[0]);
  return found;
}

function ChatMediaPanel({ title, myId, otherId, groupId, hiddenIds, labelFor, onClose, onOpenImage, onOpenVideo, onJump }) {
  useBackClose(true, onClose);
  const edgeBack = useEdgeSwipeBack(true);
  const { theme } = useTheme();
  const [tab, setTab] = useState('media');
  const [picking, setPicking] = useState(false);
  const [picked, setPicked] = useState(() => new Set());
  const togglePick = (id) => setPicked((prev) => { const n = new Set(prev); if (n.has(id)) n.delete(id); else n.add(id); return n; });
  const [store, setStore] = useState({ media: null, links: null, voice: null });
  const [err, setErr] = useState({ media: '', links: '', voice: '' });
  const reqIdRef = useRef(0);

  const scopeQuery = (q) => (groupId ? q.eq('group_id', groupId) : q.is('group_id', null).or(`and(sender_id.eq.${myId},receiver_id.eq.${otherId}),and(sender_id.eq.${otherId},receiver_id.eq.${myId})`));
  const stillFresh = (m) => !hiddenIds.has(m.id) && !(m.expires_at && new Date(m.expires_at).getTime() <= Date.now()) && !parseOnce(m);

  const load = async (which) => {
    const myReq = ++reqIdRef.current;
    setErr((prev) => ({ ...prev, [which]: '' }));
    let q = supabase.from('messages').select('*')
      .eq('deleted', false).order('created_at', { ascending: false }).limit(CHAT_MEDIA_LIMIT);
    q = scopeQuery(q);
    q = which === 'links' ? q.eq('type', 'text') : which === 'voice' ? q.eq('type', 'audio') : q.in('type', ['image', 'video']);
    const { data, error } = await q;
    if (reqIdRef.current !== myReq) return;
    if (error) { setErr((prev) => ({ ...prev, [which]: friendlyError(error, "Couldn't load this. Try again.") })); return; }
    setStore((prev) => ({ ...prev, [which]: (data || []).filter(stillFresh) }));
  };

  useEffect(() => { setStore({ media: null, links: null, voice: null }); setErr({ media: '', links: '', voice: '' }); load('media'); }, [otherId, groupId]);
  useEffect(() => { if (store[tab] === null && !err[tab]) load(tab); }, [tab]);

  const downloadOne = async (m) => {
    try {
      const res = await fetch(m.media_url);
      const blob = await res.blob();
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `zchat-${m.type}-${m.id}.${m.type === 'video' ? 'mp4' : 'jpg'}`;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    } catch { window.open(m.media_url, '_blank'); }
  };
  const downloadPicked = async (items) => {
    for (const m of items) { if (picked.has(m.id)) await downloadOne(m); }
    playUiSound('tap');
    setPicking(false); setPicked(new Set());
  };
  const media = (store.media || []).filter((m) => m.media_url).slice().reverse();
  const links = [];
  (store.links || []).slice().reverse().forEach((m) => {
    extractLinks(m.content).forEach((link, i) => links.push({ key: `${m.id}-${i}`, link, m }));
  });
  const voices = (store.voice || []).filter((m) => m.media_url).slice().reverse();
  const dateLabel = (iso) => new Date(iso).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' });
  const countFor = (key, list) => (store[key] === null ? '' : ` (${list.length})`);
  const tabs = [
    { key: 'media', label: `Media${countFor('media', media)}` },
    { key: 'links', label: `Links${countFor('links', links)}` },
    { key: 'voice', label: `Voice${countFor('voice', voices)}` },
  ];
  const openLink = (link) => {
    const isEmail = link.includes('@') && !/^https?:|^www\./i.test(link);
    const href = isEmail ? `mailto:${link}` : (/^https?:/i.test(link) ? link : `https://${link}`);
    window.open(href, '_blank', 'noopener');
  };

  return (
    <>
    <WideDim onClose={onClose} z={60} />
    <div {...edgeBack} style={{ position: 'fixed', inset: 0, zIndex: 60, background: theme.bgGradient, display: 'flex', flexDirection: 'column' }} className="zchat-panel-open zchat-wide-page">
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '14px 16px', paddingTop: 'calc(14px + env(safe-area-inset-top))', flexShrink: 0 }}>
        <div role="button" aria-label="Back" onClick={onClose} style={{ cursor: 'pointer', color: theme.ink, display: 'flex' }}><ArrowLeft size={20} /></div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontWeight: 800, fontSize: 16.5, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</div>
          <div style={{ fontSize: 11.5, color: theme.muted }}>Media, links and voice messages</div>
        </div>
      </div>
      <div style={{ display: 'flex', borderBottom: `1px solid ${theme.border}`, flexShrink: 0 }}>
        {tabs.map((t) => (
          <div key={t.key} onClick={() => setTab(t.key)} style={{
            flex: 1, textAlign: 'center', padding: '11px 0', fontSize: 13, fontWeight: 700, cursor: 'pointer',
            color: tab === t.key ? theme.ink : theme.muted, borderBottom: tab === t.key ? `2.5px solid ${theme.coral}` : '2.5px solid transparent',
          }}>{t.label}</div>
        ))}
      </div>
      <div style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch', paddingBottom: 'calc(12px + env(safe-area-inset-bottom))' }}>
        {err[tab] && (
          <div style={{ textAlign: 'center', padding: '30px 20px' }}>
            <div style={{ fontSize: 13, color: theme.danger, fontWeight: 700, marginBottom: 10 }}>{err[tab]}</div>
            <div role="button" onClick={() => load(tab)} style={{ display: 'inline-block', fontSize: 13, fontWeight: 800, color: theme.coralDeep, cursor: 'pointer' }}>Try again</div>
          </div>
        )}
        {!err[tab] && store[tab] === null && (
          <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.ink} /></div>
        )}
        {!err.media && store.media !== null && tab === 'media' && (
          media.length ? (
            <>
              <div style={{ display: 'flex', justifyContent: 'flex-end', padding: '8px 12px 0' }}>
                <div role="button" onClick={() => { if (picking) setPicked(new Set()); setPicking((v) => !v); }} style={{ fontSize: 12.5, fontWeight: 800, color: theme.coral, cursor: 'pointer' }}>{picking ? 'Cancel' : 'Select'}</div>
              </div>
              {(() => {
                const weekAgo = Date.now() - 7 * 86400000;
                const thisWeek = media.filter((m) => new Date(m.created_at).getTime() >= weekAgo);
                const earlier = media.filter((m) => new Date(m.created_at).getTime() < weekAgo);
                const grid = (items) => (
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 2, padding: 2 }}>
                    {items.map((m) => (
                      <div key={m.id} onClick={() => (picking ? togglePick(m.id) : (m.type === 'image' ? onOpenImage(m.media_url) : onOpenVideo({ url: m.media_url, trimStart: m.trim_start, trimEnd: m.trim_end, overlayUrl: m.overlay_url })))}
                        style={{ position: 'relative', aspectRatio: '1 / 1', background: '#000', cursor: 'pointer', overflow: 'hidden' }}>
                        {m.type === 'image'
                          ? <img src={m.media_url} alt="" loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', opacity: picking && !picked.has(m.id) ? 0.5 : 1 }} />
                          : <VideoThumb src={m.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block', pointerEvents: 'none', opacity: picking && !picked.has(m.id) ? 0.5 : 1 }} />}
                        {m.type === 'video' && !picking && (
                          <div style={{ position: 'absolute', left: 6, bottom: 6, width: 22, height: 22, borderRadius: '50%', background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                            <Play size={11} color="white" style={{ marginLeft: 1 }} />
                          </div>
                        )}
                        {picking && (
                          <div style={{ position: 'absolute', top: 6, right: 6, width: 20, height: 20, borderRadius: '50%', border: '2px solid white', background: picked.has(m.id) ? '#2563eb' : 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                            {picked.has(m.id) && <Check size={12} color="white" strokeWidth={4} />}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                );
                return (
                  <>
                    {thisWeek.length > 0 && <><div style={{ fontSize: 11, fontWeight: 900, color: theme.muted, letterSpacing: '0.08em', padding: '10px 14px 4px' }}>THIS WEEK</div>{grid(thisWeek)}</>}
                    {earlier.length > 0 && <><div style={{ fontSize: 11, fontWeight: 900, color: theme.muted, letterSpacing: '0.08em', padding: '10px 14px 4px' }}>EARLIER</div>{grid(earlier)}</>}
                  </>
                );
              })()}
              {picking && (
                <div style={{ position: 'sticky', bottom: 0, padding: '10px 14px calc(10px + env(safe-area-inset-bottom))', background: theme.panelBg, borderTop: `1px solid ${theme.border}` }}>
                  <button disabled={!picked.size} onClick={() => downloadPicked(media)} style={{ width: '100%', padding: '12px', borderRadius: 13, border: 'none', fontFamily: FONT, fontWeight: 800, fontSize: 14, cursor: picked.size ? 'pointer' : 'default', background: picked.size ? theme.coral : theme.rowBg, color: picked.size ? 'white' : theme.muted }}>{picked.size ? `Save ${picked.size} to your phone` : 'Select items to save'}</button>
                </div>
              )}
            </>
          ) : <div style={{ textAlign: 'center', padding: 40, fontSize: 13, color: theme.muted }}>Photos and videos you share will show here</div>
        )}
        {!err.links && store.links !== null && tab === 'links' && (
          links.length ? links.map(({ key, link, m }) => (
            <div key={key} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderBottom: `1px solid ${theme.border}` }}>
              <div style={{ width: 32, height: 42, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink, flexShrink: 0 }}>
                {link.includes('@') && !/^https?:|^www\./i.test(link) ? <Mail size={18} /> : <LinkIcon size={18} />}
              </div>
              <div onClick={() => openLink(link)} style={{ flex: 1, minWidth: 0, cursor: 'pointer' }}>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: theme.coralDeep, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{link}</div>
                <div style={{ fontSize: 11.5, color: theme.muted }}>{labelFor(m.sender_id)} · {dateLabel(m.created_at)}</div>
              </div>
              <span onClick={() => onJump(m.id)} style={{ fontSize: 12, fontWeight: 700, color: theme.muted, cursor: 'pointer', flexShrink: 0 }}>Show</span>
            </div>
          )) : <div style={{ textAlign: 'center', padding: 40, fontSize: 13, color: theme.muted }}>Links and emails you share will show here</div>
        )}
        {!err.voice && store.voice !== null && tab === 'voice' && (
          voices.length ? voices.map((m) => (
            <div key={m.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', borderBottom: `1px solid ${theme.border}` }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: theme.ink }}>{labelFor(m.sender_id)} <span style={{ color: theme.muted, fontWeight: 500 }}>· {dateLabel(m.created_at)}</span></div>
                <AudioBubble url={m.media_url} isMe={false} />
              </div>
              <span onClick={() => onJump(m.id)} style={{ fontSize: 12, fontWeight: 700, color: theme.muted, cursor: 'pointer', flexShrink: 0 }}>Show</span>
            </div>
          )) : <div style={{ textAlign: 'center', padding: 40, fontSize: 13, color: theme.muted }}>Voice messages will show here</div>
        )}
      </div>
    </div>
    </>
  );
}

const NAME_MAX = 30;
const USERNAME_MAX = 30;
const BIO_MAX = 150;
const STORY_MENTION_TEXT = 'Mentioned you in their story';
const STORY_GROUP_MENTION_TEXT = 'Mentioned this group in their story';
const STORY_IMAGE_MS = 5000;

function usernameProblem(u) {
  if (!u) return 'Choose a username';
  if (u.length < 3) return 'Use at least 3 characters';
  if (u.length > USERNAME_MAX) return `Use ${USERNAME_MAX} characters or fewer`;
  if (!/^[a-z0-9._]+$/.test(u)) return 'Only letters, numbers, periods and underscores';
  if (u.startsWith('.') || u.endsWith('.')) return "Usernames can't start or end with a period";
  if (u.includes('..')) return "Usernames can't have two periods in a row";
  if (/^[0-9._]+$/.test(u)) return 'Add at least one letter';
  return '';
}

function timeShort(iso) {
  const diff = Math.max(0, Date.now() - new Date(iso).getTime());
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'now';
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  return `${Math.floor(hrs / 24)}d`;
}

function badgeTierFromTitle(title) {
  const m = String(title || '').toLowerCase().match(/\b(blue|red|gold|pink|green|purple)\b/);
  return m ? m[1] : null;
}

function MailBadgeIcon({ type, size = 42, badgeTier = null }) {
  const warning = type === 'report_warning';
  const mention = type === 'mention';
  const update = type === 'update';
  const badge = type === 'badge';
  const bg = warning ? '#E5383B' : mention ? '#6F55E8' : update ? '#2F2A44' : badge ? '#1E1A2E' : '#6F55E8';
  return (
    <div style={{
      width: size, height: size, borderRadius: size * 0.32, flexShrink: 0, position: 'relative',
      background: bg, display: 'flex', alignItems: 'center', justifyContent: 'center',
    }}>
      {badge ? <VerifiedBadge tier={badgeTier || 'blue'} size={size * 0.62} style={{ marginLeft: 0, filter: 'drop-shadow(0 2px 6px rgba(0,0,0,0.35))' }} />
        : warning ? <ShieldAlert size={size * 0.5} color="white" strokeWidth={2.2} />
        : mention ? <AtSign size={size * 0.46} color="white" strokeWidth={2.4} />
          : update ? <Megaphone size={size * 0.46} color="white" strokeWidth={2.2} />
          : <span style={{ fontFamily: 'Georgia, serif', fontWeight: 800, fontSize: size * 0.5, color: 'white', lineHeight: 1 }}>Z</span>}
    </div>
  );
}

function mailSenderName(type) {
  if (type === 'report_warning') return 'ZChat Safety';
  if (type === 'mention') return 'ZChat Mentions';
  if (type === 'badge') return 'ZChat Team';
  return 'ZChat Team';
}

function VerifiedTick({ size = 13 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
      <path fill="#3D9DF2" d={BADGE_SHAPE_PATH} />
      <path d="M8.6 12.3l2.3 2.2 4.6-3.6" fill="none" stroke="white" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function StoryAvatar({ profile, size = 64, ring = 'none', onClick, badgePlus = false, dim = false, segments = null, uploading = false }) {
  const { theme } = useTheme();
  const framed = !!(profile && AVATAR_FRAMES[profile.avatar_frame]);
  const hasRing = ring !== 'none' || uploading;
  const pad = !hasRing || framed ? 0 : 4;
  return (
    <div onClick={onClick} style={{ position: 'relative', width: size, height: size, flexShrink: 0, cursor: onClick ? 'pointer' : 'default', opacity: dim ? 0.5 : 1 }}>
      <div style={{ width: size, height: size, borderRadius: '50%', padding: pad, boxSizing: 'border-box' }}>
        <Avatar emoji={profile?.avatar} name={profile?.name || '?'} frame={profile?.avatar_frame} size={size - (framed || !hasRing ? 0 : 8)} />
      </div>
      {uploading ? (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="zchat-story-upload" style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }} aria-hidden="true">
          <circle cx={size / 2} cy={size / 2} r={size / 2 - 1.5} fill="none" stroke={theme.coral} strokeWidth="2.6" strokeLinecap="round" strokeDasharray={`${size * 0.9} ${size * 0.5}`} />
        </svg>
      ) : !framed && ring !== 'none' ? (
        <StoryRing size={size} segments={segments && segments.length ? segments : [ring === 'seen']} color={theme.coral} seenColor={theme.dark ? 'rgba(255,255,255,0.28)' : 'rgba(0,0,0,0.2)'} />
      ) : null}
      {framed && ring !== 'none' && !uploading && (
        <div style={{ position: 'absolute', inset: -3, borderRadius: '50%', border: `2px solid ${ring === 'unseen' ? theme.coral : theme.border}`, pointerEvents: 'none' }} />
      )}
      {badgePlus && (
        <div style={{ position: 'absolute', right: 0, bottom: 0, zIndex: 6, width: size * 0.32, height: size * 0.32, borderRadius: '50%', background: theme.coral, border: `2.5px solid ${theme.panelBg}`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 800, fontSize: size * 0.22, lineHeight: 1 }}>+</div>
      )}
    </div>
  );
}

const TEXT_STORY_BGS = [
  { k: 'violet', label: 'Violet', bg: '#5B3FD0', ink: '#FFFFFF' },
  { k: 'coral', label: 'Coral', bg: '#E8573F', ink: '#FFFFFF' },
  { k: 'teal', label: 'Teal', bg: '#0F8B83', ink: '#FFFFFF' },
  { k: 'ink', label: 'Ink', bg: '#16161C', ink: '#FFFFFF' },
  { k: 'butter', label: 'Butter', bg: '#F6D35B', ink: '#2B2208' },
  { k: 'rose', label: 'Rose', bg: '#F2A7BE', ink: '#3A1020' },
  { k: 'sky', label: 'Sky', bg: '#3B82C4', ink: '#FFFFFF' },
  { k: 'forest', label: 'Forest', bg: '#24563A', ink: '#F2FFF4' },
  { k: 'paper', label: 'Paper', bg: '#F4EEDF', ink: '#2E2618', lines: 'rgba(80,60,30,0.16)' },
  { k: 'dots', label: 'Dots', bg: '#2E2A6B', ink: '#FFFFFF', dots: 'rgba(255,255,255,0.14)' },
  { k: 'grid', label: 'Grid', bg: '#FFFFFF', ink: '#1C2333', grid: 'rgba(59,130,246,0.18)' },
];
const TEXT_STORY_FONTS = [
  { k: 'classic', label: 'Classic', css: `800 {px}px ${FONT}` },
  { k: 'serif', label: 'Serif', css: '700 {px}px Georgia, "Times New Roman", serif' },
  { k: 'type', label: 'Typewriter', css: '600 {px}px ui-monospace, Menlo, Consolas, "Courier New", monospace' },
  { k: 'marker', label: 'Marker', css: '700 {px}px "Marker Felt", "Comic Sans MS", "Chalkboard SE", cursive' },
  { k: 'round', label: 'Rounded', css: '800 {px}px ui-rounded, "SF Pro Rounded", "Nunito", "Varela Round", system-ui, sans-serif' },
];
function textStoryFont(fontIdx, px) {
  const f = TEXT_STORY_FONTS[fontIdx] || TEXT_STORY_FONTS[0];
  return f.css.replace('{px}', String(px));
}
function wrapStoryLines(ctx, text, maxW) {
  const out = [];
  String(text || '').split('\n').forEach((para) => {
    const words = para.split(/\s+/).filter(Boolean);
    if (!words.length) { out.push(''); return; }
    let line = '';
    words.forEach((w) => {
      const tryLine = line ? `${line} ${w}` : w;
      if (ctx.measureText(tryLine).width <= maxW || !line) {
        if (!line && ctx.measureText(w).width > maxW) {
          let chunk = '';
          Array.from(w).forEach((ch) => {
            if (ctx.measureText(chunk + ch).width > maxW && chunk) { out.push(chunk); chunk = ch; } else chunk += ch;
          });
          line = chunk;
        } else line = tryLine;
      } else { out.push(line); line = w; }
    });
    out.push(line);
  });
  return out;
}
function paintTextStoryBg(ctx, W, H, b) {
  ctx.fillStyle = b.bg;
  ctx.fillRect(0, 0, W, H);
  if (b.lines) {
    ctx.strokeStyle = b.lines; ctx.lineWidth = 3;
    for (let y = 140; y < H; y += 84) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }
    ctx.strokeStyle = 'rgba(220,80,80,0.28)'; ctx.beginPath(); ctx.moveTo(120, 0); ctx.lineTo(120, H); ctx.stroke();
  }
  if (b.dots) {
    ctx.fillStyle = b.dots;
    for (let y = 30; y < H; y += 60) for (let x = (y / 60) % 2 ? 30 : 60; x < W; x += 60) { ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill(); }
  }
  if (b.grid) {
    ctx.strokeStyle = b.grid; ctx.lineWidth = 2;
    for (let x = 0; x < W; x += 54) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
    for (let y = 0; y < H; y += 54) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }
  }
}
function layoutTextStory(ctx, text, fontIdx, W, H) {
  const maxW = W - 180;
  const maxH = H - 520;
  let px = 128;
  let lines = [];
  for (; px >= 46; px -= 6) {
    ctx.font = textStoryFont(fontIdx, px);
    lines = wrapStoryLines(ctx, text, maxW);
    if (lines.length * px * 1.22 <= maxH) break;
  }
  return { px, lines };
}
async function renderTextStory(text, bgIdx, fontIdx, align) {
  const W = 1080;
  const H = 1920;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  const b = TEXT_STORY_BGS[bgIdx] || TEXT_STORY_BGS[0];
  paintTextStoryBg(ctx, W, H, b);
  try { if (document.fonts && document.fonts.ready) await document.fonts.ready; } catch {}
  const { px, lines } = layoutTextStory(ctx, text, fontIdx, W, H);
  ctx.font = textStoryFont(fontIdx, px);
  ctx.fillStyle = b.ink;
  ctx.textBaseline = 'middle';
  ctx.textAlign = align === 'left' ? 'left' : 'center';
  const lh = px * 1.22;
  const top = H / 2 - ((lines.length - 1) * lh) / 2;
  lines.forEach((ln, i) => ctx.fillText(ln, align === 'left' ? 90 : W / 2, top + i * lh));
  const blob = await new Promise((r) => c.toBlob(r, 'image/jpeg', 0.92));
  if (!blob) return null;
  return new File([blob], `zchat-text-story-${Date.now()}.jpg`, { type: 'image/jpeg' });
}

function TextStoryComposer({ onClose, onShare }) {
  useBackClose(true, onClose);
  const [text, setText] = useState('');
  const [bgIdx, setBgIdx] = useState(() => { try { const v = parseInt(localStorage.getItem('zchat-textstory-bg') || '0', 10); return Number.isFinite(v) ? v % TEXT_STORY_BGS.length : 0; } catch { return 0; } });
  const [fontIdx, setFontIdx] = useState(0);
  const [align, setAlign] = useState('center');
  const [busy, setBusy] = useState(false);
  const [showColors, setShowColors] = useState(false);
  const areaRef = useRef(null);
  const b = TEXT_STORY_BGS[bgIdx] || TEXT_STORY_BGS[0];
  useEffect(() => { try { localStorage.setItem('zchat-textstory-bg', String(bgIdx)); } catch {} }, [bgIdx]);
  useEffect(() => { const t = setTimeout(() => { try { areaRef.current && areaRef.current.focus(); } catch {} }, 250); return () => clearTimeout(t); }, []);
  const len = text.trim().length;
  const previewPx = len < 20 ? 40 : len < 60 ? 32 : len < 140 ? 26 : 21;
  const f = TEXT_STORY_FONTS[fontIdx] || TEXT_STORY_FONTS[0];
  const fam = f.css.replace(/^\d+ \{px\}px /, '');
  const weight = (f.css.match(/^(\d+)/) || [0, 700])[1];
  const bgCss = b.lines ? { backgroundColor: b.bg, backgroundImage: `repeating-linear-gradient(0deg, transparent 0 26px, ${b.lines} 26px 27px)` }
    : b.dots ? { backgroundColor: b.bg, backgroundImage: `radial-gradient(circle, ${b.dots} 1.6px, transparent 2px)`, backgroundSize: '19px 19px' }
      : b.grid ? { backgroundColor: b.bg, backgroundImage: `linear-gradient(${b.grid} 1px, transparent 1px), linear-gradient(90deg, ${b.grid} 1px, transparent 1px)`, backgroundSize: '17px 17px' }
        : { background: b.bg };
  const share = async () => {
    if (!len || busy) return;
    setBusy(true);
    const file = await renderTextStory(text.trim(), bgIdx, fontIdx, align);
    setBusy(false);
    if (file) onShare(file);
  };
  const btn = { width: 42, height: 42, borderRadius: 21, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', background: 'rgba(0,0,0,0.22)', color: '#FFFFFF', fontFamily: FONT, border: 'none' };
  return (
    <Portal>
      <div className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 640, ...bgCss, display: 'flex', flexDirection: 'column', fontFamily: FONT, color: b.ink, transition: 'background-color 0.2s ease' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 12px', paddingTop: 'calc(10px + env(safe-area-inset-top))' }}>
          <button type="button" aria-label="Back" onClick={onClose} style={btn}><X size={22} color="#FFFFFF" /></button>
          <div style={{ flex: 1 }} />
          <button type="button" aria-label="Change font" onClick={() => setFontIdx((i) => (i + 1) % TEXT_STORY_FONTS.length)} style={{ ...btn, width: 'auto', padding: '0 14px', fontWeight: 800, fontSize: 15 }}>
            <span style={{ fontFamily: fam, fontWeight: weight }}>Aa</span><span style={{ fontSize: 12.5, marginLeft: 7, opacity: 0.9 }}>{f.label}</span>
          </button>
          <button type="button" aria-label="Change alignment" onClick={() => setAlign((a) => (a === 'center' ? 'left' : 'center'))} style={btn}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#FFFFFF" strokeWidth="2.2" strokeLinecap="round" aria-hidden="true">{align === 'center' ? <path d="M4 6h16M7 12h10M5 18h14" /> : <path d="M4 6h16M4 12h10M4 18h14" />}</svg>
          </button>
          <button type="button" aria-label="Change colour" onClick={() => setShowColors((s) => !s)} style={btn}>
            <span style={{ width: 20, height: 20, borderRadius: '50%', background: b.bg, border: '2.5px solid #FFFFFF', boxSizing: 'border-box' }} />
          </button>
        </div>
        {showColors && (
          <div style={{ display: 'flex', gap: 10, overflowX: 'auto', padding: '4px 14px 10px', scrollbarWidth: 'none' }}>
            {TEXT_STORY_BGS.map((o, i) => (
              <div key={o.k} role="button" aria-label={`Background ${o.label}`} onClick={() => setBgIdx(i)} style={{ width: 34, height: 34, flexShrink: 0, borderRadius: '50%', background: o.bg, border: i === bgIdx ? '3px solid #FFFFFF' : '2px solid rgba(255,255,255,0.5)', boxSizing: 'border-box', cursor: 'pointer', boxShadow: '0 0 0 1px rgba(0,0,0,0.15)' }} />
            ))}
          </div>
        )}
        <div onClick={() => { try { areaRef.current && areaRef.current.focus(); } catch {} }} style={{ flex: 1, minHeight: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 26px', cursor: 'text' }}>
          <textarea ref={areaRef} value={text} onChange={(e) => setText(e.target.value.slice(0, 700))} placeholder="Type a status" aria-label="Status text" rows={1}
            style={{ width: '100%', maxHeight: '100%', resize: 'none', border: 'none', outline: 'none', background: 'transparent', color: b.ink, textAlign: align, fontFamily: fam, fontWeight: weight, fontSize: previewPx, lineHeight: 1.22, caretColor: b.ink, overflow: 'auto', fieldSizing: 'content', minHeight: previewPx * 1.3 }} />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))' }}>
          <div style={{ flex: 1, fontSize: 12.5, opacity: 0.85, fontWeight: 600 }}>{len ? `${len}/700` : 'Shared with your followers for 24 hours'}</div>
          <button type="button" aria-label="Share to your story" disabled={!len || busy} onClick={share} style={{ height: 44, padding: '0 18px', borderRadius: 22, border: 'none', background: '#FFFFFF', color: '#111', fontFamily: FONT, fontWeight: 800, fontSize: 14.5, display: 'flex', alignItems: 'center', gap: 8, cursor: len ? 'pointer' : 'default', opacity: len ? 1 : 0.55 }}>
            {busy ? <Spinner size={16} color="#111" /> : <StatusIcon size={17} color="#111" />}Your story
          </button>
        </div>
      </div>
    </Portal>
  );
}

function StoryCreateSheet({ onClose, onCamera, onGallery, onText, onDraw }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const drag = useSheetDrag(onClose);
  const items = [
    { k: 'camera', label: 'Camera', icon: <Camera />, on: onCamera },
    { k: 'gallery', label: 'Photos and videos', short: 'Gallery', icon: <ImageIcon />, on: onGallery },
    { k: 'text', label: 'Text', icon: <Type />, on: onText },
    { k: 'draw', label: 'Draw', icon: <DoodleIcon />, on: onDraw },
  ];
  return (
    <Portal>
      <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 640, background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT }}>
        <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" {...drag.sheetProps} style={{ ...drag.sheetStyle, width: '100%', maxWidth: 480, background: theme.panelBg, borderRadius: '22px 22px 0 0', paddingBottom: 'calc(16px + env(safe-area-inset-bottom))' }}>
          <div data-sheet-handle="true" style={{ display: 'flex', justifyContent: 'center', padding: '9px 0 4px', touchAction: 'none' }}><div style={{ width: 36, height: 4, borderRadius: 2, background: theme.border }} /></div>
          <div style={{ fontSize: 16, fontWeight: 800, color: theme.ink, textAlign: 'center', padding: '6px 16px 14px' }}>New story</div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 4, padding: '0 10px 4px' }}>
            {items.map((it) => (
              <div key={it.k} role="button" aria-label={it.label} onClick={() => { playUiSound('tap'); it.on(); }} className="zchat-press zplain-tile" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 9, padding: '13px 2px 11px', borderRadius: 16, cursor: 'pointer', WebkitTapHighlightColor: 'transparent' }}>
                <div style={{ height: 32, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{React.cloneElement(it.icon, { size: 30, strokeWidth: 1.6, color: theme.ink })}</div>
                <div style={{ fontSize: 12.5, fontWeight: 600, color: theme.ink }}>{it.short || it.label}</div>
              </div>
            ))}
          </div>
          <div style={{ fontSize: 12, color: theme.muted, textAlign: 'center', padding: '14px 24px 0', lineHeight: 1.45 }}>Stories disappear after 24 hours. Your followers can see them.</div>
        </div>
      </div>
    </Portal>
  );
}

function readStoryMutes(uid) {
  try { const a = JSON.parse(localStorage.getItem(`zchat-story-mutes-${uid}`) || '[]'); return new Set(Array.isArray(a) ? a : []); } catch { return new Set(); }
}
function writeStoryMutes(uid, set) {
  try { localStorage.setItem(`zchat-story-mutes-${uid}`, JSON.stringify([...set].slice(-500))); } catch {}
  try { window.dispatchEvent(new Event('zchat-story-mutes')); } catch {}
}

function StoryRing({ size, segments, color, seenColor, gap = 6, width = 2.6 }) {
  const n = segments.length;
  const r = size / 2 - width / 2;
  const circ = 2 * Math.PI * r;
  const gapLen = n > 1 ? Math.min(gap, circ / n / 3) : 0;
  const seg = circ / n - gapLen;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ position: 'absolute', inset: 0, transform: 'rotate(-90deg)', pointerEvents: 'none' }} aria-hidden="true">
      {segments.map((seen, i) => (
        <circle key={i} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={seen ? seenColor : color} strokeWidth={seen ? Math.max(1.6, width - 1) : width} strokeLinecap="round"
          strokeDasharray={`${Math.max(0.1, seg)} ${circ}`} strokeDashoffset={-(i * (seg + gapLen))} />
      ))}
    </svg>
  );
}

function AddToHighlightSheet({ userId, story, onClose, onDone }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const drag = useSheetDrag(onClose);
  const [list, setList] = useState(null);
  const [busy, setBusy] = useState(null);
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  useEffect(() => {
    let alive = true;
    supabase.from('highlights').select('*').eq('user_id', userId).order('created_at', { ascending: false }).then(({ data }) => { if (alive) setList(data || []); });
    return () => { alive = false; };
  }, [userId]);
  const item = (hid) => ({ highlight_id: hid, user_id: userId, media_url: story.media_url, media_type: story.media_type, overlay_url: story.overlay_url || null, caption: story.caption || null });
  const addTo = async (h) => {
    if (busy) return;
    setBusy(h.id);
    const { error } = await supabase.from('highlight_items').insert(item(h.id));
    setBusy(null);
    onDone(error ? "Couldn't add it. Try again." : `Added to ${h.title}`);
  };
  const createNew = async () => {
    if (busy) return;
    setBusy('new');
    const { data: h, error } = await supabase.from('highlights').insert({ user_id: userId, title: (title.trim() || 'Highlights').slice(0, 20), cover_url: story.media_url, cover_type: story.media_type }).select().single();
    if (error || !h) { setBusy(null); onDone("Couldn't make the highlight. Try again."); return; }
    await supabase.from('highlight_items').insert(item(h.id));
    setBusy(null);
    onDone(`Added to ${h.title}`);
  };
  return (
    <Portal>
      <div onClick={onClose} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 700, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT }}>
        <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" {...drag.sheetProps} style={{ ...drag.sheetStyle, width: '100%', maxWidth: 480, maxHeight: 'min(80vh, calc(100% - 24px))', overflowY: 'auto', background: theme.panelBg, borderRadius: '22px 22px 0 0', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))' }}>
          <div data-sheet-handle="true" style={{ display: 'flex', justifyContent: 'center', padding: '9px 0 4px', touchAction: 'none' }}><div style={{ width: 36, height: 4, borderRadius: 2, background: theme.border }} /></div>
          <div style={{ fontSize: 16, fontWeight: 800, color: theme.ink, textAlign: 'center', padding: '6px 16px 12px' }}>Add to highlight</div>
          <div style={{ display: 'flex', gap: 14, overflowX: 'auto', padding: '2px 16px 10px', scrollbarWidth: 'none' }}>
            <div role="button" aria-label="New highlight" onClick={() => setCreating(true)} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, flexShrink: 0, cursor: 'pointer', width: 70 }}>
              <div style={{ width: 64, height: 64, borderRadius: '50%', border: `2px dashed ${theme.muted}`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink }}><Plus size={24} /></div>
              <div style={{ fontSize: 12, color: theme.ink, fontWeight: 600 }}>New</div>
            </div>
            {list === null && <div style={{ display: 'flex', alignItems: 'center', padding: '0 10px' }}><Spinner size={18} color={theme.muted} /></div>}
            {(list || []).map((h) => (
              <div key={h.id} role="button" aria-label={`Highlight ${h.title}`} onClick={() => addTo(h)} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, flexShrink: 0, cursor: 'pointer', width: 70, opacity: busy && busy !== h.id ? 0.5 : 1 }}>
                <div style={{ width: 64, height: 64, borderRadius: '50%', overflow: 'hidden', background: theme.rowBg, border: `2px solid ${theme.border}`, position: 'relative' }}>
                  {h.cover_type === 'video' ? <VideoThumb src={h.cover_url} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <img src={h.cover_url} alt="" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
                  {busy === h.id && <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Spinner size={16} color="#FFFFFF" /></div>}
                </div>
                <div style={{ fontSize: 12, color: theme.ink, fontWeight: 600, maxWidth: 70, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{h.title}</div>
              </div>
            ))}
          </div>
          {creating && (
            <div style={{ display: 'flex', gap: 8, padding: '6px 16px 4px' }}>
              <input autoFocus value={title} onChange={(e) => setTitle(e.target.value.slice(0, 20))} placeholder="Highlight name" aria-label="Highlight name" style={{ ...inputStyle(theme), flex: 1 }} />
              <button type="button" onClick={createNew} disabled={busy === 'new'} style={{ padding: '0 16px', borderRadius: 12, border: 'none', background: theme.coral, color: '#FFFFFF', fontWeight: 800, fontFamily: FONT, cursor: 'pointer' }}>{busy === 'new' ? <Spinner size={14} color="#FFFFFF" /> : 'Add'}</button>
            </div>
          )}
        </div>
      </div>
    </Portal>
  );
}

function StoryArchivePage({ userId, onClose, onOpen }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [rows, setRows] = useState(null);
  useEffect(() => {
    let alive = true;
    supabase.from('stories').select('*').eq('user_id', userId).order('created_at', { ascending: false }).limit(300).then(({ data }) => { if (alive) setRows((data || []).filter((s) => !s.repost_of)); });
    return () => { alive = false; };
  }, [userId]);
  const groups = [];
  (rows || []).forEach((s) => {
    const d = new Date(s.created_at);
    const key = `${d.getFullYear()}-${d.getMonth()}`;
    const label = d.toLocaleDateString([], { month: 'long', year: 'numeric' });
    let g = groups.find((x) => x.key === key);
    if (!g) { g = { key, label, items: [] }; groups.push(g); }
    g.items.push(s);
  });
  const all = rows || [];
  return (
    <FullPage title="Story archive" subtitle={rows ? `${rows.length} ${rows.length === 1 ? 'story' : 'stories'}` : null} onBack={onClose} zIndex={90} pad={false} portal={false}>
      {rows === null && <div style={{ display: 'flex', justifyContent: 'center', padding: 40 }}><Spinner size={22} color={theme.coral} /></div>}
      {rows && !rows.length && <EmptyState art="moments" title="No old stories yet" text="Stories you share are kept here after they disappear, only you can see this." />}
      {groups.map((g) => (
        <div key={g.key}>
          <div style={{ fontSize: 13, fontWeight: 800, color: theme.muted, padding: '14px 16px 8px' }}>{g.label}</div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 2 }}>
            {g.items.map((s) => (
              <div key={s.id} role="button" aria-label="Open old story" onClick={() => onOpen(all, s.id)} style={{ position: 'relative', aspectRatio: '9 / 16', background: theme.rowBg, overflow: 'hidden', cursor: 'pointer' }}>
                {s.media_type === 'video' ? <VideoThumb src={s.media_url} style={{ width: '100%', height: '100%', objectFit: 'cover', pointerEvents: 'none' }} /> : <img src={s.media_url} alt="" loading="lazy" draggable={false} style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />}
                <div style={{ position: 'absolute', left: 6, top: 6, background: 'rgba(0,0,0,0.5)', color: '#FFFFFF', borderRadius: 8, padding: '3px 7px', fontSize: 11.5, fontWeight: 800, lineHeight: 1.1, textAlign: 'center' }}>
                  <div>{new Date(s.created_at).getDate()}</div>
                  <div style={{ fontSize: 9.5, fontWeight: 700, opacity: 0.85 }}>{new Date(s.created_at).toLocaleDateString([], { month: 'short' })}</div>
                </div>
                {isActiveUntil(s.expires_at) && <div style={{ position: 'absolute', right: 6, bottom: 6, background: theme.coral, color: '#FFFFFF', borderRadius: 7, padding: '2px 6px', fontSize: 10, fontWeight: 800 }}>Live</div>}
              </div>
            ))}
          </div>
        </div>
      ))}
    </FullPage>
  );
}

function StoryMentionPicker({ myId, groups, privacyCtx, onPick, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const [q, setQ] = useState('');
  const [people, setPeople] = useState([]);
  const [hiddenCount, setHiddenCount] = useState(0);
  useEffect(() => {
    const term = q.trim().replace(/^@/, '');
    if (term.length < 1) { setPeople([]); setHiddenCount(0); return undefined; }
    let cancelled = false;
    const t = setTimeout(async () => {
      const { data } = await searchAccounts(term);
      const found = sanitizeAvatarList(data, myId).filter((p) => p.id !== myId && !p.is_deleted).slice(0, 24);
      let tagSetting = null;
      if (found.length) {
        const { data: rows, error } = await supabase.from('profiles').select('id, privacy_tags').in('id', found.map((p) => p.id));
        if (!error && rows) tagSetting = new Map(rows.map((r) => [r.id, r.privacy_tags]));
      }
      const ctx = privacyCtx || {};
      const iFollow = ctx.iFollow || new Set();
      const allowed = ctx.allowed || new Set();
      const ok = found.filter((p) => privacyAllows({ ...p, privacy_tags: tagSetting ? tagSetting.get(p.id) : p.privacy_tags }, 'privacy_tags', myId, iFollow, allowed));
      if (!cancelled) { setPeople(ok.slice(0, 12)); setHiddenCount(found.length - ok.length); }
    }, 220);
    return () => { cancelled = true; clearTimeout(t); };
  }, [q]);
  const term = q.trim().replace(/^@/, '').toLowerCase();
  const groupMatches = (groups || []).filter((g) => !term || (g.name || '').toLowerCase().includes(term)).slice(0, 8);
  return (
    <div onClick={onClose} style={{ position: 'absolute', inset: 0, zIndex: 8, background: 'rgba(0,0,0,0.55)', display: 'flex', alignItems: 'flex-end' }}>
      <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxHeight: '70%', background: '#11151F', borderRadius: '22px 22px 0 0', display: 'flex', flexDirection: 'column', paddingBottom: 'env(safe-area-inset-bottom)' }}>
        <div style={{ padding: '14px 16px 8px', display: 'flex', alignItems: 'center', gap: 10 }}>
          <AtSign size={18} color="white" />
          <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Mention people or groups"
            style={{ flex: 1, background: 'rgba(255,255,255,0.1)', border: 'none', outline: 'none', color: 'white', borderRadius: 18, padding: '10px 14px', fontFamily: FONT, fontSize: 15 }} />
          <X size={20} color="white" style={{ cursor: 'pointer' }} onClick={onClose} />
        </div>
        <div style={{ overflowY: 'auto', padding: '4px 8px 12px' }}>
          {groupMatches.map((g) => (
            <div key={`g-${g.id}`} onClick={() => onPick({ id: g.id, kind: 'group', label: g.name })} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px', cursor: 'pointer', color: 'white' }}>
              <GroupAvatar avatar={g.avatar} name={g.name} size={38} />
              <div><div style={{ fontWeight: 700, fontSize: 14 }}>{g.name}</div><div style={{ fontSize: 11.5, opacity: 0.6 }}>Group</div></div>
            </div>
          ))}
          {people.map((p) => (
            <div key={p.id} onClick={() => onPick({ id: p.id, kind: 'user', label: p.username })} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '8px', cursor: 'pointer', color: 'white' }}>
              <Avatar emoji={p.avatar} name={p.name} frame={p.avatar_frame} size={38} />
              <div><div style={{ fontWeight: 700, fontSize: 14 }}>{p.name}</div><div style={{ fontSize: 11.5, opacity: 0.6 }}>@{p.username}</div></div>
            </div>
          ))}
          {!groupMatches.length && !people.length && (
            <div style={{ textAlign: 'center', padding: 20, fontSize: 13, color: 'rgba(255,255,255,0.6)' }}>{term ? (hiddenCount > 0 ? 'No one you can tag matches that' : 'No one found') : 'Type a name to mention someone'}</div>
          )}
          {hiddenCount > 0 && (
            <div style={{ textAlign: 'center', padding: '6px 16px 10px', fontSize: 11.5, color: 'rgba(255,255,255,0.5)' }}>
              {hiddenCount === 1 ? '1 account does not allow tags from you.' : `${hiddenCount} accounts do not allow tags from you.`}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function StoryViewer({ groupsList, startGroup = 0, startStoryId = null, onAddStory, onShare, externalPause = false, readOnly = false, highlightLike = null, initialRepostedIds = null, myId, seen, liked, onSeen, onClose, onLike, onReply, onRepost, onDelete, onReport, onOpenProfile, onOpenMention, mutedIds = null, onToggleMute, onAddToHighlight, onOpenArchive, extraActions }) {
  useBackClose(true, onClose);
  const [gi, setGi] = useState(startGroup);
  const [si, setSi] = useState(() => {
    const g = groupsList[startGroup];
    if (!g) return 0;
    if (startStoryId) {
      const at = g.stories.findIndex((s) => s.id === startStoryId);
      if (at >= 0) return at;
    }
    const idx = g.stories.findIndex((s) => !seen.has(s.id));
    return idx >= 0 && g.profile.id !== myId ? idx : 0;
  });
  const [paused, setPaused] = useState(false);
  const [holding, setHolding] = useState(false);
  const [hideUi, setHideUi] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [failed, setFailed] = useState(false);
  const [muted, setMuted] = useState(() => { try { return localStorage.getItem('zchat-story-muted') === '1'; } catch { return false; } });
  const [reply, setReply] = useState('');
  const [replyFocus, setReplyFocus] = useState(false);
  const [showViewers, setShowViewers] = useState(false);
  const [menu, setMenu] = useState(false);
  useBackClose(menu, () => setMenu(false));
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [confirmRepost, setConfirmRepost] = useState(false);
  const [flash, setFlash] = useState('');
  const [viewCount, setViewCount] = useState(null);
  const [likeBurst, setLikeBurst] = useState(false);
  const [burstEmoji, setBurstEmoji] = useState('');
  const [repostedIds, setRepostedIds] = useState(() => new Set(initialRepostedIds || []));
  const [repostBusy, setRepostBusy] = useState(false);
  const [repostPop, setRepostPop] = useState(false);
  const [keyboardLift, setKeyboardLift] = useState(0);
  const [viewTop, setViewTop] = useState(0);
  const [dragX, setDragX] = useState(0);
  const [settling, setSettling] = useState(false);
  const [slideIn, setSlideIn] = useState('');
  const [pageHidden, setPageHidden] = useState(false);
  const [wide, setWide] = useState(() => typeof window !== 'undefined' && window.innerWidth >= 760);
  const videoRef = useRef(null);
  const elapsedRef = useRef(0);
  const lastTickRef = useRef(0);
  const durationRef = useRef(STORY_IMAGE_MS);
  const progressRef = useRef(0);
  const pressRef = useRef(null);
  const barRefs = useRef([]);
  const flashTimer = useRef(0);
  const stageRef = useRef(null);

  const group = groupsList[gi];
  const story = group ? group.stories[Math.min(si, group.stories.length - 1)] : null;
  const isMine = !!group && group.profile.id === myId;
  const stopped = paused || holding || replyFocus || showViewers || menu || confirmDelete || confirmRepost || externalPause || !loaded || pageHidden || dragX !== 0 || settling;
  const stoppedRef = useRef(stopped);
  stoppedRef.current = stopped;

  const showFlash = (text, ms = 1500) => { clearTimeout(flashTimer.current); setFlash(text); flashTimer.current = setTimeout(() => setFlash(''), ms); };

  function goNext() {
    if (!group) return;
    if (si < group.stories.length - 1) { setSi(si + 1); return; }
    if (gi < groupsList.length - 1) {
      const nextGroup = groupsList[gi + 1];
      const idx = nextGroup.stories.findIndex((s) => !seen.has(s.id));
      setSlideIn('next');
      setGi(gi + 1);
      setSi(idx >= 0 ? idx : 0);
      return;
    }
    onClose();
  }
  function goPrev() {
    if (!group) return;
    if (si > 0) { setSi(si - 1); return; }
    if (gi > 0) { setSlideIn('prev'); setSi(groupsList[gi - 1].stories.length - 1); setGi(gi - 1); return; }
    elapsedRef.current = 0;
    progressRef.current = 0;
    const bar = barRefs.current[si];
    if (bar) bar.style.width = '0%';
    if (videoRef.current) { try { videoRef.current.currentTime = 0; } catch {} }
  }
  function goGroup(dir) {
    if (dir > 0) {
      if (gi < groupsList.length - 1) { const ng = groupsList[gi + 1]; const idx = ng.stories.findIndex((s) => !seen.has(s.id)); setSlideIn('next'); setGi(gi + 1); setSi(idx >= 0 ? idx : 0); } else onClose();
    } else if (gi > 0) { setSlideIn('prev'); setGi(gi - 1); setSi(0); } else { goPrev(); }
  }

  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return undefined;
    let frame = 0;
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => { setKeyboardLift(Math.max(0, Math.round(window.innerHeight - vv.height - vv.offsetTop))); setViewTop(Math.max(0, Math.round(vv.offsetTop))); });
    };
    vv.addEventListener('resize', update);
    vv.addEventListener('scroll', update);
    update();
    return () => { cancelAnimationFrame(frame); vv.removeEventListener('resize', update); vv.removeEventListener('scroll', update); };
  }, []);
  useEffect(() => {
    const onVis = () => setPageHidden(document.visibilityState === 'hidden');
    const onResize = () => setWide(window.innerWidth >= 760);
    document.addEventListener('visibilitychange', onVis);
    window.addEventListener('resize', onResize);
    return () => { document.removeEventListener('visibilitychange', onVis); window.removeEventListener('resize', onResize); clearTimeout(flashTimer.current); };
  }, []);
  useEffect(() => {
    if (!groupsList.length) { onClose(); return; }
    if (!groupsList[gi]) { setGi(groupsList.length - 1); setSi(0); return; }
    const count = groupsList[gi].stories.length;
    if (si >= count) setSi(Math.max(0, count - 1));
  }, [groupsList]);
  useEffect(() => {
    if (!story) return;
    elapsedRef.current = 0;
    progressRef.current = 0;
    setLoaded(false);
    setFailed(false);
    durationRef.current = STORY_IMAGE_MS;
    onSeen(story);
    setViewCount(null);
    if (!readOnly && group.profile.id === myId) {
      supabase.from('story_views').select('*', { count: 'exact', head: true }).eq('story_id', story.id).then(({ count }) => setViewCount(count || 0));
    }
    const pre = [];
    if (group.stories[si + 1]) pre.push(group.stories[si + 1]);
    const ng = groupsList[gi + 1];
    if (ng && ng.stories.length) pre.push(ng.stories[Math.max(0, ng.stories.findIndex((s) => !seen.has(s.id)))]);
    pre.forEach((s) => {
      if (!s || !s.media_url) return;
      if (s.media_type === 'video') { const v = document.createElement('video'); v.preload = 'auto'; v.muted = true; v.src = s.media_url; } else { const im = new Image(); im.decoding = 'async'; im.src = s.media_url; }
    });
  }, [story && story.id]);
  useEffect(() => {
    if (!slideIn) return undefined;
    const t = setTimeout(() => setSlideIn(''), 320);
    return () => clearTimeout(t);
  }, [slideIn, gi]);
  useEffect(() => {
    if (!holding) { setHideUi(false); return undefined; }
    const t = setTimeout(() => setHideUi(true), 240);
    return () => clearTimeout(t);
  }, [holding]);
  useEffect(() => {
    if (!story) return undefined;
    let frame = 0;
    lastTickRef.current = performance.now();
    const tick = (t) => {
      const dt = Math.min(100, t - lastTickRef.current);
      lastTickRef.current = t;
      if (!stoppedRef.current) {
        let p;
        const v = videoRef.current;
        if (story.media_type === 'video' && v && !failed && Number.isFinite(v.duration) && v.duration > 0) {
          const total = Math.min(v.duration, 60);
          p = v.ended ? 1 : Math.min(1, v.currentTime / total);
          if (v.currentTime >= total - 0.04) p = 1;
        } else {
          elapsedRef.current += dt;
          p = Math.min(1, elapsedRef.current / durationRef.current);
        }
        progressRef.current = p;
        const bar = barRefs.current[si];
        if (bar) bar.style.width = `${p * 100}%`;
        if (p >= 1) { goNext(); return; }
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [gi, si, story && story.id, failed]);
  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    if (stopped && loaded) v.pause(); else if (!stopped) v.play().catch(() => { if (!v.muted) { setMuted(true); } });
  }, [stopped, loaded, story && story.id]);
  useEffect(() => {
    const onKey = (e) => {
      const tag = e.target && e.target.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      if (e.key === 'ArrowRight') { e.preventDefault(); goNext(); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); goPrev(); }
      else if (e.key === ' ') { e.preventDefault(); setPaused((p) => !p); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  if (!group || !story) return null;

  const width = () => (stageRef.current ? stageRef.current.getBoundingClientRect().width : window.innerWidth);
  const onDown = (e) => {
    if (e.target.closest && e.target.closest('[data-story-control]')) return;
    pressRef.current = { x: e.clientX, y: e.clientY, t: Date.now(), horiz: false };
    setHolding(true);
  };
  const onMove = (e) => {
    const p = pressRef.current;
    if (!p || replyFocus) return;
    const dx = e.clientX - p.x;
    const dy = e.clientY - p.y;
    if (!p.horiz && Math.abs(dx) > 14 && Math.abs(dx) > Math.abs(dy) * 1.2) p.horiz = true;
    if (p.horiz) {
      const atEdge = dx > 0 && gi === 0;
      setDragX(atEdge ? dx * 0.3 : dx);
    }
  };
  const onUp = (e) => {
    const p = pressRef.current;
    pressRef.current = null;
    setHolding(false);
    if (!p) return;
    if (replyFocus) {
      const el = document.querySelector('[data-story-reply]');
      if (el) el.blur();
      setReplyFocus(false);
      return;
    }
    const dx = e.clientX - p.x;
    const dy = e.clientY - p.y;
    if (p.horiz) {
      const w = width();
      const fast = Math.abs(dx) / Math.max(1, Date.now() - p.t) > 0.5;
      if ((Math.abs(dx) > w * 0.22 || (fast && Math.abs(dx) > 40)) && !(dx > 0 && gi === 0)) {
        setDragX(0);
        goGroup(dx < 0 ? 1 : -1);
      } else {
        setSettling(true);
        setDragX(0);
        setTimeout(() => setSettling(false), 200);
      }
      return;
    }
    if (dy > 90 && Math.abs(dy) > Math.abs(dx)) { onClose(); return; }
    if (dy < -70 && Math.abs(dy) > Math.abs(dx) && isMine && !readOnly) { setShowViewers(true); return; }
    if (dy < -70 && Math.abs(dy) > Math.abs(dx) && !isMine && !readOnly) { setReplyFocus(true); const el = document.querySelector('[data-story-reply]'); if (el) el.focus(); return; }
    if (Date.now() - p.t > 260 || Math.abs(dx) > 14 || Math.abs(dy) > 14) return;
    if (e.clientX - (stageRef.current ? stageRef.current.getBoundingClientRect().left : 0) < width() * 0.3) goPrev(); else goNext();
  };

  const isLiked = liked.has(story.id);
  const toggleLike = () => {
    if (!isLiked) { setLikeBurst(true); setTimeout(() => setLikeBurst(false), 700); }
    onLike(story, !isLiked);
  };
  const repostedHere = repostedIds.has(story.id);
  const doRepost = async () => {
    setConfirmRepost(false);
    playUiSound('repost');
    setRepostBusy(true);
    const result = await onRepost(story, group.profile);
    setRepostBusy(false);
    if (result === 'ok' || result === 'already') {
      setRepostedIds((prev) => new Set(prev).add(story.id));
      setRepostPop(true);
      setTimeout(() => setRepostPop(false), 700);
      showFlash(result === 'ok' ? 'Added to your story' : 'Already on your story', 1600);
    }
  };
  const sendReply = async () => {
    const text = reply.trim();
    if (!text) return;
    setReply('');
    const el = document.querySelector('[data-story-reply]');
    if (el) el.blur();
    setReplyFocus(false);
    showFlash('Sent', 1400);
    await onReply(story, group.profile, text);
  };
  const sendQuickReaction = async (emo) => {
    const el = document.querySelector('[data-story-reply]');
    if (el) el.blur();
    setReplyFocus(false);
    setBurstEmoji(emo);
    setTimeout(() => setBurstEmoji(''), 900);
    await onReply(story, group.profile, emo);
  };
  const mentions = Array.isArray(story.mentions) ? story.mentions : [];
  const ownerMuted = !!(mutedIds && !isMine && mutedIds.has(group.profile.id));
  const uiFade = { opacity: hideUi ? 0 : 1, transition: 'opacity 0.18s ease', pointerEvents: hideUi ? 'none' : undefined };
  const menuItems = isMine && !readOnly ? [
    onShare ? { k: 'share', label: 'Share', on: () => onShare(story, group.profile) } : null,
    onAddToHighlight ? { k: 'hl', label: 'Add to highlight', on: () => onAddToHighlight(story) } : null,
    { k: 'save', label: 'Save to phone', on: () => { silentDownload(story.media_url, story.media_type === 'video' ? 'zchat-story.mp4' : 'zchat-story.jpg'); showFlash('Saving'); } },
    onOpenArchive ? { k: 'archive', label: 'Story archive', on: () => onOpenArchive() } : null,
    { k: 'delete', label: 'Delete story', danger: true, on: () => setConfirmDelete(true) },
  ] : [
    onShare ? { k: 'share', label: 'Share', on: () => onShare(story, group.profile) } : null,
    onToggleMute ? { k: 'mute', label: ownerMuted ? `Unmute stories from ${(group.profile.name || '').split(' ')[0]}` : `Mute stories from ${(group.profile.name || '').split(' ')[0]}`, on: () => { const nowMuted = !ownerMuted; onToggleMute(group.profile, nowMuted); showFlash(nowMuted ? 'Muted' : 'Unmuted'); } } : null,
    { k: 'profile', label: 'View profile', on: () => onOpenProfile(group.profile) },
    { k: 'report', label: 'Report', danger: true, on: () => onReport(group.profile) },
  ];
  const navBtn = { position: 'absolute', top: '50%', marginTop: -22, width: 44, height: 44, borderRadius: '50%', background: 'rgba(255,255,255,0.16)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', zIndex: 20, border: 'none' };
  const stageAnim = slideIn === 'next' ? 'zchat-story-in-next 0.3s cubic-bezier(0.2, 0.9, 0.3, 1)' : slideIn === 'prev' ? 'zchat-story-in-prev 0.3s cubic-bezier(0.2, 0.9, 0.3, 1)' : undefined;

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 250, background: '#000', display: 'flex', justifyContent: 'center' }} className="zchat-fade">
      {wide && (gi > 0 || si > 0) && <button type="button" aria-label="Previous story" data-story-control onClick={goPrev} style={{ ...navBtn, left: 'calc(50% - 320px)' }}><ChevronLeft size={24} color="#FFFFFF" /></button>}
      {wide && <button type="button" aria-label="Next story" data-story-control onClick={goNext} style={{ ...navBtn, right: 'calc(50% - 320px)' }}><ChevronRight size={24} color="#FFFFFF" /></button>}
      <div ref={stageRef} key={`g-${gi}`} style={{ position: 'relative', width: '100%', maxWidth: 520, height: '100%', overflow: 'hidden', color: 'white', transform: dragX ? `translateX(${dragX}px)` : undefined, transition: settling ? 'transform 0.2s ease' : 'none', animation: stageAnim, borderRadius: wide ? 14 : 0 }}>
        <div onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={() => { pressRef.current = null; setHolding(false); setDragX(0); }}
          onDoubleClick={() => { if (!isMine && !readOnly) toggleLike(); }}
          style={{ position: 'absolute', inset: 0, touchAction: 'none', userSelect: 'none' }}>
          {story.media_type === 'video' ? (
            <video key={story.id} ref={videoRef} src={story.media_url} playsInline autoPlay muted={muted}
              onLoadedMetadata={(e) => { const d = e.currentTarget.duration; durationRef.current = Number.isFinite(d) && d > 0 ? Math.min(d, 60) * 1000 : 15000; setLoaded(true); }}
              onError={() => { setFailed(true); setLoaded(true); }}
              style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', pointerEvents: 'none' }} />
          ) : (
            <img key={story.id} src={story.media_url} alt="" draggable={false} onLoad={() => setLoaded(true)} onError={() => { setFailed(true); setLoaded(true); }}
              style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', pointerEvents: 'none' }} />
          )}
          {story.overlay_url && story.media_type === 'video' && !failed && (
            <img src={story.overlay_url} alt="" draggable={false} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'contain', pointerEvents: 'none' }} />
          )}
          {!loaded && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Spinner size={26} /></div>}
          {failed && (
            <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 10, padding: 30, textAlign: 'center' }}>
              <div style={{ fontSize: 15, fontWeight: 700 }}>This story couldn't load</div>
              <div style={{ fontSize: 13, opacity: 0.7 }}>Check your connection. It moves on by itself.</div>
            </div>
          )}
          {paused && !holding && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}><div style={{ width: 64, height: 64, borderRadius: '50%', background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Pause size={28} color="#FFFFFF" /></div></div>}
          {burstEmoji && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none', fontSize: 120, animation: 'zchat-heart-burst 0.9s ease' }}>{burstEmoji}</div>}
          {likeBurst && <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none', animation: 'zchat-heart-burst 0.7s ease' }}><Heart size={110} color="#FF3B5C" fill="#FF3B5C" /></div>}
        </div>

        <div style={{ position: 'absolute', left: 0, right: 0, top: viewTop, zIndex: 5, padding: 'calc(8px + env(safe-area-inset-top)) 10px 28px', background: 'linear-gradient(180deg, rgba(0,0,0,0.55), rgba(0,0,0,0))', pointerEvents: 'none', ...uiFade }}>
          <div style={{ display: 'flex', gap: 3 }}>
            {group.stories.map((s, i) => (
              <div key={s.id} style={{ flex: 1, height: 2.5, borderRadius: 2, background: 'rgba(255,255,255,0.35)', overflow: 'hidden' }}>
                <div ref={(el) => { barRefs.current[i] = el; }} style={{ height: '100%', background: 'white', width: `${i < si ? 100 : i === si ? progressRef.current * 100 : 0}%` }} />
              </div>
            ))}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 10, pointerEvents: hideUi ? 'none' : 'auto' }} data-story-control>
            <div onClick={() => onOpenProfile(group.profile)} style={{ display: 'flex', alignItems: 'center', gap: 9, flex: 1, minWidth: 0, cursor: 'pointer' }}>
              <Avatar emoji={group.profile.avatar} name={group.profile.name} frame={group.profile.avatar_frame} size={34} />
              <div style={{ minWidth: 0 }}>
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 7 }}>
                  <span style={{ fontWeight: 800, fontSize: 14, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{isMine && !readOnly ? 'Your story' : group.profile.name}<VerifiedBadge tier={group.profile.verified} custom={group.profile.custom_badge} size={13} /></span>
                  <span style={{ fontSize: 12, opacity: 0.75, flexShrink: 0 }}>{timeShort(story.created_at)}</span>
                </div>
                {story.repost_of && <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, opacity: 0.8 }}><Repeat size={11} /> Reposted{story.repost_label ? ` from @${story.repost_label}` : ''}</div>}
              </div>
            </div>
            <div role="button" aria-label={paused ? 'Play story' : 'Pause story'} onClick={() => setPaused((pp) => !pp)} style={{ padding: 6, cursor: 'pointer', display: 'flex' }}>{paused ? <Play size={20} color="white" /> : <Pause size={20} color="white" />}</div>
            {story.media_type === 'video' && (
              <div role="button" aria-label={muted ? 'Sound on' : 'Sound off'} onClick={() => { setMuted((m) => { const n = !m; try { localStorage.setItem('zchat-story-muted', n ? '1' : '0'); } catch {} return n; }); }} style={{ padding: 6, cursor: 'pointer', display: 'flex' }}>{muted ? <VolumeX size={20} color="white" /> : <Volume2 size={20} color="white" />}</div>
            )}
            {!readOnly && <div role="button" aria-label="Story options" onClick={() => setMenu(true)} style={{ padding: 6, cursor: 'pointer', display: 'flex' }}><MoreVertical size={20} color="white" /></div>}
            <div role="button" aria-label="Close story" onClick={onClose} style={{ padding: 6, cursor: 'pointer', display: 'flex' }}><X size={22} color="white" /></div>
          </div>
        </div>

        {(story.caption || mentions.length > 0) && !replyFocus && (
          <div data-story-control style={{ position: 'absolute', left: 14, right: 14, bottom: `calc(${readOnly && extraActions && extraActions.length ? 136 : 84}px + env(safe-area-inset-bottom))`, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, ...uiFade }}>
            {story.caption && <div style={{ background: 'rgba(0,0,0,0.45)', padding: '8px 14px', borderRadius: 14, fontSize: 14.5, fontWeight: 600, textAlign: 'center', maxWidth: '100%', wordBreak: 'break-word', whiteSpace: 'pre-wrap' }}><RichText text={story.caption} onMention={(p) => onOpenProfile(p)} /></div>}
            {mentions.length > 0 && (
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, justifyContent: 'center' }}>
                {mentions.map((mn) => (
                  <div key={`${mn.kind}-${mn.id}`} onClick={() => onOpenMention(mn)} style={{ display: 'flex', alignItems: 'center', gap: 4, background: 'rgba(255,255,255,0.92)', color: '#111', padding: '5px 11px', borderRadius: 14, fontSize: 12.5, fontWeight: 800, cursor: 'pointer' }}>
                    {mn.kind === 'group' ? <Users size={13} /> : <AtSign size={13} />}{mn.label}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {replyFocus && (
          <div onPointerDown={(e) => { e.preventDefault(); const el = document.querySelector('[data-story-reply]'); if (el) el.blur(); setReplyFocus(false); }}
            className="zchat-fade" style={{ position: 'absolute', inset: 0, zIndex: 3, background: 'rgba(0,0,0,0.55)' }} />
        )}
        <div data-story-control style={{ position: 'absolute', left: 0, right: 0, bottom: keyboardLift, zIndex: 4, padding: '14px 12px', paddingBottom: keyboardLift ? 10 : 'calc(14px + env(safe-area-inset-bottom))', background: replyFocus ? 'transparent' : 'linear-gradient(0deg, rgba(0,0,0,0.6), rgba(0,0,0,0))', display: 'flex', alignItems: 'center', gap: 10, transition: 'bottom 0.18s ease, opacity 0.18s ease', opacity: hideUi ? 0 : 1, pointerEvents: hideUi ? 'none' : undefined }}>
          {readOnly ? (
            highlightLike ? (
              <>
                <div style={{ flex: 1 }} />
                <div onClick={highlightLike.onToggle} style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '8px 12px', cursor: 'pointer' }}>
                  <Heart size={27} color={highlightLike.liked ? '#FF3B5C' : 'white'} fill={highlightLike.liked ? '#FF3B5C' : 'none'} />
                  <span style={{ fontSize: 14, fontWeight: 800 }}>{highlightLike.count > 0 ? formatCount(highlightLike.count) : ''}</span>
                </div>
              </>
            ) : extraActions && extraActions.length ? (
              <div style={{ display: 'flex', gap: 8, width: '100%', justifyContent: 'center', flexWrap: 'wrap' }}>
                {extraActions.map((a) => (
                  <div key={a.label} role="button" aria-label={a.label} onClick={() => a.on(story)} style={{ height: 42, padding: '0 16px', borderRadius: 21, background: 'rgba(255,255,255,0.16)', display: 'flex', alignItems: 'center', gap: 7, cursor: 'pointer', fontWeight: 700, fontSize: 13.5 }}>{a.icon}{a.label}</div>
                ))}
              </div>
            ) : null
          ) : isMine ? (
            <>
              <div style={{ position: 'absolute', left: 0, right: 0, bottom: 'calc(64px + env(safe-area-inset-bottom))', display: 'flex', flexDirection: 'column', alignItems: 'center', pointerEvents: 'none', opacity: 0.85 }}>
                <ChevronRight size={18} style={{ transform: 'rotate(-90deg)' }} />
                <span style={{ fontSize: 11.5, fontWeight: 700 }}>Swipe up for activity</span>
              </div>
              <div role="button" aria-label="Story viewers" onClick={() => setShowViewers(true)} style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '9px 14px', borderRadius: 22, background: 'rgba(255,255,255,0.14)', cursor: 'pointer', fontSize: 13.5, fontWeight: 700 }}>
                <Eye size={17} /> {viewCount == null ? 'Viewers' : `${viewCount} ${viewCount === 1 ? 'viewer' : 'viewers'}`}
              </div>
              <div style={{ position: 'relative', zIndex: 12, flex: 1 }} />
              {onShare && (
                <div role="button" aria-label="Share story" onClick={() => onShare(story, group.profile)} style={{ width: 42, height: 42, borderRadius: '50%', background: 'rgba(255,255,255,0.14)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><Share2 size={18} color="white" /></div>
              )}
              {onAddStory && (
                <div role="button" aria-label="Add to your story" onClick={onAddStory} style={{ height: 42, padding: '0 14px', borderRadius: 21, background: 'rgba(255,255,255,0.14)', display: 'flex', alignItems: 'center', gap: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13.5 }}>
                  <span style={{ fontSize: 20, lineHeight: 1 }}>+</span> Add
                </div>
              )}
              <div role="button" aria-label="Delete story" onClick={() => setConfirmDelete(true)} style={{ width: 42, height: 42, borderRadius: '50%', background: 'rgba(255,255,255,0.14)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}><Trash2 size={18} color="white" /></div>
            </>
          ) : (
            <>
              {replyFocus && !reply.trim() && (
                <div className="zchat-sheet-up" style={{ position: 'absolute', left: 0, right: 0, bottom: '100%', padding: '16px 18px 10px', display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 14 }}>
                  {QUICK_STORY_REACTIONS.map((emo) => (
                    <div key={emo} onPointerDown={(e) => e.preventDefault()} onClick={() => sendQuickReaction(emo)}
                      style={{ fontSize: 38, textAlign: 'center', cursor: 'pointer', lineHeight: 1.2 }}>{emo}</div>
                  ))}
                </div>
              )}
              <input data-story-reply value={reply} onChange={(e) => setReply(e.target.value.slice(0, 1000))} onFocus={() => setReplyFocus(true)} onBlur={() => setTimeout(() => { if (document.activeElement && document.activeElement.hasAttribute && document.activeElement.hasAttribute('data-story-reply')) return; setReplyFocus(false); }, 160)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); sendReply(); } }}
                placeholder={`Reply to ${(group.profile.name || '').split(' ')[0]}`} aria-label="Reply to story"
                style={{ flex: 1, minWidth: 0, padding: '11px 16px', borderRadius: 24, border: '1.5px solid rgba(255,255,255,0.55)', background: 'rgba(0,0,0,0.25)', color: 'white', outline: 'none', fontFamily: FONT, fontSize: 15 }} />
              {reply.trim() ? (
                <div role="button" aria-label="Send reply" onPointerDown={(e) => e.preventDefault()} onClick={sendReply} style={{ padding: '10px 14px', fontWeight: 800, fontSize: 14.5, cursor: 'pointer' }}>Send</div>
              ) : (
                <>
                  <div role="button" aria-label={isLiked ? 'Unlike story' : 'Like story'} onClick={toggleLike} style={{ padding: 6, cursor: 'pointer', position: 'relative', zIndex: 12, display: 'flex' }}><Heart size={26} color={isLiked ? '#FF3B5C' : 'white'} fill={isLiked ? '#FF3B5C' : 'none'} /></div>
                  <div role="button" aria-label="Repost" onClick={() => {
                    if (repostBusy) return;
                    if (repostedHere) { showFlash('Already on your story', 1600); return; }
                    setConfirmRepost(true);
                  }} style={{ padding: 6, cursor: 'pointer', position: 'relative', display: 'flex' }}>
                    {repostPop && <div style={{ position: 'absolute', inset: -4, borderRadius: '50%', border: '2px solid #34D399', animation: 'zchat-repost-ring 0.6s ease-out', pointerEvents: 'none' }} />}
                    <div style={{ transition: 'transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.5)', transform: repostPop ? 'rotate(180deg) scale(1.25)' : 'rotate(0deg) scale(1)', display: 'flex' }}>
                      {repostBusy ? <Spinner size={22} color="white" /> : <Repeat size={24} color={repostedHere ? '#34D399' : 'white'} strokeWidth={repostedHere ? 2.6 : 2} />}
                    </div>
                    {repostedHere && <div style={{ position: 'absolute', right: 1, bottom: 2, width: 13, height: 13, borderRadius: '50%', background: '#34D399', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1.5px solid black' }}><Check size={8} color="black" strokeWidth={4} /></div>}
                  </div>
                  {onShare && <div role="button" aria-label="Send story" onClick={() => onShare(story, group.profile)} style={{ padding: 6, cursor: 'pointer', display: 'flex' }}><Send size={23} color="white" /></div>}
                </>
              )}
            </>
          )}
        </div>

        {flash && <div style={{ position: 'absolute', left: '50%', top: '45%', transform: 'translate(-50%, -50%)', background: 'rgba(0,0,0,0.7)', padding: '9px 16px', borderRadius: 20, fontSize: 13.5, fontWeight: 700, zIndex: 30, pointerEvents: 'none' }} className="zchat-pop">{flash}</div>}

        {menu && (
          <div onClick={() => setMenu(false)} style={{ position: 'absolute', inset: 0, zIndex: 9, background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'flex-end' }}>
            <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', background: '#15151B', borderRadius: '22px 22px 0 0', padding: '8px 0', paddingBottom: 'calc(8px + env(safe-area-inset-bottom))' }}>
              <div style={{ display: 'flex', justifyContent: 'center', padding: '2px 0 6px' }}><div style={{ width: 36, height: 4, borderRadius: 2, background: 'rgba(255,255,255,0.25)' }} /></div>
              {menuItems.filter(Boolean).map((it) => (
                <div key={it.k} role="button" aria-label={it.label} onClick={() => { setMenu(false); it.on(); }} style={{ padding: '15px 22px', fontWeight: 700, fontSize: 15, cursor: 'pointer', color: it.danger ? '#FF5A6A' : '#FFFFFF' }}>{it.label}</div>
              ))}
              <div role="button" onClick={() => setMenu(false)} style={{ padding: '15px 22px', opacity: 0.7, fontWeight: 700, fontSize: 15, cursor: 'pointer' }}>Cancel</div>
            </div>
          </div>
        )}
        {showViewers && <StoryViewersSheet story={story} myId={myId} onClose={() => setShowViewers(false)} onOpenProfile={(p) => { setShowViewers(false); onOpenProfile(p); }} />}
        {confirmDelete && (
          <ConfirmDialog title="Delete this story?" body="It will be removed for everyone right away."
            onCancel={() => setConfirmDelete(false)}
            onConfirm={async () => { setConfirmDelete(false); const remaining = group.stories.length - 1; await onDelete(story); if (remaining <= 0) onClose(); else if (si >= remaining) setSi(remaining - 1); }} />
        )}
        {confirmRepost && (
          <ConfirmDialog title="Add to your story?" body={`${(group.profile.name || 'Their').split(' ')[0]}'s story will show on your story for 24 hours, with their name on it.`} confirmLabel="Add" danger={false} layer={420}
            onCancel={() => setConfirmRepost(false)} onConfirm={doRepost} />
        )}
      </div>
    </div>
  );
}

function JumpToLatestButton({ count, onClick, bottom }) {
  const { theme } = useTheme();
  return (
    <div onPointerDown={(e) => e.preventDefault()} onClick={onClick} className="zchat-pop" role="button" aria-label="Jump to latest message" style={{
      position: 'absolute', right: 14, bottom, zIndex: 11, width: 42, height: 42, borderRadius: '50%', cursor: 'pointer',
      background: theme.panelBg, border: `1px solid ${theme.border}`, boxShadow: '0 6px 18px rgba(0,0,0,0.28)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', color: theme.ink,
    }}>
      <ChevronRight size={22} style={{ transform: 'rotate(90deg)' }} />
      {count > 0 && (
        <div style={{ position: 'absolute', top: -7, right: -4, minWidth: 20, height: 20, padding: '0 5px', boxSizing: 'border-box', borderRadius: 10, background: theme.coral, color: 'white', fontSize: 11, fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          {count > 99 ? '99+' : count}
        </div>
      )}
    </div>
  );
}

async function notifyBioMentions(profile, oldBio, newBio) {
  try {
    const before = extractMentions(oldBio || '');
    const after = extractMentions(newBio || '');
    const fresh = [...after].filter((u) => !before.has(u) && u !== (profile.username || '').toLowerCase());
    if (!fresh.length) return;
    const { data } = await supabase.from('profiles').select('id, username').in('username', fresh);
    for (const p of data || []) {
      if (p.id === profile.id) continue;
      const { data: sent, error } = await supabase.rpc('send_bio_mention', { p_target: p.id });
      if (!error && sent) sendPushNotification(p.id, 'ZChat', `${profile.name} mentioned you in their bio`, `/?profile=${profile.id}`, profile.avatar);
    }
  } catch {}
}

const CALL_TURN_URLS = '';
const CALL_TURN_USERNAME = '';
const CALL_TURN_CREDENTIAL = '';
const CALL_RING_MS = 45000;

function callIceConfig() {
  const servers = [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302', 'stun:stun.cloudflare.com:3478'] }];
  if (CALL_TURN_URLS) servers.push({ urls: CALL_TURN_URLS.split(',').map((u) => u.trim()).filter(Boolean), username: CALL_TURN_USERNAME, credential: CALL_TURN_CREDENTIAL });
  return { iceServers: servers, iceCandidatePoolSize: 4 };
}

function formatCallDuration(ms) {
  const total = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return h ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${m}:${String(s).padStart(2, '0')}`;
}

function startCallTone(kind) {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return () => {};
    const ctx = new Ctx();
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});
    const master = ctx.createGain();
    master.gain.value = kind === 'incoming' ? 0.9 : 0.55;
    const comp = ctx.createDynamicsCompressor();
    master.connect(comp);
    comp.connect(ctx.destination);
    let stopped = false;
    const note = (freq, start, length, volume, type = 'sine') => {
      const t0 = ctx.currentTime + start;
      [1, 2, 3].forEach((harmonic, i) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = i === 0 ? type : 'sine';
        o.frequency.value = freq * harmonic;
        const v = volume / (harmonic * harmonic * 1.4);
        g.gain.setValueAtTime(0.0001, t0);
        g.gain.exponentialRampToValueAtTime(v, t0 + 0.012);
        g.gain.exponentialRampToValueAtTime(0.0001, t0 + length);
        o.connect(g);
        g.connect(master);
        o.start(t0);
        o.stop(t0 + length + 0.05);
      });
    };
    const incomingPhrase = () => {
      const seq = [659.25, 830.61, 987.77, 1318.51, 987.77, 1318.51];
      seq.forEach((f, i) => note(f, i * 0.16, 0.5, 0.22, 'triangle'));
      [659.25, 830.61, 987.77].forEach((f, i) => note(f, 1.25 + i * 0.16, 0.6, 0.2, 'triangle'));
      if (navigator.vibrate) { try { navigator.vibrate([500, 300, 500]); } catch {} }
    };
    const outgoingPhrase = () => {
      note(440, 0, 1.4, 0.08);
      note(480, 0, 1.4, 0.08);
    };
    const pattern = () => {
      if (stopped) return;
      if (kind === 'incoming') incomingPhrase(); else outgoingPhrase();
    };
    pattern();
    const iv = setInterval(pattern, kind === 'incoming' ? 2600 : 4000);
    return () => {
      stopped = true;
      clearInterval(iv);
      if (navigator.vibrate) { try { navigator.vibrate(0); } catch {} }
      ctx.close().catch(() => {});
    };
  } catch {
    return () => {};
  }
}

function useCallEngine(options) {
  const [call, setCall] = useState(null);
  const callRef = useRef(null);
  const pcsRef = useRef(new Map());
  const pendingIceRef = useRef(new Map());
  const channelRef = useRef(null);
  const localRef = useRef(null);
  const timersRef = useRef({});
  const toneStopRef = useRef(null);
  const screenRef = useRef(null);
  const optsRef = useRef(options);
  optsRef.current = options;

  const put = (value) => { callRef.current = value; setCall(value); };
  const patch = (fnOrObj) => {
    const prev = callRef.current;
    if (!prev) return;
    const next = { ...prev, ...(typeof fnOrObj === 'function' ? fnOrObj(prev) : fnOrObj) };
    callRef.current = next;
    setCall(next);
  };
  const stopTone = () => { if (toneStopRef.current) { toneStopRef.current(); toneStopRef.current = null; } };
  const playTone = (kind) => { stopTone(); toneStopRef.current = startCallTone(kind); };
  const send = (msg) => {
    const ch = channelRef.current;
    if (!ch) return;
    ch.send({ type: 'broadcast', event: 'signal', payload: { ...msg, from: optsRef.current.myId } });
  };

  const getMedia = async (kind, facing = 'user') => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      optsRef.current.snack("Calls aren't supported in this browser");
      return null;
    }
    try {
      return await navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
        video: kind === 'video' ? { facingMode: facing, width: { ideal: 1280 }, height: { ideal: 720 } } : false,
      });
    } catch {
      optsRef.current.snack(kind === 'video' ? 'Allow camera and microphone to make video calls' : 'Allow microphone access to make calls');
      return null;
    }
  };

  const cleanup = () => {
    Object.values(timersRef.current).forEach((t) => clearTimeout(t));
    timersRef.current = {};
    stopTone();
    if (screenRef.current) { screenRef.current.stream.getTracks().forEach((t) => t.stop()); screenRef.current = null; }
    pcsRef.current.forEach((pc) => { try { pc.close(); } catch {} });
    pcsRef.current = new Map();
    pendingIceRef.current = new Map();
    if (localRef.current) localRef.current.getTracks().forEach((t) => t.stop());
    localRef.current = null;
    if (channelRef.current) supabase.removeChannel(channelRef.current);
    channelRef.current = null;
  };

  const removePeer = (peerId) => {
    const pc = pcsRef.current.get(peerId);
    if (pc) { try { pc.close(); } catch {} }
    pcsRef.current.delete(peerId);
    patch((prev) => {
      const remoteStreams = { ...prev.remoteStreams };
      delete remoteStreams[peerId];
      return { remoteStreams, participants: prev.participants.filter((id) => id !== peerId) };
    });
  };

  const flushIce = async (peerId) => {
    const pc = pcsRef.current.get(peerId);
    const queue = pendingIceRef.current.get(peerId) || [];
    pendingIceRef.current.delete(peerId);
    for (const c of queue) { try { await pc.addIceCandidate(c); } catch {} }
  };

  const createPeer = (peerId) => {
    const pc = new RTCPeerConnection(callIceConfig());
    pcsRef.current.set(peerId, pc);
    const local = localRef.current;
    if (local) local.getTracks().forEach((t) => pc.addTrack(t, local));
    pc.ontrack = (e) => {
      const stream = (e.streams && e.streams[0]) || new MediaStream([e.track]);
      patch((prev) => ({ remoteStreams: { ...prev.remoteStreams, [peerId]: stream } }));
    };
    pc.onicecandidate = (e) => {
      if (e.candidate) send({ type: 'ice', to: peerId, candidate: typeof e.candidate.toJSON === 'function' ? e.candidate.toJSON() : e.candidate });
    };
    pc.onconnectionstatechange = () => {
      const state = pc.connectionState;
      if (state === 'connected') {
        stopTone();
        clearTimeout(timersRef.current[`drop-${peerId}`]);
        patch((prev) => ({ status: 'active', startedAt: prev.startedAt || Date.now(), reconnecting: false }));
        const cur = callRef.current;
        if (cur) {
          send({ type: 'mute', muted: !!cur.muted });
          if (cur.kind === 'video') send({ type: 'camera', off: !!cur.cameraOff });
        }
      } else if (state === 'disconnected' || state === 'failed') {
        patch({ reconnecting: true });
        if (optsRef.current.myId < peerId && pc.signalingState === 'stable') offerTo(peerId, true).catch(() => {});
        clearTimeout(timersRef.current[`drop-${peerId}`]);
        timersRef.current[`drop-${peerId}`] = setTimeout(() => {
          if (pc.connectionState === 'connected') return;
          const current = callRef.current;
          if (!current) return;
          if (current.mode === 'direct') finish('failed'); else removePeer(peerId);
        }, state === 'failed' ? 9000 : 18000);
      }
    };
    return pc;
  };

  const offerTo = async (peerId, restart) => {
    const pc = pcsRef.current.get(peerId) || createPeer(peerId);
    const offer = await pc.createOffer(restart ? { iceRestart: true } : undefined);
    await pc.setLocalDescription(offer);
    send({ type: 'offer', to: peerId, sdp: { type: pc.localDescription.type, sdp: pc.localDescription.sdp } });
  };

  const handleSignal = async (p) => {
    const c = callRef.current;
    const myId = optsRef.current.myId;
    if (!c || !p || p.from === myId) return;
    if (p.to && p.to !== myId) return;
    try {
      if (p.type === 'accept' && c.mode === 'direct' && c.direction === 'outgoing') {
        stopTone();
        clearTimeout(timersRef.current.noAnswer);
        patch({ status: 'connecting' });
        await offerTo(p.from);
      } else if (p.type === 'join' && c.mode === 'group' && c.status !== 'ringing') {
        patch((prev) => ({ participants: prev.participants.includes(p.from) ? prev.participants : [...prev.participants, p.from] }));
        if (!pcsRef.current.has(p.from)) {
          if (myId < p.from) await offerTo(p.from); else send({ type: 'hello', to: p.from });
        }
      } else if (p.type === 'hello' && c.mode === 'group') {
        if (!pcsRef.current.has(p.from)) await offerTo(p.from);
      } else if (p.type === 'offer') {
        const pc = pcsRef.current.get(p.from) || createPeer(p.from);
        await pc.setRemoteDescription(p.sdp);
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        send({ type: 'answer', to: p.from, sdp: { type: pc.localDescription.type, sdp: pc.localDescription.sdp } });
        await flushIce(p.from);
        if (c.mode === 'group') patch((prev) => ({ participants: prev.participants.includes(p.from) ? prev.participants : [...prev.participants, p.from] }));
      } else if (p.type === 'answer') {
        const pc = pcsRef.current.get(p.from);
        if (pc && pc.signalingState === 'have-local-offer') {
          await pc.setRemoteDescription(p.sdp);
          await flushIce(p.from);
        }
      } else if (p.type === 'ice') {
        const pc = pcsRef.current.get(p.from);
        if (pc && pc.remoteDescription) { try { await pc.addIceCandidate(p.candidate); } catch {} } else {
          const q = pendingIceRef.current.get(p.from) || [];
          q.push(p.candidate);
          pendingIceRef.current.set(p.from, q);
        }
      } else if (p.type === 'decline' && c.mode === 'direct') {
        finish('declined');
      } else if (p.type === 'end' && c.mode === 'direct') {
        finish('remote');
      } else if (p.type === 'leave' && c.mode === 'group') {
        removePeer(p.from);
      } else if (p.type === 'mute') {
        patch((prev) => ({ remoteMuted: { ...(prev.remoteMuted || {}), [p.from]: !!p.muted } }));
      } else if (p.type === 'force-mute') {
        const cur = callRef.current;
        if (cur && !cur.muted && localRef.current) {
          localRef.current.getAudioTracks().forEach((t) => { t.enabled = false; });
          patch({ muted: true });
          send({ type: 'mute', muted: true });
          optsRef.current.snack('Someone in the call muted you');
        }
      } else if (p.type === 'camera') {
        patch((prev) => ({ remoteCameraOff: { ...(prev.remoteCameraOff || {}), [p.from]: !!p.off } }));
      }
    } catch {}
  };

  const joinChannel = (callId) => new Promise((resolve) => {
    const ch = supabase.channel(`call-${callId}`, { config: { broadcast: { self: false } } });
    ch.on('broadcast', { event: 'signal' }, ({ payload }) => { handleSignal(payload); });
    channelRef.current = ch;
    let done = false;
    const finishJoin = () => { if (!done) { done = true; resolve(); } };
    ch.subscribe((status) => { if (status === 'SUBSCRIBED') finishJoin(); });
    setTimeout(finishJoin, 5000);
  });

  const finish = (reason = 'hangup') => {
    const c = callRef.current;
    if (!c || c.status === 'ended') return;
    const nowIso = new Date().toISOString();
    const connected = !!c.startedAt;
    if (c.mode === 'direct') {
      if (reason === 'hangup' || reason === 'no_answer' || reason === 'failed') send({ type: 'end' });
      if (reason !== 'declined' && reason !== 'busy') {
        const status = connected ? 'ended' : reason === 'no_answer' ? 'missed' : c.direction === 'outgoing' ? 'cancelled' : 'ended';
        supabase.from('calls').update({ status, ended_at: nowIso }).eq('id', c.id).then(() => {});
      }
      if (c.direction === 'outgoing' && optsRef.current.onDirectEnded) optsRef.current.onDirectEnded(c, connected ? Date.now() - c.startedAt : 0, reason);
    } else {
      send({ type: 'leave' });
      if (pcsRef.current.size === 0) supabase.from('calls').update({ status: 'ended', ended_at: nowIso }).eq('id', c.id).then(() => {});
    }
    cleanup();
    const labels = { declined: 'Call declined', busy: 'On another call', no_answer: 'No answer', failed: 'Call dropped', remote: 'Call ended', hangup: 'Call ended' };
    put({ ...c, status: 'ended', minimized: false, endLabel: labels[reason] || 'Call ended', endedAt: Date.now(), summaryDuration: connected ? Date.now() - c.startedAt : 0, localStream: null, remoteStreams: {} });
    const endedId = c.id;
    setTimeout(() => { if (callRef.current && callRef.current.id === endedId && callRef.current.status === 'ended') put(null); }, 15000);
  };

  const startDirect = async (profile, kind) => {
    if (callRef.current && callRef.current.status === 'ended') put(null);
    if (callRef.current) return;
    const opts = optsRef.current;
    const local = await getMedia(kind);
    if (!local) return;
    localRef.current = local;
    const { data: row, error } = await supabase.from('calls').insert({ caller_id: opts.myId, callee_id: profile.id, kind, status: 'ringing' }).select().single();
    if (error || !row) {
      local.getTracks().forEach((t) => t.stop());
      localRef.current = null;
      opts.snack(friendlyError(error, "Couldn't start the call. You can only call people who follow you back."));
      return;
    }
    put({ id: row.id, mode: 'direct', kind, direction: 'outgoing', status: 'ringing', peer: profile, group: null, localStream: local, remoteStreams: {}, participants: [], muted: false, cameraOff: false, facing: 'user' });
    playTone('outgoing');
    await joinChannel(row.id);
    opts.notify(profile.id, opts.myName, `Incoming ${kind === 'video' ? 'video' : 'voice'} call`, `/?call=${row.id}`, opts.myAvatar);
    timersRef.current.noAnswer = setTimeout(() => {
      const current = callRef.current;
      if (current && current.id === row.id && current.status === 'ringing') finish('no_answer');
    }, CALL_RING_MS);
  };

  const startGroup = async (group, kind) => {
    if (callRef.current && callRef.current.status === 'ended') put(null);
    if (callRef.current) return;
    const opts = optsRef.current;
    const local = await getMedia(kind);
    if (!local) return;
    localRef.current = local;
    const { data: row, error } = await supabase.from('calls').insert({ caller_id: opts.myId, group_id: group.id, kind, status: 'ringing' }).select().single();
    if (error || !row) {
      local.getTracks().forEach((t) => t.stop());
      localRef.current = null;
      opts.snack(friendlyError(error, "Couldn't start the group call. Try again."));
      return;
    }
    put({ id: row.id, mode: 'group', kind, direction: 'outgoing', status: 'active', peer: null, group, localStream: local, remoteStreams: {}, participants: [], muted: false, cameraOff: false, facing: 'user', startedAt: Date.now() });
    await joinChannel(row.id);
    send({ type: 'join' });
    if (opts.onGroupStarted) opts.onGroupStarted(row, group);
  };

  const joinGroupCall = async (row, group, joinOpts = {}) => {
    if (callRef.current && callRef.current.status === 'ended') put(null);
    if (callRef.current) return;
    const local = await getMedia(row.kind);
    if (!local) return;
    localRef.current = local;
    if (joinOpts.cameraOff) local.getVideoTracks().forEach((t) => { t.enabled = false; });
    put({ id: row.id, mode: 'group', kind: row.kind, direction: 'incoming', status: 'active', peer: null, group, localStream: local, remoteStreams: {}, participants: [], muted: false, cameraOff: !!joinOpts.cameraOff, facing: 'user', startedAt: Date.now() });
    await joinChannel(row.id);
    supabase.from('calls').update({ status: 'active' }).eq('id', row.id).eq('status', 'ringing').then(() => {});
    send({ type: 'join' });
  };

  const incoming = (row, caller, group) => {
    if (callRef.current && callRef.current.status === 'ended') put(null);
    if (callRef.current) {
      if (row.callee_id) supabase.from('calls').update({ status: 'busy', ended_at: new Date().toISOString() }).eq('id', row.id).then(() => {});
      return;
    }
    put({ id: row.id, mode: row.group_id ? 'group' : 'direct', kind: row.kind, direction: 'incoming', status: 'ringing', peer: caller, group: group || null, row, localStream: null, remoteStreams: {}, participants: [], muted: false, cameraOff: false, facing: 'user' });
    playTone('incoming');
    const age = Math.max(0, Date.now() - new Date(row.created_at || Date.now()).getTime());
    timersRef.current.ringOut = setTimeout(() => {
      const current = callRef.current;
      if (current && current.id === row.id && current.status === 'ringing') {
        cleanup();
        put(null);
        if (optsRef.current.onMissed) optsRef.current.onMissed(current);
      }
    }, Math.max(5000, CALL_RING_MS - age));
  };

  const accept = async (acceptOpts = {}) => {
    playUiSound('like');
    const c = callRef.current;
    if (!c || c.direction !== 'incoming' || c.status !== 'ringing') return;
    stopTone();
    clearTimeout(timersRef.current.ringOut);
    if (c.mode === 'group') {
      put(null);
      await joinGroupCall(c.row || { id: c.id, kind: c.kind }, c.group, acceptOpts);
      return;
    }
    const local = await getMedia(c.kind);
    if (!local) { decline(); return; }
    localRef.current = local;
    if (acceptOpts.cameraOff) local.getVideoTracks().forEach((t) => { t.enabled = false; });
    patch({ localStream: local, status: 'connecting', cameraOff: !!acceptOpts.cameraOff });
    await joinChannel(c.id);
    supabase.from('calls').update({ status: 'accepted', answered_at: new Date().toISOString() }).eq('id', c.id).then(() => {});
    send({ type: 'accept' });
  };

  const decline = () => {
    playUiSound('cancel');
    const c = callRef.current;
    if (!c) return;
    if (c.mode === 'direct' && c.status === 'ringing') supabase.from('calls').update({ status: 'declined', ended_at: new Date().toISOString() }).eq('id', c.id).then(() => {});
    cleanup();
    put(null);
  };

  const onRowUpdate = (row) => {
    const c = callRef.current;
    if (!c || !row || row.id !== c.id) return;
    if (c.mode === 'direct') {
      if (c.direction === 'outgoing' && (row.status === 'declined' || row.status === 'busy')) finish(row.status);
      else if (c.direction === 'incoming' && c.status === 'ringing' && ['cancelled', 'missed', 'ended', 'accepted'].includes(row.status)) {
        cleanup();
        put(null);
        if (row.status !== 'accepted' && optsRef.current.onMissed) optsRef.current.onMissed(c);
      }
    } else if (c.direction === 'incoming' && c.status === 'ringing' && row.status === 'ended') {
      cleanup();
      put(null);
    }
  };

  const toggleMute = () => {
    const c = callRef.current;
    if (!c || !localRef.current) return;
    const next = !c.muted;
    localRef.current.getAudioTracks().forEach((t) => { t.enabled = !next; });
    patch({ muted: next });
    send({ type: 'mute', muted: next });
  };

  const toggleCamera = () => {
    const c = callRef.current;
    if (!c || !localRef.current || c.kind !== 'video') return;
    const next = !c.cameraOff;
    localRef.current.getVideoTracks().forEach((t) => { t.enabled = !next; });
    patch({ cameraOff: next });
    send({ type: 'camera', off: next });
  };

  const flipBusyRef = useRef(false);
  const flipCamera = async () => {
    const c = callRef.current;
    if (!c || c.kind !== 'video' || !localRef.current || flipBusyRef.current) return;
    flipBusyRef.current = true;
    const facing = c.facing === 'user' ? 'environment' : 'user';
    const old = localRef.current.getVideoTracks()[0];
    const wasEnabled = old ? old.enabled : !c.cameraOff;
    if (old) { try { localRef.current.removeTrack(old); old.stop(); } catch {} }
    const open = async (constraints) => navigator.mediaDevices.getUserMedia({ video: constraints, audio: false });
    let fresh = null;
    try {
      fresh = await open({ facingMode: { exact: facing }, width: { ideal: 1280 }, height: { ideal: 720 } });
    } catch {
      try { fresh = await open({ facingMode: facing }); } catch {}
    }
    if (!fresh) {
      try { fresh = await open({ facingMode: c.facing || 'user' }); } catch {}
      if (!fresh) { flipBusyRef.current = false; optsRef.current.snack("Couldn't switch camera"); return; }
      const back = fresh.getVideoTracks()[0];
      back.enabled = wasEnabled;
      localRef.current.addTrack(back);
      pcsRef.current.forEach((pc) => { const sender = pc.getSenders().find((sd) => sd.track == null || (sd.track && sd.track.kind === 'video')); if (sender) sender.replaceTrack(back).catch(() => {}); });
      patch({ localStream: new MediaStream(localRef.current.getTracks()) });
      flipBusyRef.current = false;
      optsRef.current.snack("Couldn't switch camera");
      return;
    }
    const track = fresh.getVideoTracks()[0];
    track.enabled = wasEnabled;
    localRef.current.addTrack(track);
    pcsRef.current.forEach((pc) => {
      const sender = pc.getSenders().find((sd) => sd.track && sd.track.kind === 'video') || pc.getSenders().find((sd) => !sd.track);
      if (sender) sender.replaceTrack(track).catch(() => {});
    });
    patch({ facing, localStream: new MediaStream(localRef.current.getTracks()) });
    playUiSound('tap');
    flipBusyRef.current = false;
  };

  const minimize = (value) => patch({ minimized: value });

  const stopScreenShare = () => {
    const sc = screenRef.current;
    if (!sc) return;
    screenRef.current = null;
    sc.stream.getTracks().forEach((t) => t.stop());
    const cam = localRef.current && localRef.current.getVideoTracks()[0];
    pcsRef.current.forEach((pc) => {
      const sender = pc.getSenders().find((s) => s.track && s.track.kind === 'video');
      if (sender && cam) sender.replaceTrack(cam);
    });
    patch({ sharingScreen: false, screenStream: null });
    const cur = callRef.current;
    if (cur) send({ type: 'camera', off: !!cur.cameraOff });
  };
  const toggleScreenShare = async () => {
    const c = callRef.current;
    if (!c || c.kind !== 'video' || !localRef.current) return;
    if (screenRef.current) { stopScreenShare(); return; }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) { optsRef.current.snack('Screen sharing works in computer browsers'); return; }
    try {
      const display = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
      const track = display.getVideoTracks()[0];
      if (!track) return;
      screenRef.current = { stream: display, track };
      pcsRef.current.forEach((pc) => {
        const sender = pc.getSenders().find((s) => s.track && s.track.kind === 'video');
        if (sender) sender.replaceTrack(track);
      });
      track.onended = () => stopScreenShare();
      patch({ sharingScreen: true, screenStream: display });
      send({ type: 'camera', off: false });
    } catch {}
  };

  useEffect(() => {
    const resume = async () => {
      if (document.visibilityState !== 'visible') return;
      const c = callRef.current;
      if (!c || c.status === 'ended' || c.status === 'ringing') return;
      document.querySelectorAll('[data-zchat-call-audio]').forEach((el) => {
        if (el.srcObject && el.paused) { const p = el.play(); if (p && p.catch) p.catch(() => {}); }
      });
      const local = localRef.current;
      if (local) {
        const dead = local.getTracks().filter((t) => t.readyState === 'ended');
        if (dead.length) {
          try {
            const fresh = await navigator.mediaDevices.getUserMedia({
              audio: dead.some((t) => t.kind === 'audio') ? { echoCancellation: true, noiseSuppression: true, autoGainControl: true } : false,
              video: dead.some((t) => t.kind === 'video') ? { facingMode: c.facing || 'user' } : false,
            });
            fresh.getTracks().forEach((track) => {
              const old = dead.find((t) => t.kind === track.kind);
              if (old) local.removeTrack(old);
              if (track.kind === 'audio') track.enabled = !c.muted;
              if (track.kind === 'video') track.enabled = !c.cameraOff;
              local.addTrack(track);
              pcsRef.current.forEach((pc) => {
                const sender = pc.getSenders().find((s) => s.track && s.track.kind === track.kind);
                if (sender) sender.replaceTrack(track);
              });
            });
            patch({ localStream: new MediaStream(local.getTracks()) });
          } catch {}
        }
      }
      pcsRef.current.forEach((pc, peerId) => {
        if ((pc.connectionState === 'disconnected' || pc.connectionState === 'failed') && pc.signalingState === 'stable') offerTo(peerId, true).catch(() => {});
      });
    };
    const kick = () => {
      if (document.visibilityState !== 'visible') return;
      document.querySelectorAll('[data-zchat-call-audio]').forEach((el) => { try { const pr = el.play(); if (pr && pr.catch) pr.catch(() => {}); } catch {} });
      const local = localRef.current;
      const c = callRef.current;
      if (local && c) local.getTracks().forEach((t) => { if (t.readyState === 'live') t.enabled = t.kind === 'audio' ? !c.muted : !c.cameraOff; });
    };
    const resumeAll = () => { kick(); resume(); setTimeout(kick, 800); };
    document.addEventListener('visibilitychange', resumeAll);
    window.addEventListener('pageshow', resumeAll);
    window.addEventListener('focus', resumeAll);
    return () => {
      document.removeEventListener('visibilitychange', resumeAll);
      window.removeEventListener('pageshow', resumeAll);
      window.removeEventListener('focus', resumeAll);
    };
  }, []);

  // Speaker vs call (earpiece-style) output. Real phones let native apps pick
  // the earpiece directly; a website can't do that on every phone, so this
  // does the closest real thing a browser allows: switching to speakerphone
  // is not extra work (it's already the default the browser plays through
  // for a live call), and where the browser exposes it, this also lets you
  // pick a connected Bluetooth or wired headset instead of the speaker.
  const [speakerOn, setSpeakerOn] = useState(true);
  const [audioOutputs, setAudioOutputs] = useState([]);
  const sinkSupported = typeof HTMLMediaElement !== 'undefined' && 'setSinkId' in HTMLMediaElement.prototype;
  const applySink = async (deviceId) => {
    if (!sinkSupported) return;
    const els = document.querySelectorAll('[data-zchat-call-audio]');
    for (const el of els) {
      try { await el.setSinkId(deviceId); } catch {}
    }
  };
  const refreshOutputs = async () => {
    if (!sinkSupported || !navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return [];
    try {
      const list = (await navigator.mediaDevices.enumerateDevices()).filter((d) => d.kind === 'audiooutput');
      setAudioOutputs(list);
      return list;
    } catch { return []; }
  };
  const toggleSpeaker = async () => {
    if (!sinkSupported) {
      optsRef.current.snack("Your browser doesn't allow switching call audio here");
      return;
    }
    const outputs = audioOutputs.length ? audioOutputs : await refreshOutputs();
    const external = outputs.find((d) => !/default|speaker/i.test(d.label));
    if (speakerOn && external) {
      await applySink(external.deviceId);
      setSpeakerOn(false);
    } else {
      await applySink('default');
      setSpeakerOn(true);
    }
  };
  useEffect(() => { if (call && call.status === 'active') refreshOutputs(); }, [call && call.status]);

  const muteOther = (peerId) => send({ type: 'force-mute', to: peerId });
  const dismissSummary = () => { if (callRef.current && callRef.current.status === 'ended') put(null); };

  useEffect(() => () => cleanup(), []);

  return { call, startDirect, startGroup, joinGroupCall, incoming, accept, decline, hangup: () => finish('hangup'), onRowUpdate, toggleMute, toggleCamera, flipCamera, minimize, muteOther, dismissSummary, toggleScreenShare, speakerOn, toggleSpeaker, speakerSupported: sinkSupported };
}

function CallVideo({ stream, muted, mirror, fit = 'cover' }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (el.srcObject !== stream) el.srcObject = stream || null;
    if (stream) { const p = el.play && el.play(); if (p && p.catch) p.catch(() => {}); }
  }, [stream]);
  return <video ref={ref} data-zchat-call-audio="1" autoPlay playsInline muted={muted} style={{ width: '100%', height: '100%', objectFit: fit, display: 'block', background: '#000', transform: mirror ? 'scaleX(-1)' : 'none' }} />;
}

function CallAudio({ stream }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (el.srcObject !== stream) el.srcObject = stream || null;
    if (stream) { const p = el.play && el.play(); if (p && p.catch) p.catch(() => {}); }
  }, [stream]);
  return <audio ref={ref} data-zchat-call-audio="1" autoPlay playsInline />;
}

