  mono: { up: 0x1D670, lo: 0x1D68A, dg: 0x1D7F6 },
  script: { up: 0x1D4D0, lo: 0x1D4EA },
  gothic: { up: 0x1D56C, lo: 0x1D586 },
  elegant: { up: 0x1D608, lo: 0x1D622 },
