          {previewSpec && previewSpec.deco && BUBBLE_DECO[bubbleStyle] && <div aria-hidden="true" style={{ position: 'absolute', pointerEvents: 'none', zIndex: 1, ...previewSpec.deco }}>{BUBBLE_DECO[bubbleStyle]()}</div>}
