  const [pinSheetFor, setPinSheetFor] = useState(null);
  const [muteSheet, setMuteSheet] = useState(null);
  const [mailOpenId, setMailOpenId] = useState(null);
  const [storyData, setStoryData] = useState({ byUser: {}, profiles: {}, seen: new Set(), liked: new Set(), ready: false });
  const [storyViewer, setStoryViewer] = useState(null);
  const [mutualIds, setMutualIds] = useState(new Set());
  const [iFollowIds, setIFollowIds] = useState(new Set());
  const [privacyAllowed, setPrivacyAllowed] = useState(new Set());
  const [blockedByIds, setBlockedByIds] = useState(new Set());
  const [blockConfirmFor, setBlockConfirmFor] = useState(null);
  const [unblockConfirmFor, setUnblockConfirmFor] = useState(null);
  const [showBlockedList, setShowBlockedList] = useState(false);
  const [storyShareFor, setStoryShareFor] = useState(null);
  const [stickerSheetFor, setStickerSheetFor] = useState(null);
  const [celebrateTier, setCelebrateTier] = useState(null);
  const [deepPost, setDeepPost] = useState(null);
  const [reportThanks, setReportThanks] = useState(null);
  const [rewardReady, setRewardReady] = useState({});
  const [myRewards, setMyRewards] = useState([]);
  const [collectionOpen, setCollectionOpen] = useNavState(false);
  const [feedOpen, setFeedOpen] = useNavState(false);
  const [feedStart, setFeedStart] = useState(null);
  const [homeTab, setHomeTab] = useState('chats');
  const [momentsKept, setMomentsKept] = useState(false);
  useEffect(() => { if (homeTab === 'moments') setMomentsKept(true); }, [homeTab]);
  const [showCreate, setShowCreate] = useState(false);
  const [postComposer, setPostComposer] = useState(null);
  const [postsVersion, setPostsVersion] = useState(0);
  const postInputRef = useRef(null);
  const searchInputRef = useRef(null);
  const openFeedAt = (post, tab) => { setFeedStart(post ? { postId: post.id, tab: tab || 'foryou' } : (tab ? { postId: null, tab } : null)); setFeedOpen(true); };
  const sharePost = async (outputs, caption) => {
    setPostComposer(null);
    let done = 0;
    let failed = 0;
    setSnack('Posting');
    for (const item of outputs) {
      const { url, error } = await uploadMedia(item.file, session.user.id);
      if (error || !url) { failed += 1; continue; }
      let overlayUrl = null;
      if (item.overlayFile) { const up = await uploadMedia(item.overlayFile, session.user.id); if (!up.error) overlayUrl = up.url; }
      const { error: insErr } = await supabase.from('posts').insert({ user_id: session.user.id, media_url: url, media_type: item.kind === 'video' ? 'video' : 'image', overlay_url: overlayUrl, caption: caption || null });
      if (insErr) failed += 1; else done += 1;
    }
    setPostsVersion((v) => v + 1);
    if (failed && !done) showSnack('Could not post. Check your connection and try again.');
    else if (failed) showSnack(`Posted ${done}, ${failed} failed`);
    else showSnack(done === 1 ? 'Posted to your profile' : `Posted ${done} items`);
    playUiSound('tap');
  };
  const swipeRef = useRef(null);
  const feedSwipe = {
    onTouchStart: (e) => {
      const t = e.touches && e.touches[0];
      swipeRef.current = t ? { x: t.clientX, y: t.clientY, time: Date.now() } : null;
    },
    onTouchEnd: (e) => {
      const start = swipeRef.current;
      swipeRef.current = null;
      if (!start || feedOpen) return;
      const t = e.changedTouches && e.changedTouches[0];
      if (!t) return;
      const dx = t.clientX - start.x;
      const dy = Math.abs(t.clientY - start.y);
      if (dx > 90 && dy < 60 && Date.now() - start.time < 700 && start.x < 60) {
        setFeedOpen(true);
        playUiSound('tap');
      }
    },
  };
  const lastAppResumeRef = useRef(0);
  const backStateRef = useRef({});
  backStateRef.current.steps = () => [
    [feedOpen, () => setFeedOpen(false)],
    [collectionOpen, () => setCollectionOpen(false)],
    [showStickers, () => setShowStickers(false)],
    [showSettings, () => setShowSettings(false)],
    [showMail, () => setShowMail(false)],
    [showDiscover, () => setShowDiscover(false)],
    [showArchived, () => setShowArchived(false)],
    [profileOf, () => setProfileOf(null)],
    [mobileShowChat || activeProfile || activeGroup, () => { setMobileShowChat(false); setActiveProfile(null); setActiveGroup(null); }],
    [showCreate, () => setShowCreate(false)],
    [homeTab !== 'chats', () => setHomeTab('chats')],
  ];
  navCtl.rootOpen = () => backStateRef.current.steps().some(([open]) => !!open);
  navCtl.rootClose = () => {
    const hit = backStateRef.current.steps().find(([open]) => !!open);
    if (!hit) return false;
    hit[1]();
    return true;
  };
  useEffect(() => { navSync(); });
  const newVersionAvailable = useNewVersionAvailable();
  const [updateLater, setUpdateLater] = useState(false);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [recordLocked, setRecordLocked] = useState(false);
  const [recordLevels, setRecordLevels] = useState([]);
  const levelTimerRef = useRef(null);
  const levelCtxRef = useRef(null);
  const [recordDragX, setRecordDragX] = useState(0);
  const recordCancelRef = useRef(false);
  const recordGestureRef = useRef(null);
  const cameraGalleryRef = useRef(null);
  const blockRefreshTimerRef = useRef(null);
  const blockRefreshRef = useRef(null);
  const [activeGroupCall, setActiveGroupCall] = useState(null);
  const followRefreshTimerRef = useRef(null);
  const followRefreshRef = useRef(null);
  const storyFollowSetRef = useRef(new Set());
  const storyFeedRef = useRef(null);
  const callEngineRef = useRef(null);
  const handleCallRowRef = useRef(null);
  const [storyComposer, setStoryComposer] = useState(null);
  const [storyCreate, setStoryCreate] = useState(false);
  const [textStory, setTextStory] = useState(false);
  const [storyPaint, setStoryPaint] = useState(false);
  const [storyCamera, setStoryCamera] = useState(false);
  const [storyArchive, setStoryArchive] = useState(false);
  const [highlightFor, setHighlightFor] = useState(null);
