            const c = callEngine.call;
            if (c.mode !== 'direct' || c.kind !== 'video' || !c.peer) return null;
            const stream = (c.remoteStreams || {})[c.peer.id];
            if (!stream || !stream.getVideoTracks().length || (c.remoteCameraOff || {})[c.peer.id]) return null;
