          {duelPlay.g === 'taps' && <TapSprint key={duelPlay.id} onDuelFinish={(v) => finishDuel(duelPlay, v)} />}
          {duelPlay.g === 'sd' && <SoloGame key={duelPlay.id} k={duelPlay.k} seed={duelPlay.id} onDuelFinish={(v) => finishDuel(duelPlay, v)} />}
