const PIN_LETTERS = { 2: 'ABC', 3: 'DEF', 4: 'GHI', 5: 'JKL', 6: 'MNO', 7: 'PQRS', 8: 'TUV', 9: 'WXYZ' };
function AppPinPad({ subtitle, onComplete, error, length = 4, light }) {
  const { theme } = useTheme();
  const [pin, setPin] = useState('');
  const [shake, setShake] = useState(false);
  const busyRef = useRef(false);
  useEffect(() => {
    if (!error) return undefined;
    setShake(true);
    setPin('');
    busyRef.current = false;
    const t = setTimeout(() => setShake(false), 520);
    return () => clearTimeout(t);
  }, [error]);
  const push = (d) => {
    if (busyRef.current || pin.length >= length) return;
    hapticTap();
    const next = pin + d;
    setPin(next);
    if (next.length === length) {
      busyRef.current = true;
      setTimeout(() => { onComplete(next); setPin(''); setTimeout(() => { busyRef.current = false; }, 50); }, 140);
    }
  };
  const back = () => { hapticTap(); setPin((p) => p.slice(0, -1)); };
  useEffect(() => {
    const onKey = (e) => {
      if (/^[0-9]$/.test(e.key)) { e.preventDefault(); push(e.key); }
      else if (e.key === 'Backspace') { e.preventDefault(); back(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });
  const ink = light ? 'white' : theme.ink;
  const keyBg = light ? 'rgba(255,255,255,0.14)' : theme.rowBg;
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', 'back'];
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: 10, userSelect: 'none' }}>
      {subtitle && <div style={{ fontSize: 14.5, color: light ? 'rgba(255,255,255,0.78)' : theme.muted, textAlign: 'center', minHeight: 20 }}>{subtitle}</div>}
      <div className={shake ? 'zchat-shake' : ''} style={{ display: 'flex', gap: 16, margin: '22px 0 30px' }}>
        {Array.from({ length }).map((_, i) => (
          <div key={i} style={{ width: 14, height: 14, borderRadius: '50%', border: `1.5px solid ${ink}`, background: i < pin.length ? ink : 'transparent', transition: 'background 0.12s' }} />
        ))}
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 74px)', gap: 18 }}>
        {keys.map((k, i) => (
          k === '' ? <div key={i} /> : (
            <div key={i} role="button" aria-label={k === 'back' ? 'Delete digit' : `Digit ${k}`} onClick={() => (k === 'back' ? back() : push(k))} className="zchat-press" style={{ width: 74, height: 74, borderRadius: '50%', background: k === 'back' ? 'transparent' : keyBg, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: ink }}>
              {k === 'back' ? <ArrowLeft size={24} /> : (
                <>
                  <span style={{ fontSize: 28, fontWeight: 500, lineHeight: 1 }}>{k}</span>
                  <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: '0.12em', marginTop: 3, opacity: 0.75, minHeight: 11 }}>{PIN_LETTERS[k] || ''}</span>
                </>
              )}
            </div>
          )
        ))}
      </div>
    </div>
  );
}

function AppLockScreen({ onUnlock, onForgot }) {
  const { theme } = useTheme();
  const [err, setErr] = useState(0);
  const [tries, setTries] = useState(0);
  const [askForgot, setAskForgot] = useState(false);
  const bioId = readAppLock().b || null;
  const [bioBusy, setBioBusy] = useState(false);
  const tryBio = async () => {
    if (!bioId || bioBusy) return;
    setBioBusy(true);
    try { if (await bioVerify(bioId)) { playUiSound('toggle'); onUnlock(); return; } } catch {}
    setBioBusy(false);
  };
  useEffect(() => { if (bioId) { const t = setTimeout(tryBio, 350); return () => clearTimeout(t); } return undefined; }, []);
  const check = async (pin) => {
    const ok = await verifyPin(pin);
    if (ok) { playUiSound('toggle'); onUnlock(); }
    else { setErr((e) => e + 1); setTries((t) => t + 1); playUiSound('cancel'); }
  };
  return (
    <Portal>
      <div className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 980, background: AUTH_BG, color: 'white', fontFamily: FONT, overflow: 'hidden' }}>
        <AuthPhoto shade={0.62} />
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '24px 16px calc(24px + env(safe-area-inset-bottom))', overflowY: 'auto' }}>
          <ZMark size={56} />
          <div style={{ fontSize: 22, fontWeight: 800, letterSpacing: '-0.01em', marginTop: 16 }}>ZChat is locked</div>
          <AppPinPad light subtitle={tries ? 'Wrong PIN, try again' : 'Enter your PIN'} onComplete={check} error={err} />
          {bioId && (
            <button type="button" onClick={tryBio} disabled={bioBusy} className="zchat-press" style={{ marginTop: 22, height: 44, padding: '0 18px', borderRadius: 22, border: '1px solid rgba(255,255,255,0.32)', background: 'rgba(3,4,11,0.35)', color: '#fff', fontWeight: 700, fontSize: 14.5, fontFamily: FONT, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8 }}>
              {bioBusy ? <Spinner size={14} /> : <ShieldCheck size={17} />}Use fingerprint or face
            </button>
          )}
          <div role="button" aria-label="Forgot PIN" onClick={() => setAskForgot(true)} style={{ marginTop: 22, fontSize: 14, fontWeight: 700, color: 'rgba(255,255,255,0.8)', cursor: 'pointer' }}>Forgot your PIN?</div>
        </div>
        {askForgot && (
          <ConfirmSheet title="Forgot your PIN?" text="You will be logged out and the PIN removed. Sign in again to get back into your chats." confirmLabel="Log out" zIndex={990}
            onCancel={() => setAskForgot(false)} onConfirm={onForgot} />
        )}
      </div>
    </Portal>
  );
}

function AppLockSection() {
  const { theme } = useTheme();
  const [cfg, setCfg] = useState(readAppLock);
  const [flow, setFlow] = useState(null);
  const [err, setErr] = useState(0);
  const [bioOk, setBioOk] = useState(false);
  const [bioBusy, setBioBusy] = useState(false);
  useEffect(() => { let alive = true; bioPlatformReady().then((v) => { if (alive) setBioOk(!!v); }); return () => { alive = false; }; }, []);
  const toggleBio = async () => {
    if (bioBusy) return;
    if (cfg.b) { const next = { ...cfg }; delete next.b; writeAppLock(next); setCfg(next); return; }
    setBioBusy(true);
    try {
      const id = await bioRegister();
      if (id) { const next = { ...cfg, b: id }; writeAppLock(next); setCfg(next); playUiSound('like'); }
    } catch {}
    setBioBusy(false);
  };
  useBackClose(!!flow, () => setFlow(null));
  const save = (next) => { writeAppLock(next); setCfg(next); };
  const begin = (mode, next) => { setErr(0); setFlow({ mode, next }); };
  const onPin = async (pin) => {
    if (!flow) return;
    if (flow.mode === 'verify') {
      const ok = await verifyPin(pin);
      if (!ok) { setErr((e) => e + 1); return; }
      if (flow.next === 'off') { save({ d: cfg.d || 0 }); setFlow(null); playUiSound('toggle'); }
      else { setErr(0); setFlow({ mode: 'set' }); }
      return;
    }
    if (flow.mode === 'set') { setErr(0); setFlow({ mode: 'confirm', first: pin }); return; }
    if (flow.mode === 'confirm') {
      if (pin !== flow.first) { setErr((e) => e + 1); setFlow({ mode: 'set', mismatch: true }); return; }
      const h = await hashAppPin(pin);
      save({ h, d: cfg.d || 0, ...(cfg.b ? { b: cfg.b } : {}) });
      setFlow(null);
      playUiSound('like');
    }
  };
  const on = !!cfg.h;
  const delays = [[0, 'Immediately'], [60, 'After 1 minute'], [300, 'After 5 minutes'], [1800, 'After 30 minutes']];
  const titles = { verify: 'Enter your PIN', set: 'Choose a PIN', confirm: 'Confirm your PIN' };
  const subs = flow ? (flow.mode === 'verify' ? (err ? 'Wrong PIN, try again' : 'Your current PIN') : flow.mode === 'set' ? (flow.mismatch ? 'The PINs did not match, start again' : 'Four digits you will remember') : 'Type the same PIN again') : '';
  return (
    <div>
      <div style={{ padding: '12px 2px 6px', fontSize: 13, color: theme.muted, lineHeight: 1.5 }}>Ask for a PIN when you come back to ZChat. Your chats stay hidden until you enter it.</div>
      <IgRow inset={false} icon={<Lock size={16} />} label="Require PIN" right={<IgToggle on={on} onClick={() => (on ? begin('verify', 'off') : begin('set'))} />} />
      {on && bioOk && <IgRow inset={false} icon={<ShieldCheck size={16} />} label="Fingerprint or face" sub="Unlock without typing your PIN" right={bioBusy ? <Spinner size={16} color={theme.muted} /> : <IgToggle on={!!cfg.b} onClick={toggleBio} />} />}
      {on && <IgRow inset={false} icon={<Pencil size={16} />} label="Change PIN" onClick={() => begin('verify', 'change')} />}
      {on && <IgRow inset={false} icon={<EyeOff size={16} />} label="Lock now" onClick={() => { try { window.dispatchEvent(new Event('zchat-lock-now')); } catch {} }} />}
      {on && (
        <>
          <IgHeading>Lock again</IgHeading>
          {delays.map(([d, l]) => (
            <div key={d} role="button" aria-label={l} onClick={() => { save({ ...cfg, d }); hapticTap(); }} className="zchat-row-press" style={{ display: 'flex', alignItems: 'center', padding: '13px 2px', borderBottom: `1px solid ${theme.border}`, cursor: 'pointer' }}>
              <span style={{ flex: 1, fontSize: 15, fontWeight: 600, color: theme.ink }}>{l}</span>
              {(cfg.d || 0) === d && <Check size={18} color={theme.coral} strokeWidth={2.6} />}
            </div>
          ))}
          <div style={{ padding: '10px 2px 0', fontSize: 12.5, color: theme.muted, lineHeight: 1.5 }}>Counted from the moment you leave the app or switch tabs.</div>
        </>
      )}
      {flow && (
        <FullPage title={titles[flow.mode]} onBack={() => setFlow(null)} zIndex={70}>
          <AppPinPad key={flow.mode} subtitle={subs} onComplete={onPin} error={err} />
        </FullPage>
      )}
    </div>
  );
}

function ConnectFourCard({ state, myId, live, peerName, onMove, onRematch, ink, fresh }) {
  const { theme } = useTheme();
  const myMark = state.x === myId ? 1 : state.o === myId ? 2 : 0;
  const result = state.w ? (state.w === 'd' ? { who: 3, line: null } : (c4Winner(state.b) || { who: state.w === 'x' ? 1 : 2, line: null })) : null;
  const finished = !!result;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (result.who === 3 ? 'draw' : result.who === myMark ? 'win' : 'lose') : null);
  const myTurn = live && !finished && state.t === myId && myMark > 0;
  const winLine = result && result.line ? result.line : [];
  const status = finished
    ? (result.who === 3 ? 'Draw' : result.who === myMark ? 'You won' : `${peerName || 'They'} won`)
    : myTurn ? 'Your move' : live ? 'Their move' : `Move ${state.n}`;
  const drop = (col) => {
    if (!myTurn) return;
    let row = -1;
    for (let y = C4_H - 1; y >= 0; y--) { if (!state.b[y * C4_W + col]) { row = y; break; } }
    if (row < 0) return;
    const b = state.b.slice();
    b[row * C4_W + col] = myMark;
    const w = c4Winner(b);
    hapticTap();
    playUiSound('tap');
    onMove({ ...state, b, t: myMark === 1 ? state.o : state.x, n: (state.n || 0) + 1, w: w ? (w.who === 3 ? 'd' : w.who === 1 ? 'x' : 'o') : null });
  };
  const cell = 24;
  const gap = 3;
  const pad = 6;
  const colors = { 1: '#FBBF24', 2: '#F43F5E' };
  const boardW = C4_W * cell + (C4_W - 1) * gap + pad * 2;
  return (
    <GameCardShell k="c4" width={boardW + 20} live={live} title="Connect four" status={status} hot={myTurn}>
      <div style={{ padding: pad, borderRadius: 12, background: theme.dark ? '#2F3F9E' : '#3B5BDB', display: 'grid', gridTemplateColumns: `repeat(7, ${cell}px)`, gap, boxSizing: 'border-box' }}>
        {state.b.map((v, i) => {
          const col = i % C4_W;
          return (
            <div key={i} role={myTurn ? 'button' : undefined} aria-label={myTurn ? `Column ${col + 1}` : undefined} data-silent="1" onClick={() => drop(col)} style={{
              width: cell, height: cell, borderRadius: '50%', background: v ? colors[v] : (theme.dark ? 'rgba(10,6,22,0.6)' : 'rgba(255,255,255,0.92)'),
              boxShadow: winLine.includes(i) ? 'inset 0 0 0 3px white' : (v ? 'inset 0 -2px 0 rgba(0,0,0,0.18)' : 'none'), cursor: myTurn ? 'pointer' : 'default',
            }} />
          );
        })}
      </div>
      {myMark > 0 && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 8, fontSize: 11.5, color: theme.muted }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: colors[myMark] }} />You{live && !finished && myTurn ? ', tap a column' : ''}
        </div>
      )}
      {live && finished && onRematch && (
        <button onClick={onRematch} className="zchat-gbtn" style={{ marginTop: 10, width: '100%', height: 34, borderRadius: 10, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Play again</button>
      )}
    </GameCardShell>
  );
}

function RpsCard({ state, myId, live, peerName, onMove, onRematch, ink, fresh }) {
  const { theme } = useTheme();
  const side = state.x === myId ? 'x' : state.o === myId ? 'o' : null;
  useGameResultSound(live, fresh, !!state.w, `${state.id}:${state.n}`, state.w ? (state.w === 'd' ? 'draw' : state.w === side ? 'win' : 'lose') : null);
  const other = side === 'x' ? 'o' : 'x';
  const rounds = state.r || [];
  const wins = { x: 0, o: 0 };
  rounds.forEach((rd) => { const w = rpsRoundWinner(rd.x, rd.o); if (w === 1) wins.x += 1; else if (w === 2) wins.o += 1; });
  const finished = !!state.w;
  const cur = rounds[rounds.length - 1] || { x: null, o: null };
  const iPicked = !!(side && cur[side]);
  const canPick = live && !finished && !!side && !iPicked;
  const status = finished
    ? (state.w === 'd' ? 'Draw' : state.w === side ? 'You won' : `${peerName || 'They'} won`)
    : canPick ? 'Your pick' : live ? 'Their pick' : `Round ${rounds.length}`;
  const pick = (h) => {
    if (!canPick) return;
    const r = rounds.map((x) => ({ ...x }));
    const last = r[r.length - 1];
    last[side] = h;
    let w = null;
    if (last.x && last.o) {
      const rw = rpsRoundWinner(last.x, last.o);
      const nw = { ...wins };
      if (rw === 1) nw.x += 1; else if (rw === 2) nw.o += 1;
      if (nw.x >= 2) w = 'x'; else if (nw.o >= 2) w = 'o'; else if (r.length >= 9) w = 'd'; else r.push({ x: null, o: null });
    }
    hapticTap();
    playUiSound('tap');
    onMove({ ...state, r, n: (state.n || 0) + 1, w });
  };
  const done = rounds.filter((rd) => rd.x && rd.o);
  const mine = side || 'x';
  const theirs = side ? other : 'o';
  return (
    <GameCardShell k="rps" width={236} live={live} title="Rock paper scissors" status={status} hot={canPick}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, marginBottom: 8 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted }}>You</span>
        <span style={{ fontSize: 20, fontWeight: 900, color: ink || theme.ink, letterSpacing: '0.04em' }}>{wins[mine]} : {wins[theirs]}</span>
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 70 }}>{peerName || 'Them'}</span>
      </div>
      {done.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginBottom: 8 }}>
          {done.map((rd, i) => {
            const rw = rpsRoundWinner(rd[mine], rd[theirs]);
            return (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 16 }}>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: theme.muted, width: 16 }}>{i + 1}</span>
                <RpsIcon h={rd[mine]} size={22} />
                <span style={{ fontSize: 10.5, color: theme.muted }}>vs</span>
                <RpsIcon h={rd[theirs]} size={22} />
                <span style={{ marginLeft: 'auto', fontSize: 10.5, fontWeight: 800, color: rw === 1 ? '#22c55e' : rw === 2 ? theme.danger : theme.muted }}>{rw === 1 ? 'Won' : rw === 2 ? 'Lost' : 'Tie'}</span>
              </div>
            );
          })}
        </div>
      )}
      {live && !finished && side && canPick && (
        <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>
          {Object.keys(RPS_HANDS).map((h) => (
            <div key={h} role="button" aria-label={RPS_HANDS[h].l} data-silent="1" onClick={() => pick(h)} className="zchat-gbtn" style={{ ...gameBtnStyle('white'), width: 58, height: 58, display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 18 }}><RpsIcon h={h} size={34} /></div>
          ))}
        </div>
      )}
      {live && !finished && side && iPicked && (
        <div style={{ textAlign: 'center', fontSize: 11.5, color: theme.muted }}>You picked {RPS_HANDS[cur[side]].l.toLowerCase()}. Waiting for {peerName || 'them'}</div>
      )}
      {live && finished && onRematch && (
        <button onClick={onRematch} className="zchat-gbtn" style={{ marginTop: 8, width: '100%', height: 34, borderRadius: 10, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Play again</button>
      )}
    </GameCardShell>
  );
}


function GameCardShell({ width, live, children, title, status, hot, icon, k }) {
  const { theme } = useTheme();
  const gk = k || Object.keys(GAME_TITLES).find((x) => GAME_TITLES[x] === title && x !== 'reflex' && x !== 'quiz');
  const bg = GAME_ART_BG[gk] || ['#6D4DF5', '#C13BDC'];
  return (
    <div onClick={(e) => e.stopPropagation()} style={{ width, boxSizing: 'border-box', borderRadius: 22, overflow: 'hidden', background: theme.dark ? '#18181B' : '#FFFFFF', border: `1px solid ${theme.dark ? 'rgba(255,255,255,0.09)' : 'rgba(0,0,0,0.12)'}`, boxShadow: theme.dark ? '0 10px 26px rgba(0,0,0,0.38)' : '0 10px 24px rgba(0,0,0,0.14)', opacity: live ? 1 : 0.8, filter: live ? 'none' : 'saturate(0.7)' }}>
      <div style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: 9, padding: '9px 9px 9px 9px', background: bg[0], overflow: 'hidden' }}>
        <div style={{ position: 'relative', width: 36, height: 36, borderRadius: 11, overflow: 'hidden', flexShrink: 0, boxShadow: '0 0 0 2px rgba(255,255,255,0.35)' }}>
          {gk ? <GameArt k={gk} width={36} height={36} radius={11} /> : <div style={{ width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>{icon}</div>}
        </div>
        <div style={{ position: 'relative', flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 900, color: 'white', letterSpacing: '-0.01em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</div>
          <div className={hot ? 'zchat-turn-pulse' : undefined} style={{ display: 'inline-flex', alignItems: 'center', gap: 5, marginTop: 3, padding: '2px 8px', borderRadius: 999, maxWidth: '100%', boxSizing: 'border-box', fontSize: 10.5, fontWeight: 900, background: hot ? '#FDE047' : 'rgba(0,0,0,0.28)', color: hot ? '#6B3A00' : 'rgba(255,255,255,0.95)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
            {hot && <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#16A34A', flexShrink: 0 }} />}
            <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{status}</span>
          </div>
        </div>
        {gk && <div style={{ position: 'relative' }}><GameInfoButton k={gk} onDark /></div>}
      </div>
      <div style={{ padding: '12px 10px 12px' }}>{children}</div>
    </div>
  );
}
function GameAgainButton({ onClick, label = 'Play again', color = 'gold' }) {
  return <GameButton onClick={onClick} label={label} color={color} full small style={{ marginTop: 12 }} />;
}

function dotsBoxEdges(r, c) { return { top: r * 3 + c, bottom: (r + 1) * 3 + c, left: r * 4 + c, right: r * 4 + c + 1 }; }
function dotsApplyMove(state, kind, idx, mark) {
  const h = state.h.slice();
  const v = state.v.slice();
  const bx = state.bx.slice();
  if (kind === 'h') { if (h[idx]) return null; h[idx] = mark; } else { if (v[idx]) return null; v[idx] = mark; }
  let gained = 0;
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const i = r * 3 + c;
      if (bx[i]) continue;
      const e = dotsBoxEdges(r, c);
      if (h[e.top] && h[e.bottom] && v[e.left] && v[e.right]) { bx[i] = mark; gained += 1; }
    }
  }
  let w = null;
  if (h.every(Boolean) && v.every(Boolean)) {
    const a = bx.filter((x) => x === 1).length;
    const b = bx.filter((x) => x === 2).length;
    w = a > b ? 'x' : b > a ? 'o' : 'd';
  }
  return { h, v, bx, gained, w };
}
function DotsCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const myMark = state.x === myId ? 1 : state.o === myId ? 2 : 0;
  const finished = !!state.w;
  const myTurn = live && !finished && state.t === myId && myMark > 0;
  const sx = state.bx.filter((b) => b === 1).length;
  const so = state.bx.filter((b) => b === 2).length;
  const mine = myMark === 2 ? so : sx;
  const theirs = myMark === 2 ? sx : so;
  const winMark = state.w === 'x' ? 1 : state.w === 'o' ? 2 : 0;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (state.w === 'd' ? 'draw' : winMark === myMark ? 'win' : 'lose') : null);
  const status = finished ? (state.w === 'd' ? 'Draw' : winMark === myMark ? 'You won' : `${peerName || 'They'} won`) : myTurn ? 'Your move' : live ? 'Their move' : `Move ${state.n}`;
  const colors = { 1: '#FBBF24', 2: '#F43F5E' };
  const play = (kind, idx) => {
    if (!myTurn) return;
    const res = dotsApplyMove(state, kind, idx, myMark);
    if (!res) return;
    hapticTap();
    playUiSound(res.gained ? 'point' : 'tap');
    onMove({ ...state, h: res.h, v: res.v, bx: res.bx, t: res.gained ? state.t : (myMark === 1 ? state.o : state.x), n: (state.n || 0) + 1, w: res.w });
  };
  const S = 196;
  const p = (i) => 14 + i * 56;
  const edgeFill = (m) => (m ? colors[m] : (theme.dark ? 'rgba(255,255,255,0.14)' : 'rgba(30,20,60,0.12)'));
  const edges = [];
  for (let r = 0; r < 4; r++) for (let c = 0; c < 3; c++) { const i = r * 3 + c; edges.push(<rect key={`h${i}`} x={p(c) + 7} y={p(r) - 4} width="42" height="8" rx="4" fill={edgeFill(state.h[i])} role={myTurn && !state.h[i] ? 'button' : undefined} aria-label={myTurn && !state.h[i] ? `Line ${i + 1}` : undefined} data-silent="1" onClick={() => play('h', i)} style={{ cursor: myTurn && !state.h[i] ? 'pointer' : 'default' }} />); }
  for (let r = 0; r < 3; r++) for (let c = 0; c < 4; c++) { const i = r * 4 + c; edges.push(<rect key={`v${i}`} x={p(c) - 4} y={p(r) + 7} width="8" height="42" rx="4" fill={edgeFill(state.v[i])} role={myTurn && !state.v[i] ? 'button' : undefined} aria-label={myTurn && !state.v[i] ? `Line ${i + 13}` : undefined} data-silent="1" onClick={() => play('v', i)} style={{ cursor: myTurn && !state.v[i] ? 'pointer' : 'default' }} />); }
  return (
    <GameCardShell width={S + 20} live={live} title="Dots and boxes" status={status} hot={myTurn} icon={<GridDotsIcon size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, marginBottom: 6 }}>
        <span style={{ width: 9, height: 9, borderRadius: '50%', background: colors[myMark || 1] }} />
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted }}>You</span>
        <span style={{ fontSize: 18, fontWeight: 900, color: theme.ink, letterSpacing: '0.04em' }}>{mine} : {theirs}</span>
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 70 }}>{peerName || 'Them'}</span>
        <span style={{ width: 9, height: 9, borderRadius: '50%', background: colors[myMark === 2 ? 1 : 2] }} />
      </div>
      <svg width={S} height={S} viewBox={`0 0 ${S} ${S}`} style={{ display: 'block', borderRadius: 12, background: theme.dark ? 'rgba(10,6,22,0.45)' : 'rgba(255,255,255,0.7)' }} aria-hidden={!myTurn}>
        {state.bx.map((owner, i) => (owner ? <rect key={`b${i}`} x={p(i % 3) + 6} y={p(Math.floor(i / 3)) + 6} width="44" height="44" rx="8" fill={colors[owner]} opacity="0.38" /> : null))}
        {edges}
        {[0, 1, 2, 3].map((r) => [0, 1, 2, 3].map((c) => <circle key={`d${r}${c}`} cx={p(c)} cy={p(r)} r="5" fill={theme.ink} opacity="0.85" />))}
      </svg>
      {live && !finished && myTurn && state.n === 0 && <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>Tap a line. Close a box to score and go again</div>}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

const HANG_MAX = 6;
function HangFigure({ misses, color }) {
  const show = (n) => (misses >= n ? 1 : 0.12);
  return (
    <svg width="64" height="76" viewBox="0 0 64 76" fill="none" stroke={color} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M6 72h30M16 72V6h30v10" />
      <circle cx="46" cy="24" r="7" opacity={show(1)} />
      <path d="M46 31v18" opacity={show(2)} />
      <path d="M46 36l-9 8" opacity={show(3)} />
      <path d="M46 36l9 8" opacity={show(4)} />
      <path d="M46 49l-8 12" opacity={show(5)} />
      <path d="M46 49l8 12" opacity={show(6)} />
    </svg>
  );
}
function HangCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const word = String(state.sw || '').toLowerCase();
  const guessed = Array.isArray(state.gl) ? state.gl : [];
  const isSetter = state.x === myId;
  const isGuesser = state.o === myId;
  const misses = guessed.filter((l) => !word.includes(l)).length;
  const finished = !!state.w;
  const outcome = finished ? (state.w === 'o' ? (isGuesser ? 'win' : 'lose') : (isSetter ? 'win' : 'lose')) : null;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const canGuess = live && !finished && isGuesser;
  const status = finished
    ? (state.w === 'o' ? (isGuesser ? 'You got it' : `${peerName || 'They'} got it`) : (isGuesser ? 'Out of tries' : `${peerName || 'They'} missed`))
    : canGuess ? 'Your guess' : live ? (isSetter ? `${peerName || 'They'} is guessing` : `Waiting for ${peerName || 'them'}`) : `Guess ${state.n}`;
  const guess = (l) => {
    if (!canGuess || guessed.includes(l)) return;
    const gl = [...guessed, l];
    const hit = word.includes(l);
    const nm = gl.filter((x) => !word.includes(x)).length;
    const done = word.split('').every((ch) => gl.includes(ch));
    hapticTap();
    playUiSound(hit ? 'point' : 'cancel');
    onMove({ ...state, gl, n: (state.n || 0) + 1, w: done ? 'o' : nm >= HANG_MAX ? 'x' : null });
  };
  const reveal = isSetter || finished;
  const rows = ['abcdefghi', 'jklmnopqr', 'stuvwxyz'];
  return (
    <GameCardShell width={240} live={live} title="Hangman" status={status} hot={canGuess} icon={<Type size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
        <HangFigure misses={misses} color={theme.ink} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 3 }}>
            {word.split('').map((ch, i) => {
              const shown = guessed.includes(ch) || reveal;
              return (
                <div key={i} style={{ width: 17, height: 22, borderRadius: 4, background: theme.dark ? 'rgba(10,6,22,0.6)' : '#FFFFFF', border: `1px solid ${theme.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12.5, fontWeight: 900, textTransform: 'uppercase', color: shown && !guessed.includes(ch) ? theme.muted : theme.ink }}>{shown ? ch : ''}</div>
              );
            })}
          </div>
          <div style={{ fontSize: 11.5, color: misses >= HANG_MAX - 1 ? theme.danger : theme.muted, marginTop: 6, fontWeight: 700 }}>{misses} of {HANG_MAX} wrong</div>
        </div>
      </div>
      {canGuess && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 3, marginTop: 10, alignItems: 'center' }}>
          {rows.map((r) => (
            <div key={r} style={{ display: 'flex', gap: 2 }}>
              {r.split('').map((l) => {
                const used = guessed.includes(l);
                const hit = used && word.includes(l);
                return (
                  <div key={l} role={used ? undefined : 'button'} aria-label={used ? undefined : `Guess ${l}`} data-silent="1" onClick={() => guess(l)} style={{ width: 22, height: 26, borderRadius: 5, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 800, textTransform: 'uppercase', cursor: used ? 'default' : 'pointer', background: hit ? '#22C55E' : used ? (theme.dark ? 'rgba(255,255,255,0.05)' : 'rgba(30,20,60,0.06)') : (theme.dark ? 'rgba(255,255,255,0.12)' : '#FFFFFF'), color: hit ? 'white' : used ? theme.muted : theme.ink, opacity: used && !hit ? 0.45 : 1, border: `1px solid ${theme.border}` }}>{l}</div>
                );
              })}
            </div>
          ))}
        </div>
      )}
      {isSetter && !finished && live && <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>You picked the word. Watch them guess.</div>}
      {finished && <div style={{ marginTop: 8, fontSize: 12, color: theme.muted, textAlign: 'center' }}>The word was <b style={{ color: theme.ink }}>{word.toUpperCase()}</b></div>}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} label={isGuesser ? 'Your turn to pick a word' : 'Play again'} />}
    </GameCardShell>
  );
}

function DuelCard({ state, myId, live, peerName, onPlay, onRematch, fresh }) {
  const { theme } = useTheme();
  const side = state.x === myId ? 'x' : state.o === myId ? 'o' : null;
  const mine = side === 'o' ? state.ro : state.rx;
  const theirs = side === 'o' ? state.rx : state.ro;
  const finished = !!state.w;
  const kindBase = DUEL_KINDS[state.g] || DUEL_KINDS.qduel;
  const kind = state.g === 'sd' && SCORE_DUELS[state.k] ? { ...kindBase, unit: SCORE_DUELS[state.k].unit } : kindBase;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (state.w === 'd' ? 'draw' : state.w === side ? 'win' : 'lose') : null);
  const canPlay = live && !finished && !!side && mine == null;
  const status = finished ? (state.w === 'd' ? 'Draw' : state.w === side ? 'You won' : `${peerName || 'They'} won`) : canPlay ? 'Your round' : live ? `Waiting for ${peerName || 'them'}` : 'Round sent';
  const sub = kind.sub;
  const icon = state.g === 'wduel' ? <Type size={15} color={theme.coral} /> : state.g === 'rduel' || state.g === 'taps' ? <BoltIcon size={15} color={theme.coral} /> : state.g === 'math' ? <Plus size={15} color={theme.coral} /> : <HelpCircle size={15} color={theme.coral} />;
  const line = (label, v, highlight) => (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '7px 10px', borderRadius: 10, background: theme.dark ? 'rgba(10,6,22,0.45)' : 'rgba(255,255,255,0.7)' }}>
      <span style={{ fontSize: 12.5, fontWeight: 700, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
      <span style={{ fontSize: 12.5, fontWeight: 800, color: v == null ? theme.muted : highlight ? '#22C55E' : theme.ink, whiteSpace: 'nowrap' }}>{v == null ? 'Not yet' : kind.unit(v)}</span>
    </div>
  );
  return (
    <GameCardShell k={state.g === 'sd' ? state.k : state.g} width={224} live={live} title={gameTitle(state)} status={status} hot={canPlay} icon={icon}>
      <div style={{ fontSize: 11.5, color: theme.muted, marginBottom: 8, lineHeight: 1.4 }}>{sub}</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {line('You', mine, finished && state.w === side)}
        {line(peerName || 'Them', theirs, finished && state.w && state.w !== 'd' && state.w !== side)}
      </div>
      {canPlay && <GameAgainButton onClick={onPlay} label="Play your round" color="green" />}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function WordPromptSheet({ title, text, placeholder, onSubmit, onCancel, numeric }) {
  useBackClose(true, onCancel);
  const { theme } = useTheme();
  const [v, setV] = useState('');
  const clean = numeric ? v.replace(/[^0-9]/g, '') : v.trim().toLowerCase();
  const ok = numeric ? (/^[0-9]{1,3}$/.test(clean) && +clean >= 1 && +clean <= 100) : /^[a-z]{3,12}$/.test(clean);
  const submitValue = () => onSubmit(numeric ? parseInt(clean, 10) : clean);
  return (
    <Portal>
      <div onClick={onCancel} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 95, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT, background: 'rgba(0,0,0,0.45)' }}>
        <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxWidth: 460, background: theme.panelBg, borderRadius: '24px 24px 0 0', padding: '10px 20px', paddingBottom: 'calc(18px + env(safe-area-inset-bottom))', boxShadow: '0 -10px 40px rgba(0,0,0,0.25)' }}>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '2px 0 12px' }}><div style={{ width: 38, height: 4, borderRadius: 2, background: theme.border }} /></div>
          <div style={{ fontSize: 18, fontWeight: 800, color: theme.ink }}>{title}</div>
          <div style={{ fontSize: 13, color: theme.muted, marginTop: 4, lineHeight: 1.45 }}>{text}</div>
          <input autoFocus value={v} onChange={(e) => setV(e.target.value)} placeholder={placeholder} aria-label={placeholder} autoCapitalize="none" autoCorrect="off" spellCheck={false} maxLength={numeric ? 3 : 12} inputMode={numeric ? 'numeric' : undefined}
            onKeyDown={(e) => { if (e.key === 'Enter' && ok) submitValue(); }}
            style={{ ...inputStyle(theme), marginTop: 14, fontSize: 18, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'lowercase' }} />
          <div style={{ fontSize: 12, color: theme.muted, marginTop: 6 }}>{numeric ? 'A whole number from 1 to 100. They never see it until the end.' : '3 to 12 letters, no spaces. They never see it until the end.'}</div>
          <button disabled={!ok} onClick={() => ok && submitValue()} className="zchat-press" style={{ ...primaryBtn(theme, !ok), marginTop: 14 }}>Send the challenge</button>
        </div>
      </div>
    </Portal>
  );
}


function useTurnStatus(state, myId, live, peerName) {
  const myMark = state.x === myId ? 1 : state.o === myId ? 2 : 0;
  const finished = !!state.w;
  const myTurn = live && !finished && state.t === myId && myMark > 0;
  const winMark = state.w === 'x' ? 1 : state.w === 'o' ? 2 : 0;
  const outcome = finished ? (state.w === 'd' ? 'draw' : winMark === myMark ? 'win' : 'lose') : null;
  const status = finished ? (state.w === 'd' ? 'Draw' : winMark === myMark ? 'You won' : `${peerName || 'They'} won`) : myTurn ? 'Your move' : live ? 'Their move' : `Move ${state.n}`;
  return { myMark, finished, myTurn, winMark, outcome, status };
}
function ScoreLine({ mine, theirs, peerName, myColor, theirColor }) {
  const { theme } = useTheme();
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, marginBottom: 8 }}>
      {myColor && <span style={{ width: 9, height: 9, borderRadius: '50%', background: myColor }} />}
      <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted }}>You</span>
      <span style={{ fontSize: 18, fontWeight: 900, color: theme.ink, letterSpacing: '0.04em' }}>{mine} : {theirs}</span>
      <span style={{ fontSize: 12, fontWeight: 700, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 70 }}>{peerName || 'Them'}</span>
      {theirColor && <span style={{ width: 9, height: 9, borderRadius: '50%', background: theirColor }} />}
    </div>
  );
}

function GomokuCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const res = finished && state.w !== 'd' ? lineWinner(state.b, 9, 9, 5) : null;
  const winLine = res && res.line ? res.line : [];
  const tap = (i) => {
    if (!myTurn || state.b[i]) return;
    const b = state.b.slice();
    b[i] = myMark;
    const w = lineWinner(b, 9, 9, 5);
    hapticTap();
    playUiSound('tap');
    onMove({ ...state, b, t: myMark === 1 ? state.o : state.x, n: (state.n || 0) + 1, w: w ? (w.who === 3 ? 'd' : w.who === 1 ? 'x' : 'o') : null, lastIdx: i });
  };
  const cell = 21;
  const S = 9 * cell;
  const last = state.lastIdx;
  return (
    <GameCardShell width={S + 20 + 8} live={live} title="Five in a row" status={status} hot={myTurn} icon={<GridDotsIcon size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, marginBottom: 8, fontSize: 12, fontWeight: 700, color: theme.muted }}>
        <span style={{ width: 11, height: 11, borderRadius: '50%', background: myMark === 2 ? '#FFFFFF' : '#1F1537', border: '1px solid rgba(0,0,0,0.3)' }} />You
        <span style={{ width: 11, height: 11, borderRadius: '50%', background: myMark === 2 ? '#1F1537' : '#FFFFFF', border: '1px solid rgba(0,0,0,0.3)', marginLeft: 8 }} /><span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 90 }}>{peerName || 'Them'}</span>
      </div>
      <svg width={S + 8} height={S + 8} viewBox={`0 0 ${S + 8} ${S + 8}`} style={{ display: 'block', borderRadius: 10, background: '#D9A066' }}>
        {Array.from({ length: 9 }).map((_, k) => <g key={k}><line x1={4 + cell / 2} y1={4 + cell / 2 + k * cell} x2={4 + S - cell / 2} y2={4 + cell / 2 + k * cell} stroke="#7A4A1D" strokeWidth="1" /><line x1={4 + cell / 2 + k * cell} y1={4 + cell / 2} x2={4 + cell / 2 + k * cell} y2={4 + S - cell / 2} stroke="#7A4A1D" strokeWidth="1" /></g>)}
        {state.b.map((v, i) => {
          const cx = 4 + cell / 2 + (i % 9) * cell;
          const cy = 4 + cell / 2 + Math.floor(i / 9) * cell;
          if (!v) return myTurn ? <circle key={i} cx={cx} cy={cy} r={cell / 2} fill="transparent" role="button" aria-label={`Spot ${i + 1}`} data-silent="1" onClick={() => tap(i)} style={{ cursor: 'pointer' }} /> : null;
          return (
            <g key={i}>
              <circle cx={cx + 0.6} cy={cy + 1} r={cell * 0.42} fill="rgba(0,0,0,0.25)" />
              <circle cx={cx} cy={cy} r={cell * 0.42} fill={v === 1 ? '#1F1537' : '#FFFFFF'} stroke={winLine.includes(i) ? theme.coral : 'rgba(0,0,0,0.25)'} strokeWidth={winLine.includes(i) ? 2.5 : 1} />
              {i === last && <circle cx={cx} cy={cy} r="2.2" fill={v === 1 ? '#FFFFFF' : '#1F1537'} />}
            </g>
          );
        })}
      </svg>
      {live && !finished && myTurn && state.n === 0 && <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>Tap a crossing. Five in a line wins</div>}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function ReversiCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const count = (m) => state.b.filter((v) => v === m).length;
  const mine = count(myMark || 1);
  const theirs = count(myMark === 2 ? 1 : 2);
  const tap = (i) => {
    if (!myTurn) return;
    const flips = reversiFlips(state.b, i, myMark);
    if (!flips.length) return;
    const b = state.b.slice();
    b[i] = myMark;
    flips.forEach((k) => { b[k] = myMark; });
    const other = myMark === 1 ? 2 : 1;
    const otherId = myMark === 1 ? state.o : state.x;
    let t = otherId;
    let w = null;
    if (!reversiHasMove(b, other)) {
      if (reversiHasMove(b, myMark)) t = myId;
      else { const a = b.filter((v) => v === 1).length; const c = b.filter((v) => v === 2).length; w = a > c ? 'x' : c > a ? 'o' : 'd'; }
    }
    hapticTap();
    playUiSound(flips.length >= 3 ? 'point' : 'tap');
    onMove({ ...state, b, t, n: (state.n || 0) + 1, w, lastIdx: i });
  };
  const cell = 30;
  return (
    <GameCardShell width={6 * cell + 8 + 20} live={live} title="Reversi" status={status} hot={myTurn} icon={<GridDotsIcon size={15} color={theme.coral} />}>
      <ScoreLine mine={mine} theirs={theirs} peerName={peerName} myColor={myMark === 2 ? '#FFFFFF' : '#1F1537'} theirColor={myMark === 2 ? '#1F1537' : '#FFFFFF'} />
      <div style={{ display: 'grid', gridTemplateColumns: `repeat(6, ${cell}px)`, gap: 0, padding: 4, borderRadius: 10, background: '#1B7A3E', border: '2px solid #0F5A2B', boxSizing: 'border-box', width: 6 * cell + 8 }}>
        {state.b.map((v, i) => {
          const can = myTurn && !v && reversiFlips(state.b, i, myMark).length > 0;
          return (
            <div key={i} role={can ? 'button' : undefined} aria-label={can ? `Square ${i + 1}` : undefined} data-silent="1" onClick={() => tap(i)} style={{ width: cell, height: cell, boxSizing: 'border-box', border: '1px solid rgba(0,0,0,0.25)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: can ? 'pointer' : 'default' }}>
              {v ? <div style={{ width: cell - 8, height: cell - 8, borderRadius: '50%', background: v === 1 ? 'radial-gradient(circle at 35% 35%, #4B4162, #120B22)' : 'radial-gradient(circle at 35% 35%, #FFFFFF, #CBD5E1)', boxShadow: '0 2px 3px rgba(0,0,0,0.35)', outline: state.lastIdx === i ? `2px solid ${theme.coral}` : 'none' }} />
                : can ? <div style={{ width: 8, height: 8, borderRadius: '50%', background: 'rgba(255,255,255,0.45)' }} /> : null}
            </div>
          );
        })}
      </div>
      {live && !finished && myTurn && state.n === 0 && <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>Tap a glowing square to trap their discs</div>}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function NimCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const take = (row, k) => {
    if (!myTurn) return;
    const r = state.r.slice();
    const n = r[row];
    if (k < 0 || k >= n) return;
    r[row] = k;
    const left = r.reduce((a, b) => a + b, 0);
    hapticTap();
    playUiSound(left === 0 ? 'point' : 'tap');
    onMove({ ...state, r, t: myMark === 1 ? state.o : state.x, n: (state.n || 0) + 1, w: left === 0 ? (myMark === 1 ? 'x' : 'o') : null });
  };
  const left = state.r.reduce((a, b) => a + b, 0);
  return (
    <GameCardShell width={216} live={live} title="Nim sticks" status={status} hot={myTurn} icon={<GamepadIcon size={15} color={theme.coral} />}>
      <div style={{ fontSize: 11.5, color: theme.muted, marginBottom: 8, textAlign: 'center' }}>{finished ? `${left} left` : 'Tap a stick to take it and the ones after it. Last stick wins.'}</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'center', padding: '6px 0' }}>
        {state.r.map((n, row) => (
          <div key={row} style={{ display: 'flex', gap: 6, minHeight: 36, alignItems: 'center' }}>
            {n === 0 ? <span style={{ fontSize: 11, color: theme.muted }}>Empty</span> : Array.from({ length: n }).map((_, k) => (
              <div key={k} role={myTurn ? 'button' : undefined} aria-label={myTurn ? `Row ${row + 1} stick ${k + 1}` : undefined} data-silent="1" onClick={() => take(row, k)} style={{ width: 10, height: 36, borderRadius: 5, background: 'linear-gradient(180deg, #FCD9A8, #D9A066)', boxShadow: '0 2px 3px rgba(0,0,0,0.3)', cursor: myTurn ? 'pointer' : 'default', position: 'relative' }}>
                <div style={{ position: 'absolute', top: -3, left: 1, width: 8, height: 8, borderRadius: '50%', background: '#EF4444' }} />
              </div>
            ))}
          </div>
        ))}
      </div>
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function MancalaCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const p = state.p;
  const myStore = myMark === 2 ? 13 : 6;
  const theirStore = myMark === 2 ? 6 : 13;
  const myPits = myMark === 2 ? [7, 8, 9, 10, 11, 12] : [0, 1, 2, 3, 4, 5];
  const theirPits = myMark === 2 ? [0, 1, 2, 3, 4, 5] : [7, 8, 9, 10, 11, 12];
  const sow = (pit) => {
    if (!myTurn || !p[pit] || !myPits.includes(pit)) return;
    const np = p.slice();
    let stones = np[pit];
    np[pit] = 0;
    let pos = pit;
    while (stones > 0) {
      pos = (pos + 1) % 14;
      if (pos === theirStore) continue;
      np[pos] += 1;
      stones -= 1;
    }
    let again = pos === myStore;
    if (!again && myPits.includes(pos) && np[pos] === 1 && np[12 - pos] > 0) { np[myStore] += np[12 - pos] + 1; np[12 - pos] = 0; np[pos] = 0; }
    const sideEmpty = (pits) => pits.every((i) => np[i] === 0);
    let w = null;
    if (sideEmpty([0, 1, 2, 3, 4, 5]) || sideEmpty([7, 8, 9, 10, 11, 12])) {
      [0, 1, 2, 3, 4, 5].forEach((i) => { np[6] += np[i]; np[i] = 0; });
      [7, 8, 9, 10, 11, 12].forEach((i) => { np[13] += np[i]; np[i] = 0; });
      w = np[6] > np[13] ? 'x' : np[13] > np[6] ? 'o' : 'd';
      again = false;
    }
    hapticTap();
    playUiSound(again ? 'point' : 'tap');
    onMove({ ...state, p: np, t: w ? state.t : (again ? myId : (myMark === 1 ? state.o : state.x)), n: (state.n || 0) + 1, w });
  };
  const pit = (i, mineRow) => {
    const can = myTurn && mineRow && p[i] > 0;
    return (
      <div key={i} role={can ? 'button' : undefined} aria-label={can ? `Pit ${i + 1}` : undefined} data-silent="1" onClick={() => sow(i)} style={{ width: 22, height: 32, borderRadius: 12, background: can ? '#FDE68A' : (theme.dark ? 'rgba(10,6,22,0.5)' : 'rgba(255,255,255,0.8)'), border: `1px solid ${can ? '#D97706' : theme.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 900, color: can ? '#78350F' : theme.ink, cursor: can ? 'pointer' : 'default' }}>{p[i]}</div>
    );
  };
  const store = (i, label) => (
    <div style={{ width: 24, height: 70, borderRadius: 12, background: theme.dark ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.9)', border: `1px solid ${theme.border}`, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 2, flexShrink: 0 }}>
      <span style={{ fontSize: 15, fontWeight: 900, color: theme.ink }}>{p[i]}</span>
      <span style={{ fontSize: 8.5, fontWeight: 700, color: theme.muted }}>{label}</span>
    </div>
  );
  return (
    <GameCardShell width={240} live={live} title="Mancala" status={status} hot={myTurn} icon={<GamepadIcon size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 5, padding: 5, borderRadius: 14, background: 'linear-gradient(180deg, #B4722E, #7C4A1A)', boxSizing: 'border-box', width: '100%', maxWidth: 220, justifyContent: 'center', margin: '0 auto' }}>
        {store(theirStore, 'Them')}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
          <div style={{ display: 'flex', gap: 2 }}>{theirPits.slice().reverse().map((i) => pit(i, false))}</div>
          <div style={{ display: 'flex', gap: 2 }}>{myPits.map((i) => pit(i, true))}</div>
        </div>
        {store(myStore, 'You')}
      </div>
      <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>{finished ? `Final ${p[myStore]} to ${p[theirStore]}` : myTurn ? 'Tap one of your gold pits to sow' : 'Bottom row is yours. End in your store to go again.'}</div>
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function PairsCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const faces = useMemo(() => { const picks = seededShuffle(MEMORY_TOKENS.map((t) => t.k), `pairs:${state.id}`).slice(0, 8); return seededShuffle([...picks, ...picks], `deal:${state.id}`); }, [state.id]);
  const [pick, setPick] = useState(null);
  useEffect(() => { setPick(null); }, [state.n]);
  const mine = state.d.filter((v) => v === myMark).length / 2;
  const theirs = state.d.filter((v) => v && v !== myMark).length / 2;
  const flip = (i) => {
    if (!myTurn || state.d[i]) return;
    if (pick == null) { setPick(i); hapticTap(); playUiSound('key'); return; }
    if (pick === i) return;
    const match = faces[pick] === faces[i];
    const d = state.d.slice();
    if (match) { d[pick] = myMark; d[i] = myMark; }
    const allDone = d.every(Boolean);
    let w = null;
    if (allDone) { const a = d.filter((v) => v === 1).length; const b = d.filter((v) => v === 2).length; w = a > b ? 'x' : b > a ? 'o' : 'd'; }
    hapticTap();
    playUiSound(match ? 'point' : 'cancel');
    onMove({ ...state, d, last: [pick, i], t: w ? state.t : (match ? myId : (myMark === 1 ? state.o : state.x)), n: (state.n || 0) + 1, w });
  };
  const showLast = live && Array.isArray(state.last) && state.n > 0;
  return (
    <GameCardShell width={228} live={live} title="Pairs" status={status} hot={myTurn} icon={<Sparkles size={15} color={theme.coral} />}>
      <ScoreLine mine={mine} theirs={theirs} peerName={peerName} myColor="#FBBF24" theirColor="#F43F5E" />
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 44px)', gap: 4 }}>
        {faces.map((f, i) => {
          const owner = state.d[i];
          const up = !!owner || pick === i || (showLast && state.last.includes(i));
          return (
            <div key={i} role={myTurn && !owner ? 'button' : undefined} aria-label={myTurn && !owner ? `Card ${i + 1}` : undefined} data-silent="1" onClick={() => flip(i)} style={{ width: 44, height: 44, borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24, cursor: myTurn && !owner ? 'pointer' : 'default', background: owner ? (owner === myMark ? 'rgba(251,191,36,0.35)' : 'rgba(244,63,94,0.35)') : up ? (theme.dark ? 'rgba(255,255,255,0.14)' : '#FFFFFF') : CARD_BACK, border: `1px solid ${owner ? 'transparent' : theme.border}`, transition: 'background 0.2s' }}>
              {up ? <MemoryToken k={f} size={26} /> : null}
            </div>
          );
        })}
      </div>
      <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>{finished ? 'All pairs found' : myTurn ? (pick == null ? (showLast ? 'Their last two cards stay up for you' : 'Flip two cards. A match means another go') : 'Now flip a second card') : showLast ? 'No match. Their turn now' : ''}</div>
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function DieFace({ v, size = 36, held, onClick, label }) {
  const dots = { 1: [[1, 1]], 2: [[0, 0], [2, 2]], 3: [[0, 0], [1, 1], [2, 2]], 4: [[0, 0], [0, 2], [2, 0], [2, 2]], 5: [[0, 0], [0, 2], [1, 1], [2, 0], [2, 2]], 6: [[0, 0], [0, 1], [0, 2], [2, 0], [2, 1], [2, 2]] };
  return (
    <div role={onClick ? 'button' : undefined} aria-label={label} data-silent="1" onClick={onClick} style={{ width: size, height: size, borderRadius: size * 0.22, background: held ? '#FDE68A' : '#FFFFFF', border: held ? '2px solid #D97706' : '1px solid rgba(0,0,0,0.15)', boxShadow: '0 2px 4px rgba(0,0,0,0.25)', position: 'relative', cursor: onClick ? 'pointer' : 'default', flexShrink: 0, boxSizing: 'border-box' }}>
      {(dots[v] || []).map(([r, c], i) => <div key={i} style={{ position: 'absolute', width: size * 0.17, height: size * 0.17, borderRadius: '50%', background: '#1F1537', left: `${18 + c * 32}%`, top: `${18 + r * 32}%`, transform: 'translate(-50%, -50%)' }} />)}
    </div>
  );
}
function DiceCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const side = state.x === myId ? 'x' : state.o === myId ? 'o' : null;
  const mine = side === 'o' ? state.do : state.dx;
  const theirs = side === 'o' ? state.dx : state.do;
  const finished = !!state.w;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (state.w === 'd' ? 'draw' : state.w === side ? 'win' : 'lose') : null);
  const [roll, setRoll] = useState(null);
  const [held, setHeld] = useState([false, false, false, false, false]);
  const [rolls, setRolls] = useState(0);
  const canPlay = live && !finished && !!side && mine == null;
  const status = finished ? (state.w === 'd' ? 'Draw' : state.w === side ? 'You won' : `${peerName || 'They'} won`) : canPlay ? 'Your roll' : live ? `Waiting for ${peerName || 'them'}` : 'Roll sent';
  const doRoll = () => {
    const next = (roll || [0, 0, 0, 0, 0]).map((v, i) => (roll && held[i] ? v : 1 + Math.floor(Math.random() * 6)));
    setRoll(next);
    setRolls((r) => r + 1);
    hapticTap();
    playUiSound('toggle');
  };
  const send = () => {
    if (!roll) return;
    const key = side === 'o' ? 'do' : 'dx';
    const next = { ...state, [key]: roll, n: (state.n || 0) + 1 };
    if (next.dx && next.do) { const a = diceRank(next.dx).score; const b = diceRank(next.do).score; next.w = a === b ? 'd' : a > b ? 'x' : 'o'; }
    playUiSound('point');
    onMove(next);
  };
  const row = (label, d, highlight) => (
    <div style={{ padding: '6px 8px', borderRadius: 10, background: theme.dark ? 'rgba(10,6,22,0.45)' : 'rgba(255,255,255,0.7)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: d ? 5 : 0 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
        <span style={{ marginLeft: 'auto', fontSize: 10.5, fontWeight: 800, color: highlight ? '#22C55E' : theme.muted, whiteSpace: 'nowrap' }}>{d ? diceRank(d).name : 'Not rolled yet'}</span>
      </div>
      {d && <div style={{ display: 'flex', gap: 4 }}>{d.map((v, i) => <DieFace key={i} v={v} size={26} />)}</div>}
    </div>
  );
  return (
    <GameCardShell width={240} live={live} title="Poker dice" status={status} hot={canPlay} icon={<GamepadIcon size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {row('You', mine, finished && state.w === side)}
        {row(peerName || 'Them', theirs, finished && state.w && state.w !== 'd' && state.w !== side)}
      </div>
      {canPlay && (
        <div style={{ marginTop: 10 }}>
          {roll && (
            <div style={{ display: 'flex', gap: 6, justifyContent: 'center', marginBottom: 8 }}>
              {roll.map((v, i) => <DieFace key={i} v={v} size={34} held={held[i]} label={`Die ${i + 1}`} onClick={rolls < 2 ? () => { setHeld((h) => h.map((x, k) => (k === i ? !x : x))); hapticTap(); playUiSound('key'); } : undefined} />)}
            </div>
          )}
          {roll && <div style={{ fontSize: 11.5, color: theme.muted, textAlign: 'center', marginBottom: 6 }}>{rolls < 2 ? `${diceRank(roll).name}. Tap dice to hold, then roll again` : diceRank(roll).name}</div>}
          <div style={{ display: 'flex', gap: 8 }}>
            {rolls < 2 && <button onClick={doRoll} className="zchat-gbtn" style={{ flex: 1, height: 34, borderRadius: 10, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>{roll ? 'Roll again' : 'Roll the dice'}</button>}
            {roll && <button onClick={send} className="zchat-gbtn" style={{ flex: 1, height: 34, borderRadius: 10, border: `1.5px solid ${theme.coral}`, background: 'transparent', color: theme.coral, fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('white') }}>Keep these</button>}
          </div>
        </div>
      )}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function PlayingCard({ i, size = 34, hidden }) {
  const c = cardOf(i);
  const h = Math.round(size * 1.4);
  return (
    <div style={{ width: size, height: h, borderRadius: Math.round(size * 0.16), background: hidden ? 'repeating-linear-gradient(45deg, #7C5CFC 0 4px, #5B3FD6 4px 8px)' : '#FFFFFF', border: '1px solid rgba(0,0,0,0.18)', boxShadow: '0 2px 4px rgba(0,0,0,0.25)', position: 'relative', flexShrink: 0, color: c.red ? '#DC2626' : '#111827', fontFamily: FONT, boxSizing: 'border-box' }}>
      {!hidden && <span style={{ position: 'absolute', top: 2, left: 3, fontSize: size * 0.32, fontWeight: 900, lineHeight: 1 }}>{c.label}</span>}
      {!hidden && <span style={{ position: 'absolute', right: 3, bottom: 2, fontSize: size * 0.5, lineHeight: 1 }}>{c.sym}</span>}
    </div>
  );
}
function BlackjackCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const side = state.x === myId ? 'x' : state.o === myId ? 'o' : null;
  const deck = useMemo(() => deckFor(state.id), [state.id]);
  const handX = deck.slice(0, state.hx);
  const handO = deck.slice(26, 26 + state.ho);
  const vx = bjValue(handX);
  const vo = bjValue(handO);
  const finished = !!state.w;
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, finished ? (state.w === 'd' ? 'draw' : state.w === side ? 'win' : 'lose') : null);
  const myHand = side === 'o' ? handO : handX;
  const theirHand = side === 'o' ? handX : handO;
  const myVal = side === 'o' ? vo : vx;
  const theirVal = side === 'o' ? vx : vo;
  const myStood = side === 'o' ? state.so : state.sx;
  const theirStood = side === 'o' ? state.sx : state.so;
  const canAct = live && !finished && !!side && !myStood && myVal <= 21;
  const status = finished ? (state.w === 'd' ? 'Draw' : state.w === side ? 'You won' : `${peerName || 'They'} won`) : canAct ? 'Hit or stand' : live ? `Waiting for ${peerName || 'them'}` : `Round ${state.n}`;
  const act = (hit) => {
    if (!canAct) return;
    const next = { ...state, n: (state.n || 0) + 1 };
    if (hit) { if (side === 'o') next.ho += 1; else next.hx += 1; }
    const nvx = bjValue(deck.slice(0, next.hx));
    const nvo = bjValue(deck.slice(26, 26 + next.ho));
    if (!hit) { if (side === 'o') next.so = true; else next.sx = true; }
    if (nvx > 21) next.sx = true;
    if (nvo > 21) next.so = true;
    if (next.sx && next.so) {
      const bx = nvx > 21;
      const bo = nvo > 21;
      next.w = bx && bo ? 'd' : bx ? 'o' : bo ? 'x' : nvx === nvo ? 'd' : nvx > nvo ? 'x' : 'o';
    }
    hapticTap();
    playUiSound(hit ? 'key' : 'toggle');
    onMove(next);
  };
  const hand = (label, cards, val, stood, highlight) => (
    <div style={{ padding: '6px 8px', borderRadius: 10, background: theme.dark ? 'rgba(10,6,22,0.45)' : 'rgba(255,255,255,0.7)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 5 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: theme.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</span>
        <span style={{ marginLeft: 'auto', fontSize: 12, fontWeight: 900, color: val > 21 ? theme.danger : highlight ? '#22C55E' : theme.ink }}>{val > 21 ? `Bust ${val}` : val}{stood && val <= 21 ? ' · stand' : ''}</span>
      </div>
      <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>{cards.map((c) => <PlayingCard key={c} i={c} size={30} />)}</div>
    </div>
  );
  return (
    <GameCardShell width={240} live={live} title="Blackjack" status={status} hot={canAct} icon={<LayoutDashboard size={15} color={theme.coral} />}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {hand('You', myHand, myVal, myStood, finished && state.w === side)}
        {hand(peerName || 'Them', theirHand, theirVal, theirStood, finished && state.w && state.w !== 'd' && state.w !== side)}
      </div>
      {canAct && (
        <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
          <button onClick={() => act(true)} className="zchat-gbtn" style={{ flex: 1, height: 34, borderRadius: 10, border: 'none', background: theme.coral, color: 'white', fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('gold') }}>Hit</button>
          <button onClick={() => act(false)} className="zchat-gbtn" style={{ flex: 1, height: 34, borderRadius: 10, border: `1.5px solid ${theme.coral}`, background: 'transparent', color: theme.coral, fontWeight: 800, fontSize: 12.5, fontFamily: FONT, cursor: 'pointer' , ...gameBtnStyle('white') }}>Stand</button>
        </div>
      )}
      {!canAct && !finished && live && <div style={{ marginTop: 8, fontSize: 11.5, color: theme.muted, textAlign: 'center' }}>Closest to 21 without going over wins</div>}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function WarCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const deck = useMemo(() => deckFor(state.id), [state.id]);
  const strength = (i) => (i % 13 === 0 ? 13 : i % 13);
  const rounds = Array.from({ length: state.k }).map((_, r) => ({ cx: deck[r * 2], co: deck[r * 2 + 1] }));
  const wins = { x: 0, o: 0 };
  rounds.forEach((r) => { const a = strength(r.cx); const b = strength(r.co); if (a > b) wins.x += 1; else if (b > a) wins.o += 1; });
  const mine = myMark === 2 ? wins.o : wins.x;
  const theirs = myMark === 2 ? wins.x : wins.o;
  const draw = () => {
    if (!myTurn || state.k >= 5) return;
    const k = state.k + 1;
    let w = null;
    if (k >= 5) {
      const all = Array.from({ length: k }).map((_, r) => ({ cx: deck[r * 2], co: deck[r * 2 + 1] }));
      const ws = { x: 0, o: 0 };
      all.forEach((r) => { const a = strength(r.cx); const b = strength(r.co); if (a > b) ws.x += 1; else if (b > a) ws.o += 1; });
      w = ws.x > ws.o ? 'x' : ws.o > ws.x ? 'o' : 'd';
    }
    hapticTap();
    playUiSound('point');
    onMove({ ...state, k, t: myMark === 1 ? state.o : state.x, n: (state.n || 0) + 1, w });
  };
  const myKey = myMark === 2 ? 'co' : 'cx';
  const theirKey = myMark === 2 ? 'cx' : 'co';
  return (
    <GameCardShell width={224} live={live} title="High card" status={finished ? status : myTurn ? 'Your draw' : live ? 'Their draw' : `Round ${state.k}`} hot={myTurn} icon={<LayoutDashboard size={15} color={theme.coral} />}>
      <ScoreLine mine={mine} theirs={theirs} peerName={peerName} />
      <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
        {Array.from({ length: 5 }).map((_, r) => {
          const rd = rounds[r];
          const a = rd ? strength(rd[myKey]) : 0;
          const b = rd ? strength(rd[theirKey]) : 0;
          return (
            <div key={r} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '4px 8px', borderRadius: 10, background: theme.dark ? 'rgba(10,6,22,0.45)' : 'rgba(255,255,255,0.7)', opacity: rd ? 1 : 0.5 }}>
              <span style={{ fontSize: 11, fontWeight: 800, color: theme.muted, width: 14 }}>{r + 1}</span>
              {rd ? <PlayingCard i={rd[myKey]} size={26} /> : <PlayingCard i={0} size={26} hidden />}
              <span style={{ fontSize: 10.5, color: theme.muted }}>vs</span>
              {rd ? <PlayingCard i={rd[theirKey]} size={26} /> : <PlayingCard i={0} size={26} hidden />}
              <span style={{ marginLeft: 'auto', fontSize: 11, fontWeight: 800, color: !rd ? theme.muted : a > b ? '#22C55E' : a < b ? theme.danger : theme.muted }}>{!rd ? '' : a > b ? 'Won' : a < b ? 'Lost' : 'Tie'}</span>
            </div>
          );
        })}
      </div>
      {myTurn && <GameAgainButton onClick={draw} label={`Draw round ${state.k + 1}`} />}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function SnakesCard({ state, myId, live, peerName, onMove, onRematch, fresh }) {
  const { theme } = useTheme();
  const { myMark, finished, myTurn, outcome, status } = useTurnStatus(state, myId, live, peerName);
  useGameResultSound(live, fresh, finished, `${state.id}:${state.n}`, outcome);
  const cell = 32;
  const cols = 6;
  const rows = 5;
  const posOf = (n) => {
    if (n <= 0) return { x: 0, y: rows * cell + 8 };
    const idx = n - 1;
    const r = Math.floor(idx / cols);
    const c = r % 2 === 0 ? idx % cols : cols - 1 - (idx % cols);
    return { x: c * cell + cell / 2, y: (rows - 1 - r) * cell + cell / 2 };
  };
  const roll = () => {
    if (!myTurn) return;
    const d = 1 + Math.floor(Math.random() * 6);
    const key = myMark === 2 ? 'po' : 'px';
    let pos = state[key] + d;
    if (pos > 30) pos = state[key];
    if (SL_LADDERS[pos]) pos = SL_LADDERS[pos];
    else if (SL_SNAKES[pos]) pos = SL_SNAKES[pos];
    const w = pos === 30 ? (myMark === 1 ? 'x' : 'o') : null;
    hapticTap();
    playUiSound(SL_LADDERS[state[key] + d] ? 'point' : SL_SNAKES[state[key] + d] ? 'cancel' : 'toggle');
    onMove({ ...state, [key]: pos, d, t: w ? state.t : (myMark === 1 ? state.o : state.x), n: (state.n || 0) + 1, w });
  };
  const me = myMark === 2 ? state.po : state.px;
  const them = myMark === 2 ? state.px : state.po;
  const W = cols * cell;
  const H = rows * cell;
  return (
    <GameCardShell width={W + 20} live={live} title="Snakes and ladders" status={status} hot={myTurn} icon={<Activity size={15} color={theme.coral} />}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ display: 'block', borderRadius: 10 }}>
        {Array.from({ length: 30 }).map((_, i) => {
          const n = i + 1;
          const p = posOf(n);
          const special = SL_LADDERS[n] ? '#86EFAC' : SL_SNAKES[n] ? '#FCA5A5' : ((Math.floor(i / cols) + i) % 2 ? '#FDE68A' : '#FEF3C7');
          return (
            <g key={n}>
              <rect x={p.x - cell / 2} y={p.y - cell / 2} width={cell} height={cell} fill={special} stroke="#D6B36A" strokeWidth="1" />
              <text x={p.x - cell / 2 + 3} y={p.y - cell / 2 + 10} fontFamily={FONT} fontSize="8" fontWeight="800" fill="#7C5A12">{n}</text>
            </g>
          );
        })}
        {Object.entries(SL_LADDERS).map(([a, b]) => { const pa = posOf(+a); const pb = posOf(b); return <line key={`l${a}`} x1={pa.x} y1={pa.y} x2={pb.x} y2={pb.y} stroke="#16A34A" strokeWidth="4" strokeLinecap="round" opacity="0.85" />; })}
        {Object.entries(SL_SNAKES).map(([a, b]) => { const pa = posOf(+a); const pb = posOf(b); return <path key={`s${a}`} d={`M${pa.x} ${pa.y} Q ${(pa.x + pb.x) / 2 + 14} ${(pa.y + pb.y) / 2} ${pb.x} ${pb.y}`} fill="none" stroke="#DC2626" strokeWidth="4" strokeLinecap="round" opacity="0.85" />; })}
        {[[state.px, '#FBBF24', -5], [state.po, '#F43F5E', 5]].map(([pos, color, dx], i) => { const p = posOf(pos); return <circle key={i} cx={pos > 0 ? p.x + dx : 10 + i * 14} cy={pos > 0 ? p.y + 6 : H - 10} r="6" fill={color} stroke="white" strokeWidth="1.5" />; })}
      </svg>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, fontSize: 11.5, color: theme.muted }}>
        <span style={{ width: 9, height: 9, borderRadius: '50%', background: myMark === 2 ? '#F43F5E' : '#FBBF24' }} />You {me}
        <span style={{ width: 9, height: 9, borderRadius: '50%', background: myMark === 2 ? '#FBBF24' : '#F43F5E', marginLeft: 6 }} />{peerName || 'Them'} {them}
        {state.d > 0 && <span style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 4 }}>Last roll <DieFace v={state.d} size={18} /></span>}
      </div>
      {myTurn && <GameAgainButton onClick={roll} label="Roll the die" />}
      {live && finished && onRematch && <GameAgainButton onClick={onRematch} />}
    </GameCardShell>
  );
}

function InfoIcon({ size = 16, color = 'currentColor' }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <circle cx="12" cy="12" r="10" /><path d="M12 16v-4M12 8h.01" />
    </svg>
  );
}
const GAME_RULES = {
  ttt: { how: ['You are X or O. Take turns tapping an empty square.', 'The card in the chat updates after every move.'], win: 'Get three of your marks in a line, across, down or corner to corner.' },
  c4: { how: ['Tap any column to drop your disc. It falls to the lowest free spot.', 'Take turns with your friend.'], win: 'Line up four of your discs in a row, across, down or diagonally.' },
  rps: { how: ['You both secretly pick rock, paper or scissors.', 'Rock beats scissors, scissors beat paper, paper beats rock.', 'The same pick is a tie and you play the round again.'], win: 'First to win two rounds wins the match.' },
  ship: { how: ['Each of you has a hidden fleet of four ships on a 6 by 6 sea.', 'Take turns tapping a square on their sea to fire.', 'Red means a hit and you fire again. A white dot means a miss and it is their turn.', 'Your own fleet is shown small under their sea, with their shots on it.'], win: 'Sink every ship in their fleet before they sink yours.' },
  num: { how: ['One player picks a secret number from 1 to 100.', 'The other taps a number to guess. The card says go higher or go lower.', 'Numbers that are ruled out turn grey, so you always see what is left.'], win: `The guesser wins by finding the number within ${NUM_MAX_GUESSES} guesses. Otherwise the picker wins.` },
  dots: { how: ['Take turns tapping a line between two dots.', 'If your line closes a box, the box is yours and you go again.'], win: 'When every line is drawn, whoever owns more boxes wins.' },
  hang: { how: ['One player picks a secret word. The other guesses it one letter at a time.', 'Right letters appear in the word. Wrong letters add a part to the drawing.'], win: 'The guesser wins by finding the word before six wrong letters. Otherwise the word picker wins.' },
  wduel: { how: ['You both get the same secret five letter word.', 'Type a guess. Green is the right letter in the right spot, yellow is in the word but somewhere else, grey is not in the word.', 'Each of you plays your round whenever you like.'], win: 'Whoever finds the word in fewer tries wins.' },
  rduel: { how: ['Tap Play your round, then tap the pad to start.', 'Wait for the pad to turn green and tap it right away. Tapping too soon lets you retry.'], win: 'The faster time wins.' },
  qduel: { how: ['You both get the same five questions.', 'Tap one answer for each question.'], win: 'Most right answers wins. The same score is a draw.' },
  math: { how: ['Ten quick sums, the same ones for both of you.', 'Tap the right answer as fast as you can.'], win: 'Most right answers wins. With the same score, the faster time wins.' },
  taps: { how: ['Tap the pad to start a five second timer.', 'Keep tapping as fast as you can until time runs out.'], win: 'More taps wins.' },
  gomoku: { how: ['Take turns placing a stone on any free crossing.', 'The player who started the game plays black.'], win: 'First to get five stones in an unbroken line wins, across, down or diagonally.' },
  reversi: { how: ['Place a disc so a line of their discs is trapped between your new disc and another of yours.', 'Every trapped disc flips to your colour.', 'Only squares that can flip something show a dot. With no move, your turn is skipped.'], win: 'When nobody can move, whoever has more discs wins.' },
  pairs: { how: ['All cards start face down. On your turn flip two cards.', 'A match is yours and you go again. No match and it is their turn.', 'Their last two cards stay face up so you can remember them.'], win: 'When every pair is found, whoever collected more pairs wins.' },
  dice: { how: ['Tap Roll the dice to throw five dice.', 'Tap the dice you want to keep, then roll the rest once more.', 'Tap Keep these to lock in your hand. You each roll on your own.'], win: 'The better hand wins: five of a kind, four of a kind, full house, straight, three of a kind, two pair, one pair. With the same hand, the higher total wins.' },
  bj: { how: ['You both start with two cards from the same deck.', 'Hit takes another card. Stand keeps what you have.', 'Number cards count their number, J Q and K count 10, an Ace counts 11 or 1.'], win: 'Closest to 21 without going over wins. Over 21 is a bust.' },
  war: { how: ['Take turns tapping Draw. Each round deals one card to each of you.', 'The higher card wins the round. Ace is the highest.'], win: 'After five rounds, whoever won more rounds wins.' },
  sl: { how: ['Take turns tapping Roll the die and move forward.', 'Land on the bottom of a green ladder to climb up. Land on the head of a red snake and you slide down.', 'You must land exactly on 30.'], win: 'First to reach square 30 wins.' },
  nim: { how: ['There are three rows of sticks.', 'On your turn tap a stick. You take that stick and every stick after it in the same row.'], win: 'Whoever takes the very last stick wins.' },
  mancala: { how: ['Your pits are the bottom row and your store is on the right.', 'Tap one of your pits to pick up its seeds and drop them one by one around the board.', 'If your last seed lands in your store you go again.'], win: 'When one side runs out of seeds, whoever has more seeds in their store wins.' },
  '2048': { how: ['Swipe, or use the arrow keys, to slide every tile.', 'Two tiles with the same number merge into one.'], win: 'Make a 2048 tile. Every merge adds to your score.' },
  snake: { how: ['Swipe or use the arrows to steer.', 'Eat the red dots to grow. You speed up as you grow.'], win: 'Do not hit the walls or your own tail. Eat as many as you can.' },
  sky: { how: ['Tap anywhere to flap and rise. Gravity pulls you down.', 'Fly through the gaps between the pipes. The speed stays the same the whole run.'], win: 'Every pipe you pass is one point. Touching a pipe or the ground ends the run.' },
  bricks: { how: ['Slide your finger to move the paddle. Tap to launch the ball.', 'Bounce the ball up to break the bricks.'], win: 'Clear every brick to reach the next level. You have three lives.' },
  word: { how: ['Guess the five letter word in six tries.', 'Green is the right letter in the right spot, yellow is in the word but somewhere else, grey is not in the word.'], win: 'Solve it to keep your streak going.' },
  memory: { how: ['Flip two cards at a time.', 'Matching cards stay face up.'], win: 'Find every pair in as few moves as you can.' },
  reflex: { how: ['Tap the pad to start, then wait for green.', 'Tap the moment it turns green.'], win: 'The lower your time, the better.' },
  quiz: { how: ['Ten general knowledge questions.', 'Tap the answer you think is right.'], win: 'Get as many right as you can.' },
  echo: { how: ['Watch the pads light up and listen.', 'Repeat the same pattern by tapping the pads.', 'Every round adds one more step.'], win: 'Reach as many levels as you can without a mistake.' },
};
Object.assign(GAME_RULES, {
  paint: { how: ['You start in the top left corner, they start in the bottom right. Your area has a white outline.', 'On your turn pick a colour. Your whole area turns that colour and swallows every touching square of the same colour.', 'You cannot pick your own colour or theirs.'], win: 'Own more than half of the board, or own more when the board is full.' },
  bomb: { how: ['There are 20 boxes. One of them hides a bomb.', 'Take turns opening one box at a time.'], win: 'Whoever opens the bomb loses. If only the bomb is left, the player who would have to open it loses.' },
  gem: { how: ['Six gems are buried under a 6 by 6 field.', 'Take turns digging a square. Find a gem and you dig again.', 'An empty square shows how many gems touch it, so use the numbers to find them.'], win: 'First to dig up four gems wins.' },
  fade: { how: ['Tic tac toe with a twist: each of you can only have three marks on the board.', 'When you place a fourth, your oldest mark disappears. The faded mark is the next one to go.'], win: 'Get three in a row. There are no draws, keep going until someone wins.' },
  stack: { how: ['A block slides back and forth above your tower.', 'Tap to drop it. Only the part that lands on the tower stays, the rest falls off.', 'Land three perfect drops in a row and your block grows back a little.'], win: 'Build as many floors as you can.' },
  dash: { how: ['Your cube runs on its own and keeps speeding up.', 'Tap to jump. Tap again in the air for a second jump.', 'Jump over spikes and boxes.'], win: 'Run as far as you can. Every 40 steps is one metre.' },
  catch: { how: ['Slide your finger to move the basket.', 'Catch fruit for one point and stars for three.', 'Catching a bomb or missing a fruit costs a heart. You have three.'], win: 'Catch as much as you can before the hearts run out.' },
  ctrap: { how: ['A colour word appears written in a different colour of ink.', 'Tap the colour of the ink, not the word you read.', 'A wrong tap takes a point and one second away.'], win: 'Score as many points as you can in 30 seconds.' },
  odd: { how: ['A grid of tiles appears. One tile is a slightly different shade.', 'Tap it to go up a level. The grid grows and the difference gets smaller.', 'A wrong tap costs two seconds.'], win: 'Reach the highest level you can in 30 seconds.' },
  hilo: { how: ['A number from 1 to 99 is shown.', 'Guess if the next number will be higher or lower.'], win: 'Keep your streak going as long as you can. One wrong guess ends the run.' },
});
function getRules(k) {
  if (typeof k === 'string' && k.indexOf('sd:') === 0) {
    const base = GAME_RULES[k.slice(3)];
    if (!base) return null;
    return { how: ['You both play the exact same level on your own phone, whenever you like.', ...base.how, 'When your run ends, tap Send to post your score in the chat.'], win: 'The higher score wins the duel.' };
  }
  return GAME_RULES[k] || null;
}
function howtoSeen(k) { try { return localStorage.getItem(`zchat-howto-${k}`) === '1'; } catch { return true; } }
function HowToPlaySheet({ k, onClose }) {
  useBackClose(true, onClose);
  const { theme } = useTheme();
  const rules = getRules(k) || { how: [], win: '' };
  useEffect(() => { try { localStorage.setItem(`zchat-howto-${k}`, '1'); } catch {} }, [k]);
  return (
    <Portal>
      <div onClick={(e) => { e.stopPropagation(); onClose(); }} onPointerDown={(e) => e.stopPropagation()} onTouchStart={(e) => e.stopPropagation()} onContextMenu={(e) => e.stopPropagation()} className="zchat-fade" style={{ position: 'fixed', inset: 0, zIndex: 700, display: 'flex', alignItems: 'flex-end', justifyContent: 'center', fontFamily: FONT, background: 'rgba(5,8,16,0.55)' }}>
        <div onClick={(e) => e.stopPropagation()} className="zchat-sheet-up" style={{ width: '100%', maxWidth: 480, maxHeight: 'min(88vh, calc(100% - 24px))', display: 'flex', flexDirection: 'column', background: theme.panelBg, borderRadius: '26px 26px 0 0', overflow: 'hidden', paddingBottom: 'calc(14px + env(safe-area-inset-bottom))' }}>
          <div style={{ padding: '10px 16px 0', flexShrink: 0 }}>
            <div style={{ display: 'flex', justifyContent: 'center', paddingBottom: 10 }}><div style={{ width: 38, height: 4, borderRadius: 2, background: theme.border }} /></div>
            <div style={{ width: '100%', aspectRatio: '16 / 7', borderRadius: 18, overflow: 'hidden' }}><GameArt k={gameArtKey(k)} width="100%" height="100%" radius={18} /></div>
          </div>
          <div data-sheet-scroll="true" style={{ overflowY: 'auto', minHeight: 0, padding: '14px 20px 6px' }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: theme.coral, letterSpacing: '0.06em', textTransform: 'uppercase' }}>How to play</div>
            <div style={{ fontSize: 24, fontWeight: 800, color: theme.ink, letterSpacing: '-0.02em', marginTop: 2 }}>{gameKeyTitle(k)}</div>
            <div style={{ marginTop: 12, display: 'flex', flexDirection: 'column', gap: 10 }}>
              {rules.how.map((t, i) => (
                <div key={i} style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
                  <div style={{ width: 24, height: 24, borderRadius: 8, background: `${theme.coral}22`, color: theme.coralDeep, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12.5, fontWeight: 900, flexShrink: 0 }}>{i + 1}</div>
                  <div style={{ fontSize: 14.5, color: theme.ink, lineHeight: 1.45 }}>{t}</div>
                </div>
              ))}
            </div>
            {rules.win && (
              <div style={{ display: 'flex', gap: 12, alignItems: 'flex-start', marginTop: 14, padding: '12px 14px', borderRadius: 14, background: theme.dark ? 'rgba(245,158,11,0.12)' : 'rgba(245,158,11,0.14)' }}>
                <TrophyIcon size={20} color="#F59E0B" />
                <div style={{ fontSize: 14, color: theme.ink, lineHeight: 1.45 }}><b>How to win. </b>{rules.win}</div>
              </div>
            )}
          </div>
          <div style={{ padding: '10px 20px 0', flexShrink: 0 }}>
            <GameButton onClick={onClose} label="Got it" color="green" full />
          </div>
        </div>
      </div>
    </Portal>
  );
}
function GameInfoButton({ k, small, header, onDark }) {
  const { theme } = useTheme();
  const [open, setOpen] = useState(false);
  if (!getRules(k)) return null;
  const show = (e) => { if (e) { e.stopPropagation(); e.preventDefault(); } setOpen(true); };
  return (
    <>
      {header ? (
        <HeaderIconButton label="How to play" onClick={show}><InfoIcon /></HeaderIconButton>
      ) : (
        <span role="button" aria-label={`How to play ${gameKeyTitle(k)}`} onClick={show} onPointerDown={(e) => e.stopPropagation()} style={small
          ? { display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 22, height: 22, borderRadius: '50%', color: theme.muted, cursor: 'pointer', flexShrink: 0 }
          : { display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 30, height: 30, borderRadius: '50%', background: onDark ? 'rgba(0,0,0,0.35)' : theme.rowBg, color: onDark ? 'white' : theme.ink, cursor: 'pointer', flexShrink: 0, backdropFilter: onDark ? 'blur(6px)' : 'none', WebkitBackdropFilter: onDark ? 'blur(6px)' : 'none' }}>
          <InfoIcon size={small ? 15 : 17} />
        </span>
      )}
      {open && <HowToPlaySheet k={k} onClose={() => setOpen(false)} />}
    </>
  );
}

