  paint: ['#8B5CF6', '#EC4899'], bomb: ['#F97316', '#7F1D1D'], gem: ['#92400E', '#1E293B'], fade: ['#0EA5E9', '#7C3AED'],
  stack: ['#1E1B4B', '#7C3AED'], dash: ['#6D28D9', '#F472B6'], catch: ['#38BDF8', '#22C55E'], ctrap: ['#111827', '#4B5563'], odd: ['#14B8A6', '#0F766E'], hilo: ['#4338CA', '#9333EA'],
